/**
 * LiveTripTracking — Real-time trip progress screen
 *
 * ✅ Animated progress tracker
 * ✅ Supabase-backed trip presence tracking
 * ✅ Bilingual (EN / AR)
 * ✅ Emergency SOS button
 * ✅ Share location with trusted contact
 * ✅ Chat & call driver
 * ✅ Full dark Wasel design system
 */

import { Suspense, lazy, useState, useEffect, useCallback, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Navigation,
  Phone,
  MessageSquare,
  Shield,
  Share2,
  ChevronDown,
  ChevronUp,
  Star,
  AlertTriangle,
  CheckCircle,
  Brain,
  Leaf,
  X,
  Copy,
  XCircle,
  ThumbsUp,
} from 'lucide-react';
import { Button } from './ui/button';
import { Avatar, AvatarFallback, AvatarImage } from './ui/avatar';
import type { WaselMapProps } from './WaselMap';
import { toast } from 'sonner';
import { useNavigate } from 'react-router';
import { WaselBadge } from './wasel-ui/WaselBadge';
import { usePushNotifications } from '../hooks/usePushNotifications';
import { activeTripAPI } from '../services/activeTrip';
import { API_URL, fetchWithRetry, getAuthDetails } from '../services/core';
import { updateDirectBookingStatus } from '../services/directSupabase';
import { subscribeToLiveTripPresence, type LiveTripSnapshot } from '../services/liveTripTracking';
import { shareContent } from '../hooks/useShare';
import { useLocalAuth } from '../contexts/LocalAuth';
import { tx } from '../locales/tx';

const WaselMap = lazy(async () => {
  const mod = await import('./WaselMap');
  return { default: mod.WaselMap };
});

// ─── Trip data ────────────────────────────────────────────────────────────────

const DEFAULT_TRIP = {
  id: 'WA-9124',
  from: '7th Circle, Amman',
  fromAr: 'الدوار السابع، عمّان',
  fromCoord: { lat: 31.9562, lng: 35.8637 },
  to: 'University of Jordan',
  toAr: 'جامعة الأردن',
  toCoord: { lat: 32.0156, lng: 35.8696 },
  driver: {
    id: 'driver-ahmad-khalil',
    name: 'Ahmad Khalil',
    nameAr: 'أحمد خليل',
    rating: 4.92,
    trips: 1847,
    img: 'https://i.pravatar.cc/150?u=ah-k',
    phone: '+962 7 7853 8619',
    initials: 'AK',
  },
  vehicle: { model: 'Toyota Corolla', color: 'White', plate: '50·12345', year: 2022 },
  price: 1.85,
  startedAt: '7:42 AM',
  estimatedArrival: '8:04 AM',
  totalDistanceKm: 9.4,
  passengers: 2,
  shareCode: 'WA-9124',
  status: 'en_route' as const,
};

const DEFAULT_WAYPOINTS = [
  { label: 'Pickup', coord: { lat: 31.9562, lng: 35.8637 } },
  { label: 'Tlaa Al Ali', coord: { lat: 31.9808, lng: 35.8436 } },
  { label: 'Khalda', coord: { lat: 31.9976, lng: 35.8579 } },
  { label: 'University of Jordan', coord: { lat: 32.0156, lng: 35.8696 } },
];

// ─── Progress timeline ──────────────────────────────────────────────────────

function ProgressTimeline({
  progress,
  waypoints,
}: {
  progress: number;
  waypoints: Array<{ label: string }>;
}) {
  const activeIndex = Math.min(
    Math.max(Math.floor((progress / 100) * Math.max(waypoints.length - 1, 1)), 0),
    Math.max(waypoints.length - 1, 0),
  );
  return (
    <div className="flex items-start gap-2">
      {waypoints.map((wp, i) => {
        const reached = progress >= (i / Math.max(waypoints.length - 1, 1)) * 100;
        return (
          <div key={i} className="flex flex-col items-center flex-1">
            <div
              className={`w-6 h-6 rounded-full border-2 flex items-center justify-center transition-all ${
                reached
                  ? 'bg-primary border-primary shadow-md shadow-primary/30'
                  : 'bg-background border-border'
              }`}
            >
              {reached ? (
                <CheckCircle className="w-3.5 h-3.5 text-white" />
              ) : i === activeIndex ? (
                <motion.div
                  className="w-2 h-2 rounded-full bg-primary"
                  animate={{ scale: [1, 1.4, 1] }}
                  transition={{ duration: 1.5, repeat: Infinity }}
                />
              ) : (
                <div className="w-2 h-2 rounded-full bg-border" />
              )}
            </div>
            <div className="mt-1 text-center px-0.5">
              <p className="text-[9px] text-slate-400 leading-tight font-medium">{wp.label}</p>
            </div>
            {i < waypoints.length - 1 && <div className="absolute" style={{ display: 'none' }} />}
          </div>
        );
      })}
    </div>
  );
}

// ─── ETA card ─────────────────────────────────────────────────────────────────

function ETACard({
  eta,
  timeLeft,
  totalDistanceKm,
  price,
  telemetryFresh,
}: {
  eta: string;
  timeLeft: number;
  totalDistanceKm: number;
  price: number;
  telemetryFresh: boolean;
}) {
  return (
    <div className="flex items-center gap-3">
      <div className="text-center bg-primary/10 border border-primary/20 rounded-2xl px-4 py-2.5 flex-shrink-0">
        <div className="text-2xl font-bold text-primary">
          {timeLeft}
          {tx('liveTripTracking.m')}
        </div>
        <div className="text-[10px] text-slate-500">{tx('liveTripTracking.to_arrive')}</div>
      </div>
      <div className="flex-1">
        <div className="text-white font-bold">
          {tx('liveTripTracking.eta')}
          {eta}
        </div>
        <div className="text-slate-500 text-xs mt-0.5">
          {totalDistanceKm.toFixed(1)} {tx('liveTripTracking.km_total')}
          {price.toFixed(3)} JOD
        </div>
        <div className="flex items-center gap-1 mt-1">
          <Leaf className="w-3 h-3 text-emerald-400" />
          <span className="text-[10px] text-emerald-400">
            {telemetryFresh ? 'Live telemetry active' : 'Waiting for fresh telemetry'}
          </span>
        </div>
      </div>
    </div>
  );
}

function LiveMapLoader() {
  return (
    <div className="flex h-full min-h-[320px] items-center justify-center bg-[#081220] text-sm text-slate-400">
      {tx('liveTripTracking.loading_map')}
    </div>
  );
}

function LiveMap(props: WaselMapProps) {
  return (
    <Suspense fallback={<LiveMapLoader />}>
      <WaselMap {...props} />
    </Suspense>
  );
}

// ─── SOS dialog ───────────────────────────────────────────────────────────────

function SOSDialog({ open, onClose }: { open: boolean; onClose: () => void }) {
  const [confirmed, setConfirmed] = useState(false);

  const handleSOS = () => {
    setConfirmed(true);
    setTimeout(() => {
      toast.error('🚨 Emergency alert sent! Help is on the way.');
      onClose();
      setConfirmed(false);
    }, 2000);
  };

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 bg-black/80 backdrop-blur-sm flex items-center justify-center p-4"
        >
          <motion.div
            initial={{ scale: 0.8, y: 20 }}
            animate={{ scale: 1, y: 0 }}
            exit={{ scale: 0.8, y: 20 }}
            className="w-full max-w-sm bg-card border border-red-500/30 rounded-3xl p-6 text-center shadow-2xl shadow-red-500/20"
          >
            <div className="w-16 h-16 rounded-full bg-red-500/10 border-2 border-red-500/30 flex items-center justify-center mx-auto mb-4">
              <AlertTriangle className="w-8 h-8 text-red-400" />
            </div>
            <h3 className="text-xl font-bold text-white mb-1">
              {tx('liveTripTracking.emergency_sos')}
            </h3>
            <p className="text-red-400 font-semibold mb-1">طوارئ</p>
            <p className="text-slate-400 text-sm mb-6">
              {tx(
                'liveTripTracking.this_will_alert_wasel_s_safety_team_and_share_your_live_location_with_emergency_contacts',
              )}
            </p>

            {!confirmed ? (
              <div className="space-y-3">
                <Button
                  onClick={() => { void handleSOS(); }}
                  className="w-full bg-red-500 hover:bg-red-600 text-white font-bold h-12 rounded-xl shadow-lg shadow-red-500/20"
                >
                  <AlertTriangle className="w-4 h-4 mr-2" />
                  {tx('liveTripTracking.send_emergency_alert')}
                </Button>
                <Button
                  onClick={() => { void onClose(); }}
                  variant="ghost"
                  className="w-full text-slate-400 hover:text-white rounded-xl h-10"
                >
                  {tx('liveTripTracking.cancel')}
                </Button>
              </div>
            ) : (
              <motion.div
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                className="flex flex-col items-center gap-3"
              >
                <motion.div
                  animate={{ rotate: 360 }}
                  transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
                  className="w-10 h-10 border-2 border-red-400 border-t-transparent rounded-full"
                />
                <p className="text-red-400 font-bold">{tx('liveTripTracking.sending_alert')}</p>
              </motion.div>
            )}
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// ─── Post-trip Rating Sheet ────────────────────────────────────────────────────

const EMOJI_RATINGS = [
  { stars: 1, emoji: '😞', label: 'Poor', labelAr: 'سيء' },
  { stars: 2, emoji: '😕', label: 'Fair', labelAr: 'مقبول' },
  { stars: 3, emoji: '😐', label: 'OK', labelAr: 'جيد' },
  { stars: 4, emoji: '😊', label: 'Good', labelAr: 'جيد جداً' },
  { stars: 5, emoji: '🤩', label: 'Excellent', labelAr: 'ممتاز' },
];

function TripRatingSheet({
  open,
  driverName,
  driverImg,
  driverInitials,
  fare,
  onSubmit,
  onSkip,
}: {
  open: boolean;
  driverName: string;
  driverImg: string;
  driverInitials: string;
  fare: string;
  onSubmit: (stars: number, comment: string) => void;
  onSkip: () => void;
}) {
  const [stars, setStars] = useState(0);
  const [hovered, setHovered] = useState(0);
  const [comment, setComment] = useState('');
  const [submitting, setSubmitting] = useState(false);

  const active = hovered || stars;
  const emojiData = EMOJI_RATINGS[active - 1];

  const handleSubmit = async () => {
    if (!stars) {
      toast.error('Please select a rating first.');
      return;
    }
    setSubmitting(true);
    await onSubmit(stars, comment);
    setSubmitting(false);
  };

  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 bg-black/70 backdrop-blur-sm flex items-end justify-center"
        >
          <motion.div
            initial={{ y: '100%' }}
            animate={{ y: 0 }}
            exit={{ y: '100%' }}
            transition={{ type: 'spring', stiffness: 320, damping: 32 }}
            className="w-full max-w-lg bg-card border border-border rounded-t-3xl p-6 space-y-5 shadow-2xl"
          >
            {/* Handle */}
            <div className="w-10 h-1 bg-border rounded-full mx-auto -mt-1" />

            {/* Header */}
            <div className="flex items-center gap-3">
              <Avatar className="w-14 h-14 border-2 border-primary/20">
                <AvatarImage src={driverImg} />
                <AvatarFallback className="bg-muted text-white font-bold">
                  {driverInitials}
                </AvatarFallback>
              </Avatar>
              <div>
                <h2 className="text-lg font-bold text-white">
                  {tx('liveTripTracking.rate_your_ride')}
                </h2>
                <p className="text-slate-400 text-sm">
                  {tx('liveTripTracking.with')}
                  <span className="text-primary font-semibold">{driverName}</span>
                  <span className="text-slate-600 mx-1.5">·</span>
                  <span className="text-emerald-400 font-semibold">{fare} JOD</span>
                </p>
              </div>
            </div>

            {/* Star row */}
            <div className="flex justify-center gap-3">
              {EMOJI_RATINGS.map(({ stars: s, emoji }) => (
                <button
                  key={s}
                  onMouseEnter={() => setHovered(s)}
                  onMouseLeave={() => setHovered(0)}
                  onClick={() => { void setStars(s); }}
                  className="flex flex-col items-center gap-1 group"
                >
                  <motion.div
                    animate={{ scale: active === s ? 1.25 : 1 }}
                    transition={{ type: 'spring', stiffness: 400, damping: 18 }}
                    className="text-3xl select-none"
                  >
                    {emoji}
                  </motion.div>
                  {[1, 2, 3, 4, 5].indexOf(s) >= 0 && (
                    <Star
                      className={`w-4 h-4 transition-colors ${
                        s <= active ? 'fill-amber-400 text-amber-400' : 'text-border'
                      }`}
                    />
                  )}
                </button>
              ))}
            </div>

            {/* Emoji label */}
            <AnimatePresence mode="wait">
              {emojiData && (
                <motion.div
                  key={emojiData.label}
                  initial={{ opacity: 0, y: 4 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -4 }}
                  className="text-center"
                >
                  <span className="text-white font-bold">{emojiData.label}</span>
                  <span className="text-slate-500 ml-2 text-sm" dir="rtl">
                    {emojiData.labelAr}
                  </span>
                </motion.div>
              )}
            </AnimatePresence>

            {/* Comment box */}
            <div>
              <textarea
                value={comment}
                onChange={e => setComment(e.target.value)}
                placeholder={tx('liveTripTracking.add_a_comment_optional')}
                rows={2}
                className="w-full bg-background border border-border rounded-xl px-3 py-2.5 text-sm text-slate-300 placeholder:text-slate-600 focus:outline-none focus:border-primary/30 resize-none"
              />
            </div>

            {/* Actions */}
            <div className="flex gap-3">
              <Button
                variant="ghost"
                className="flex-1 h-11 border border-border text-slate-400 hover:text-white rounded-xl"
                onClick={() => { void onSkip(); }}
                disabled={submitting}
              >
                {tx('liveTripTracking.skip')}
              </Button>
              <Button
                className="flex-1 h-11 bg-primary hover:bg-primary/90 text-white font-bold rounded-xl shadow-lg shadow-primary/20 disabled:opacity-60"
                onClick={() => { void handleSubmit(); }}
                disabled={submitting || !stars}
              >
                {submitting ? (
                  <motion.div
                    animate={{ rotate: 360 }}
                    transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
                    className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full mr-2"
                  />
                ) : (
                  <ThumbsUp className="w-4 h-4 mr-2" />
                )}
                {tx('liveTripTracking.submit_rating')}
              </Button>
            </div>

            {/* Loyalty nudge */}
            <p className="text-center text-[11px] text-slate-600">
              {tx('liveTripTracking.ratings_earn_you')}{' '}
              <span className="text-amber-400 font-semibold">
                {tx('liveTripTracking.10_wasel_points')}
              </span>{' '}
              {tx('liveTripTracking.toward_gold_tier')}
            </p>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// ─── Cancel Trip Confirmation ──────────────────────────────────────────────────

function CancelConfirmDialog({
  open,
  onClose,
  onConfirm,
  cancelling,
}: {
  open: boolean;
  onClose: () => void;
  onConfirm: () => void;
  cancelling: boolean;
}) {
  return (
    <AnimatePresence>
      {open && (
        <motion.div
          initial={{ opacity: 0 }}
          animate={{ opacity: 1 }}
          exit={{ opacity: 0 }}
          className="fixed inset-0 z-50 bg-black/70 backdrop-blur-sm flex items-center justify-center p-4"
        >
          <motion.div
            initial={{ scale: 0.88, y: 20 }}
            animate={{ scale: 1, y: 0 }}
            exit={{ scale: 0.88, y: 20 }}
            transition={{ type: 'spring', stiffness: 320, damping: 28 }}
            className="w-full max-w-sm bg-card border border-border rounded-3xl p-6 text-center shadow-2xl"
          >
            <div className="w-14 h-14 rounded-full bg-red-500/10 border border-red-500/20 flex items-center justify-center mx-auto mb-4">
              <XCircle className="w-7 h-7 text-red-400" />
            </div>
            <h3 className="text-lg font-bold text-white mb-1">
              {tx('liveTripTracking.cancel_this_ride')}
            </h3>
            <p className="text-red-400 text-sm font-medium mb-1" dir="rtl">
              إلغاء هذه الرحلة؟
            </p>
            <p className="text-slate-400 text-xs mb-6">
              {tx(
                'liveTripTracking.the_driver_has_already_been_dispatched_a_cancellation_fee_may_apply',
              )}
            </p>
            <div className="flex gap-3">
              <Button
                variant="ghost"
                className="flex-1 h-11 border border-border text-slate-400 hover:text-white rounded-xl"
                onClick={() => { void onClose(); }}
                disabled={cancelling}
              >
                {tx('liveTripTracking.keep_ride')}
              </Button>
              <Button
                className="flex-1 h-11 bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 text-red-400 font-bold rounded-xl disabled:opacity-60"
                onClick={() => { void onConfirm(); }}
                disabled={cancelling}
              >
                {cancelling ? (
                  <motion.div
                    animate={{ rotate: 360 }}
                    transition={{ duration: 1, repeat: Infinity, ease: 'linear' }}
                    className="w-4 h-4 border-2 border-red-400/30 border-t-red-400 rounded-full"
                  />
                ) : (
                  'Cancel Ride'
                )}
              </Button>
            </div>
          </motion.div>
        </motion.div>
      )}
    </AnimatePresence>
  );
}

// ─── Main component ────────────────────────────────────────────────────────────

export function LiveTripTracking() {
  const navigate = useNavigate();
  const { user } = useLocalAuth();
  const { notifyDriverApproaching, notifyDriverArrived, notifyTripStarted, notifyTripCompleted } =
    usePushNotifications();
  const [liveTrip, setLiveTrip] = useState<LiveTripSnapshot | null>(null);
  const [tripLoaded, setTripLoaded] = useState(false);
  const [showDetails, setShowDetails] = useState(false);
  const [showSOS, setShowSOS] = useState(false);
  const [showCancel, setShowCancel] = useState(false);
  const [cancelling, setCancelling] = useState(false);
  const [showRating, setShowRating] = useState(false);
  const [aiTip, setAiTip] = useState(true);
  const trip = liveTrip ?? DEFAULT_TRIP;
  const waypoints = liveTrip?.waypoints ?? DEFAULT_WAYPOINTS;
  const progress = liveTrip?.progress ?? 0;
  const timeLeft = liveTrip?.timeLeftMinutes ?? 0;
  const driverPhoneDigits = trip.driver.phone.replace(/[^\d]/g, '');

  // Track which milestones we've already notified about
  const notifiedRef = useRef({
    approaching: false,
    arrived: false,
    started: false,
    completed: false,
  });

  useEffect(() => {
    if (!user?.id) {
      setLiveTrip(null);
      setTripLoaded(true);
      return () => {};
    }

    const unsubscribe = subscribeToLiveTripPresence(user.id, snapshot => {
      setLiveTrip(snapshot);
      setTripLoaded(true);
    });

    return unsubscribe;
  }, [user?.id]);

  // Push notification milestones
  useEffect(() => {
    // ~30% → driver approaching pickup
    if (progress >= 30 && !notifiedRef.current.approaching) {
      notifiedRef.current.approaching = true;
      notifyDriverApproaching(trip.driver.name);
    }
    // ~45% → driver arrived at pickup
    if (progress >= 45 && !notifiedRef.current.arrived) {
      notifiedRef.current.arrived = true;
      notifyDriverArrived(trip.driver.name);
    }
    // ~50% → trip started
    if (progress >= 50 && !notifiedRef.current.started) {
      notifiedRef.current.started = true;
      notifyTripStarted();
    }
    // ~90% → arriving soon
    if (progress >= 90 && !notifiedRef.current.completed) {
      notifiedRef.current.completed = true;
      notifyTripCompleted(trip.price.toFixed(3));
    }
  }, [
    notifyDriverApproaching,
    notifyDriverArrived,
    notifyTripCompleted,
    notifyTripStarted,
    progress,
    trip.driver.name,
    trip.price,
  ]);

  // Auto-complete at 100% → show rating sheet instead of immediately navigating
  useEffect(() => {
    if ((trip.status === 'completed' || progress >= 100) && !showRating) {
      activeTripAPI.clearActiveTrip().catch(() => {});
      // Brief delay so the "You've Arrived" overlay can be seen, then show rating
      const t = setTimeout(() => setShowRating(true), 2500);
      return () => clearTimeout(t);
    }
  }, [progress, showRating, trip.status]);

  const handleRatingSubmit = useCallback(
    async (stars: number, comment: string) => {
      try {
        const { token } = await getAuthDetails();
        await fetchWithRetry(`${API_URL}/reviews`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
          body: JSON.stringify({
            reviewee_id: trip.driver.id,
            role: 'driver',
            overall_rating: stars,
            comment,
            trip_id: liveTrip?.tripId ?? trip.shareCode,
          }),
        });
      } catch {
        // Not critical — proceed regardless
      }
      toast.success('Thanks for rating! · شكراً على تقييمك', {
        description: '+10 Wasel Points earned 🌟',
      });
      setShowRating(false);
      navigate('/app/my-trips');
    },
    [liveTrip?.tripId, navigate, trip.driver.id, trip.shareCode],
  );

  const handleRatingSkip = useCallback(() => {
    setShowRating(false);
    navigate('/app/my-trips');
  }, [navigate]);

  const handleCancelConfirm = useCallback(async () => {
    setCancelling(true);
    if (liveTrip?.bookingId) {
      await updateDirectBookingStatus(liveTrip.bookingId, 'cancelled').catch(() => undefined);
    }
    await activeTripAPI.clearActiveTrip().catch(() => false);
    setCancelling(false);
    setShowCancel(false);
    toast.info('Ride cancelled · تم إلغاء الرحلة');
    navigate('/app/dashboard');
  }, [liveTrip?.bookingId, navigate]);

  const copyShareCode = useCallback(() => {
    navigator.clipboard?.writeText(trip.shareCode).then(() => {
      toast.success('Safety code copied!');
    });
  }, [trip.shareCode]);

  if (!tripLoaded) {
    return (
      <div className="flex min-h-[calc(100dvh-4rem)] items-center justify-center bg-background p-6">
        <div className="w-full max-w-md rounded-3xl border border-border bg-card p-8 text-center shadow-2xl">
          <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl border border-primary/20 bg-primary/10">
            <Navigation className="h-7 w-7 animate-pulse text-primary" />
          </div>
          <h2 className="text-xl font-bold text-white">
            {tx('liveTripTracking.loading_live_trip')}
          </h2>
          <p className="mt-2 text-sm text-slate-400">
            {tx(
              'liveTripTracking.wasel_is_checking_the_active_booking_and_driver_telemetry_for_this_account',
            )}
          </p>
        </div>
      </div>
    );
  }

  if (!liveTrip) {
    return (
      <div className="flex min-h-[calc(100dvh-4rem)] items-center justify-center bg-background p-6">
        <div className="w-full max-w-md rounded-3xl border border-border bg-card p-8 text-center shadow-2xl">
          <div className="mx-auto mb-4 flex h-14 w-14 items-center justify-center rounded-2xl border border-primary/20 bg-primary/10">
            <Navigation className="h-7 w-7 text-primary" />
          </div>
          <h2 className="text-xl font-bold text-white">
            {tx('liveTripTracking.no_active_trip_right_now')}
          </h2>
          <p className="mt-2 text-sm text-slate-400">
            {tx(
              'liveTripTracking.live_tracking_appears_here_once_a_confirmed_trip_starts_streaming_location_updates_from_the_driver',
            )}
          </p>
          <Button
            className="mt-6 h-11 rounded-xl px-5 font-semibold"
            onClick={() => { void navigate(); }}
          >
            {tx('liveTripTracking.open_my_trips')}
          </Button>
        </div>
      </div>
    );
  }

  const arrived = trip.status === 'completed' || progress >= 100;
  const currentLegIndex = Math.min(
    Math.max(Math.floor((progress / 100) * (waypoints.length - 1)), 0),
    Math.max(waypoints.length - 2, 0),
  );
  const currentLegProgress = (progress / 100) * Math.max(waypoints.length - 1, 1) - currentLegIndex;
  const currentStart = waypoints[currentLegIndex]?.coord ?? trip.fromCoord;
  const currentEnd = waypoints[currentLegIndex + 1]?.coord ?? trip.toCoord;
  const fallbackDriverPosition = {
    lat:
      currentStart.lat +
      (currentEnd.lat - currentStart.lat) * Math.max(0, Math.min(currentLegProgress, 1)),
    lng:
      currentStart.lng +
      (currentEnd.lng - currentStart.lng) * Math.max(0, Math.min(currentLegProgress, 1)),
  };
  const driverPosition = liveTrip?.driverPosition ?? fallbackDriverPosition;
  const mapCenter = driverPosition;
  const mapRoute = waypoints.map(waypoint => ({
    lat: waypoint.coord.lat,
    lng: waypoint.coord.lng,
    label: waypoint.label,
  }));
  const mapMarkers = [
    { lat: trip.fromCoord.lat, lng: trip.fromCoord.lng, label: 'Pickup', type: 'pickup' as const },
    {
      lat: driverPosition.lat,
      lng: driverPosition.lng,
      label: 'Driver',
      type: 'waypoint' as const,
    },
    { lat: trip.toCoord.lat, lng: trip.toCoord.lng, label: 'Dropoff', type: 'dropoff' as const },
  ];

  return (
    <div className="flex flex-col lg:flex-row h-[calc(100dvh-4rem)] bg-background relative">
      {/* ── MAP ── */}
      <div className="flex-1 relative">
        <LiveMap
          className="w-full h-full"
          center={mapCenter}
          zoom={13}
          route={mapRoute}
          markers={mapMarkers}
          showTraffic
          showMosques
          showRadars
        />

        {/* Live badge overlay */}
        <div className="absolute top-4 left-4 z-10 flex flex-wrap items-center gap-2">
          <WaselBadge variant="live" label={tx('liveTripTracking.live_tracking')} />
          <div className="rounded-full border border-cyan-400/20 bg-slate-950/70 px-3 py-1.5 text-[11px] font-semibold text-slate-100 backdrop-blur-md">
            {trip.from} {tx('liveTripTracking.to')}
            {trip.to}
          </div>
          <div className="rounded-full border border-white/10 bg-slate-950/70 px-3 py-1.5 text-[11px] font-semibold text-cyan-300 backdrop-blur-md">
            {tx('liveTripTracking.driver_near')}{' '}
            {waypoints[Math.min(currentLegIndex + 1, waypoints.length - 1)]?.label ?? trip.to}
          </div>
          {liveTrip && !liveTrip.telemetryFresh ? (
            <div className="rounded-full border border-amber-400/20 bg-slate-950/70 px-3 py-1.5 text-[11px] font-semibold text-amber-300 backdrop-blur-md">
              {tx('liveTripTracking.waiting_for_fresh_gps_heartbeat')}
            </div>
          ) : null}
        </div>

        {/* Progress bar overlay */}
        <div className="absolute bottom-0 left-0 right-0 h-1.5 bg-muted">
          <motion.div
            className="h-full bg-gradient-to-r from-primary to-cyan-400"
            style={{ width: `${progress}%` }}
            transition={{ duration: 0.5 }}
          />
        </div>

        {/* Arrived overlay */}
        <AnimatePresence>
          {arrived && (
            <motion.div
              initial={{ opacity: 0 }}
              animate={{ opacity: 1 }}
              className="absolute inset-0 bg-primary/20 backdrop-blur-sm flex items-center justify-center z-20"
            >
              <motion.div
                initial={{ scale: 0 }}
                animate={{ scale: 1 }}
                transition={{ type: 'spring', stiffness: 300 }}
                className="bg-card border border-primary/30 rounded-3xl p-8 text-center shadow-2xl"
              >
                <CheckCircle className="w-16 h-16 text-primary mx-auto mb-3" />
                <h2 className="text-2xl font-bold text-white">
                  {tx('liveTripTracking.you_ve_arrived')}
                </h2>
                <p className="text-primary font-semibold mt-1">وصلت إلى وجهتك</p>
              </motion.div>
            </motion.div>
          )}
        </AnimatePresence>
      </div>

      {/* ── INFO PANEL ── */}
      <div className="w-full lg:w-96 bg-background border-t lg:border-t-0 lg:border-l border-border flex flex-col overflow-y-auto">
        {/* Trip ID bar */}
        <div className="px-4 py-2.5 border-b border-border bg-card flex items-center justify-between">
          <div className="flex items-center gap-2">
            <motion.div
              className="w-2 h-2 rounded-full bg-primary"
              animate={{ scale: [1, 1.5, 1], opacity: [1, 0.4, 1] }}
              transition={{ duration: 1.5, repeat: Infinity }}
            />
            <span className="text-sm text-white font-bold">
              {tx('liveTripTracking.trip')}
              {liveTrip?.tripId ?? trip.shareCode}
            </span>
          </div>
          <button
            onClick={() => { void navigate(-1); }}
            className="text-slate-500 hover:text-white transition-colors"
            aria-label="Close trip tracking"
          >
            <X className="w-4 h-4" />
          </button>
        </div>

        <div className="flex-1 p-4 space-y-4 overflow-y-auto">
          {/* ETA */}
          <ETACard
            eta={trip.estimatedArrival}
            timeLeft={Math.round(timeLeft)}
            totalDistanceKm={trip.totalDistanceKm}
            price={trip.price}
            telemetryFresh={liveTrip?.telemetryFresh ?? false}
          />

          {/* Progress bar */}
          <div className="space-y-1.5">
            <div className="flex justify-between text-xs text-slate-500">
              <span>{tx('liveTripTracking.trip_progress')}</span>
              <span className="text-primary font-semibold">{Math.round(progress)}%</span>
            </div>
            <div className="w-full h-2.5 bg-muted rounded-full overflow-hidden">
              <motion.div
                className="h-full bg-gradient-to-r from-primary to-cyan-400 rounded-full"
                style={{ width: `${progress}%` }}
                transition={{ duration: 0.5 }}
              />
            </div>
          </div>

          {/* Waypoints */}
          <div className="relative">
            <ProgressTimeline progress={progress} waypoints={waypoints} />
          </div>

          {/* Driver card */}
          <div className="rounded-2xl bg-card border border-border p-3">
            <div className="flex items-center gap-3">
              <Avatar className="w-12 h-12 border-2 border-primary/20">
                <AvatarImage src={trip.driver.img} />
                <AvatarFallback className="bg-muted text-white">
                  {trip.driver.initials}
                </AvatarFallback>
              </Avatar>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-1.5">
                  <span className="text-white font-bold text-sm">{trip.driver.name}</span>
                  <Shield className="w-3.5 h-3.5 text-primary flex-shrink-0" />
                </div>
                <p className="text-xs text-slate-500">
                  {trip.vehicle.model} · {trip.vehicle.plate}
                </p>
                <div className="flex items-center gap-1 mt-0.5">
                  <Star className="w-3 h-3 text-amber-400 fill-current" />
                  <span className="text-xs text-amber-400 font-semibold">{trip.driver.rating}</span>
                  <span className="text-xs text-slate-600">
                    · {trip.driver.trips.toLocaleString()} {tx('liveTripTracking.trips')}
                  </span>
                </div>
              </div>
              {/* Quick contact */}
              <div className="flex gap-1.5 flex-shrink-0">
                <button
                  onClick={() => {
                    window.open(`tel:${trip.driver.phone}`, '_self');
                    toast.info(`Calling ${trip.driver.name}…`);
                  }}
                  className="w-9 h-9 rounded-xl bg-background border border-border flex items-center justify-center text-slate-400 hover:text-primary hover:border-primary/30 transition-all"
                  aria-label={`Call ${trip.driver.name}`}
                >
                  <Phone className="w-3.5 h-3.5" />
                </button>
                <button
                  onClick={() => {
                    window.open(
                      `https://wa.me/${driverPhoneDigits}?text=${encodeURIComponent(`Hi ${trip.driver.name}, I'm on trip ${liveTrip?.tripId ?? trip.shareCode} with Wasel.`)}`,
                      '_blank',
                      'noopener,noreferrer',
                    );
                  }}
                  className="w-9 h-9 rounded-xl bg-background border border-border flex items-center justify-center text-slate-400 hover:text-cyan-400 hover:border-cyan-400/30 transition-all"
                  aria-label={`Message ${trip.driver.name} on WhatsApp`}
                >
                  <MessageSquare className="w-3.5 h-3.5" />
                </button>
              </div>
            </div>
          </div>

          {/* Safety code */}
          <button
            onClick={() => { void copyShareCode(); }}
            className="w-full flex items-center gap-2 bg-card border border-border rounded-xl px-3 py-2.5 hover:border-muted-foreground/30 transition-all group"
          >
            <Shield className="w-3.5 h-3.5 text-primary flex-shrink-0" />
            <span className="text-xs text-slate-500 flex-1 text-left">
              {tx('liveTripTracking.safety_code')}
              <strong className="text-white font-mono">{trip.shareCode}</strong>
            </span>
            <Copy className="w-3.5 h-3.5 text-slate-600 group-hover:text-slate-400 transition-colors" />
          </button>

          {/* Toggle trip details */}
          <button
            onClick={() => { void setShowDetails(!showDetails); }}
            className="w-full flex items-center justify-between px-3 py-2 rounded-xl bg-card border border-border text-sm text-slate-400 hover:text-white transition-all"
          >
            <span>{tx('liveTripTracking.trip_details')}</span>
            {showDetails ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </button>

          <AnimatePresence>
            {showDetails && (
              <motion.div
                initial={{ opacity: 0, height: 0 }}
                animate={{ opacity: 1, height: 'auto' }}
                exit={{ opacity: 0, height: 0 }}
                className="overflow-hidden"
              >
                <div className="rounded-xl bg-card border border-border overflow-hidden">
                  {[
                    { label: 'From', value: trip.from, valueAr: trip.fromAr },
                    { label: 'To', value: trip.to, valueAr: trip.toAr },
                    { label: 'Started', value: trip.startedAt },
                    { label: 'ETA', value: trip.estimatedArrival },
                    { label: 'Distance', value: `${trip.totalDistanceKm.toFixed(1)} km` },
                    { label: 'Passengers', value: `${trip.passengers}` },
                    { label: 'Fare', value: `${trip.price.toFixed(3)} JOD` },
                  ].map(({ label, value, valueAr }, i) => (
                    <div
                      key={label}
                      className={`flex justify-between items-start px-3 py-2 text-xs ${i > 0 ? 'border-t border-border' : ''}`}
                    >
                      <span className="text-slate-500">{label}</span>
                      <div className="text-right">
                        <span className="text-slate-200">{value}</span>
                        {valueAr && (
                          <p className="text-slate-600 text-[10px]" dir="rtl">
                            {valueAr}
                          </p>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </motion.div>
            )}
          </AnimatePresence>

          {/* AI tip */}
          <AnimatePresence>
            {aiTip && (
              <motion.div
                initial={{ opacity: 0, y: 10 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, x: 30 }}
                className="flex items-start gap-2 bg-cyan-500/5 border border-cyan-500/10 rounded-xl px-3 py-2.5"
              >
                <Brain className="w-3.5 h-3.5 text-cyan-400 flex-shrink-0 mt-0.5" />
                <p className="text-xs text-slate-500 flex-1">
                  <span className="text-cyan-400 font-semibold">
                    {tx('liveTripTracking.ai_tip')}
                  </span>
                  {liveTrip?.telemetryFresh ? (
                    <>
                      {tx(
                        'liveTripTracking.your_driver_heartbeat_is_fresh_and_this_trip_is_tracking_live_against_the_route_corridor',
                      )}
                    </>
                  ) : (
                    <>
                      {tx(
                        'liveTripTracking.telemetry_is_catching_up_we_will_refresh_the_route_state_as_soon_as_the_next_gps_heartbeat_lands',
                      )}
                    </>
                  )}
                </p>
                <button
                  onClick={() => { void setAiTip(false); }}
                  className="text-slate-700 hover:text-slate-500"
                >
                  <X className="w-3 h-3" />
                </button>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* Bottom actions */}
        <div className="p-4 border-t border-border space-y-2.5 bg-background">
          <Button
            onClick={() =>
              shareContent({
                title: `Wasel Trip ${liveTrip?.tripId ?? trip.shareCode} — Live Location`,
                text: `Track my trip from ${trip.from} to ${trip.to} on Wasel. Safety code: ${trip.shareCode}`,
                url: `${window.location.origin}/track/${liveTrip?.tripId ?? trip.shareCode}`,
                successMessage: 'Live trip link copied!',
                successMessageAr: 'تم نسخ رابط الرحلة!',
              })
            }
            variant="ghost"
            className="w-full h-10 border border-border text-slate-300 hover:text-white hover:border-muted-foreground/30 rounded-xl text-sm font-medium"
          >
            <Share2 className="w-3.5 h-3.5 mr-2" />
            {tx('liveTripTracking.share_live_location')}
          </Button>

          {/* Cancel ride — only shown while trip is not yet complete */}
          {!arrived && (
            <Button
              onClick={() => { void setShowCancel(true); }}
              variant="ghost"
              className="w-full h-10 border border-orange-500/20 text-orange-400 hover:bg-orange-500/5 hover:text-orange-300 hover:border-orange-500/40 rounded-xl text-sm font-medium"
            >
              <XCircle className="w-3.5 h-3.5 mr-2" />
              {tx('liveTripTracking.cancel_ride')}
            </Button>
          )}

          <Button
            onClick={() => { void setShowSOS(true); }}
            className="w-full h-10 bg-red-500/10 hover:bg-red-500/20 border border-red-500/20 text-red-400 hover:text-red-300 rounded-xl text-sm font-bold transition-all"
          >
            <AlertTriangle className="w-3.5 h-3.5 mr-2" />
            {tx('liveTripTracking.emergency_sos_2')}
          </Button>
        </div>
      </div>

      {/* SOS Dialog */}
      <SOSDialog open={showSOS} onClose={() => setShowSOS(false)} />

      {/* Cancel Confirmation */}
      <CancelConfirmDialog
        open={showCancel}
        onClose={() => setShowCancel(false)}
        onConfirm={() => { void handleCancelConfirm(); }}
        cancelling={cancelling}
      />

      {/* Post-trip Rating Sheet */}
      <TripRatingSheet
        open={showRating}
        driverName={trip.driver.name}
        driverImg={trip.driver.img}
        driverInitials={trip.driver.initials}
        fare={trip.price.toFixed(3)}
        onSubmit={() => { void handleRatingSubmit(); }}
        onSkip={handleRatingSkip}
      />
    </div>
  );
}

/**
 * Mobile Bottom Navigation
 * Shared with the app's core navigation model for consistent UX.
 */

import { Bus, Clock, Network, Package, PlusCircle, Search } from 'lucide-react';
import { useLocation, useNavigate } from 'react-router';
import { CORE_NAV_ITEMS } from '../config/user-navigation';
import { useLanguage } from '../contexts/LanguageContext';
import { C, F, GRAD_GOLD } from '../utils/wasel-ds';

const BG = 'rgba(6,19,31,0.96)';
const CYAN = C.cyan;
const GOLD = C.gold;
const INACTIVE = C.textDim;
const BORDER = C.border;

const ICONS = {
  find: Search,
  post: PlusCircle,
  packages: Package,
  'mobility-os': Network,
  trips: Clock,
  bus: Bus,
} as const;

interface MobileBottomNavProps {
  language?: 'en' | 'ar';
}

function NavItem({ item, isActive, isArabic, navigate }: {
  item: typeof CORE_NAV_ITEMS[number];
  isActive: boolean;
  isArabic: boolean;
  navigate: ReturnType<typeof useNavigate>;
}) {
  const Icon = ICONS[item.id as keyof typeof ICONS];
  const isPost = item.id === 'post';
  const itemColor = item.accent === 'gold' ? GOLD : CYAN;

  return (
    <button
      onClick={() => { void navigate(item.path); }}
      aria-label={isArabic ? item.labelAr : item.label}
      aria-current={isActive ? 'page' : undefined}
      style={{
        flex: 1,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        justifyContent: 'center',
        gap: 3,
        minHeight: 56,
        minWidth: 44,
        padding: '8px 4px 6px',
        background: 'transparent',
        border: 'none',
        cursor: 'pointer',
        WebkitTapHighlightColor: 'transparent',
        outline: 'none',
        position: 'relative',
        transform: isActive ? 'scale(1.05)' : 'scale(1)',
        transition: 'transform 0.15s ease',
      }}
    >
      {isActive && !isPost && (
        <div
          style={{
            position: 'absolute',
            top: 0,
            left: '25%',
            right: '25%',
            height: 2,
            borderRadius: '0 0 2px 2px',
            background: itemColor,
            boxShadow: `0 2px 8px ${itemColor}80`,
          }}
        />
      )}

      {isPost ? (
        <div
          style={{
            width: 48,
            height: 48,
            borderRadius: 16,
            background: isActive
              ? GRAD_GOLD
              : 'linear-gradient(135deg,rgba(255,190,92,0.2),rgba(255,147,106,0.16))',
            border: `1.5px solid ${isActive ? GOLD : 'rgba(255,190,92,0.34)'}`,
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            boxShadow: isActive
              ? '0 10px 24px rgba(255,190,92,0.28)'
              : '0 4px 14px rgba(255,190,92,0.14)',
            transition: 'all 0.2s ease',
          }}
        >
          <Icon
            size={22}
            strokeWidth={isActive ? 2.5 : 2}
            color={isActive ? '#111316' : GOLD}
          />
        </div>
      ) : (
        <div
          style={{
            position: 'relative',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
          }}
        >
          {Icon && (
            <Icon
              size={22}
              strokeWidth={isActive ? 2.5 : 1.8}
              style={{
                color: isActive ? itemColor : INACTIVE,
                transition: 'color 0.18s ease',
              }}
            />
          )}
        </div>
      )}

      <span
        style={{
          fontSize: 10,
          fontWeight: isActive ? 700 : 500,
          color: isActive ? (isPost ? GOLD : itemColor) : INACTIVE,
          fontFamily: F,
          lineHeight: 1,
          whiteSpace: 'nowrap',
          transition: 'color 0.18s ease',
          letterSpacing: isActive ? '0.01em' : '0',
        }}
      >
        {isArabic ? item.labelAr : item.label}
      </span>
    </button>
  );
}

export function MobileBottomNav({ language }: MobileBottomNavProps) {
  const { language: activeLanguage } = useLanguage();
  const location = useLocation();
  const navigate = useNavigate();
  const resolvedLanguage = language ?? activeLanguage;
  const isArabic = resolvedLanguage === 'ar';

  const isActive = (path: string) => {
    if (path === '/')
      {return (
        location.pathname === '/' || location.pathname === '/app' || location.pathname === '/app/'
      );}
    return location.pathname.startsWith(path) || location.pathname.startsWith('/app' + path);
  };

  return (
    <>
      <style>{`
        .wasel-bottom-nav {
          display: flex !important;
        }
        .wrl-main-content {
          padding-bottom: 80px !important;
        }
      `}</style>

      <nav
        className="wasel-bottom-nav"
        aria-label={isArabic ? 'التنقل الرئيسي' : 'Main navigation'}
        style={{
          position: 'fixed',
          bottom: 0,
          left: 0,
          right: 0,
          zIndex: 600,
          background: BG,
          borderTop: `1px solid ${BORDER}`,
          boxShadow: '0 -12px 36px rgba(0,0,0,0.42), 0 -1px 0 rgba(88,221,255,0.08)',
          paddingBottom: 'max(8px, env(safe-area-inset-bottom, 8px))',
          flexDirection: 'row',
          justifyContent: 'space-around',
          alignItems: 'stretch',
          willChange: 'transform',
          transform: 'translateZ(0)',
        }}
      >
        {CORE_NAV_ITEMS.map(item => (
          <NavItem key={item.id} item={item} isActive={isActive(item.path)} isArabic={isArabic} navigate={navigate} />
        ))}
      </nav>
    </>
  );
}

/**
 * NotificationCenter.tsx  ← REFACTORED
 *
 * Orchestrator only — all sub-components and helpers are now in
 * src/components/notifications/.
 *
 * Before: 39 KB single-file monolith
 * After:  ~6 KB orchestrator + 3 focused modules:
 *   - notificationHelpers.ts    (pure functions + static maps)
 *   - NotificationMetric.tsx    (stat tile)
 *   - NotificationItem.tsx      (notification row card)
 */
import { startTransition, useDeferredValue, useMemo, useState } from 'react';
import {
  AlertTriangle,
  BellOff,
  CheckCheck,
  Inbox,
  RefreshCw,
  Search,
  Trash2,
  Wifi,
  WifiOff,
} from 'lucide-react';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import { Input } from './ui/input';
import { ScrollArea } from './ui/scroll-area';
import { WaselStateCard } from './system/WaselStateCard';
import { useLanguage } from '../contexts/LanguageContext';
import { useNotifications, type Notification } from '../hooks/useNotifications';
import { useIframeSafeNavigate } from '../hooks/useIframeSafeNavigate';
import { normalizeTextTree } from '../utils/textEncoding';
import {
  buildNotificationSections,
  getNotificationSummary,
  matchesNotificationFilter,
  matchesNotificationSearch,
  type NotificationFilter,
} from '../features/notifications/notificationCenterModel';
import { NotificationItem } from './notifications/NotificationItem';
import { NotificationMetric } from './notifications/NotificationMetric';

// ── Types ─────────────────────────────────────────────────────────────────────

type FilterConfig = { value: NotificationFilter; label: string };

// ── Component ─────────────────────────────────────────────────────────────────

export function NotificationCenter() {
  const nav = useIframeSafeNavigate();
  const {
    notifications,
    unreadCount,
    archivedIds,
    loading,
    connectionStatus,
    errorMessage,
    markAsRead,
    markAllAsRead,
    archiveNotification,
    restoreArchivedNotifications,
    refresh,
  } = useNotifications();

  const { language } = useLanguage();
  const isRTL = language === 'ar';

  const [filter, setFilter] = useState<NotificationFilter>('all');
  const [searchTerm, setSearchTerm] = useState('');
  const deferredSearchTerm = useDeferredValue(searchTerm);

  // ── Labels (bilingual) ──────────────────────────────────────────────────────
  const labels = normalizeTextTree({
    title: isRTL ? 'مركز الإشعارات' : 'Notification Center',
    subtitle: isRTL
      ? 'رتّب التنبيهات المهمة، تابع الحجوزات، وأبقِ العمليات تحت السيطرة.'
      : 'See important updates fast.',
    all: isRTL ? 'الكل' : 'All',
    unread: isRTL ? 'غير المقروءة' : 'Unread',
    urgent: isRTL ? 'عاجلة' : 'Urgent',
    archived: isRTL ? 'المؤرشفة' : 'Archived',
    rides: isRTL ? 'الرحلات' : 'Rides',
    messages: isRTL ? 'الرسائل' : 'Messages',
    wallet: isRTL ? 'المحفظة' : 'Wallet',
    trust: isRTL ? 'الثقة' : 'Trust',
    support: isRTL ? 'الدعم' : 'Support',
    system: isRTL ? 'النظام' : 'System',
    total: isRTL ? 'مرئية' : 'Visible',
    unreadCount: isRTL ? 'تحتاج انتباهاً' : 'Need attention',
    urgentCount: isRTL ? 'أولوية عالية' : 'High priority',
    archivedCount: isRTL ? 'مخفية' : 'Archived',
    searchPlaceholder: isRTL
      ? 'ابحث في العنوان أو الرسالة أو النوع'
      : 'Search title, message, or type',
    markAllRead: isRTL ? 'تعيين الكل كمقروء' : 'Mark all read',
    restoreArchived: isRTL ? 'استعادة المؤرشفة' : 'Restore archived',
    refresh: isRTL ? 'تحديث' : 'Refresh',
    view: isRTL ? 'فتح' : 'Open',
    markRead: isRTL ? 'تعيين كمقروء' : 'Mark read',
    archive: isRTL ? 'أرشفة' : 'Archive',
    today: isRTL ? 'اليوم' : 'Today',
    week: isRTL ? 'آخر 7 أيام' : 'Last 7 days',
    earlier: isRTL ? 'أقدم' : 'Earlier',
    online: isRTL ? 'متصل' : 'Online',
    offline: isRTL ? 'غير متصل' : 'Offline',
    syncing: isRTL ? 'مزامنة' : 'Syncing',
    noResults: isRTL ? 'لا توجد نتائج' : 'No results',
    emptyAll: isRTL ? 'لم تصل أي إشعارات بعد.' : 'No notifications yet.',
    emptyFiltered: isRTL ? 'هذا العرض هادئ الآن.' : 'Nothing here right now.',
    localDraft: isRTL ? 'محلي' : 'Local',
    urgentBadge: isRTL ? 'عاجل' : 'Urgent',
    highBadge: isRTL ? 'مرتفع' : 'High',
    loadingEyebrow: isRTL ? 'مركز الإشعارات' : 'Notification Center',
    loadingTitle: isRTL ? 'نجهز تدفق الإشعارات الآن' : 'Preparing your notification stream',
    loadingDescription: isRTL
      ? 'نجمع الحجوزات ورسائل الدعم ونشاط المحفظة في موجز واحد واضح.'
      : 'Pulling bookings, support messages, and wallet activity into one clear feed.',
    loadingFooter: isRTL
      ? 'سيمتلئ هذا العرض بمجرد اكتمال المزامنة.'
      : 'This view will fill in as soon as the sync completes.',
    serviceUnavailable: isRTL ? 'خدمة الإشعارات غير متاحة' : 'Notification service unavailable',
    resetView: isRTL ? 'إعادة ضبط العرض' : 'Reset view',
  });

  // ── Derived state ───────────────────────────────────────────────────────────
  const archivedSet = useMemo(() => new Set(archivedIds), [archivedIds]);

  const summary = useMemo(
    () => getNotificationSummary(notifications, archivedSet),
    [archivedSet, notifications],
  );

  const filteredNotifications = useMemo(
    () =>
      notifications.filter(
        n =>
          matchesNotificationFilter({ notification: n, filter, archivedIds: archivedSet }) &&
          matchesNotificationSearch(n, deferredSearchTerm),
      ),
    [archivedSet, deferredSearchTerm, filter, notifications],
  );

  const sections = useMemo(
    () =>
      buildNotificationSections(filteredNotifications, new Date(), {
        today: labels.today,
        week: labels.week,
        earlier: labels.earlier,
      }),
    [filteredNotifications, labels.earlier, labels.today, labels.week],
  );

  const filters: FilterConfig[] = [
    { value: 'all', label: labels.all },
    { value: 'unread', label: labels.unread },
    { value: 'urgent', label: labels.urgent },
    { value: 'rides', label: labels.rides },
    { value: 'messages', label: labels.messages },
    { value: 'wallet', label: labels.wallet },
    { value: 'trust', label: labels.trust },
    { value: 'support', label: labels.support },
    { value: 'system', label: labels.system },
    { value: 'archived', label: labels.archived },
  ];

  // ── Handlers ────────────────────────────────────────────────────────────────
  const isSafeExternalUrl = (url: string): boolean => {
    try {
      const parsed = new URL(url, window.location.origin);
      if (!['http:', 'https:'].includes(parsed.protocol)) {return false;}
      if (parsed.hostname === window.location.hostname) {return true;}
      return true;
    } catch {
      return false;
    }
  };

  const handleOpenAction = async (notification: Notification) => {
    if (!notification.read) {
      await markAsRead(notification.id).catch(() => undefined);
    }
    if (!notification.action_url) {return;}
    if (notification.action_url.startsWith('/')) {
      await nav(notification.action_url);
      return;
    }
    if (isSafeExternalUrl(notification.action_url)) {
      window.open(notification.action_url, '_blank', 'noopener,noreferrer');
    }
  };

  const itemLabels = {
    view: labels.view,
    markRead: labels.markRead,
    archive: labels.archive,
    urgentBadge: labels.urgentBadge,
    highBadge: labels.highBadge,
    localDraft: labels.localDraft,
  };

  // ── Loading states ──────────────────────────────────────────────────────────
  if (loading && notifications.length === 0) {
    return (
      <WaselStateCard
        eyebrow={labels.loadingEyebrow}
        title={labels.loadingTitle}
        description={labels.loadingDescription}
        icon={Inbox}
        loading
        footer={labels.loadingFooter}
      />
    );
  }

  // ── Render ──────────────────────────────────────────────────────────────────
  return (
    <div className="mx-auto max-w-5xl space-y-5">
      {/* ── Summary card ── */}
      <Card className="overflow-hidden border-white/10 bg-[radial-gradient(circle_at_top_left,rgba(34,211,238,0.14),transparent_32%),linear-gradient(135deg,rgba(4,12,24,0.96),rgba(8,15,28,0.98))] shadow-[0_28px_80px_-48px_rgba(34,211,238,0.6)]">
        <CardHeader className="border-b border-white/8 pb-5">
          <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
            <div className="space-y-3">
              <div className="inline-flex items-center gap-2 rounded-full border border-cyan-400/20 bg-cyan-400/10 px-3 py-1 text-[11px] uppercase tracking-[0.24em] text-cyan-200">
                <Inbox className="size-3.5" />
                {labels.title}
              </div>
              <div>
                <CardTitle className="text-3xl font-semibold tracking-tight text-white">
                  {labels.title}
                </CardTitle>
                <p className="mt-2 max-w-2xl text-sm leading-6 text-slate-300">{labels.subtitle}</p>
              </div>
            </div>

            <div className="flex flex-wrap items-center gap-2">
              <Badge variant="outline" className="gap-1 border-white/15 bg-white/5">
                {connectionStatus === 'online' && <Wifi className="size-3 text-emerald-400" />}
                {connectionStatus === 'offline' && <WifiOff className="size-3 text-rose-400" />}
                {connectionStatus === 'syncing' && (
                  <RefreshCw className="size-3 animate-spin text-cyan-300" />
                )}
                <span className="text-slate-200">
                  {connectionStatus === 'online'
                    ? labels.online
                    : connectionStatus === 'offline'
                      ? labels.offline
                      : labels.syncing}
                </span>
              </Badge>

              <Button
                variant="outline"
                size="sm"
                onClick={() => void refresh()}
                disabled={connectionStatus === 'offline'}
                className="border-white/15 bg-white/5 text-white hover:bg-white/10"
              >
                <RefreshCw
                  className={`size-4 ${connectionStatus === 'syncing' ? 'animate-spin' : ''}`}
                />
                {labels.refresh}
              </Button>

              {unreadCount > 0 && (
                <Button
                  size="sm"
                  onClick={() => void markAllAsRead()}
                  className="bg-cyan-400 text-slate-950 hover:bg-cyan-300"
                >
                  <CheckCheck className="size-4" />
                  {labels.markAllRead}
                </Button>
              )}

              {summary.archived > 0 && (
                <Button
                  variant="outline"
                  size="sm"
                  onClick={() => { void restoreArchivedNotifications(); }}
                  className="border-white/15 bg-white/5 text-white hover:bg-white/10"
                >
                  {labels.restoreArchived}
                </Button>
              )}
            </div>
          </div>
        </CardHeader>

        <CardContent className="grid gap-3 pt-6 md:grid-cols-4">
          <NotificationMetric label={labels.total} value={summary.total} tone="neutral" />
          <NotificationMetric label={labels.unreadCount} value={summary.unread} tone="attention" />
          <NotificationMetric label={labels.urgentCount} value={summary.urgent} tone="urgent" />
          <NotificationMetric
            label={labels.archivedCount}
            value={summary.archived}
            tone="archived"
          />
        </CardContent>
      </Card>

      {/* ── Error banner ── */}
      {errorMessage && (
        <Card className="border-amber-400/25 bg-amber-400/10">
          <CardContent className="flex flex-col gap-3 pt-6 text-sm text-amber-50 md:flex-row md:items-center md:justify-between">
            <div className="flex items-start gap-3">
              <AlertTriangle className="mt-0.5 size-4 shrink-0" />
              <div className="space-y-1">
                <p className="font-semibold">{labels.serviceUnavailable}</p>
                <p className="text-amber-100/90">{errorMessage}</p>
              </div>
            </div>
            <Button
              variant="outline"
              size="sm"
              onClick={() => void refresh()}
              className="border-amber-200/30 bg-transparent text-amber-50 hover:bg-amber-300/10"
            >
              <RefreshCw className="size-4" />
              {labels.refresh}
            </Button>
          </CardContent>
        </Card>
      )}

      {/* ── Search + filters ── */}
      <Card className="border-white/10 bg-card/80 backdrop-blur">
        <CardContent className="space-y-4 pt-6">
          <div className="relative">
            <Search className="pointer-events-none absolute inset-y-0 left-3 my-auto size-4 text-muted-foreground" />
            <Input
              value={searchTerm}
              onChange={event => {
                const nextValue = event.target.value;
                startTransition(() => setSearchTerm(nextValue));
              }}
              placeholder={labels.searchPlaceholder}
              className="h-11 rounded-2xl border-white/10 bg-background/60 pl-10"
            />
          </div>

          <div className="flex flex-wrap gap-2">
            {filters.map(entry => (
              <Button
                key={entry.value}
                variant={filter === entry.value ? 'default' : 'outline'}
                size="sm"
                onClick={() => { void setFilter(entry.value); }}
                className={
                  filter === entry.value
                    ? 'bg-primary text-primary-foreground'
                    : 'border-white/10 bg-background/40'
                }
              >
                {entry.label}
              </Button>
            ))}
          </div>
        </CardContent>
      </Card>

      {/* ── Notification list ── */}
      <div className="space-y-4">
        {sections.length === 0 ? (
          <WaselStateCard
            eyebrow={filter === 'archived' ? labels.archived : labels.title}
            title={labels.noResults}
            description={searchTerm || filter !== 'all' ? labels.emptyFiltered : labels.emptyAll}
            icon={filter === 'archived' ? Trash2 : BellOff}
            minHeight={280}
            actions={
              searchTerm || filter !== 'all' ? (
                <Button
                  variant="outline"
                  onClick={() => {
                    setSearchTerm('');
                    setFilter('all');
                  }}
                  className="border-white/15 bg-white/5 text-white hover:bg-white/10"
                >
                  {labels.resetView}
                </Button>
              ) : (
                <Button
                  variant="outline"
                  onClick={() => void refresh()}
                  className="border-white/15 bg-white/5 text-white hover:bg-white/10"
                >
                  <RefreshCw className="size-4" />
                  {labels.refresh}
                </Button>
              )
            }
          />
        ) : (
          sections.map(section => (
            <div key={section.key} className="space-y-3">
              <div className="px-1 text-xs font-semibold uppercase tracking-[0.22em] text-muted-foreground">
                {section.title}
              </div>

              <ScrollArea className="max-h-[720px]">
                <div className="space-y-3 pr-2">
                  {section.items.map((notification, index) => (
                    <NotificationItem
                      key={notification.id}
                      notification={notification}
                      index={index}
                      isRTL={isRTL}
                      filter={filter}
                      filters={filters}
                      labels={itemLabels}
                      onOpen={n => void handleOpenAction(n)}
                      onMarkRead={id => void markAsRead(id)}
                      onArchive={id => archiveNotification(id)}
                    />
                  ))}
                </div>
              </ScrollArea>
            </div>
          ))
        )}
      </div>
    </div>
  );
}

import {
  ArrowUpRight,
  CircleDollarSign,
  MapPin,
  MoveRight,
  Route as RouteIcon,
  Sparkles,
  Timer,
  TrendingUp,
} from 'lucide-react';
import { Badge } from './ui/badge';
import { Button } from './ui/button';
import { Card, CardContent } from './ui/card';
import { useLanguage } from '../contexts/LanguageContext';
import { useIframeSafeNavigate } from '../hooks/useIframeSafeNavigate';
import {
  getAllCities,
  getPopularRoutes,
  JORDAN_MOBILITY_NETWORK,
  type JordanRoute,
} from '../config/jordan-mobility-network';

interface PopularRoutesProps {
  onGetStarted?: () => void;
}

function formatDuration(minutes: number, isRTL = false) {
  if (minutes < 60) {return isRTL ? `${minutes} د` : `${minutes}m`;}
  const hours = Math.floor(minutes / 60);
  const remainder = minutes % 60;
  if (isRTL) {return remainder ? `${hours} س ${remainder} د` : `${hours} س`;}
  return remainder ? `${hours}h ${remainder}m` : `${hours}h`;
}

function demandLabel(route: JordanRoute, isRTL: boolean) {
  if (route.popularity === 'high') {return isRTL ? 'طلب مرتفع' : 'High demand';}
  if (route.popularity === 'medium') {return isRTL ? 'طلب متوازن' : 'Balanced demand';}
  return isRTL ? 'طلب ناشئ' : 'Emerging demand';
}

function categoryLabel(route: JordanRoute, isRTL: boolean) {
  if (route.category === 'intercity') {return isRTL ? 'بين المدن' : 'Intercity';}
  if (route.category === 'regional') {return isRTL ? 'إقليمي' : 'Regional';}
  return isRTL ? 'محلي' : 'Local';
}

export function PopularRoutes({ onGetStarted }: PopularRoutesProps) {
  const { language, t } = useLanguage();
  const navigate = useIframeSafeNavigate();
  const isRTL = language === 'ar';
  const popularRoutes = getPopularRoutes();
  const connectedCities = getAllCities().length;
  const publishedCorridors = JORDAN_MOBILITY_NETWORK.length;
  const intercityCount = JORDAN_MOBILITY_NETWORK.filter(
    route => route.category === 'intercity',
  ).length;
  const handleGetStarted = onGetStarted ?? (() => navigate('/app/find-ride'));

  const openRoute = (route: JordanRoute) =>
    navigate(
      `/app/find-ride?from=${encodeURIComponent(route.origin)}&to=${encodeURIComponent(route.destination)}&search=1`,
    );

  const openSupply = (route?: JordanRoute) => {
    if (!route) {
      navigate('/app/offer-ride');
      return;
    }

    navigate(
      `/app/offer-ride?from=${encodeURIComponent(route.origin)}&to=${encodeURIComponent(route.destination)}`,
    );
  };

  return (
    <section className="py-20 bg-muted">
      <div className="max-w-7xl mx-auto px-6">
        <div className="text-center mb-12">
          <div className="flex items-center justify-center gap-2 mb-4">
            <TrendingUp className="w-8 h-8 text-primary" />
            <Badge className="bg-primary/10 text-primary border-primary/20">
              {isRTL ? 'أعلى المسارات طلباً' : 'Highest-demand corridors'}
            </Badge>
          </div>
          <h2 className="mb-4">
            {isRTL ? 'المسارات الأعلى طلباً عبر الأردن' : "Jordan's highest-demand corridors"}
          </h2>
          <p className="text-xl text-muted-foreground max-w-3xl mx-auto">
            {isRTL
              ? 'هذه الصفحة مبنية على مخطط شبكة واصل الأردنية الفعلي. افتح أي ممر لرؤية السعر الأساسي، زمن الرحلة، ونوع الحركة على هذا الخط.'
              : "This page is grounded in Wasel's actual Jordan mobility network. Open any corridor to see the base fare, trip duration, and the type of movement that lane supports."}
          </p>
        </div>

        <div className="grid md:grid-cols-4 gap-6 mb-12">
          <Card className="border-primary/10">
            <CardContent className="p-6 text-center">
              <div className="text-3xl text-primary mb-2">{connectedCities}</div>
              <p className="text-sm text-muted-foreground">
                {isRTL ? 'مدن متصلة' : 'Connected cities'}
              </p>
            </CardContent>
          </Card>
          <Card className="border-primary/10">
            <CardContent className="p-6 text-center">
              <div className="text-3xl text-primary mb-2">{publishedCorridors}</div>
              <p className="text-sm text-muted-foreground">
                {isRTL ? 'ممرات منشورة' : 'Published corridors'}
              </p>
            </CardContent>
          </Card>
          <Card className="border-primary/10">
            <CardContent className="p-6 text-center">
              <div className="text-3xl text-primary mb-2">{popularRoutes.length}</div>
              <p className="text-sm text-muted-foreground">
                {isRTL ? 'مسارات بطلب مرتفع' : 'High-demand lanes'}
              </p>
            </CardContent>
          </Card>
          <Card className="border-primary/10">
            <CardContent className="p-6 text-center">
              <div className="text-3xl text-primary mb-2">{intercityCount}</div>
              <p className="text-sm text-muted-foreground">
                {isRTL ? 'خطوط بين المدن' : 'Intercity corridors'}
              </p>
            </CardContent>
          </Card>
        </div>

        <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6 mb-8">
          {popularRoutes.map(route => (
            <Card
              key={route.id}
              className="group relative overflow-hidden border-border transition-all duration-300 hover:border-primary/30 hover:shadow-xl"
            >
              <div className="absolute top-0 left-0 bg-gradient-to-r from-accent to-accent/90 px-4 py-1 text-xs text-accent-foreground rounded-br-lg">
                {categoryLabel(route, isRTL)}
              </div>

              <div className="absolute top-0 right-0 rounded-bl-lg bg-gradient-to-l from-primary to-primary/90 px-4 py-1 text-xs text-primary-foreground">
                {demandLabel(route, isRTL)}
              </div>

              <CardContent className="p-6">
                <div className="mb-4 flex items-center justify-between gap-2 pt-4">
                  <Badge className="border-primary/20 bg-primary/10 text-primary">
                    <Sparkles className="mr-1 w-3 h-3" />
                    {isRTL ? 'من شبكة واصل' : 'From the Wasel network'}
                  </Badge>
                </div>

                <button
                  type="button"
                  onClick={() => void openRoute(route)}
                  className="w-full text-left"
                  style={{
                    background: 'transparent',
                    border: 'none',
                    padding: 0,
                    cursor: 'pointer',
                  }}
                >
                  <div className="mb-4">
                    <div className="mb-2 flex items-center justify-between">
                      <div className="min-w-0 flex-1">
                        <h3 className="text-foreground transition-colors group-hover:text-primary">
                          {isRTL ? route.originAr : route.origin}
                        </h3>
                        <p className="text-sm text-muted-foreground">
                          {isRTL ? 'مدينة الانطلاق' : route.originAr}
                        </p>
                      </div>
                      <MoveRight className="mx-3 h-6 w-6 flex-shrink-0 text-primary transition-transform group-hover:translate-x-1" />
                      <div className="min-w-0 flex-1 text-right">
                        <h3 className="text-foreground transition-colors group-hover:text-primary">
                          {isRTL ? route.destinationAr : route.destination}
                        </h3>
                        <p className="text-sm text-muted-foreground">
                          {isRTL ? 'الوجهة' : route.destinationAr}
                        </p>
                      </div>
                    </div>
                  </div>

                  <div className="mb-4 space-y-3">
                    <div className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-2 text-muted-foreground">
                        <CircleDollarSign className="h-4 w-4 text-primary" />
                        <span>{isRTL ? 'السعر الأساسي' : 'Base shared fare'}</span>
                      </div>
                      <span className="text-lg text-primary">{route.baseFare.toFixed(1)} JOD</span>
                    </div>

                    <div className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-2 text-muted-foreground">
                        <Timer className="h-4 w-4 text-primary" />
                        <span>{isRTL ? 'المدة المعتادة' : 'Typical duration'}</span>
                      </div>
                      <span className="text-foreground">{formatDuration(route.duration, isRTL)}</span>
                    </div>

                    <div className="flex items-center justify-between text-sm">
                      <div className="flex items-center gap-2 text-muted-foreground">
                        <MapPin className="h-4 w-4 text-primary" />
                        <span>{isRTL ? 'المسافة' : 'Distance'}</span>
                      </div>
                      <Badge variant="secondary" className="bg-primary/10 text-primary">
                        {route.distance} {t('popularRoutes.km')}
                      </Badge>
                    </div>
                  </div>
                </button>

                <div className="border-t border-border pt-3">
                  <p className="text-center text-xs text-muted-foreground">
                    {isRTL
