import { useState, useEffect, useRef, useCallback } from 'react';
import { Send, Loader2 } from 'lucide-react';
import { chatService, type Message } from '@/services/chat';
import { Button } from '@/components/ui/button';
import { Card } from '@/components/ui/card';
import { Avatar } from '@/components/ui/avatar';
import { useAuth } from '@/contexts/AuthContext';
import { tx } from '../locales/tx';

interface TripChatProps {
  tripId: string;
  onClose?: () => void;
}

export function TripChat({ tripId, onClose }: TripChatProps) {
  const { user } = useAuth();
  const [messages, setMessages] = useState<Message[]>([]);
  const [newMessage, setNewMessage] = useState('');
  const [loading, setLoading] = useState(true);
  const [sending, setSending] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLInputElement>(null);

   const loadMessages = useCallback(async () => {
      try {
        const data = await chatService.getMessages(tripId);
        setMessages(data);

        const unreadIds = data
          .filter(m => m.sender_id !== user?.id && !m.read_by.includes(user?.id || ''))
          .map(m => m.id);

        if (unreadIds.length > 0) {
          await chatService.markAsRead(unreadIds);
        }
      } catch (error) {
        console.error('Failed to load messages:', error);
      } finally {
        setLoading(false);
      }
    }, [tripId, user?.id]);

   const scrollToBottom = () => {
      messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    };

   useEffect(() => {
      void loadMessages();
      const unsubscribe = chatService.subscribeToTrip(tripId, message => {
        setMessages(prev => [...prev, message]);
        if (message.sender_id !== user?.id) {
          chatService.markAsRead([message.id]);
        }
      });

      return () => {
        unsubscribe();
      };
    }, [loadMessages, tripId, user?.id]);

   useEffect(() => {
     scrollToBottom();
   }, [messages]);

  const handleSend = async () => {
    if (!newMessage.trim() || sending) {return;}

    setSending(true);
    try {
      await chatService.sendMessage({
        tripId,
        content: newMessage.trim(),
      });
      setNewMessage('');
      inputRef.current?.focus();
    } catch (error) {
      console.error('Failed to send message:', error);
    } finally {
      setSending(false);
    }
  };

  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };

  if (loading) {
    return (
      <Card className="flex items-center justify-center h-96">
        <Loader2 className="animate-spin" size={32} />
      </Card>
    );
  }

  return (
    <Card className="flex flex-col h-[600px] max-h-[80vh]">
      <div className="flex items-center justify-between p-4 border-b">
        <h3 className="font-semibold">{tx('tripChat.trip_chat')}</h3>
        {onClose && (
          <button onClick={() => { void onClose(); }} className="text-gray-500 hover:text-gray-700">
            ✕
          </button>
        )}
      </div>

      <div className="flex-1 overflow-y-auto p-4 space-y-4">
        {messages.length === 0 ? (
          <div className="text-center text-gray-500 py-8">
            {tx('tripChat.no_messages_yet_start_the_conversation')}
          </div>
        ) : (
          messages.map(message => {
            const isOwn = message.sender_id === user?.id;
            return (
              <div key={message.id} className={`flex gap-3 ${isOwn ? 'flex-row-reverse' : ''}`}>
                <Avatar className="w-8 h-8 flex-shrink-0">
                  {message.sender?.avatar_url ? (
                    <img src={message.sender.avatar_url} alt={message.sender.full_name} />
                  ) : (
                    <div className="w-full h-full bg-blue-500 flex items-center justify-center text-white text-sm">
                      {message.sender?.full_name?.[0] || '?'}
                    </div>
                  )}
                </Avatar>
                <div className={`flex-1 ${isOwn ? 'text-right' : ''}`}>
                  <div
                    className={`inline-block px-4 py-2 rounded-lg max-w-[70%] ${
                      isOwn ? 'bg-blue-500 text-white' : 'bg-gray-100 text-gray-900'
                    }`}
                  >
                    {message.content}
                  </div>
                  <div className="text-xs text-gray-500 mt-1">
                    {new Date(message.created_at).toLocaleTimeString([], {
                      hour: '2-digit',
                      minute: '2-digit',
                    })}
                  </div>
                </div>
              </div>
            );
          })
        )}
        <div ref={messagesEndRef} />
      </div>

      <div className="p-4 border-t">
        <div className="flex gap-2">
          <input
            ref={inputRef}
            type="text"
            value={newMessage}
            onChange={e => setNewMessage(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder={tx('messages.typeMessage')}
            className="flex-1 px-4 py-2 border rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
            disabled={sending}
          />
          <Button onClick={() => { void handleSend(); }} disabled={!newMessage.trim() || sending} className="px-4">
            {sending ? <Loader2 className="animate-spin" size={20} /> : <Send size={20} />}
          </Button>
        </div>
      </div>
    </Card>
  );
}

import { useMemo, useState, useEffect } from 'react';
import { Car, Clock, Package } from 'lucide-react';
import { getRideBookings } from '../services/rideLifecycle';
import { getConnectedPackages } from '../services/journeyLogistics';
import { C, F, R, TYPE } from '../utils/wasel-ds';
import { tx } from '../locales/tx';

type ActiveItem = {
  kind: 'ride' | 'package';
  id: string;
  title: string;
  subtitle: string;
  eta: string;
  timeLeftMinutes: number;
  status: string;
  statusColor: string;
  icon: typeof Car;
  path: string;
};

export function ActiveTripsBanner({ onNavigate }: { onNavigate: (path: string) => void }) {
  const [now, setNow] = useState(() => Date.now());
  const rideBookings = useMemo(() => getRideBookings(), []);
  const packages = useMemo(() => getConnectedPackages(), []);

  useEffect(() => {
    const id = setInterval(() => setNow(Date.now()), 30000);
    return () => clearInterval(id);
  }, []);

  const activeItems: ActiveItem[] = useMemo(() => {
    const items: ActiveItem[] = [];

    rideBookings.forEach(b => {
      if (b.status === 'pending_driver' || b.status === 'confirmed') {
        items.push({
          kind: 'ride',
          id: b.id,
          title: `${b.from} → ${b.to}`,
          subtitle: `Seats: ${b.seatsRequested}`,
          eta: b.time,
          timeLeftMinutes: b.time
            ? Math.max(1, Math.round((new Date(b.time).getTime() - now) / 60000))
            : 0,
          status: b.status,
          statusColor: b.status === 'confirmed' ? C.green : C.gold,
          icon: Car,
          path: `/app/live-trip?id=${b.id}`,
        });
      }
    });

    packages.forEach(p => {
      if (p.status === 'searching' || p.status === 'matched' || p.status === 'in_transit') {
        items.push({
          kind: 'package',
          id: p.id,
          title: `Package: ${p.trackingId}`,
          subtitle: `${p.from} → ${p.to}`,
          eta: p.createdAt
            ? new Date(p.createdAt).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
            : '--',
          timeLeftMinutes: 15,
          status: p.status,
          statusColor:
            p.status === 'in_transit' ? C.cyan : p.status === 'matched' ? C.green : C.gold,
          icon: Package,
          path: '/app/packages',
        });
      }
    });

    return items;
  }, [rideBookings, packages]);

  if (activeItems.length === 0) {return null;}

  return (
    <div
      style={{
        display: 'grid',
        gap: 12,
        margin: '24px 0',
      }}
    >
      {activeItems.map(item => (
        <button
          key={item.id}
          onClick={() => { void onNavigate(item.path); }}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: 14,
            padding: '16px 20px',
            borderRadius: R.md,
            background: C.elevated,
            border: `1px solid ${C.borderHov}`,
            boxShadow: `0 10px 24px ${item.statusColor}10`,
            cursor: 'pointer',
            textAlign: 'left',
            transition: 'all 0.2s ease',
          }}
        >
          <div
            style={{
              width: 48,
              height: 48,
              borderRadius: 16,
              background: `${item.statusColor}14`,
              border: `1px solid ${item.statusColor}26`,
              display: 'grid',
              placeItems: 'center',
              color: item.statusColor,
              flexShrink: 0,
            }}
          >
            <item.icon size={22} />
          </div>

          <div style={{ flex: 1, minWidth: 0 }}>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                justifyContent: 'space-between',
                gap: 8,
              }}
            >
              <span
                style={{
                  fontWeight: TYPE.weight.ultra,
                  color: C.text,
                  fontFamily: F,
                  fontSize: TYPE.size.base,
                  overflow: 'hidden',
                  textOverflow: 'ellipsis',
                  whiteSpace: 'nowrap',
                }}
              >
                {item.title}
              </span>
              <span
                style={{
                  padding: '3px 10px',
                  borderRadius: 99,
                  background: `${item.statusColor}14`,
                  border: `1px solid ${item.statusColor}30`,
                  color: item.statusColor,
                  fontSize: TYPE.size.xs,
                  fontWeight: TYPE.weight.bold,
                  whiteSpace: 'nowrap',
                }}
              >
                {item.status}
              </span>
            </div>
            <div
              style={{
                color: C.textMuted,
                fontSize: TYPE.size.sm,
                marginTop: 2,
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {item.subtitle}
            </div>
            <div
              style={{
                color: C.textDim,
                fontSize: TYPE.size.xs,
                marginTop: 6,
                display: 'flex',
                gap: 12,
                alignItems: 'center',
              }}
            >
              <span style={{ display: 'flex', alignItems: 'center', gap: 4 }}>
                <Clock size={10} />
                {tx('tripProgressCard.eta')}
                {item.eta}
              </span>
              {item.timeLeftMinutes > 0 && (
                <span style={{ fontWeight: TYPE.weight.bold, color: C.textMuted }}>
                  {item.timeLeftMinutes}
                  {tx('tripProgressCard.m_left')}
                </span>
              )}
            </div>
          </div>

          <div
            style={{
              width: 8,
              height: 8,
              borderRadius: '50%',
              background: item.statusColor,
              boxShadow: `0 0 8px ${item.statusColor}`,
              animation: 'pulse 2s infinite',
              flexShrink: 0,
            }}
          />
        </button>
      ))}
    </div>
  );
}

/**
 * WaselMap — Interactive map for Wasel | واصل
 *
 * ✅ Leaflet + OpenStreetMap/CartoDB (NO API key required)
 * ✅ Dark theme via CartoDB Dark Matter tiles
 * ✅ Live GPS tracking with animated pulse ring
 * ✅ Mosque markers via Overpass API (free, no key) + pre-defined fallback
 * ✅ Speed camera / radar markers across Jordan highways
 * ✅ Route drawing with OSRM free routing + Polyline fallback
 * ✅ Map type switcher: Standard / Satellite / Terrain
 * ✅ Fullscreen mode
 * ✅ Custom zoom controls
 * ✅ Live speed / accuracy HUD
 * ✅ POI info panels (mosque details, radar alerts)
