import { useState, useEffect, useLayoutEffect, useCallback } from 'react';
import { Download, X } from 'lucide-react';
import { C, R, SH, SPACE, TYPE } from '../../utils/wasel-ds';
import { WaselButton } from '../wasel-ui/WaselButton';
import { tx } from '../../locales/tx';

type InstallPromptState = 'idle' | 'available' | 'dismissed' | 'installed';

interface BeforeInstallPromptEvent extends Event {
  prompt(): Promise<void>;
  userChoice: Promise<{ outcome: 'accepted' | 'dismissed' }>;
}

export function PWAInstallPrompt() {
  const [state, setState] = useState<InstallPromptState>('idle');
  const [deferredPrompt, setDeferredPrompt] = useState<BeforeInstallPromptEvent | null>(null);
  const [isStandalone, setIsStandalone] = useState(false);

  useLayoutEffect(() => {
    if (typeof window === 'undefined') {return;}

    const isStandaloneMode =
      window.matchMedia('(display-mode: standalone)').matches ||
      (window.navigator as Navigator & { standalone?: boolean }).standalone === true;

    setIsStandalone(isStandaloneMode);
    if (isStandaloneMode) {
      setState('installed');
    }
  }, []);

  useEffect(() => {
    if (typeof window === 'undefined') {return;}

    const handler = (event: Event) => {
      const promptEvent = event as BeforeInstallPromptEvent;
      event.preventDefault();
      setDeferredPrompt(promptEvent);
      setState('available');
    };

    window.addEventListener('beforeinstallprompt', handler);
    window.addEventListener('appinstalled', () => {
      setState('installed');
      setDeferredPrompt(null);
    });

    return () => {
      window.removeEventListener('beforeinstallprompt', handler);
      window.removeEventListener('appinstalled', () => {});
    };
  }, []);

  const handleInstall = useCallback(async () => {
    if (!deferredPrompt) {return;}

    try {
      await deferredPrompt.prompt();
      const choice = await deferredPrompt.userChoice;

      if (choice.outcome === 'accepted') {
        setState('installed');
      } else {
        setState('dismissed');
      }
    } catch {
      setState('dismissed');
    } finally {
      setDeferredPrompt(null);
    }
  }, [deferredPrompt]);

  const handleDismiss = useCallback(() => {
    setState('dismissed');
    setDeferredPrompt(null);

    try {
      sessionStorage.setItem('wasel-pwa-install-dismissed', Date.now().toString());
    } catch {
      // Storage not available
    }
  }, []);

  const wasRecentlyDismissed = (() => {
    try {
      const dismissed = sessionStorage.getItem('wasel-pwa-install-dismissed');
      if (!dismissed) {return false;}
      const dismissedTime = parseInt(dismissed, 10);
      const sevenDays = 7 * 24 * 60 * 60 * 1000;
      const now = Date.now();
      return now - dismissedTime < sevenDays;
    } catch {
      return false;
    }
  })();

  if (state !== 'available' || isStandalone) {
    return null;
  }

  if (wasRecentlyDismissed || state !== 'available') {
    return null;
  }

  return (
    <div
      style={{
        position: 'fixed',
        bottom: SPACE[5],
        left: SPACE[4],
        right: SPACE[4],
        zIndex: 9999,
        display: 'flex',
        flexDirection: 'column',
        gap: SPACE[2],
      }}
    >
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: SPACE[3],
          padding: SPACE[4],
          borderRadius: R.xxl,
          background: `linear-gradient(180deg, ${C.cardSolid}, ${C.card})`,
          border: `1px solid ${C.border}`,
          boxShadow: `${SH.lg}, 0 0 0 1px ${C.border}40`,
          backdropFilter: 'blur(20px)',
          WebkitBackdropFilter: 'blur(20px)',
        }}
      >
        <div
          style={{
            width: 44,
            height: 44,
            borderRadius: R.xl,
            background: `linear-gradient(135deg, ${C.cyan}30, ${C.green}30)`,
            border: `1px solid ${C.border}`,
            display: 'grid',
            placeItems: 'center',
            flexShrink: 0,
          }}
        >
          <Download size={22} color={C.cyan} />
        </div>

        <div style={{ flex: 1, minWidth: 0 }}>
          <div
            style={{
              color: C.text,
              fontWeight: TYPE.weight.bold,
              fontSize: TYPE.size.base,
              lineHeight: 1.3,
            }}
          >
            {tx('pWAInstallPrompt.install_wasel')}
          </div>
          <div
            style={{
              color: C.textMuted,
              fontSize: TYPE.size.sm,
              lineHeight: 1.4,
              marginTop: 2,
            }}
          >
            {tx('pWAInstallPrompt.add_to_home_screen_for_faster_access_and_offline_use')}
          </div>
        </div>

        <div style={{ display: 'flex', gap: 8, flexShrink: 0 }}>
          <WaselButton
            variant="ghost"
            size="sm"
            onClick={handleDismiss}
            aria-label={tx('pWAInstallPrompt.dismiss_install_prompt')}
            style={{
              minWidth: 36,
              minHeight: 36,
              padding: 6,
              borderRadius: R.full,
              color: C.textMuted,
            }}
          >
            <X size={18} />
          </WaselButton>
          <WaselButton
            size="sm"
            onClick={() => handleInstall()}
            aria-label={tx('pWAInstallPrompt.install_wasel_app')}
            style={{
              minHeight: 36,
              padding: '8px 16px',
              borderRadius: R.full,
              background: `linear-gradient(135deg, ${C.cyan}, ${C.green})`,
              color: C.bg,
              fontWeight: TYPE.weight.bold,
              fontSize: TYPE.size.sm,
            }}
          >
            {tx('pWAInstallPrompt.install')}
          </WaselButton>
        </div>
      </div>
    </div>
  );
}

/**
 * NotificationItem.tsx
 *
 * Single notification card row with icon, content, priority badges,
 * timestamp, and action buttons.
 *
 * Extracted from the 39 KB NotificationCenter monolith so it can be:
 *   - Tested independently
 *   - Reused in other views (e.g. a drawer or push notification overlay)
 *   - Lazy-loaded without pulling in the full center
 */
import React from 'react';
import { motion } from 'framer-motion';
import { Check, Trash2 } from 'lucide-react';
import type { Notification } from '../../hooks/useNotifications';
import {
  getNotificationCategory,
  type NotificationCategory,
  type NotificationFilter,
} from '../../features/notifications/notificationCenterModel';
import { WaselBadge, WaselButton, WaselCard } from '../wasel-ui';
import { C, R, SH, SPACE, TYPE } from '../../utils/wasel-ds';
import { CATEGORY_ICON, formatRelativeTimestamp } from './notificationHelpers';

type FilterConfig = { value: NotificationFilter; label: string };

type NotificationItemProps = {
  notification: Notification;
  index: number;
  isRTL: boolean;
  filter: NotificationFilter;
  filters: FilterConfig[];
  labels: {
    view: string;
    markRead: string;
    archive: string;
    urgentBadge: string;
    highBadge: string;
    localDraft: string;
  };
  onOpen: (n: Notification) => void;
  onMarkRead: (id: string) => void;
  onArchive: (id: string) => void;
};

const categoryTone: Record<
  NotificationCategory,
  { background: string; border: string; icon: string; badge: string }
> = {
  rides: {
    background: `linear-gradient(135deg, ${C.cyanDim}, ${C.elevated})`,
    border: C.cyanDim,
    icon: C.cyan,
    badge: C.cyanDim,
  },
  messages: {
    background: `linear-gradient(135deg, ${C.blueDim}, ${C.elevated})`,
    border: C.blueDim,
    icon: C.blueLight,
    badge: C.blueDim,
  },
  wallet: {
    background: `linear-gradient(135deg, ${C.goldDim}, ${C.elevated})`,
    border: C.goldDim,
    icon: C.gold,
    badge: C.goldDim,
  },
  trust: {
    background: `linear-gradient(135deg, ${C.greenDim}, ${C.elevated})`,
    border: C.greenDim,
    icon: C.green,
    badge: C.greenDim,
  },
  support: {
    background: `linear-gradient(135deg, ${C.errorDim}, ${C.elevated})`,
    border: C.errorDim,
    icon: C.error,
    badge: C.errorDim,
  },
  system: {
    background: `linear-gradient(135deg, ${C.cardSolid}, ${C.elevated})`,
    border: C.border,
    icon: C.textSub,
    badge: C.elevated,
  },
};

export const NotificationItem = React.memo(({
  notification,
  index,
  isRTL,
  filter,
  filters,
  labels,
  onOpen,
  onMarkRead,
  onArchive,
}: NotificationItemProps) => {
  const category = getNotificationCategory(notification);
  const Icon = CATEGORY_ICON[category];
  const tone = categoryTone[category];

  return (
    <motion.div
      initial={{ opacity: 0, y: 8 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ delay: index * 0.03, duration: 0.18 }}
    >
      <WaselCard
        variant="solid"
        padding="0"
        radius={R.xxl}
        hover
        style={{ overflow: 'hidden', background: tone.background, borderColor: tone.border }}
      >
        <div
          style={{
            display: 'grid',
            gap: SPACE[4],
            padding: SPACE[5],
            gridTemplateColumns: 'auto minmax(0, 1fr) auto',
          }}
        >
          {/* Icon */}
          <div style={{ display: 'flex', alignItems: 'flex-start' }}>
            <div
              style={{
                borderRadius: R.xl,
                border: `1px solid ${C.borderFaint}`,
                background: C.overlay,
                padding: SPACE[3],
                boxShadow: SH.sm,
              }}
            >
              <Icon size={20} color={tone.icon} />
            </div>
          </div>

          {/* Body */}
          <div style={{ display: 'grid', gap: SPACE[3], minWidth: 0 }}>
            <div
              style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'flex-start', gap: SPACE[2] }}
            >
              <div style={{ display: 'grid', gap: SPACE[1], minWidth: 0 }}>
                <div
                  style={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: SPACE[2] }}
                >
                  <h3
                    style={{
                      margin: 0,
                      fontSize: TYPE.size.base,
                      fontWeight: TYPE.weight.bold,
                      color: C.text,
                    }}
                  >
                    {notification.title}
                  </h3>

                  {!notification.read && (
                    <span
                      aria-hidden="true"
                      style={{
                        width: 8,
                        height: 8,
                        borderRadius: R.full,
                        background: C.cyan,
                        boxShadow: SH.blue,
                        flexShrink: 0,
                      }}
                    />
                  )}

                  {notification.priority === 'urgent' && (
                    <WaselBadge variant="hot" label={labels.urgentBadge} />
                  )}

                  {notification.priority === 'high' && (
                    <WaselBadge variant="new" label={labels.highBadge} />
                  )}

                  {notification.source === 'local' && (
                    <WaselBadge variant="custom" label={labels.localDraft} />
                  )}
                </div>

                <p
                  style={{
                    margin: 0,
                    maxWidth: 760,
                    fontSize: TYPE.size.sm,
                    lineHeight: 1.65,
                    color: C.textSub,
                  }}
                >
                  {notification.message}
                </p>
              </div>
            </div>

            {/* Meta row */}
            <div
              style={{
                display: 'flex',
                flexWrap: 'wrap',
                alignItems: 'center',
                gap: SPACE[2],
                fontSize: TYPE.size.xs,
                color: C.textMuted,
              }}
            >
              <WaselBadge
                variant="custom"
                label={filters.find(f => f.value === category)?.label ?? category}
                style={{ background: tone.badge, color: tone.icon, borderColor: tone.border }}
              />
              <span>{formatRelativeTimestamp(notification.created_at, isRTL)}</span>
            </div>
          </div>

          {/* Actions */}
          <div
            style={{
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'flex-start',
              justifyContent: 'flex-end',
              gap: SPACE[2],
            }}
          >
            {notification.action_url && (
              <WaselButton size="sm" onClick={() => { void onOpen(notification); }}>
                {labels.view}
              </WaselButton>
            )}

            {!notification.read && (
              <WaselButton
                variant="outline"
                size="sm"
                icon={<Check size={16} />}
                onClick={() => { void onMarkRead(notification.id); }}
              >
                {labels.markRead}
              </WaselButton>
            )}

            {filter !== 'archived' && (
              <WaselButton
                variant="ghost"
                size="sm"
                icon={<Trash2 size={16} />}
                onClick={() => { void onArchive(notification.id); }}
              >
                {labels.archive}
              </WaselButton>
            )}
          </div>
        </div>
      </WaselCard>
    </motion.div>
  );
});

