  description?: string;
  error?: string;
  hint?: ReactNode;
  icon?: ReactNode;
  trailing?: ReactNode;
  dir?: 'ltr' | 'rtl';
  onChange?: (value: string) => void;
}

function PasswordToggle({ showPassword, onToggle }: { showPassword: boolean; onToggle: () => void }) {
  return (
    <button
      type="button"
      onClick={() => { void onToggle(); }}
      aria-label={showPassword ? 'Hide password' : 'Show password'}
      style={{
        background: 'none',
        border: 'none',
        cursor: 'pointer',
        color: C.textMuted,
        display: 'inline-flex',
        padding: 0,
        flexShrink: 0,
      }}
    >
      {showPassword ? <EyeOff size={16} /> : <Eye size={16} />}
    </button>
  );
}

export function WaselInput({
  label,
  description,
  error,
  hint,
  icon,
  trailing,
  type = 'text',
  dir = 'ltr',
  onChange,
  id,
  style,
  ...rest
}: WaselInputProps) {
  const [focused, setFocused] = useState(false);
  const [showPassword, setShowPassword] = useState(false);
  const isPassword = type === 'password';
  const resolvedType = isPassword && showPassword ? 'text' : type;
  const hasError = Boolean(error);

  const borderColor = hasError ? C.error : focused ? C.borderHov : C.border;
  const boxShadow = hasError
    ? `0 0 0 3px ${C.errorDim}`
    : focused
      ? `0 0 0 3px ${C.cyanDim}`
      : 'none';

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: '6px' }}>
      {(label || description) && (
        <div
          style={{
            display: 'flex',
            justifyContent: 'space-between',
            alignItems: 'baseline',
            gap: '8px',
          }}
        >
          {label && (
            <label
              htmlFor={id}
              style={{
                fontSize: TYPE.size.sm,
                fontWeight: TYPE.weight.bold,
                color: C.textSub,
                fontFamily: F,
                lineHeight: 1.4,
              }}
            >
              {label}
            </label>
          )}
          {description && (
            <span style={{ fontSize: TYPE.size.xs, color: C.textMuted, fontFamily: F }}>
              {description}
            </span>
          )}
        </div>
      )}

      <div
        dir={dir}
        style={{
          display: 'flex',
          alignItems: 'center',
          gap: '10px',
          padding: '0 14px',
          minHeight: '50px',
          borderRadius: R.lg,
          background: focused ? C.card2 : C.cardSolid,
          border: `1.5px solid ${borderColor}`,
          boxShadow,
          transition: `border-color ${ANIM.dur.normal} ${ANIM.ease.default}, box-shadow ${ANIM.dur.normal} ${ANIM.ease.default}, background ${ANIM.dur.normal} ${ANIM.ease.default}`,
        }}
      >
        {icon && (
          <span
            style={{ flexShrink: 0, color: C.textMuted, display: 'inline-flex', fontSize: '16px' }}
          >
            {icon}
          </span>
        )}

        <input
          {...rest}
          id={id}
          type={resolvedType}
          onChange={e => onChange?.(e.target.value)}
          onFocus={e => {
            setFocused(true);
            rest.onFocus?.(e);
          }}
          onBlur={e => {
            setFocused(false);
            rest.onBlur?.(e);
          }}
          style={{
            flex: 1,
            border: 'none',
            outline: 'none',
            background: 'transparent',
            fontSize: TYPE.size.base,
            fontFamily: F,
            color: C.text,
            textAlign: dir === 'rtl' ? 'right' : 'left',
            minWidth: 0,
            ...style,
          }}
        />

        {isPassword && (
          <PasswordToggle showPassword={showPassword} onToggle={() => setShowPassword(v => !v)} />
        )}

        {trailing && !isPassword && (
          <span style={{ flexShrink: 0, display: 'inline-flex' }}>{trailing}</span>
        )}
      </div>

      {error && (
        <span style={{ fontSize: TYPE.size.xs, color: C.error, fontFamily: F, lineHeight: 1.5 }}>
          {sanitizeHtml(error)}
        </span>
      )}

      {hint && !error && hint}
    </div>
  );
}

import type {
  AuthChangeEvent,
  AuthError,
  Session,
  User,
} from '@supabase/auth-js';
import type { SupabaseClient } from '@supabase/supabase-js';
import { authAPI } from '../services/auth';
import { getAuthCallbackUrl, resolveAuthRedirectOrigin } from '../utils/env';
import { deriveAccountTrustScore } from '../domain/trust/score';

export type Profile = {
  id: string;
  email?: string | null;
  full_name?: string | null;
  phone_number?: string | null;
  phone_verified?: boolean | null;
  email_verified?: boolean | null;
  role?: string | null;
  wallet_balance?: number | null;
  rating?: number | null;
  rating_as_driver?: number | null;
  trip_count?: number | null;
  verified?: boolean | null;
  sanad_verified?: boolean | null;
  verification_level?: string | null;
  wallet_status?: string | null;
  avatar_url?: string | null;
  two_factor_enabled?: boolean | null;
  driver_status?: string | null;
};

export type AuthOperationError = AuthError | Error | null;

export interface WaselUser {
  id: string;
  name: string;
  email: string;
  phone?: string;
  role: 'rider' | 'driver' | 'both' | 'admin';
  balance: number;
  rating: number;
  trips: number;
  verified: boolean;
  sanadVerified: boolean;
  verificationLevel: string;
  walletStatus: 'active' | 'limited' | 'frozen' | 'closed' | 'unavailable';
  avatar?: string;
  joinedAt: string;
  emailVerified: boolean;
  phoneVerified: boolean;
  twoFactorEnabled: boolean;
  trustScore: number;
  driverStatus?: string;
  backendMode: 'supabase';
}

export function createLocalAuthUser(localUser: WaselUser): User {
  return {
    id: localUser.id,
    email: localUser.email,
    phone: localUser.phone,
    user_metadata: {
      name: localUser.name,
      role: localUser.role,
    },
  } as unknown as User;
}

export function createLocalAuthProfile(localUser: WaselUser): Profile {
  return {
    id: localUser.id,
    email: localUser.email,
    full_name: localUser.name,
    phone_number: localUser.phone ?? null,
    wallet_balance: localUser.balance,
    rating: localUser.rating,
    trip_count: localUser.trips,
    verified: localUser.verified,
    sanad_verified: localUser.sanadVerified,
    verification_level: localUser.verificationLevel,
    wallet_status: localUser.walletStatus,
    avatar_url: localUser.avatar ?? null,
    phone_verified: localUser.phoneVerified,
    email_verified: localUser.emailVerified,
    two_factor_enabled: localUser.twoFactorEnabled,
  };
}

export function shouldIgnoreProfileError(error: Error): boolean {
  return error.message?.includes('aborted') || error.message?.includes('not found');
}

export async function loadProfile(): Promise<Profile | null> {
  const profileData = await authAPI.getProfile();
  return (profileData?.profile as Profile | null) || null;
}

export function normalizeOperationError(error: unknown, fallback: string): Error {
  return error instanceof Error ? error : new Error(fallback);
}

export async function signInWithOAuthProvider(
  client: SupabaseClient | null,
  provider: 'google' | 'facebook' | 'microsoft' | 'apple',
  returnTo?: string,
): Promise<{ error: AuthOperationError }> {
  if (!client) {
    return { error: new Error('Backend not configured') };
  }

  try {
    const redirectTo = getAuthCallbackUrl(
      resolveAuthRedirectOrigin(),
      returnTo ? { returnTo } : undefined,
    );

    const scopes =
      provider === 'facebook'
        ? 'email,public_profile'
        : provider === 'microsoft'
          ? 'openid profile email'
          : provider === 'apple'
            ? 'name email'
            : 'openid profile email';

    const { error } = await client.auth.signInWithOAuth({
      provider: provider as any,
      options: {
        redirectTo,
        scopes,
        // Supabase recommends PKCE for OAuth when supported; it's a no-op for
        // providers that don't support it (Apple, older Facebook clients).
        queryParams:
          provider === 'facebook'
            ? { display: 'popup' }
            : undefined,
      },
    });

    return { error: error ?? null };
  } catch (error: unknown) {
    const providerName = provider.charAt(0).toUpperCase() + provider.slice(1);
    return {
      error: normalizeOperationError(
        error,
        `${providerName} login failed`,
      ),
    };
  }
}

export function shouldRefreshProfile(event: AuthChangeEvent, session: Session | null): boolean {
  return Boolean(session?.user) && event === 'SIGNED_IN';
}

function computeTrustScore(
  user: Pick<
    WaselUser,
    'verified' | 'sanadVerified' | 'emailVerified' | 'phoneVerified' | 'trips' | 'rating'
  >,
) {
  return deriveAccountTrustScore(user);
}

function resolveUserName(
  profile: Profile | null,
  authUser: Pick<User, 'user_metadata' | 'email'> | null,
): string {
  return (
    profile?.full_name ||
    authUser?.user_metadata?.full_name ||
    authUser?.user_metadata?.name ||
    authUser?.email?.split('@')?.[0] ||
    'Wasel User'
  );
}

function resolveUserRole(profileRole: string | null | undefined): WaselUser['role'] {
  if (profileRole === 'driver' || profileRole === 'both') {return profileRole;}
  if (profileRole === 'admin') {return 'admin';}
  return 'rider';
}

function resolveVerificationLevel(
  profile: Profile | null,
  role: WaselUser['role'],
  sanadVerified: boolean,
  phoneVerified: boolean,
  emailVerified: boolean,
): string {
  if (profile?.verification_level) {return profile.verification_level;}
  if (sanadVerified) {
    return role === 'driver' || role === 'both' ? 'level_3' : 'level_2';
  }
  if (phoneVerified || emailVerified) {return 'level_1';}
  return 'level_0';
}

function resolveWalletStatus(
  profileStatus: string | null | undefined,
): WaselUser['walletStatus'] {
  if (
    profileStatus === 'limited' ||
    profileStatus === 'frozen' ||
    profileStatus === 'closed' ||
    profileStatus === 'unavailable'
  ) {
    return profileStatus;
  }
  return 'active';
}

export function mapBackendProfile({
  authUser,
  profile,
}: {
  authUser: Pick<
    User,
    | 'id'
    | 'email'
    | 'phone'
    | 'created_at'
    | 'email_confirmed_at'
    | 'phone_confirmed_at'
    | 'user_metadata'
  >;
  profile: Profile | null;
}): WaselUser {
  const name = resolveUserName(profile, authUser);
  const phone = profile?.phone_number ?? authUser?.phone ?? undefined;
  const verified = Boolean(profile?.verified ?? profile?.sanad_verified ?? false);
  const sanadVerified = Boolean(profile?.sanad_verified ?? verified);
  const emailVerified = Boolean(profile?.email_verified ?? authUser?.email_confirmed_at ?? false);
  const phoneVerified = Boolean(profile?.phone_verified ?? authUser?.phone_confirmed_at ?? false);
  const role = resolveUserRole(profile?.role);
  const verificationLevel = resolveVerificationLevel(profile, role, sanadVerified, phoneVerified, emailVerified);
  const walletStatus = resolveWalletStatus(profile?.wallet_status);

  const baseUser: WaselUser = {
    id: authUser?.id || `user-${Date.now()}`,
    name,
    email: authUser?.email || profile?.email || '',
    phone,
    role,
    balance: Number(profile?.wallet_balance ?? 0),
    rating: Number(profile?.rating ?? 5),
    trips: Number(profile?.trip_count ?? 0),
    verified,
    sanadVerified,
    verificationLevel,
    walletStatus,
    avatar: profile?.avatar_url ?? authUser?.user_metadata?.avatar_url ?? authUser?.user_metadata?.picture ?? undefined,
    joinedAt: String(authUser?.created_at ?? new Date().toISOString()).slice(0, 10),
    emailVerified,
    phoneVerified,
    twoFactorEnabled: Boolean(profile?.two_factor_enabled),
    trustScore: 0,
    driverStatus: profile?.driver_status ?? undefined,
    backendMode: 'supabase',
  };

  return {
    ...baseUser,
    trustScore: computeTrustScore(baseUser),
  };
}

export function applyUserUpdates(user: WaselUser, updates: Partial<WaselUser>): WaselUser {
  const next = { ...user, ...updates };
  next.trustScore = computeTrustScore({
    verified: next.verified,
    sanadVerified: next.sanadVerified,
    emailVerified: next.emailVerified,
    phoneVerified: next.phoneVerified,
    trips: next.trips,
    rating: next.rating,
  });

  next.verificationLevel =
    next.verificationLevel ||
    (next.sanadVerified
      ? next.role === 'driver' || next.role === 'both'
        ? 'level_3'
        : 'level_2'
      : next.phoneVerified || next.emailVerified
        ? 'level_1'
        : 'level_0');

  return next;
}

﻿import { createContext, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import type { AuthChangeEvent, Session, User } from '@supabase/auth-js';
import { getAuthCallbackUrl, resolveAuthRedirectOrigin } from '../../utils/env';
import { sanitizeLogMessage } from '../../utils/sanitization';
import { parseOAuthError } from '../../utils/oauthErrors';
import { sessionManager } from '../../utils/sessionManager';
import {
  normalizeOperationError,
  signInWithOAuthProvider,
  type AuthOperationError,
  type Profile,
  type WaselUser,
  mapBackendProfile,
  applyUserUpdates,
} from '../authContextHelpers';
import { getSupabaseClient, loadProfileFromBackend } from './auth-service';
import { getProfileDisplayName, splitFullName } from './helpers';

export type SignUpResult = {
  error: AuthOperationError;
  requiresEmailConfirmation?: boolean;
  user?: User | null;
};

export interface AuthContextType {
  user: User | null;
  profile: Profile | null;
  session: Session | null;
  loading: boolean;
  isBackendConnected: boolean;
  waselUser: WaselUser | null;
  signUp: (options: {
    password: string,
    fullName: string,
    phone?: string,
    returnTo?: string,
  ) => Promise<SignUpResult>;
  signIn: (email: string, password: string) => Promise<{ error: AuthOperationError }>;
  signInWithGoogle: (returnTo?: string) => Promise<{ error: AuthOperationError }>;
  signInWithFacebook: (returnTo?: string) => Promise<{ error: AuthOperationError }>;
  signInWithMicrosoft: (returnTo?: string) => Promise<{ error: AuthOperationError }>;
  signInWithApple: (returnTo?: string) => Promise<{ error: AuthOperationError }>;
  signOut: () => Promise<void>;
  updateProfile: (updates: Partial<Profile>) => Promise<{ error: AuthOperationError }>;
  updateUser: (updates: Partial<WaselUser>) => Promise<void>;
  refreshProfile: () => Promise<void>;
  resetPassword: (email: string, returnTo?: string) => Promise<{ error: AuthOperationError }>;
  changePassword: (nextPassword: string) => Promise<{ error: AuthOperationError }>;
}

export const AuthContext = createContext<AuthContextType>({
  user: null,
  profile: null,
  session: null,
  loading: true,
  isBackendConnected: false,
  waselUser: null,
  signUp: async () => ({ error: null }),
  signIn: async () => ({ error: null }),
  signInWithGoogle: async () => ({ error: null }),
  signInWithFacebook: async () => ({ error: null }),
  signInWithMicrosoft: async () => ({ error: null }),
  signInWithApple: async () => ({ error: null }),
  signOut: async () => { },
  updateProfile: async () => ({ error: null }),
  updateUser: async () => { },
  refreshProfile: async () => { },
  resetPassword: async () => ({ error: null }),
  changePassword: async () => ({ error: null }),
});

interface AuthProviderProps {
  children: React.ReactNode;
}

export function AuthProvider({ children }: AuthProviderProps) {
  const [user, setUser] = useState<User | null>(null);
  const [profile, setProfile] = useState<Profile | null>(null);
  const [session, setSession] = useState<Session | null>(null);
  const [initializing, setInitializing] = useState(true);
  const [busy, setBusy] = useState(false);
  const [isBackendConnected, setIsBackendConnected] = useState(false);
  const [waselUser, setWaselUser] = useState<WaselUser | null>(null);
  const optimisticRef = useRef<Partial<WaselUser> | null>(null);

  const fetchProfile = useCallback(async (forceCreate = false, authUser?: User | null) => {
    if (!authUser || !getSupabaseClient()) {
      setProfile(null);
      return null;
    }
    const activeUser = authUser;

    let nextProfile = await loadProfileFromBackend();

    if (!nextProfile && forceCreate) {
      const { firstName, lastName } = getProfileDisplayName(activeUser);

      try {
        const { authAPI } = await import('../../services/auth');
        await authAPI.createProfile(activeUser.id, activeUser.email ?? '', firstName, lastName);
        nextProfile = await loadProfileFromBackend();
      } catch (error) {
        if (import.meta.env?.DEV) {
          console.warn('[Auth] Profile bootstrap skipped:', sanitizeLogMessage(String(error)));
        }
      }
    }

    setProfile(nextProfile);
    return nextProfile;
  }, []);

  useEffect(() => {
    let mounted = true;
    let unsubscribe: (() => void) | undefined;
    let removeAuthMessageListener: (() => void) | undefined;

    const initializeAuth = async () => {
      try {
        const client = getSupabaseClient();
        if (!mounted) {return;}

        if (!client) {
          setUser(null);
          setProfile(null);
          setSession(null);
          setInitializing(false);
          setIsBackendConnected(false);
          return;
        }

        const syncFromSession = (event: string, nextSession: Session | null) => {
          if (!mounted) {return;}

          setSession(nextSession);
          setUser(nextSession?.user ?? null);
          setIsBackendConnected(true);

          if (!nextSession?.user) {
            setProfile(null);
            setInitializing(false);
            sessionManager.endSession();
            return;
          }

          if (event === 'SIGNED_IN' || event === 'INITIAL_SESSION') {
            sessionManager.startSession(nextSession.user.id);
          }

          const shouldEnsureProfile =
            event === 'INITIAL_SESSION' || event === 'SIGNED_IN' || event === 'USER_UPDATED';
          const shouldRefreshProfile =
            event === 'INITIAL_SESSION' ||
            event === 'SIGNED_IN' ||
            event === 'USER_UPDATED' ||
            event === 'TOKEN_REFRESHED';

          if (!shouldRefreshProfile) {
            setInitializing(false);
            return;
          }

          void fetchProfile(shouldEnsureProfile, nextSession.user)
            .catch(error => {
              if (import.meta.env?.DEV) {
                console.warn('[Auth] Profile refresh warning:', sanitizeLogMessage(String(error)));
              }
            })
            .finally(() => {
              if (mounted) {setInitializing(false);}
            });
        };

        const {
          data: { subscription },
        } = client.auth.onAuthStateChange((event: AuthChangeEvent, nextSession: Session | null) => {
          syncFromSession(event, nextSession);
        });
        unsubscribe = () => subscription.unsubscribe();

        const handleAuthMessage = async (event: MessageEvent) => {
          if (event.origin !== window.location.origin) {return;}
          if (!event.data || typeof event.data !== 'object') {return;}
          if (event.data.type !== 'wasel-auth-complete') {return;}

          try {
            const { data, error } = await client.auth.getSession();
            if (error) {throw error;}
            if (!mounted || !data.session) {return;}

            setSession(data.session);
            setUser(data.session.user);
            await fetchProfile(true, data.session.user);
          } catch (error) {
            if (import.meta.env?.DEV) {
              console.warn('Auth callback sync warning:', sanitizeLogMessage(String(error)));
            }
          } finally {
            if (mounted) {setInitializing(false);}
          }
        };

        window.addEventListener('message', handleAuthMessage);
        removeAuthMessageListener = () => window.removeEventListener('message', handleAuthMessage);
      } catch (error) {
        if (import.meta.env?.DEV) {
          console.warn('[Auth] Session initialization skipped:', sanitizeLogMessage(String(error)));
        }
        if (mounted) {
          setIsBackendConnected(false);
          setInitializing(false);
        }
      }
    };

    void initializeAuth();

    return () => {
      mounted = false;
      removeAuthMessageListener?.();
      unsubscribe?.();
    };
  }, [fetchProfile]);

  useEffect(() => {
    if (!user) {
      setWaselUser(null);
      return;
    }

    const mapped = mapBackendProfile({
      authUser: user,
      profile,
    });

    const pending = optimisticRef.current;
    optimisticRef.current = null;
    const nextUser = pending ? applyUserUpdates(mapped, pending) : mapped;
    setWaselUser(nextUser);
  }, [user, profile]);

  const signUp = useCallback(
    async (
      email: string,
      password: string,
      fullName: string,
      phone?: string,
      returnTo?: string,
    ): Promise<SignUpResult> => {
      if (!getSupabaseClient()) {
        return { error: new Error('Backend not configured') };
      }

      const { firstName, lastName } = splitFullName(fullName);

      setBusy(true);
      try {
        const { authAPI } = await import('../../services/auth');
        const data = await authAPI.signUp({
          email,
          password,
          firstName,
          lastName,
          phone: phone ?? '',
          returnTo,
        });
        const authUser = data.user ?? data.session?.user ?? null;

        if (authUser && data.session) {
          setSession(data.session);
          setUser(authUser);
          await fetchProfile(true, authUser);
        }

        return {
          error: null,
          requiresEmailConfirmation: !data.session,
          user: authUser,
        };
      } catch (error: unknown) {
        return { error: normalizeOperationError(error, 'Signup failed') };
      } finally {
        setBusy(false);
      }
    },
    [fetchProfile],
  );

  const signIn = useCallback(
    async (email: string, password: string): Promise<{ error: AuthOperationError }> => {
      setBusy(true);
      try {
        const { authAPI } = await import('../../services/auth');
        const data = await authAPI.signIn(email, password);
        const authUser = data.user ?? data.session?.user ?? null;

        if (authUser && data.session) {
          setSession(data.session);
          setUser(authUser);
          await fetchProfile(true, authUser);
        }

        return { error: null };
      } catch (error: unknown) {
        return { error: normalizeOperationError(error, 'Login failed') };
      } finally {
        setBusy(false);
      }
    },
    [fetchProfile],
  );

  const createOAuthSignIn = useCallback(
    (provider: 'google' | 'facebook' | 'microsoft' | 'apple') =>
      async (returnTo?: string): Promise<{ error: AuthOperationError }> => {
        const client = await getSupabaseClient();
        if (!client) {
          return { error: new Error('Backend not configured') };
        }

        setBusy(true);
        try {
          const result = await signInWithOAuthProvider(client, provider, returnTo);

          if (result.error) {
            const oauthError = parseOAuthError(result.error, provider as unknown);
            if (oauthError && import.meta.env?.DEV) {
              console.error(`[OAuth ${provider}]`, sanitizeLogMessage(oauthError));
            }
            const errorToReturn = oauthError
              ? new Error(oauthError.userMessage)
              : result.error;
            return { error: errorToReturn as AuthOperationError };
          }

          // Supabase JS will navigate away via window.location on success, but
          // if for any reason the navigation doesn't fire we still want the
          // button to look interactive again. Reset busy on next tick.
          queueMicrotask(() => setBusy(false));
          return result;
        } catch (error: unknown) {
          const providerName = provider.charAt(0).toUpperCase() + provider.slice(1);
          return { error: normalizeOperationError(error, `${providerName} sign-in failed`) };
        } finally {
          // If the redirect happened, this is a no-op; if it didn't, this
          // re-enables the UI.
          setBusy(false);
        }
      },
    [],
  );

  const signInWithGoogle = useMemo(() => createOAuthSignIn('google'), [createOAuthSignIn]);
  const signInWithFacebook = useMemo(() => createOAuthSignIn('facebook'), [createOAuthSignIn]);
  const signInWithMicrosoft = useMemo(() => createOAuthSignIn('microsoft'), [createOAuthSignIn]);
  const signInWithApple = useMemo(() => createOAuthSignIn('apple'), [createOAuthSignIn]);

  const signOut = useCallback(async () => {
    setBusy(true);
    try {
      const { authAPI } = await import('../../services/auth');
      await authAPI.signOut();
      setUser(null);
      setProfile(null);
      setSession(null);
      sessionManager.endSession();
    } catch (error) {
      if (import.meta.env?.DEV) {
        console.error('Sign out error:', sanitizeLogMessage(String(error)));
      }
    } finally {
      setBusy(false);
    }
  }, []);

  const updateProfile = useCallback(
    async (updates: Partial<Profile>): Promise<{ error: AuthOperationError }> => {
      if (!user) {
        return { error: new Error('No user logged in') };
      }

      setBusy(true);
      try {
        const { authAPI } = await import('../../services/auth');
        const result = await authAPI.updateProfile(updates);
        if (result.success) {
          setProfile(prev => (prev ? { ...prev, ...updates } : prev));
          fetchProfile(false, user).catch(() => { });
          return { error: null };
        }

        return {
          error: new Error(
            typeof result.error === 'string' ? result.error : 'Failed to update profile',
          ),
        };
      } catch (error: unknown) {
        return { error: normalizeOperationError(error, 'Update failed') };
      } finally {
        setBusy(false);
      }
    },
    [fetchProfile, user],
  );

  const refreshProfile = useCallback(async () => {
    if (!user) {return;}
    await fetchProfile({ authUser: user });
  }, [fetchProfile, user]);

  const updateUser = useCallback(
    async (updates: Partial<WaselUser>) => {
      if (!user) {return;}

      const profileUpdates: Partial<Profile> = {};
      if (updates.name !== undefined) {profileUpdates.full_name = updates.name;}
      if (updates.phone !== undefined) {profileUpdates.phone_number = updates.phone;}
      if (updates.balance !== undefined) {profileUpdates.wallet_balance = updates.balance;}
      if (updates.rating !== undefined) {profileUpdates.rating = updates.rating;}
      if (updates.trips !== undefined) {profileUpdates.trip_count = updates.trips;}
      if (updates.verified !== undefined) {profileUpdates.verified = updates.verified;}
      if (updates.sanadVerified !== undefined) {profileUpdates.sanad_verified = updates.sanadVerified;}
      if (updates.verificationLevel !== undefined) {profileUpdates.verification_level = updates.verificationLevel;}
      if (updates.walletStatus !== undefined) {profileUpdates.wallet_status = updates.walletStatus;}
      if (updates.avatar !== undefined) {profileUpdates.avatar_url = updates.avatar;}
      if (updates.emailVerified !== undefined) {profileUpdates.email_verified = updates.emailVerified;}
      if (updates.phoneVerified !== undefined) {profileUpdates.phone_verified = updates.phoneVerified;}
      if (updates.twoFactorEnabled !== undefined) {profileUpdates.two_factor_enabled = updates.twoFactorEnabled;}
      if (updates.driverStatus !== undefined) {profileUpdates.driver_status = updates.driverStatus;}

      optimisticRef.current = { ...(optimisticRef.current ?? {}), ...updates };
      setWaselUser(prev => (prev ? applyUserUpdates(prev, updates) : prev));

      const result = await updateProfile(profileUpdates);
      if (result.error) {
        optimisticRef.current = null;
        setWaselUser(prev => (prev && user ? mapBackendProfile({ authUser: user, profile: profile }) : prev));
      }
    },
    [user, profile, updateProfile],
  );

  const resetPassword = useCallback(
    async (email: string, returnTo?: string): Promise<{ error: AuthOperationError }> => {
      const client = getSupabaseClient();
      if (!client) {return { error: new Error('Backend not configured') };}

      try {
        const { error } = await client.auth.resetPasswordForEmail(email, {
          redirectTo: getAuthCallbackUrl(
            resolveAuthRedirectOrigin(),
            returnTo ? { returnTo } : undefined,
          ),
        });
        return { error: error ?? null };
      } catch (error: unknown) {
        return { error: normalizeOperationError(error, 'Password reset failed') };
      }
    },
    [],
  );

  const changePassword = useCallback(
    async (nextPassword: string): Promise<{ error: AuthOperationError }> => {
      const client = getSupabaseClient();
      if (!client) {return { error: new Error('Backend not configured') };}

      setBusy(true);
      try {
        const { error } = await client.auth.updateUser({ password: nextPassword });
        return { error: error ?? null };
      } catch (error: unknown) {
        return { error: normalizeOperationError(error, 'Password update failed') };
      } finally {
        setBusy(false);
      }
    },
    [],
  );

  const value = useMemo(
    () => ({
      user,
      profile,
      session,
      loading: initializing || busy,
      isBackendConnected,
      waselUser,
      signUp,
      signIn,
      signInWithGoogle,
      signInWithFacebook,
      signInWithMicrosoft,
      signInWithApple,
      signOut,
      updateProfile,
      updateUser,
      refreshProfile,
      resetPassword,
      changePassword,
    }),
    [
      busy,
      changePassword,
      initializing,
      isBackendConnected,
      profile,
      refreshProfile,
      resetPassword,
      session,
      signIn,
      signInWithApple,
      signInWithFacebook,
      signInWithGoogle,
      signInWithMicrosoft,
      signOut,
      signUp,
      updateProfile,
      updateUser,
      user,
      waselUser,
    ],
  );

  return <AuthContext.Provider value={value}>{children}</AuthContext.Provider>;
}

import { deriveAccountTrustScore } from '../trust/score';

export type WaselUserRole = 'passenger' | 'driver' | 'both' | 'admin';
export type WaselVerificationLevel = 'level_0' | 'level_1' | 'level_2' | 'level_3';
export type WaselWalletStatus = 'active' | 'limited' | 'frozen' | 'closed';
export type WaselBackendMode = 'supabase' | 'demo';

export interface WaselUserProfile {
  id: string;
  name: string;
  email: string;
  role: WaselUserRole;
  verified: boolean;
  rating: number;
  trips: number;
  balance: number;
  phone?: string;
  avatar?: string;
  joinedAt?: string;
  phoneVerified: boolean;
  emailVerified: boolean;
  sanadVerified: boolean;
  verificationLevel: WaselVerificationLevel;
  trustScore: number;
  walletStatus: WaselWalletStatus;
  backendMode: WaselBackendMode;
}

type DemoProfileInput = {
  id: string;
  name: string;
  email: string;
  role?: WaselUserRole;
  verified?: boolean;
  rating?: number;
  trips?: number;
  balance?: number;
  phone?: string;
  avatar?: string;
  joinedAt?: string;
};

type PartialProfileSource = Partial<{
  full_name: string;
  fullName: string;
  name: string;
  phone: string;
  phone_number: string;
  role: string;
  verified: boolean;
  email_verified: boolean;
  phone_verified: boolean;
  sanad_verified: boolean;
  verification_level: string;
  rating: number;
  trips: number;
  trip_count: number;
  wallet_balance: number;
  balance: number;
  wallet_status: string;
  created_at: string;
  joined_at: string;
  avatar_url: string;
  two_factor_enabled: boolean;
}>;

function toRole(value: unknown): WaselUserRole {
  if (value === 'driver' || value === 'admin' || value === 'both') {return value;}
  return 'passenger';
}

export function deriveVerificationLevel(input: {
  phoneVerified?: boolean;
  role?: WaselUserRole;
  verified?: boolean;
}): WaselVerificationLevel {
  if (input.role === 'driver' || input.role === 'both') {return 'level_3';}
  if (input.verified) {return 'level_2';}
  if (input.phoneVerified) {return 'level_1';}
  return 'level_0';
}

export function deriveTrustScore(input: {
  verificationLevel: WaselVerificationLevel;
  rating?: number;
  trips?: number;
}): number {
  return deriveAccountTrustScore({
    phoneVerified: input.verificationLevel !== 'level_0',
    emailVerified: input.verificationLevel === 'level_2' || input.verificationLevel === 'level_3',
    rating: input.rating,
    trips: input.trips,
  });
}

export function createDemoUserProfile(input: DemoProfileInput): WaselUserProfile {
  const role = input.role ?? 'passenger';
  const phoneVerified = Boolean(input.phone);
  const emailVerified = Boolean(input.email);
  const verified = Boolean(input.verified);
  const verificationLevel = deriveVerificationLevel({ phoneVerified, role, verified });
  const rating = input.rating ?? 4.8;
  const trips = input.trips ?? 0;

  return {
    id: input.id,
    name: input.name,
    email: input.email,
    role,
    verified,
    rating,
    trips,
    balance: input.balance ?? 0,
    phone: input.phone,
    avatar: input.avatar,
    joinedAt: input.joinedAt ?? new Date().toISOString().slice(0, 10),
    phoneVerified,
    emailVerified,
    sanadVerified: false,
    verificationLevel,
    trustScore: deriveTrustScore({ verificationLevel, rating, trips }),
    walletStatus: 'active',
    backendMode: 'demo',
  };
}

export function mapBackendProfile(args: {
  authUser: {
    id: string;
    email?: string;
    phone?: string;
    created_at?: string;
    user_metadata?: Record<string, unknown>;
    app_metadata?: Record<string, unknown>;
    email_confirmed_at?: string | null;
    phone_confirmed_at?: string | null;
  };
  profile?: PartialProfileSource | null;
}): WaselUserProfile {
  const { authUser, profile } = args;
  const metadata = authUser.user_metadata ?? {};
  const role = toRole(profile?.role ?? metadata.role);
  const phone = profile?.phone_number ?? profile?.phone ?? authUser.phone ?? undefined;
  const rating = typeof profile?.rating === 'number' ? profile.rating : 4.7;
  const trips = resolveTripCount(profile);
  const verified = Boolean(profile?.verified);
  const phoneVerified = Boolean(profile?.phone_verified ?? authUser.phone_confirmed_at ?? false);
  const emailVerified = Boolean(profile?.email_verified ?? authUser.email_confirmed_at ?? false);
  const verificationLevel = resolveVerificationLevel(profile, phoneVerified, role, verified);

  return {
    id: authUser.id,
    name: resolveName(profile, metadata, authUser),
    email: authUser.email ?? '',
    role,
    verified: verified || verificationLevel === 'level_2' || verificationLevel === 'level_3',
    rating,
    trips,
    balance: resolveBalance(profile),
    phone,
    avatar: typeof profile?.avatar_url === 'string' ? profile.avatar_url : undefined,
    joinedAt: profile?.created_at ?? profile?.joined_at ?? authUser.created_at?.slice(0, 10),
    phoneVerified,
    emailVerified,
    sanadVerified: false,
    verificationLevel,
    trustScore: deriveTrustScore({ verificationLevel, rating, trips }),
    walletStatus: resolveWalletStatus(profile),
    backendMode: 'supabase',
  };
}

function resolveTripCount(profile?: PartialProfileSource | null): number {
  if (typeof profile?.trip_count === 'number') {return profile.trip_count;}
  if (typeof profile?.trips === 'number') {return profile.trips;}
  return 0;
}

function resolveVerificationLevel(
  profile: PartialProfileSource | null | undefined,
  phoneVerified: boolean,
  role: WaselUserRole,
  verified: boolean,
): WaselVerificationLevel {
  const raw = profile?.verification_level;
  if (raw === 'level_0' || raw === 'level_1' || raw === 'level_2' || raw === 'level_3') {
    return raw;
  }
  return deriveVerificationLevel({ phoneVerified, role, verified });
}

function resolveName(
  profile: PartialProfileSource | null | undefined,
  metadata: Record<string, unknown>,
  authUser: { email?: string },
): string {
  return String(
    profile?.full_name ??
      profile?.fullName ??
      profile?.name ??
      metadata.full_name ??
      metadata.name ??
      authUser.email?.split('@')[0] ??
      'Wasel User',
  );
}

function resolveBalance(profile?: PartialProfileSource | null): number {
  if (typeof profile?.wallet_balance === 'number') {return profile.wallet_balance;}
  if (typeof profile?.balance === 'number') {return profile.balance;}
  return 0;
}

function resolveWalletStatus(profile?: PartialProfileSource | null): WaselWalletStatus {
  const status = profile?.wallet_status;
  if (status === 'limited' || status === 'frozen' || status === 'closed') {return status;}
  return 'active';
}

import { useEffect, useMemo, useState } from 'react';
import { ArrowRight, Bus, Car, Calendar, Package } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';
import { useLocalAuth } from '../../contexts/LocalAuth';
import { useIframeSafeNavigate } from '../../hooks/useIframeSafeNavigate';
import { getStoredBusBookings, type StoredBusBooking } from '../../services/bus';
import { getConnectedPackages, type PackageRequest } from '../../services/journeyLogistics';
import { getRideBookings, type RideBookingRecord } from '../../services/rideLifecycle';
import { supabase } from '../../utils/supabase/client';
import { C, F, R, TYPE } from '../../utils/wasel-ds';
import { PageShell, SectionCard, StatusBadge } from '../../components/wasel-ui/WaselPagePrimitives';

type ItemKind = 'ride' | 'package' | 'bus' | 'scheduled';

type TimelineItem = {
  id: string;
  kind: ItemKind;
  title: string;
  subtitle: string;
  date: string;
  time: string;
  amount?: number;
  status: string;
  statusColor: string;
  Icon: typeof Car;
  path: string;
};

type ScheduledPickupRow = {
  id: string;
  item_type: 'ride' | 'package_delivery' | 'package_return';
  status: string;
  pickup_location: string;
  dropoff_location?: string;
  scheduled_at: string;
  estimated_price?: number;
};

const STATUS_LABEL: Record<string, { en: string; ar: string }> = {
  pending_driver: { en: 'Pending driver', ar: 'بانتظار السائق' },
  pending: { en: 'Pending', ar: 'قيد الانتظار' },
  confirmed: { en: 'Confirmed', ar: 'مؤكد' },
  completed: { en: 'Completed', ar: 'مكتمل' },
  cancelled: { en: 'Cancelled', ar: 'ملغي' },
  rejected: { en: 'Rejected', ar: 'مرفوض' },
  delivered: { en: 'Delivered', ar: 'تم التوصيل' },
  in_transit: { en: 'In transit', ar: 'في الطريق' },
  scheduled: { en: 'Scheduled', ar: 'مجدول' },
  missed: { en: 'Missed', ar: 'فائت' },
};

const EMPTY_CTA: Record<ItemKind, { en: string; ar: string; path: string }> = {
  ride: { en: 'Book your first ride', ar: 'احجز رحلتك الأولى', path: '/app/find-ride' },
  package: { en: 'Send a package', ar: 'أرسل طرداً', path: '/app/packages' },
  bus: { en: 'Browse bus routes', ar: 'تصفح خطوط الباص', path: '/app/bus' },
  scheduled: { en: 'Schedule a pickup', ar: 'جدول استلاماً', path: '/app/schedule' },
};

function groupByDate(items: TimelineItem[]): { label: string; items: TimelineItem[] }[] {
  const now = new Date();
  const todayStr = now.toISOString().split('T')[0] ?? '';
  const weekAgo = new Date(now);
  weekAgo.setDate(weekAgo.getDate() - 7);
  const weekAgoStr = weekAgo.toISOString().split('T')[0] ?? '';

  const groups: { today: TimelineItem[]; week: TimelineItem[]; earlier: TimelineItem[] } = {
    today: [],
    week: [],
    earlier: [],
  };
  for (const item of items) {
    if (item.date === todayStr) {groups.today.push(item);}
    else if (item.date >= weekAgoStr) {groups.week.push(item);}
    else {groups.earlier.push(item);}
  }

  return [
    { label: 'Today', items: groups.today },
    { label: 'This week', items: groups.week },
    { label: 'Earlier', items: groups.earlier },
  ].filter(g => g.items.length > 0);
}

export function ActivityPage() {
  const { user } = useLocalAuth();
  const { language, t } = useLanguage();
  const nav = useIframeSafeNavigate();
  const ar = language === 'ar';
  const [filter, setFilter] = useState<'all' | ItemKind>('all');
  const [scheduledItems, setScheduledItems] = useState<ScheduledPickupRow[]>([]);

  const rides = useMemo(() => getRideBookings(), []);
  const packages = useMemo(() => getConnectedPackages(), []);
  const buses = useMemo(() => getStoredBusBookings(), []);

  useEffect(() => {
    let cancelled = false;
    async function loadScheduled() {
      if (!supabase || !user?.id) {return;}
      const { data } = await supabase
        .from('scheduled_pickups')
        .select('id,item_type,status,pickup_location,dropoff_location,scheduled_at,estimated_price')
        .eq('user_id', user.id)
        .order('scheduled_at', { ascending: false });
      if (!cancelled && data) {setScheduledItems(data as ScheduledPickupRow[]);}
    }
    void loadScheduled();
    return () => {
      cancelled = true;
    };
  }, [user?.id]);

  const items: TimelineItem[] = useMemo(() => {
    const mapped: TimelineItem[] = [];

    rides.forEach((b: RideBookingRecord) => {
      const isActive = b.status === 'confirmed' || b.status === 'pending_driver';
      mapped.push({
        id: b.id,
        kind: 'ride',
        title: b.from ? `${b.from} → ${b.to}` : t('activity.rideTitle'),
        subtitle: t('activity.seatsLabel') + ': ' + b.seatsRequested,
        date: b.date,
        time: b.time,
        status: b.status,
        statusColor:
          b.status === 'completed'
            ? C.green
            : b.status === 'cancelled' || b.status === 'rejected'
              ? C.error
