    });

    buses.forEach((b: StoredBusBooking) => {
      mapped.push({
        id: b.id,
        kind: 'bus',
        title: t('activity.busTitle'),
        subtitle: `${b.pickupStop} → ${b.dropoffStop}`,
        date: b.scheduleDate,
        time: b.departureTime,
        amount: Number(b.totalPrice ?? 0),
        status: b.status,
        statusColor:
