                        size={16}
                        color={C.textMuted}
                        style={{ flexShrink: 0, transform: ar ? 'rotate(180deg)' : 'none' }}
                      />
                    </button>
                  );
                })}
              </div>
            ))}
          </div>
        )}
      </SectionCard>
    </PageShell>
  );
}

