            <div>
              <label
                style={{ display: 'block', color: DS.sub, fontSize: '0.76rem', marginBottom: 8 }}
              >
                {tx('common.from')}
              </label>
              <select
                value={origin}
                onChange={event => {
                  setOrigin(event.target.value);
                  setBookingComplete(false);
                  setBookingSource(null);
                }}
                style={{
                  width: '100%',
                  height: 46,
                  borderRadius: r(14),
                  border: `1px solid ${DS.border}`,
                  background: DS.card2,
                  color: C.text,
                  padding: '0 14px',
                  fontFamily: DS.F,
                }}
              >
                {CITIES.map(city => (
                  <option key={city} value={city}>
                    {cityLabel(city, ar)}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label
                style={{ display: 'block', color: DS.sub, fontSize: '0.76rem', marginBottom: 8 }}
              >
                {tx('common.to')}
              </label>
              <select
                value={destination}
                onChange={event => {
                  setDestination(event.target.value);
                  setBookingComplete(false);
                  setBookingSource(null);
                }}
                style={{
                  width: '100%',
                  height: 46,
                  borderRadius: r(14),
                  border: `1px solid ${DS.border}`,
                  background: DS.card2,
                  color: C.text,
                  padding: '0 14px',
                  fontFamily: DS.F,
                }}
              >
                {CITIES.map(city => (
                  <option key={city} value={city}>
                    {cityLabel(city, ar)}
                  </option>
                ))}
              </select>
            </div>
            <div>
              <label
                style={{ display: 'block', color: DS.sub, fontSize: '0.76rem', marginBottom: 8 }}
              >
                {tx('busPage.travel_date')}
              </label>
              <input
                type="date"
                min={today}
                value={tripDate}
                onChange={event => {
                  setTripDate(event.target.value);
                  setBookingComplete(false);
                }}
                style={{
                  width: '100%',
                  height: 46,
                  borderRadius: r(14),
                  border: `1px solid ${DS.border}`,
                  background: DS.card2,
                  color: C.text,
                  padding: '0 14px',
                  fontFamily: DS.F,
                }}
              />
            </div>
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, marginTop: 14 }}>
            {JOURNEY_PRESETS.map(preset => {
              const active = origin === preset.from && destination === preset.to;
              return (
                <button
                  key={preset.label}
                  type="button"
                  onClick={() => {
                    setOrigin(preset.from);
                    setDestination(preset.to);
                    setBookingComplete(false);
                    setBookingSource(null);
                  }}
                  style={{
                    borderRadius: r(14),
                    border: `1px solid ${active ? DS.green : DS.border}`,
                    background: active ? `${DS.green}12` : DS.card2,
                    padding: '10px 14px',
                    color: C.text,
                    cursor: 'pointer',
                    fontWeight: 800,
                  }}
                >
                  {cityLabel(preset.from, ar)} {ar ? 'إلى' : 'to'} {cityLabel(preset.to, ar)}
                </button>
              );
            })}
          </div>
        </div>

        <div
          className="sp-4col"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(4,1fr)',
            gap: 14,
            marginBottom: 18,
          }}
        >
          {[
            {
              label: local('Routes', 'المسارات'),
              value: `${exactRouteCount}/${busRoutes.length}`,
              detail: local('Exact matches first', 'المطابقات الدقيقة أولاً'),
              icon: <Route size={18} />,
              color: DS.green,
            },
            {
              label: local('Seats', 'المقاعد'),
              value: `${totalOpenSeats}`,
              detail: local('Visible now', 'المتاح الآن'),
              icon: <Users size={18} />,
              color: activeBus.color ?? DS.cyan,
            },
            {
              label: local('Best fare', 'أفضل سعر'),
              value: `${Math.min(...busRoutes.map(route => route.price))} JOD`,
              detail: local('Lowest on screen', 'الأقل في النتائج'),
              icon: <CreditCard size={18} />,
              color: DS.cyan,
            },
            {
              label: local('Operators', 'المشغّلون'),
              value: `${operatorCount}`,
              detail: local('Shown now', 'المعروض الآن'),
              icon: <TimerReset size={18} />,
              color: DS.gold,
            },
          ].map(item => (
            <div
              key={item.label}
              style={{
                background: C.card,
                border: `1px solid ${DS.border}`,
                borderRadius: r(18),
                padding: '18px 18px 16px',
                boxShadow: SH.card,
              }}
            >
              <div
                style={{
                  width: 42,
                  height: 42,
                  borderRadius: r(12),
                  background: `${item.color}16`,
                  border: `1px solid ${item.color}30`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  color: item.color,
                  marginBottom: 14,
                }}
              >
                {item.icon}
              </div>
              <div
                style={{ color: item.color, fontWeight: 900, fontSize: '1.05rem', marginBottom: 4 }}
              >
                {item.value}
              </div>
              <div style={{ color: C.text, fontWeight: 700, fontSize: '0.86rem' }}>
                {item.label}
              </div>
              <div style={{ color: DS.muted, fontSize: '0.74rem', marginTop: 4 }}>
                {item.detail}
              </div>
            </div>
          ))}
        </div>

        {(routesLoading || routesInfo) && (
          <div
            role="status"
            aria-live="polite"
            style={{
              marginBottom: 16,
              background: DS.card2,
              border: `1px solid ${DS.border}`,
              borderRadius: r(14),
              padding: '12px 14px',
              color: DS.sub,
              fontSize: '0.8rem',
            }}
          >
            {routesLoading ? local('Refreshing departures...', 'يتم تحديث مواعيد المغادرة...') : routesInfo}
          </div>
        )}

        <div
          className="sp-2col"
          style={{
            marginBottom: 18,
            display: 'grid',
            gridTemplateColumns: 'minmax(0, 1.15fr) minmax(280px, 0.85fr)',
            gap: 14,
          }}
        >
          <BusRouteList
            routes={busRoutes}
            selectedId={selected}
            onSelect={(id) => { setSelected(id); setBookingComplete(false); setBookingSource(null); }}
            origin={origin}
            destination={destination}
            tripDate={tripDate}
            today={today}
            ar={ar}
            onBookingComplete={() => setBookingComplete(false)}
          />
          <BusBookingForm
            activeBus={activeBus}
            scheduleMode={scheduleMode}
            setScheduleMode={setScheduleMode}
            selectedDeparture={selectedDeparture}
            setSelectedDeparture={setSelectedDeparture}
            departureTimes={departureTimes}
            passengers={passengers}
            setPassengers={setPassengers}
            seatPreference={seatPreference}
            setSeatPreference={setSeatPreference}
            tripDate={tripDate}
            today={today}
            totalPrice={totalPrice}
            bookingDisabled={bookingDisabled}
            bookingBusy={bookingBusy}
            bookingComplete={bookingComplete}
            bookingTicketCode={bookingTicketCode}
            bookingSource={bookingSource}
            handleBusBooking={handleBusBooking}
            openBusSupport={openBusSupport}
            ar={ar}
          />
        </div>

        <BusMap
          activeBus={{
            from: activeBus.from,
            to: activeBus.to,
            pickupPoint: activeBus.pickupPoint,
            dropoffPoint: activeBus.dropoffPoint,
            via: activeBus.via,
            dep: activeBus.dep,
            arr: activeBus.arr,
            duration: activeBus.duration,
            color: activeBus.color,
          }}
          routeCenter={routeCenter}
          pickupCoord={pickupCoord}
          dropoffCoord={dropoffCoord}
        />

        <BusSchedule
          busRoutes={busRoutes}
          origin={origin}
          destination={destination}
          onSelect={(id) => { setSelected(id); setBookingComplete(false); setBookingSource(null); }}
          onBookingComplete={() => setBookingComplete(false)}
        />

        <ServiceFlowPlaybook focusService="bus" />
      </PageShell>
    </Protected>
  );
}

import { useMemo } from 'react';
import { CheckCircle2, ExternalLink } from 'lucide-react';
import type { BusRoute } from '../../../services/bus';
import { C, SH } from '../../../utils/wasel-ds';
import { DS, r } from '../../shared/pageShared';
import { tx } from '../../../locales/tx';

export function BusBookingForm({
  activeBus,
  scheduleMode,
  setScheduleMode,
  selectedDeparture,
  setSelectedDeparture,
  departureTimes,
  passengers,
  setPassengers,
  seatPreference,
  setSeatPreference,
  tripDate,
  today,
  totalPrice,
  bookingDisabled,
  bookingBusy,
  bookingComplete,
  bookingTicketCode,
  bookingSource,
  handleBusBooking,
  openBusSupport,
  ar,
}: {
  activeBus: BusRoute & {
    from: string;
    to: string;
    company: string;
    serviceLevel?: string;
    price: number;
    scheduleDays?: string;
    frequency?: string;
    seats: number;
    color?: string;
    pickupPoint: string;
    dropoffPoint: string;
    dep: string;
    arr: string;
  };
  scheduleMode: 'depart-now' | 'schedule-later';
  setScheduleMode: (mode: 'depart-now' | 'schedule-later') => void;
  selectedDeparture: string;
  setSelectedDeparture: (time: string) => void;
  departureTimes: string[];
  passengers: number;
  setPassengers: (updater: (value: number) => number) => void;
  seatPreference: 'window' | 'aisle' | 'front-zone';
  setSeatPreference: (v: 'window' | 'aisle' | 'front-zone') => void;
  tripDate: string;
  today: string;
  totalPrice: number;
  bookingDisabled: boolean;
  bookingBusy: boolean;
  bookingComplete: boolean;
  bookingTicketCode: string | null;
  bookingSource: 'server' | 'local' | null;
  handleBusBooking: () => void;
  openBusSupport: () => void;
  ar: boolean;
}) {
  const seatOptions = useMemo(() => [
    { value: 'window', label: tx('busPage.window') },
    { value: 'aisle', label: tx('busPage.aisle') },
    { value: 'front-zone', label: tx('busPage.front_zone') },
  ], [ar]);

  return (
    <div
      style={{
        background: DS.card,
        border: `1px solid ${activeBus.color ?? DS.cyan}30`,
        borderRadius: r(22),
        overflow: 'hidden',
        boxShadow: `0 16px 42px ${activeBus.color ?? DS.cyan}10`,
      }}
    >
      <div
        style={{
          padding: '22px 22px 18px',
          background: `linear-gradient(135deg, ${DS.navy}, ${activeBus.color ?? DS.cyan}22)`,
        }}
      >
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 10,
            marginBottom: 10,
          }}
        >
          <div>
            <div style={{ color: C.text, fontWeight: 900, fontSize: '1.15rem' }}>
              {tx('busPage.reserve_your_seat')}
            </div>
            <div style={{ color: DS.sub, fontSize: '0.8rem', marginTop: 4 }}>
              {activeBus.from} {tx('busPage.to_5')}
              {activeBus.to} - {activeBus.company} - {activeBus.serviceLevel ?? 'Standard'}
            </div>
          </div>
        </div>
        <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
          {(['depart-now', 'schedule-later'] as const).map(mode => (
            <button
              key={mode}
              onClick={() => {
                setScheduleMode(mode);
              }}
              type="button"
              style={{
                height: 38,
                padding: '0 14px',
                borderRadius: '99px',
                border: 'none',
                cursor: 'pointer',
                background:
                  scheduleMode === mode
                    ? mode === 'depart-now'
                      ? DS.gradC
                      : DS.gradG
                    : C.elevated,
                color: C.text,
                fontWeight: 700,
              }}
            >
              {mode === 'depart-now' ? local('Depart now', 'غادر الآن') : local('Book later', 'احجز لاحقًا')}
            </button>
          ))}
        </div>
      </div>
      <div style={{ padding: 22, display: 'flex', flexDirection: 'column', gap: 16 }}>
        <div
          style={{
            background: DS.card2,
            border: `1px solid ${DS.border}`,
            borderRadius: r(16),
            padding: '14px 16px',
          }}
        >
          <div
            style={{
              color: DS.muted,
              fontSize: '0.68rem',
              fontWeight: 800,
              letterSpacing: 0,
              textTransform: 'uppercase',
              marginBottom: 6,
            }}
          >
            {tx('busPage.departure_plan_2')}
          </div>
          <div style={{ color: C.text, fontWeight: 800, fontSize: '0.95rem' }}>
            {selectedDeparture}
          </div>
          <div style={{ color: DS.sub, fontSize: '0.78rem', marginTop: 4 }}>
            {tx('busPage.board_at')}
            {activeBus.pickupPoint} {tx('busPage.arrive_at')}
            {activeBus.dropoffPoint}.
          </div>
        </div>
        <div>
          <label
            style={{
              display: 'block',
              color: DS.sub,
              fontSize: '0.76rem',
              marginBottom: 8,
