          >
            {tx(
              'busPage.this_coach_is_full_right_now_switch_routes_and_keep_the_same_corridor_filters',
            )}
          </div>
        )}
        {scheduleMode === 'schedule-later' && (
          <input
            type="date"
            min={today}
            value={tripDate}
            onChange={() => {}}
            style={{
              width: '100%',
              height: 46,
