              border: `1px ${DS.border}`,
              background: DS.card2,
              color: C.text,
              padding: '0 14px',
              fontFamily: DS.F,
            }}
          />
        )}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
          <div>
            <label
              style={{
                display: 'block',
                color: DS.sub,
                fontSize: '0.76rem',
                marginBottom: 8,
              }}
            >
              {tx('trips.passengers')}
            </label>
            <div
              style={{
                display: 'flex',
                alignItems: 'center',
                background: DS.card2,
                border: `1px solid ${DS.border}`,
                borderRadius: r(14),
                overflow: 'hidden',
              }}
            >
              <button
                onClick={() => setPassengers(value => Math.max(1, value - 1))}
                type="button"
                style={{
                  width: 42,
                  height: 46,
                  border: 'none',
                  background: 'transparent',
                  color: C.text,
                  fontSize: '1.1rem',
                  cursor: 'pointer',
                }}
              >
                -
              </button>
              <div style={{ flex: 1, textAlign: 'center', color: C.text, fontWeight: 800 }}>
                {passengers}
              </div>
              <button
                onClick={() => {
                  if (activeBus.seats > 0) {
                    setPassengers(value => Math.min(activeBus.seats, value + 1));
                  }
                }}
                type="button"
                disabled={activeBus.seats === 0 || passengers >= activeBus.seats}
                style={{
                  width: 42,
                  height: 46,
                  border: 'none',
                  background: 'transparent',
                  color: C.text,
