            >
              {seatOptions.map(option => (
                <option key={option.value} value={option.value}>
                  {option.label}
                </option>
              ))}
            </select>
          </div>
        </div>
        <div
          style={{
            background: `linear-gradient(135deg, ${C.cyanDim}, ${C.goldDim})`,
