import { useEffect, useMemo, useState } from 'react';
import { Brain, Boxes, Network } from 'lucide-react';
import { useLanguage } from '../../contexts/LanguageContext';
import { useLocalAuth } from '../../contexts/LocalAuth';
import { useIframeSafeNavigate } from '../../hooks/useIframeSafeNavigate';
import { usePushNotifications } from '../../hooks/usePushNotifications';
import {
  CoreExperienceBanner,
  DS,
  PageShell,
  Protected,
  r,
  SectionHead,
} from '../../pages/waselServiceShared';
import { createPackageComposer, validatePackageComposer } from '../../pages/waselCorePageHelpers';
import {
  createConnectedPackage,
  getConnectedPackages,
  getConnectedRides,
  getConnectedStats,
  getPackageByTrackingId,
  updatePackageVerification,
  type PackageRequest,
} from '../../services/journeyLogistics';
import { notificationsAPI } from '../../services/notifications.js';
import { recordMovementActivity } from '../../services/movementMembership';
import { createSupportTicket } from '../../services/supportInbox';
import { walletApi } from '../../services/walletApi';
import { calculateDirectPrice } from '../../shared/pricing/priceCalculator';
import {
  getCorridorOpportunity,
  getFeaturedCorridors,
  getMarketplaceNodes,
} from '../../config/wasel-movement-network';
import { C, R, SH } from '../../utils/wasel-ds';
import { ServiceFlowPlaybook } from '../shared/ServiceFlowPlaybook';
import { PackageReturnsPanel } from './components/PackageReturnsPanel';
import { PackageSendPanel } from './components/PackageSendPanel';
import { PackageTrackPanel } from './components/PackageTrackPanel';
import { tx } from '../../locales/tx';

const CITY_LABELS_AR: Record<string, string> = {
  Amman: 'عمّان',
  Aqaba: 'العقبة',
  Irbid: 'إربد',
  Zarqa: 'الزرقاء',
  'Dead Sea': 'البحر الميت',
  Karak: 'الكرك',
  Madaba: 'مادبا',
  Petra: 'البتراء',
  Jerash: 'جرش',
  Mafraq: 'المفرق',
  Salt: import.meta.env.VITE_PACKAGES_SALT_LABEL || 'السلط',
};

function cityLabel(city: string, ar: boolean): string {
  return ar ? (CITY_LABELS_AR[city] ?? city) : city;
}

function routeLabel(from: string, to: string, ar: boolean): string {
  return ar ? `${cityLabel(from, ar)} إلى ${cityLabel(to, ar)}` : `${from} to ${to}`;
}

function corridorLabel(label: string, ar: boolean): string {
  if (!ar) {return label;}
  return label
    .replace(/Amman/g, 'عمّان')
    .replace(/Aqaba/g, 'العقبة')
    .replace(/Irbid/g, 'إربد')
    .replace(/Zarqa/g, 'الزرقاء')
    .replace(/Karak/g, 'الكرك')
    .replace(/Madaba/g, 'مادبا');
}

function packageStatusMessage(
  action: 'share_code' | 'confirm_pickup' | 'confirm_delivery',
  trackingId: string,
  ar: boolean,
): string {
  if (action === 'share_code') {
    return ar ? `تمت مشاركة الرمز لـ ${trackingId}.` : `Code shared for ${trackingId}.`;
  }
  if (action === 'confirm_pickup') {
    return ar ? `تم تأكيد الاستلام لـ ${trackingId}.` : `Pickup confirmed for ${trackingId}.`;
  }
  return ar ? `تم التسليم: ${trackingId}.` : `Delivered: ${trackingId}.`;
}

export function PackagesPage() {
  const nav = useIframeSafeNavigate();
  const { language } = useLanguage();
  const ar = language === 'ar';
  const { user } = useLocalAuth();
  const { notify, requestPermission, permission } = usePushNotifications();
  const [activeTab, setActiveTab] = useState<'send' | 'track' | 'raje3'>('send');
  const [pkg, setPkg] = useState(() => createPackageComposer());
  const [trackId, setTrackId] = useState('');
  const [trackedPackage, setTrackedPackage] = useState<PackageRequest | null>(
    () => getConnectedPackages()[0] ?? null,
  );
  const [networkStats, setNetworkStats] = useState(() => getConnectedStats());
  const [recentPackages, setRecentPackages] = useState<PackageRequest[]>(() =>
    getConnectedPackages().slice(0, 4),
  );
  const [createError, setCreateError] = useState<string | null>(null);
  const [trackingMessage, setTrackingMessage] = useState<string | null>(null);
  const [busyState, setBusyState] = useState<'idle' | 'creating' | 'tracking'>('idle');

  const featuredCorridors = useMemo(() => getFeaturedCorridors(3), []);
  const marketplaceNodes = useMemo(() => getMarketplaceNodes().slice(2), []);
  const corridorPlan = useMemo(() => getCorridorOpportunity(pkg.from, pkg.to), [pkg.from, pkg.to]);

  const matchingRideCount = getConnectedRides().filter(
    ride => ride.acceptsPackages && ride.from === pkg.from && ride.to === pkg.to,
  ).length;
  const trackedStatusColor =
    trackedPackage?.status === 'delivered'
      ? DS.green
      : trackedPackage?.status === 'in_transit'
        ? DS.cyan
        : trackedPackage?.status === 'matched'
          ? DS.gold
          : DS.muted;

  const refreshPackageSnapshot = () => {
    setNetworkStats(getConnectedStats());
    setRecentPackages(getConnectedPackages().slice(0, 4));
  };

  useEffect(() => {
    refreshPackageSnapshot();
  }, [pkg.sent, activeTab]);

  const resetComposer = () => {
    setPkg(createPackageComposer());
    setCreateError(null);
  };

  const focusTrackingItem = (item: PackageRequest, activateTrack = false) => {
    if (activateTrack) {setActiveTab('track');}
    setTrackId(item.trackingId);
    setTrackedPackage(item);
    setTrackingMessage(ar ? `التتبع جاهز: ${item.trackingId}.` : `Tracking ready: ${item.trackingId}.`);
  };

  const handlePackageCreate = async (packageType: 'delivery' | 'return' = 'delivery') => {
    const validationError = validatePackageComposer(pkg);
    if (validationError) {
      setCreateError(validationError);
      return;
    }

    setBusyState('creating');
    setCreateError(null);

    try {
      const weightKg = parseFloat(pkg.weight.match(/\d+(?:\.\d+)?/)?.[0] || '0.5');
      const priceResult = calculateDirectPrice('package', weightKg, 8);

      const created = await createConnectedPackage({
        from: pkg.from,
        to: pkg.to,
        weight: pkg.weight,
        note: pkg.note,
        packageType,
        recipientName: pkg.recipientName,
        recipientPhone: pkg.recipientPhone,
      });

      setPkg(previous => ({ ...previous, sent: true, trackingId: created.trackingId }));
      setTrackedPackage(created);
      setTrackId(created.trackingId);
      setTrackingMessage(ar ? `التتبع مباشر: ${created.trackingId}.` : `Tracking live: ${created.trackingId}.`);
      refreshPackageSnapshot();
      void recordMovementActivity('package_created', corridorPlan?.id ?? null);

      if (user?.id) {
        try {
          await walletApi.pay(user.id, priceResult.price, 'package_delivery', created.id, {
            trackingId: created.trackingId,
            from: created.from,
            to: created.to,
            weight: pkg.weight,
          });
        } catch (paymentError) {
          console.error('[Wallet] package payment failed:', paymentError);
          setTrackingMessage(
            ar
              ? `التتبع مباشر: ${created.trackingId}. سيتم تسوية الدفع عند التسليم لأن المحفظة غير متاحة الآن.`
              : `Tracking live: ${created.trackingId}. Payment will be settled on delivery (wallet unavailable).`,
          );
        }
      }

      notificationsAPI
        .createNotification({
          title:
            packageType === 'return'
              ? ar
                ? 'تم بدء طلب الإرجاع'
                : 'Return request started'
              : ar
                ? 'تم بدء حجز الطرد'
                : 'Package booking started',
          message: created.matchedRideId
            ? ar
              ? `تمت مطابقة طردك مع مسار مباشر من ${routeLabel(created.from, created.to, ar)}.`
              : `Your package was matched to a live ${created.from} to ${created.to} route.`
            : ar
              ? 'طلب الطرد مباشر وينتظر أقرب مسار مطابق.'
              : 'Your package request is live and waiting for the next matching route.',
          type: 'booking',
          priority: 'high',
          action_url: '/app/packages',
        })
        .catch(() => {});

      if (permission === 'default') {
        requestPermission().catch(() => {});
      }

      notify({
        title:
          packageType === 'return'
            ? ar
              ? 'بدأ الإرجاع'
              : 'Return Started'
            : ar
              ? 'تم إنشاء طلب الطرد'
              : 'Package request created',
        body: created.matchedRideId
          ? ar
            ? `تمت المطابقة مع ${created.matchedDriver || 'مسار متصل'}. رقم التتبع: ${created.trackingId}`
            : `Matched to ${created.matchedDriver || 'a connected route'}. Tracking ID: ${created.trackingId}`
          : ar
            ? `رقم التتبع: ${created.trackingId}. نبحث الآن عن أقرب مطابقة على الممر.`
            : `Tracking ID: ${created.trackingId}. We are searching for the next corridor match now.`,
        tag: 'package-created',
      });
    } catch (error) {
      setCreateError(
        error instanceof Error
          ? error.message
          : ar
            ? 'لم نتمكن من إنشاء طلب الطرد الآن.'
            : 'We could not create the package request right now.',
      );
    } finally {
      setBusyState('idle');
    }
  };

  const handleTrackingSearch = async () => {
    setBusyState('tracking');
    setTrackingMessage(null);

    try {
      const found = await getPackageByTrackingId(trackId);
      setTrackedPackage(found);
      setTrackingMessage(
        found
          ? ar
            ? `تم تحميل التتبع: ${found.trackingId}.`
            : `Tracking loaded: ${found.trackingId}.`
          : ar
            ? 'لم يتم العثور على طرد.'
            : 'No package found.',
      );
      refreshPackageSnapshot();
    } finally {
      setBusyState('idle');
    }
  };

  const handleVerificationAction = async (
    action: 'share_code' | 'confirm_pickup' | 'confirm_delivery',
  ) => {
    if (!trackedPackage) {return;}

    setBusyState('tracking');

    try {
      const updated = await updatePackageVerification(trackedPackage.trackingId, action);
      if (!updated) {return;}

      setTrackedPackage(updated);
      setTrackId(updated.trackingId);
      setTrackingMessage(packageStatusMessage(action, updated.trackingId, ar));
      refreshPackageSnapshot();
    } catch (error) {
      setTrackingMessage(
        error instanceof Error
          ? error.message
          : ar
            ? 'تأكيد الطرد غير متاح الآن.'
            : 'Package verification is unavailable right now.',
      );
    } finally {
      setBusyState('idle');
    }
  };

  const handleOpenSupport = () => {
    if (!trackedPackage) {return;}

    void (async () => {
      const ticket = await createSupportTicket(user?.id, {
        topic: 'package_issue',
        subject: `Package tracking help for ${trackedPackage.trackingId}`,
        detail: `Support requested for ${trackedPackage.from} to ${trackedPackage.to}. Current status: ${trackedPackage.status}.`,
        relatedId: trackedPackage.trackingId,
        routeLabel: `${trackedPackage.from} to ${trackedPackage.to}`,
      });

      setTrackingMessage(ar ? `تم فتح الدعم: ${ticket.id}.` : `Support opened: ${ticket.id}.`);
      notificationsAPI
        .createNotification({
          title: ar ? 'تم فتح دعم الطرد' : 'Package support opened',
          message: ar
            ? `الدعم يتابع الآن ${trackedPackage.trackingId}.`
            : `Support is now following ${trackedPackage.trackingId}.`,
          type: 'support',
          priority: 'high',
          action_url: '/app/profile',
        })
        .catch(() => {});
    })();
  };

  return (
    <Protected>
      <PageShell>
        <SectionHead
          emoji={<Boxes size={24} />}
          title={tx('packagesPage.send_a_package')}
          titleAr="أرسل طرداً"
          sub={tx('packagesPage.match_parcels_to_live_routes_returns_and_tracked_handoffs')}
          color={DS.gold}
          action={{ label: tx('dashboard.offerRide'), onClick: () => nav('/app/offer-ride') }}
        />

        <CoreExperienceBanner
          title={tx('packagesPage.package_flow_is_tied_to_the_same_live_corridor_graph')}
          detail={tx(
            'packagesPage.wasel_matches_parcels_to_live_drivers_first_then_falls_back_to_the_next_trusted_route_on_the_same_corridor',
          )}
          tone={DS.gold}
        />

        <div
          className="sp-4col"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(4, minmax(0, 1fr))',
            gap: 14,
            marginBottom: 18,
          }}
        >
          {[
            {
              label: ar ? 'مسارات جاهزة' : 'Ready routes',
              value: String(networkStats.packageEnabledRides),
              detail: ar ? 'مسارات تقبل الطرود' : 'Routes accepting packages',
              color: DS.green,
            },
            {
              label: ar ? 'نسبة المطابقة' : 'Match rate',
              value: corridorPlan ? `${corridorPlan.attachRatePercent}%` : '--',
              detail: ar ? 'فرصة مطابقة سريعة' : 'Chance of a fast match',
              color: DS.gold,
            },
            {
              label: ar ? 'السعر المشترك' : 'Shared price',
              value: corridorPlan ? `${corridorPlan.sharedPriceJod} ${ar ? 'دينار' : 'JOD'}` : '--',
              detail: ar ? 'سعر المسار المتوقع' : 'Expected route price',
              color: DS.cyan,
            },
            {
              label: ar ? 'مطابقة' : 'Matched',
              value: String(networkStats.matchedPackages),
              detail: ar ? 'مرتبطة برحلات حالياً' : 'Already linked to rides',
              color: DS.blue,
            },
          ].map(item => (
            <div
              key={item.label}
              style={{
                background: C.card,
                borderRadius: r(16),
                border: `1px solid ${DS.border}`,
                padding: '18px 18px 16px',
                boxShadow: SH.sm,
              }}
            >
              <div
                style={{ color: item.color, fontWeight: 900, fontSize: '1.2rem', marginBottom: 4 }}
              >
                {item.value}
              </div>
              <div style={{ color: C.text, fontWeight: 800, fontSize: '0.84rem' }}>
                {item.label}
              </div>
              <div style={{ color: DS.muted, fontSize: '0.74rem', marginTop: 4, lineHeight: 1.45 }}>
                {item.detail}
              </div>
            </div>
          ))}
        </div>

        <div
          className="sp-2col"
          style={{
            display: 'grid',
            gridTemplateColumns: '1.15fr 0.85fr',
            gap: 14,
            marginBottom: 18,
          }}
        >
          <div
            style={{
              background: DS.card,
              borderRadius: r(18),
              padding: '18px 18px 16px',
              border: `1px solid ${DS.border}`,
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
              <div
                style={{
                  width: 38,
                  height: 38,
                  borderRadius: r(12),
                  background: `${DS.cyan}12`,
                  border: `1px solid ${DS.cyan}28`,
                  display: 'grid',
                  placeItems: 'center',
                }}
              >
                <Brain size={18} color={DS.cyan} />
              </div>
              <div>
                <div style={{ color: C.text, fontWeight: 800 }}>{tx('packagesPage.route_fit')}</div>
                <div style={{ color: DS.muted, fontSize: '0.76rem', marginTop: 2 }}>
                  {tx('packagesPage.match_pickup_and_price')}
                </div>
              </div>
            </div>
            <div style={{ display: 'grid', gap: 10 }}>
              {[
                corridorPlan
                  ? ar
                    ? `${routeLabel(pkg.from, pkg.to, ar)} أوفر بنسبة ${corridorPlan.savingsPercent}% من التوصيل المنفرد.`
                    : `${corridorPlan.label} is ${corridorPlan.savingsPercent}% cheaper than solo delivery.`
                  : ar
                    ? 'اختار مساراً لعرض السعر وتفاصيل المطابقة.'
                    : 'Choose a route to see price and match details.',
                corridorPlan
                  ? ar
                    ? 'الاستلام من نقطة موثوقة على المسار المختار. ستظهر تفاصيل التنسيق بعد تأكيد الطلب.'
                    : `Pickup: ${corridorPlan.pickupPoints[0] ?? 'Trusted point'}. ${corridorPlan.autoGroupWindow}`
                  : ar
                    ? 'نقاط الاستلام تظهر هنا.'
                    : 'Pickup points show here.',
                corridorPlan
                  ? ar
                    ? 'الطلب على هذا المسار يدعم الحركة المشتركة والطرود والتسليم المتكرر.'
                    : `Demand: ${corridorPlan.businessDemand.join(', ')}.`
                  : ar
                    ? 'الإرجاعات والوثائق تساعد على تقوية المسارات الضعيفة.'
                    : 'Returns and documents can improve weak routes.',
              ].map(line => (
                <div
                  key={line}
                  style={{
                    borderRadius: r(14),
                    border: `1px solid ${DS.border}`,
                    background: DS.card2,
                    padding: '12px 14px',
                    color: C.text,
                    fontSize: '0.82rem',
                    lineHeight: 1.65,
                  }}
                >
                  {line}
                </div>
              ))}
            </div>
          </div>

          <div
            style={{
              background: DS.card,
              borderRadius: r(18),
              padding: '18px 18px 16px',
              border: `1px solid ${DS.border}`,
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 12 }}>
              <div
                style={{
                  width: 38,
                  height: 38,
                  borderRadius: r(12),
                  background: `${DS.green}12`,
                  border: `1px solid ${DS.green}28`,
                  display: 'grid',
                  placeItems: 'center',
                }}
              >
                <Network size={18} color={DS.green} />
              </div>
              <div>
                <div style={{ color: C.text, fontWeight: 800 }}>
                  {tx('packagesPage.extra_demand')}
                </div>
                <div style={{ color: DS.muted, fontSize: '0.76rem', marginTop: 2 }}>
                  {tx('packagesPage.returns_and_repeat_lanes_help')}
                </div>
              </div>
            </div>
            <div style={{ display: 'grid', gap: 10 }}>
              {marketplaceNodes.map(node => (
                <div
                  key={node.id}
                  style={{
                    borderRadius: r(14),
                    border: `1px solid ${DS.border}`,
                    background: DS.card2,
                    padding: '12px 14px',
                  }}
                >
                  <div style={{ color: C.text, fontWeight: 700, fontSize: '0.82rem' }}>
                    {ar ? 'نقطة طلب ضمن الشبكة' : node.title}
                  </div>
                  <div
                    style={{ color: DS.muted, fontSize: '0.74rem', lineHeight: 1.55, marginTop: 4 }}
                  >
                    {ar ? 'تدعم هذه النقطة الطلب المتكرر والطرود والحركة المشتركة على المسار.' : node.summary}
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>

        <div
          className="sp-3col"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
            gap: 14,
            marginBottom: 24,
          }}
        >
          {featuredCorridors.map(corridor => (
            <div
              key={corridor.id}
              style={{
                background: DS.card,
                borderRadius: r(18),
                padding: '18px 18px 16px',
                border: `1px solid ${DS.border}`,
              }}
            >
              <div
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 10,
                }}
              >
                <div style={{ color: C.text, fontWeight: 800, fontSize: '0.86rem' }}>
                  {corridorLabel(corridor.label, ar)}
                </div>
                <span style={{ color: DS.cyan, fontSize: '0.72rem', fontWeight: 700 }}>
                  {corridor.predictedDemandScore}/100
                </span>
              </div>
              <div style={{ color: DS.muted, fontSize: '0.74rem', lineHeight: 1.55, marginTop: 8 }}>
                {ar
                  ? 'مسار نشط يجمع الركاب والطرود والطلب المتكرر ضمن شبكة واحدة.'
                  : corridor.routeMoat}
              </div>
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginTop: 12 }}>
                {corridor.movementLayers.slice(0, 3).map(layer => (
                  <span
                    key={layer}
                    style={{
                      padding: '5px 9px',
                      borderRadius: '999px',
                      background: C.elevated,
                      border: `1px solid ${DS.border}`,
                      color: DS.sub,
                      fontSize: '0.69rem',
                      fontWeight: 700,
                    }}
                  >
                    {ar ? 'حركة متكررة' : layer}
                  </span>
                ))}
              </div>
            </div>
          ))}
        </div>

        <div
          style={{
            display: 'flex',
            gap: 8,
            background: C.elevated,
            borderRadius: R.xl,
            padding: 6,
            border: `1px solid ${DS.border}`,
            marginBottom: 24,
            boxShadow: SH.card,
          }}
        >
          {(
            [
              ['send', 'Send Package'],
              ['track', 'Track Package'],
              ['raje3', 'Raje3 Returns'],
            ] as const
          ).map(([key, label]) => (
            <button
              key={key}
              onClick={() => { void setActiveTab(key); }}
              style={{
                flex: 1,
                height: 44,
                borderRadius: r(12),
                border: 'none',
                cursor: 'pointer',
                fontFamily: DS.F,
                fontWeight: activeTab === key ? 800 : 600,
                fontSize: '0.82rem',
                letterSpacing: 0,
                background: activeTab === key ? DS.gradG : 'transparent',
                color: activeTab === key ? C.text : DS.muted,
                transition: 'all 0.18s',
              }}
            >
              {ar
                ? key === 'send'
                  ? 'أرسل طرد'
                  : key === 'track'
                    ? 'تتبع طرد'
                    : 'إرجاعات راجع'
                : label}
            </button>
          ))}
        </div>

        <div
          style={{
            background: C.card,
            borderRadius: r(22),
            padding: '28px 28px',
            border: `1px solid ${DS.border}`,
            boxShadow: SH.card,
          }}
        >
          {activeTab === 'send' && (
            <PackageSendPanel
              pkg={pkg}
              setPkg={setPkg}
              trackedPackage={trackedPackage}
              createError={createError}
              busyState={busyState}
              matchingRideCount={matchingRideCount}
              recentPackages={recentPackages}
              onCreate={() => handlePackageCreate('delivery')}
              onReset={resetComposer}
              onOpenTracking={() => setActiveTab('track')}
              onOpenRecent={item => focusTrackingItem(item, true)}
            />
          )}

          {activeTab === 'track' && (
            <PackageTrackPanel
              trackId={trackId}
              setTrackId={setTrackId}
              trackedPackage={trackedPackage}
              trackingMessage={trackingMessage}
              busyState={busyState}
              trackedStatusColor={trackedStatusColor}
              recentPackages={recentPackages}
              onSearch={handleTrackingSearch}
              onVerificationAction={handleVerificationAction}
              onOpenSupport={handleOpenSupport}
              onOpenRecent={item => focusTrackingItem(item)}
            />
          )}

          {activeTab === 'raje3' && (
            <PackageReturnsPanel
              createError={createError}
              busyState={busyState}
              onCreateReturn={() => handlePackageCreate('return')}
            />
          )}
        </div>

        <div style={{ marginTop: 18, display: 'grid', gap: 10 }}>
          <div
            style={{
              borderRadius: r(16),
              border: `1px solid ${DS.border}`,
              background: DS.card,
              padding: '16px 18px',
            }}
          >
            <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 8 }}>
              <Boxes size={18} color={DS.gold} />
              <div style={{ color: C.text, fontWeight: 800 }}>
                {tx('packagesPage.why_this_works')}
              </div>
            </div>
            <div style={{ color: DS.sub, fontSize: '0.8rem', lineHeight: 1.65 }}>
              {tx(
                'packagesPage.every_package_request_improves_route_matching_handoff_clarity_and_corridor_coverage_senders_get_simpler_delivery_and_the_network_gets_better_at_moving_parcels_on_real_daily_routes',
              )}
            </div>
          </div>
        </div>

        <ServiceFlowPlaybook
          focusService={
            activeTab === 'track'
              ? 'deliver-package'
              : activeTab === 'raje3'
                ? 'returns'
                : 'send-package'
          }
        />
      </PageShell>
    </Protected>
  );
}

export default PackagesPage;

import type { Dispatch, SetStateAction } from 'react';
import { CheckCircle2, Shield } from 'lucide-react';
import { useLanguage } from '../../../contexts/LanguageContext';
import { CITIES } from '../../../pages/waselCoreRideData';
import { DS, pill, r } from '../../../pages/waselServiceShared';
import { C, SH } from '../../../utils/wasel-ds';
import type { PackageRequest } from '../../../services/journeyLogistics';
import {
  PACKAGE_EXCELLENCE_POINTS_AR,
  PACKAGE_EXCELLENCE_POINTS,
  PACKAGE_SEND_STEPS_AR,
  PACKAGE_SEND_STEPS,
  PACKAGE_WEIGHT_OPTIONS,
} from '../packagesContent';
import { tx } from '../../../locales/tx';

type ComposerState = {
  from: string;
  to: string;
  weight: string;
  note: string;
  sent: boolean;
  trackingId: string;
  recipientName: string;
  recipientPhone: string;
};

type PackageSendPanelProps = {
  pkg: ComposerState;
  setPkg: Dispatch<SetStateAction<ComposerState>>;
  trackedPackage: PackageRequest | null;
  createError: string | null;
  busyState: 'idle' | 'creating' | 'tracking';
  matchingRideCount: number;
  recentPackages: PackageRequest[];
  onCreate: () => void;
  onReset: () => void;
  onOpenTracking: () => void;
  onOpenRecent: (item: PackageRequest) => void;
};

const CITY_LABELS_AR: Record<string, string> = {
  Amman: 'عمّان',
  Aqaba: 'العقبة',
  Irbid: 'إربد',
  Zarqa: 'الزرقاء',
  'Dead Sea': 'البحر الميت',
  Karak: 'الكرك',
  Madaba: 'مادبا',
  Petra: 'البتراء',
  Jerash: 'جرش',
  Mafraq: 'المفرق',
  Salt: import.meta.env.VITE_PACKAGE_SEND_SALT_LABEL || 'السلط',
};

function cityLabel(city: string, ar: boolean): string {
  return ar ? (CITY_LABELS_AR[city] ?? city) : city;
}

function weightLabel(weight: string, ar: boolean): string {
  return ar ? weight.replace('<1 kg', 'أقل من ١ كغ').replace(/kg/g, 'كغ') : weight;
}

export function PackageSendPanel({
  pkg,
  setPkg,
  trackedPackage,
  createError,
  busyState,
  matchingRideCount,
  recentPackages,
  onCreate,
  onReset,
  onOpenTracking,
  onOpenRecent,
}: PackageSendPanelProps) {
  const { language } = useLanguage();
  const ar = language === 'ar';
  const sendSteps = ar ? PACKAGE_SEND_STEPS_AR : PACKAGE_SEND_STEPS;
  const excellencePoints = ar ? PACKAGE_EXCELLENCE_POINTS_AR : PACKAGE_EXCELLENCE_POINTS;

  const errorDisplay = createError ? (
    <div
      style={{
        gridColumn: '1/-1',
        display: 'flex',
        gap: 10,
        alignItems: 'center',
        background: `${DS.gold}12`,
        border: `1px solid ${DS.gold}30`,
        borderRadius: r(14),
        padding: '12px 14px',
        color: C.text,
        fontSize: '0.84rem',
        marginBottom: 16,
      }}
    >
      <Shield size={16} color={DS.gold} />
      <span>{createError}</span>
    </div>
  ) : null;

  if (pkg.sent) {
    return (
      <div style={{ textAlign: 'center', padding: '40px 0' }}>
        <div
          style={{
            width: 60,
            height: 60,
            borderRadius: r(16),
            margin: '0 auto 16px',
            display: 'grid',
            placeItems: 'center',
            background: C.greenDim,
            border: `1px solid ${DS.green}35`,
            color: DS.green,
          }}
        >
          <CheckCircle2 size={28} />
        </div>
        <h3 style={{ color: DS.green, fontWeight: 900, margin: '0 0 8px' }}>
          {tx('packageSendPanel.package_request_created')}
        </h3>
        <p style={{ color: DS.sub }}>
          {trackedPackage?.matchedRideId
            ? ar
              ? `تمت المطابقة مع مشوار متصل من ${cityLabel(pkg.from, ar)} إلى ${cityLabel(pkg.to, ar)}.`
              : `Matched to a connected ride from ${pkg.from} to ${pkg.to}.`
            : ar
              ? `نبحث عن أفضل مشوار متصل من ${cityLabel(pkg.from, ar)} إلى ${cityLabel(pkg.to, ar)}.`
              : `Searching for the best connected ride from ${pkg.from} to ${pkg.to}.`}
        </p>
        <div
          style={{
            margin: '20px auto',
            maxWidth: 360,
            background: C.elevated,
            borderRadius: r(16),
            padding: '16px 20px',
            border: `1px solid ${DS.border}`,
            boxShadow: SH.card,
          }}
        >
          <p style={{ color: DS.muted, fontSize: '0.75rem', marginBottom: 4 }}>
            {tx('packageSendPanel.tracking_id')}
          </p>
          <p style={{ color: DS.cyan, fontWeight: 800, fontSize: '1.2rem', letterSpacing: 0 }}>
            {pkg.trackingId}
          </p>
          <p style={{ color: DS.muted, fontSize: '0.75rem', margin: '14px 0 4px' }}>
            {tx('packageSendPanel.handoff_code')}
          </p>
          <p
            style={{
              color: DS.gold,
              fontWeight: 800,
              fontSize: '1.05rem',
              letterSpacing: 0,
            }}
          >
            {trackedPackage?.handoffCode || (ar ? 'بانتظار التعيين' : 'Pending assignment')}
          </p>
          <p style={{ color: DS.sub, fontSize: '0.8rem', marginTop: 8 }}>
            {trackedPackage?.matchedDriver
              ? ar
                ? `تم التعيين إلى ${trackedPackage.matchedDriver}`
                : `Assigned to ${trackedPackage.matchedDriver}`
              : ar
                ? 'بانتظار تعيين المسار'
                : 'Waiting for route assignment'}
          </p>
          <p style={{ color: DS.muted, fontSize: '0.76rem', marginTop: 10 }}>
            {tx(
              'packageSendPanel.share_this_otp_with_the_rider_at_pickup_then_confirm_pickup_and_delivery_from_tracking',
            )}
          </p>
        </div>
        <div style={{ display: 'flex', gap: 10, justifyContent: 'center', flexWrap: 'wrap' }}>
          <button
            onClick={() => { void onOpenTracking(); }}
            style={{
              padding: '10px 24px',
              borderRadius: '99px',
              border: 'none',
              background: DS.gradC,
              color: C.text,
              cursor: 'pointer',
              fontFamily: DS.F,
              fontWeight: 700,
            }}
          >
            {tx('packageSendPanel.open_tracking')}
          </button>
          <button
            onClick={() => { void onReset(); }}
            style={{
              padding: '10px 24px',
              borderRadius: '99px',
              border: `1px solid ${DS.border}`,
              background: DS.card2,
              color: DS.gold,
              cursor: 'pointer',
              fontFamily: DS.F,
              fontWeight: 700,
            }}
          >
            {tx('packageSendPanel.create_another')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      style={{
        display: 'grid',
        gap: 16,
        gridTemplateColumns: 'minmax(0, 1.5fr) minmax(320px, 1fr)',
      }}
    >
      <div style={{ display: 'grid', gap: 14, gridTemplateColumns: '1fr 1fr' }}>
        <h3 style={{ color: C.text, fontWeight: 800, gridColumn: '1/-1', margin: '0 0 4px' }}>
          {tx('packageSendPanel.send_through_the_shared_network')}
        </h3>
        {[
          { l: ar ? 'من' : 'From', k: 'from' as const },
          { l: ar ? 'إلى' : 'To', k: 'to' as const },
        ].map(field => (
          <div key={field.l}>
            <label
              style={{
                display: 'block',
                color: DS.muted,
                fontSize: '0.7rem',
                fontWeight: 700,
                letterSpacing: 0,
                textTransform: 'uppercase',
                marginBottom: 6,
              }}
            >
              {field.l}
            </label>
            <select
              value={pkg[field.k]}
              onChange={event =>
                setPkg(previous => ({ ...previous, [field.k]: event.target.value }))
              }
              style={{
                width: '100%',
                padding: '12px 14px',
                borderRadius: r(10),
                border: `1px solid ${DS.border}`,
                background: DS.card2,
                color: C.text,
                fontFamily: DS.F,
                fontSize: '0.9rem',
                outline: 'none',
                cursor: 'pointer',
              }}
            >
              {CITIES.map(city => (
                <option key={city} value={city} style={{ background: DS.card }}>
                  {cityLabel(city, ar)}
                </option>
              ))}
            </select>
          </div>
        ))}
        <div>
          <label
            style={{
              display: 'block',
              color: DS.muted,
              fontSize: '0.7rem',
              fontWeight: 700,
              letterSpacing: 0,
              textTransform: 'uppercase',
              marginBottom: 6,
            }}
          >
            {tx('packageSendPanel.weight')}
          </label>
          <select
            value={pkg.weight}
            onChange={event => setPkg(previous => ({ ...previous, weight: event.target.value }))}
            style={{
              width: '100%',
              padding: '12px 14px',
              borderRadius: r(10),
              border: `1px solid ${DS.border}`,
              background: DS.card2,
              color: C.text,
              fontFamily: DS.F,
              fontSize: '0.9rem',
              outline: 'none',
              cursor: 'pointer',
            }}
          >
            {PACKAGE_WEIGHT_OPTIONS.map(weight => (
              <option key={weight} value={weight} style={{ background: DS.card }}>
                {weightLabel(weight, ar)}
              </option>
            ))}
          </select>
        </div>
        <div>
          <label
            style={{
              display: 'block',
              color: DS.muted,
              fontSize: '0.7rem',
              fontWeight: 700,
              letterSpacing: 0,
              textTransform: 'uppercase',
              marginBottom: 6,
            }}
          >
            {tx('packageSendPanel.recipient')}
          </label>
          <input
            data-testid="package-recipient-name"
            placeholder={tx('packageSendPanel.full_recipient_name')}
            value={pkg.recipientName}
            onChange={event =>
              setPkg(previous => ({ ...previous, recipientName: event.target.value }))
            }
            style={{
              width: '100%',
              padding: '12px 14px',
              borderRadius: r(10),
              border: `1px solid ${DS.border}`,
              background: DS.card2,
              color: C.text,
              fontFamily: DS.F,
              fontSize: '0.9rem',
              outline: 'none',
              boxSizing: 'border-box',
            }}
          />
        </div>
        <div>
          <label
            style={{
              display: 'block',
              color: DS.muted,
              fontSize: '0.7rem',
              fontWeight: 700,
              letterSpacing: 0,
              textTransform: 'uppercase',
              marginBottom: 6,
            }}
          >
            {tx('common.phone')}
          </label>
          <input
            data-testid="package-recipient-phone"
            placeholder={tx('packageSendPanel.recipient_phone')}
            value={pkg.recipientPhone}
            onChange={event =>
              setPkg(previous => ({ ...previous, recipientPhone: event.target.value }))
            }
            style={{
              width: '100%',
              padding: '12px 14px',
              borderRadius: r(10),
              border: `1px solid ${DS.border}`,
              background: DS.card2,
              color: C.text,
              fontFamily: DS.F,
              fontSize: '0.9rem',
              outline: 'none',
              boxSizing: 'border-box',
            }}
          />
        </div>
        <div>
          <label
            style={{
              display: 'block',
              color: DS.muted,
              fontSize: '0.7rem',
              fontWeight: 700,
              letterSpacing: 0,
              textTransform: 'uppercase',
              marginBottom: 6,
            }}
          >
            {tx('packageSendPanel.note')}
          </label>
          <input
            placeholder={tx('packageSendPanel.fragile_or_handling_notes')}
            value={pkg.note}
            onChange={event => setPkg(previous => ({ ...previous, note: event.target.value }))}
            style={{
              width: '100%',
              padding: '12px 14px',
              borderRadius: r(10),
              border: `1px solid ${DS.border}`,
              background: DS.card2,
              color: C.text,
              fontFamily: DS.F,
              fontSize: '0.9rem',
              outline: 'none',
              boxSizing: 'border-box',
            }}
          />
        </div>
        <div
          style={{
            gridColumn: '1/-1',
            background: C.elevated,
            borderRadius: r(14),
            padding: '16px 18px',
            border: `1px solid ${DS.border}`,
          }}
        >
          <div style={{ color: C.text, fontWeight: 800, marginBottom: 6 }}>
            {tx('packageSendPanel.connected_flow')}
          </div>
          <div style={{ color: DS.sub, fontSize: '0.82rem', lineHeight: 1.6 }}>
            {tx(
              'packageSendPanel.every_package_request_checks_live_posted_rides_first_if_a_matching_ride_accepts_parcels_the_request_attaches_to_that_route_and_tracking_starts_from_the_same_network',
            )}
          </div>
        </div>
        <div
          style={{
            gridColumn: '1/-1',
            display: 'grid',
            gap: 10,
            gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
          }}
        >
          {sendSteps.map(item => (
            <div
              key={item.title}
              style={{
                borderRadius: r(12),
                border: `1px solid ${DS.border}`,
                padding: '12px 13px',
                background: C.elevated,
              }}
            >
              <div style={{ color: C.text, fontSize: '0.82rem', fontWeight: 700 }}>
                {item.title}
              </div>
              <div style={{ color: DS.muted, fontSize: '0.74rem', marginTop: 4, lineHeight: 1.5 }}>
                {item.desc}
              </div>
            </div>
          ))}
        </div>
        {errorDisplay}
        <button
          data-testid="package-create-request"
          disabled={busyState === 'creating'}
          onClick={() => { void onCreate(); }}
          style={{
            gridColumn: '1/-1',
            height: 52,
            borderRadius: r(14),
            border: 'none',
            background: DS.gradG,
            color: C.text,
            fontWeight: 800,
            fontFamily: DS.F,
            fontSize: '0.95rem',
            cursor: busyState === 'creating' ? 'wait' : 'pointer',
            opacity: busyState === 'creating' ? 0.75 : 1,
            boxShadow: `0 4px 20px ${DS.gold}30`,
          }}
        >
          {busyState === 'creating'
            ? ar
              ? 'جاري إنشاء طلب الطرد...'
              : 'Creating package request...'
            : ar
              ? 'أنشئ طلب طرد متصل'
              : 'Create connected package request'}
        </button>
      </div>

      <div style={{ display: 'grid', gap: 14 }}>
        <div
          style={{
            background: C.elevated,
            borderRadius: r(16),
            padding: '18px 18px 16px',
            border: `1px solid ${DS.border}`,
            boxShadow: SH.card,
          }}
        >
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'space-between',
              gap: 12,
              marginBottom: 12,
            }}
          >
            <div>
              <div style={{ color: C.text, fontWeight: 800, fontSize: '0.95rem' }}>
                {tx('packageSendPanel.route_readiness')}
              </div>
              <div style={{ color: DS.muted, fontSize: '0.76rem', marginTop: 4 }}>
                {tx('packageSendPanel.live_visibility_for')}
                {cityLabel(pkg.from, ar)} {tx('packageSendPanel.to')}
                {cityLabel(pkg.to, ar)}
              </div>
            </div>
            <span style={{ ...pill(matchingRideCount > 0 ? DS.green : DS.gold) }}>
              {matchingRideCount > 0
                ? ar
                  ? `${matchingRideCount} رحلات مباشرة`
                  : `${matchingRideCount} rides live`
                : ar
                  ? 'وضع الانتظار'
                  : 'Standby mode'}
            </span>
          </div>
          <div style={{ color: DS.sub, fontSize: '0.82rem', lineHeight: 1.6 }}>
            {matchingRideCount > 0
              ? ar
                ? 'هذا الممر فيه رحلات جاهزة للطرود، لذلك المطابقة غالباً فورية أو قريبة من الفورية.'
                : 'This corridor already has package-ready rides, so matching should be immediate or near-immediate.'
              : ar
                ? 'لا توجد رحلة جاهزة للطرود على هذا المسار حالياً. سننشئ الطلب ونبقيه بالطابور لأقرب كابتن مطابق.'
                : 'No package-ready ride is live for this route yet. We will still create the request and keep it queued for the next matching captain.'}
          </div>
        </div>
        <div
          style={{
            background: C.elevated,
            borderRadius: r(16),
            padding: '18px 18px 16px',
            border: `1px solid ${DS.border}`,
            boxShadow: SH.card,
          }}
        >
          <div style={{ color: C.text, fontWeight: 800, fontSize: '0.95rem', marginBottom: 12 }}>
            {tx('packageSendPanel.what_great_looks_like')}
          </div>
          <div style={{ display: 'grid', gap: 10 }}>
            {excellencePoints.map(item => (
              <div
                key={item.title}
                style={{
                  borderRadius: r(12),
                  border: `1px solid ${DS.border}`,
                  padding: '12px 13px',
                  background: C.elevated,
                }}
              >
                <div style={{ color: C.text, fontSize: '0.84rem', fontWeight: 700 }}>
                  {item.title}
                </div>
                <div style={{ color: DS.muted, fontSize: '0.75rem', marginTop: 4 }}>
                  {item.desc}
                </div>
              </div>
            ))}
          </div>
        </div>
        <div
          style={{
            background: C.elevated,
            borderRadius: r(16),
            padding: '18px 18px 16px',
            border: `1px solid ${DS.border}`,
            boxShadow: SH.card,
          }}
        >
          <div style={{ color: C.text, fontWeight: 800, fontSize: '0.95rem', marginBottom: 10 }}>
            {tx('packageSendPanel.recent_requests')}
          </div>
          {recentPackages.length > 0 ? (
            <div style={{ display: 'grid', gap: 10 }}>
              {recentPackages.map(item => (
                <button
                  key={item.trackingId}
                  onClick={() => { void onOpenRecent(item); }}
                  style={{
                    textAlign: 'left',
                    borderRadius: r(12),
                    border: `1px solid ${DS.border}`,
                    padding: '12px 13px',
                    background: C.elevated,
                    cursor: 'pointer',
                  }}
                >
                  <div
                    style={{
                      display: 'flex',
                      justifyContent: 'space-between',
                      gap: 12,
                      flexWrap: 'wrap',
                    }}
                  >
                    <span style={{ color: C.text, fontWeight: 700, fontSize: '0.82rem' }}>
                      {cityLabel(item.from, ar)} {tx('packageSendPanel.to_2')}
                      {cityLabel(item.to, ar)}
                    </span>
                    <span style={{ ...pill(item.matchedRideId ? DS.green : DS.gold) }}>
                      {item.trackingId}
                    </span>
                  </div>
                  <div style={{ color: DS.muted, fontSize: '0.74rem', marginTop: 6 }}>
                    {item.matchedRideId
                      ? ar
                        ? `تم التعيين إلى ${item.matchedDriver || 'كابتن متصل'}`
                        : `Assigned to ${item.matchedDriver || 'connected captain'}`
                      : ar
                        ? 'بانتظار تعيين المسار'
                        : 'Waiting for route assignment'}
                  </div>
                </button>
              ))}
            </div>
          ) : (
            <div style={{ color: DS.muted, fontSize: '0.8rem' }}>
              {tx(
                'packageSendPanel.your_recent_package_requests_appear_here_for_one_click_tracking',
              )}
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

import { motion } from 'framer-motion';
import { CheckCircle2, Search } from 'lucide-react';
import { MapWrapper } from '../../../components/MapWrapper';
import { useLanguage } from '../../../contexts/LanguageContext';
import { DS, midpoint, pill, r, resolveCityCoord } from '../../../pages/waselServiceShared';
import { C, SH } from '../../../utils/wasel-ds';
import type { PackageRequest } from '../../../services/journeyLogistics';
import { tx } from '../../../locales/tx';

type PackageTrackPanelProps = {
  trackId: string;
  setTrackId: (value: string) => void;
  trackedPackage: PackageRequest | null;
  trackingMessage: string | null;
  busyState: 'idle' | 'creating' | 'tracking';
  trackedStatusColor: string;
  recentPackages: PackageRequest[];
  onSearch: () => void;
  onVerificationAction: (action: 'share_code' | 'confirm_pickup' | 'confirm_delivery') => void;
  onOpenSupport: () => void;
  onOpenRecent: (item: PackageRequest) => void;
};

const CITY_LABELS_AR: Record<string, string> = {
  Amman: 'عمّان',
  Aqaba: 'العقبة',
  Irbid: 'إربد',
  Zarqa: 'الزرقاء',
  'Dead Sea': 'البحر الميت',
  Karak: 'الكرك',
  Madaba: 'مادبا',
  Petra: 'البتراء',
  Jerash: 'جرش',
  Mafraq: 'المفرق',
  Salt: import.meta.env.VITE_PACKAGE_TRACK_SALT_LABEL || 'السلط',
};

function cityLabel(city: string, ar: boolean): string {
  return ar ? (CITY_LABELS_AR[city] ?? city) : city;
}

function routeLabel(from: string, to: string, ar: boolean): string {
  return ar ? `${cityLabel(from, ar)} إلى ${cityLabel(to, ar)}` : `${from} to ${to}`;
}

function statusLabel(status: string, ar: boolean): string {
  if (!ar) {return status.replace('_', ' ');}
  const labels: Record<string, string> = {
    searching: 'قيد البحث',
    matched: 'مطابق',
    in_transit: 'بالطريق',
    delivered: 'تم التسليم',
    cancelled: 'ملغي',
  };
  return labels[status] ?? status.replace('_', ' ');
}

function timelineLabel(label: string, ar: boolean): string {
  if (!ar) {return label;}
  return label
    .replace('Matched to a rider trip', 'تمت المطابقة مع رحلة راكب')
    .replace('Searching for a rider trip', 'جاري البحث عن رحلة راكب')
    .replace('Sender shared OTP handoff code', 'المرسل شارك رمز التسليم')
    .replace('Rider pickup confirmed', 'تم تأكيد استلام الراكب')
    .replace('Receiver delivery confirmed', 'تم تأكيد تسليم المستلم');
}

export function PackageTrackPanel({
  trackId,
  setTrackId,
  trackedPackage,
  trackingMessage,
  busyState,
  trackedStatusColor,
  recentPackages,
  onSearch,
  onVerificationAction,
  onOpenSupport,
  onOpenRecent,
}: PackageTrackPanelProps) {
  const { language } = useLanguage();
  const ar = language === 'ar';

  return (
    <div style={{ textAlign: 'center', maxWidth: 560, margin: '0 auto', padding: '20px 0' }}>
      <div style={{ fontSize: '2.5rem', marginBottom: 16 }}>{tx('packageTrackPanel.track')}</div>
      <h3 style={{ color: C.text, fontWeight: 800, margin: '0 0 8px' }}>
        {tx('packageTrackPanel.track_your_package')}
      </h3>
      <p style={{ color: DS.sub, marginBottom: 20 }}>
        {tx('packageTrackPanel.enter_your_tracking_id_to_see_ride_and_package_status_together')}
      </p>
      <div style={{ display: 'flex', gap: 10 }}>
        <input
          placeholder={tx('packageTrackPanel.pkg_xxxxx')}
          value={trackId}
          onChange={event => setTrackId(event.target.value)}
          style={{
            flex: 1,
            padding: '14px 18px',
            borderRadius: r(12),
            border: `1px solid ${DS.border}`,
            background: DS.card2,
            color: C.text,
            fontFamily: DS.F,
            fontSize: '0.95rem',
            outline: 'none',
          }}
        />
        <button
          disabled={busyState === 'tracking'}
          onClick={() => { void onSearch(); }}
          style={{
            padding: '0 22px',
            borderRadius: r(12),
            border: 'none',
            background: DS.gradC,
            color: C.text,
            fontWeight: 800,
            fontFamily: DS.F,
            cursor: busyState === 'tracking' ? 'wait' : 'pointer',
            opacity: busyState === 'tracking' ? 0.75 : 1,
          }}
        >
          <Search size={18} />
        </button>
      </div>
      {trackingMessage && (
        <div
          style={{
            marginTop: 14,
            color: trackId.trim().length > 0 && trackedPackage ? DS.cyan : DS.muted,
            fontSize: '0.82rem',
          }}
        >
          {trackingMessage}
        </div>
      )}
      {trackedPackage && trackId.trim().length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          style={{
            marginTop: 20,
            background: C.elevated,
            borderRadius: r(16),
            padding: '20px',
            border: `1px solid ${DS.border}`,
            textAlign: 'left',
            boxShadow: SH.card,
          }}
        >
          <div
            style={{
              display: 'flex',
              justifyContent: 'space-between',
              marginBottom: 16,
              gap: 12,
              flexWrap: 'wrap',
            }}
          >
            <span style={{ color: C.text, fontWeight: 800 }}>
              {tx('activity.packageTitle')}
              {trackedPackage.trackingId}
            </span>
            <span style={{ ...pill(trackedStatusColor) }}>
              {statusLabel(trackedPackage.status, ar)}
            </span>
          </div>
          <div style={{ color: DS.sub, fontSize: '0.82rem', marginBottom: 16 }}>
            {trackedPackage.matchedDriver
              ? ar
                ? `تم التعيين إلى ${trackedPackage.matchedDriver} على مسار متصل من ${routeLabel(trackedPackage.from, trackedPackage.to, ar)}.`
                : `Assigned to ${trackedPackage.matchedDriver} on a connected route from ${trackedPackage.from} to ${trackedPackage.to}.`
              : ar
                ? `ما زلنا نبحث عن مشوار منشور من ${routeLabel(trackedPackage.from, trackedPackage.to, ar)}.`
                : `Still searching for a posted ride from ${trackedPackage.from} to ${trackedPackage.to}.`}
          </div>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
              gap: 10,
              marginBottom: 16,
            }}
          >
            {[
              {
                label: ar ? 'مشاركة الرمز' : 'OTP shared',
                value: trackedPackage.verification.senderCodeSharedAt
                  ? ar
                    ? 'مؤكد'
                    : 'Confirmed'
                  : ar
                    ? 'معلق'
                    : 'Pending',
                tone: trackedPackage.verification.senderCodeSharedAt ? DS.green : DS.gold,
                detail: trackedPackage.verification.senderCodeSharedAt
                  ? ar
                    ? 'المرسل شارك رمز التسليم.'
                    : 'Sender shared the handoff code.'
                  : ar
                    ? 'شارك رمز التسليم عند الاستلام.'
                    : 'Share the handoff code at pickup.',
              },
              {
                label: ar ? 'إثبات الاستلام' : 'Pickup proof',
                value: trackedPackage.verification.riderPickupConfirmedAt
                  ? ar
                    ? 'مؤكد'
                    : 'Confirmed'
                  : ar
                    ? 'معلق'
                    : 'Pending',
                tone: trackedPackage.verification.riderPickupConfirmedAt ? DS.green : DS.gold,
                detail: trackedPackage.verification.riderPickupConfirmedAt
                  ? ar
                    ? 'الراكب أكد استلام الطرد.'
                    : 'Rider has confirmed pickup.'
                  : ar
                    ? 'أكد عندما يستلم الراكب الطرد.'
                    : 'Confirm when the rider receives the parcel.',
              },
              {
                label: ar ? 'إثبات التسليم' : 'Delivery proof',
                value: trackedPackage.verification.receiverDeliveryConfirmedAt
                  ? ar
                    ? 'مؤكد'
                    : 'Confirmed'
                  : ar
                    ? 'معلق'
                    : 'Pending',
                tone: trackedPackage.verification.receiverDeliveryConfirmedAt ? DS.green : DS.gold,
                detail: trackedPackage.verification.receiverDeliveryConfirmedAt
                  ? ar
                    ? 'المستلم أكد التسليم.'
                    : 'Receiver has confirmed delivery.'
                  : ar
                    ? 'أكد فقط بعد تسليم المستلم.'
                    : 'Confirm only after receiver handoff.',
              },
            ].map(item => (
              <div
                key={item.label}
                style={{
                  borderRadius: r(12),
                  border: `1px solid ${item.tone}35`,
                  padding: '12px 13px',
                  background: C.elevated,
                }}
              >
                <div
                  style={{
                    color: DS.muted,
                    fontSize: '0.68rem',
                    textTransform: 'uppercase',
                    letterSpacing: 0,
                  }}
                >
                  {item.label}
                </div>
                <div
                  style={{ color: item.tone, fontWeight: 800, fontSize: '0.82rem', marginTop: 6 }}
                >
                  {item.value}
                </div>
                <div
                  style={{ color: DS.muted, fontSize: '0.72rem', marginTop: 6, lineHeight: 1.45 }}
                >
                  {item.detail}
                </div>
              </div>
            ))}
          </div>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(2, minmax(0, 1fr))',
              gap: 10,
              marginBottom: 16,
            }}
          >
            {[
              { label: ar ? 'رمز التسليم' : 'Handoff code', value: trackedPackage.handoffCode },
              {
                label: ar ? 'تسليم المستلم' : 'Recipient handoff',
                value: trackedPackage.recipientName || (ar ? 'الاسم قيد الانتظار' : 'Name pending'),
              },
            ].map(item => (
              <div
                key={item.label}
                style={{
                  borderRadius: r(12),
                  border: `1px solid ${DS.border}`,
                  padding: '12px 13px',
                  background: C.elevated,
                }}
              >
                <div
                  style={{
                    color: DS.muted,
                    fontSize: '0.7rem',
                    textTransform: 'uppercase',
                    letterSpacing: 0,
                  }}
                >
                  {item.label}
                </div>
                <div style={{ color: C.text, fontWeight: 700, fontSize: '0.82rem', marginTop: 6 }}>
                  {item.value}
                </div>
              </div>
            ))}
          </div>
          <div
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(3, minmax(0, 1fr))',
              gap: 10,
              marginBottom: 16,
            }}
          >
            {[
              {
                label: ar ? 'المسار' : 'Route',
                value: routeLabel(trackedPackage.from, trackedPackage.to, ar),
              },
              {
                label: ar ? 'الوزن' : 'Weight',
                value: ar ? trackedPackage.weight.replace(/kg/g, 'كغ') : trackedPackage.weight,
              },
              {
                label: ar ? 'النوع' : 'Mode',
                value:
                  trackedPackage.packageType === 'return'
                    ? ar
                      ? 'إرجاع'
                      : 'Return'
                    : ar
                      ? 'توصيل'
                      : 'Delivery',
              },
            ].map(item => (
              <div
                key={item.label}
                style={{
                  borderRadius: r(12),
                  border: `1px solid ${DS.border}`,
                  padding: '12px 13px',
                  background: C.elevated,
                }}
              >
                <div
                  style={{
                    color: DS.muted,
                    fontSize: '0.7rem',
                    textTransform: 'uppercase',
                    letterSpacing: 0,
                  }}
                >
                  {item.label}
                </div>
                <div style={{ color: C.text, fontWeight: 700, fontSize: '0.82rem', marginTop: 6 }}>
                  {item.value}
                </div>
              </div>
            ))}
          </div>
          <div style={{ display: 'flex', flexWrap: 'wrap', gap: 10, marginBottom: 18 }}>
            <button
              onClick={() => { void onVerificationAction(); }}
              disabled={Boolean(trackedPackage.verification.senderCodeSharedAt)}
              style={{
                padding: '10px 16px',
                borderRadius: '99px',
                border: 'none',
                background: trackedPackage.verification.senderCodeSharedAt ? C.greenDim : DS.gradG,
                color: C.text,
                cursor: trackedPackage.verification.senderCodeSharedAt ? 'default' : 'pointer',
                fontFamily: DS.F,
                fontWeight: 700,
                opacity: trackedPackage.verification.senderCodeSharedAt ? 0.8 : 1,
              }}
            >
              {trackedPackage.verification.senderCodeSharedAt
                ? ar
                  ? 'تمت مشاركة الرمز'
                  : 'OTP shared'
                : ar
                  ? 'شارك رمز التسليم'
                  : 'Share OTP handoff'}
            </button>
            <button
              onClick={() => { void onVerificationAction(); }}
              disabled={
                !trackedPackage.verification.senderCodeSharedAt ||
                Boolean(trackedPackage.verification.riderPickupConfirmedAt)
              }
              style={{
                padding: '10px 16px',
                borderRadius: '99px',
                border: 'none',
                background: trackedPackage.verification.riderPickupConfirmedAt
                  ? C.greenDim
                  : DS.gradC,
                color: C.text,
                cursor:
                  !trackedPackage.verification.senderCodeSharedAt ||
                  trackedPackage.verification.riderPickupConfirmedAt
                    ? 'default'
                    : 'pointer',
                fontFamily: DS.F,
                fontWeight: 700,
                opacity:
                  !trackedPackage.verification.senderCodeSharedAt ||
                  trackedPackage.verification.riderPickupConfirmedAt
                    ? 0.75
                    : 1,
              }}
            >
              {trackedPackage.verification.riderPickupConfirmedAt
                ? ar
                  ? 'تم تأكيد الاستلام'
                  : 'Pickup confirmed'
                : ar
                  ? 'أكد استلام الراكب'
                  : 'Confirm rider pickup'}
            </button>
            <button
              onClick={() => { void onVerificationAction(); }}
              disabled={
                !trackedPackage.verification.riderPickupConfirmedAt ||
                Boolean(trackedPackage.verification.receiverDeliveryConfirmedAt)
              }
              style={{
                padding: '10px 16px',
                borderRadius: '99px',
                border: 'none',
                background: trackedPackage.verification.receiverDeliveryConfirmedAt
                  ? C.greenDim
                  : DS.gradG,
                color: C.text,
                cursor:
                  !trackedPackage.verification.riderPickupConfirmedAt ||
                  trackedPackage.verification.receiverDeliveryConfirmedAt
                    ? 'default'
                    : 'pointer',
                fontFamily: DS.F,
                fontWeight: 700,
                opacity:
                  !trackedPackage.verification.riderPickupConfirmedAt ||
                  trackedPackage.verification.receiverDeliveryConfirmedAt
                    ? 0.75
                    : 1,
              }}
            >
              {trackedPackage.verification.receiverDeliveryConfirmedAt
                ? ar
                  ? 'تم تأكيد التسليم'
                  : 'Delivery confirmed'
                : ar
                  ? 'أكد تسليم المستلم'
                  : 'Confirm receiver handoff'}
            </button>
          </div>
          <div style={{ display: 'flex', gap: 10, flexWrap: 'wrap', marginBottom: 18 }}>
            <button
              onClick={() => { void onOpenSupport(); }}
              style={{
                padding: '10px 16px',
                borderRadius: '99px',
                border: `1px solid ${DS.border}`,
                background: DS.card2,
                color: C.text,
                cursor: 'pointer',
                fontFamily: DS.F,
                fontWeight: 700,
              }}
            >
              {tx('packageTrackPanel.report_an_issue')}
            </button>
          </div>
          {trackedPackage.timeline.map((step, index) => (
            <div key={index} style={{ display: 'flex', gap: 12, marginBottom: 12 }}>
              <div
                style={{
                  width: 20,
                  height: 20,
                  borderRadius: '50%',
                  background: step.complete ? DS.gradC : DS.card,
                  border: `2px solid ${step.complete ? DS.cyan : DS.border}`,
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'center',
                  flexShrink: 0,
                }}
              >
                {step.complete && <CheckCircle2 size={11} color={C.text} />}
              </div>
              <span
                style={{
                  color: step.complete ? C.text : DS.muted,
                  fontSize: '0.85rem',
                  alignSelf: 'center',
                }}
              >
                {timelineLabel(step.label, ar)}
              </span>
            </div>
          ))}
          <div
            style={{
              marginTop: 16,
              borderRadius: r(14),
              overflow: 'hidden',
              border: `1px solid ${DS.border}`,
            }}
          >
            <MapWrapper
              mode="live"
              center={midpoint(
                resolveCityCoord(trackedPackage.from),
                resolveCityCoord(trackedPackage.to),
              )}
              pickupLocation={resolveCityCoord(trackedPackage.from)}
              dropoffLocation={resolveCityCoord(trackedPackage.to)}
              driverLocation={midpoint(
                resolveCityCoord(trackedPackage.from),
                resolveCityCoord(trackedPackage.to),
              )}
              height={220}
              showMosques={false}
              showRadars={false}
            />
          </div>
        </motion.div>
      )}
      {!trackedPackage && trackId.trim().length > 0 && (
        <div style={{ marginTop: 18, color: DS.muted, fontSize: '0.85rem' }}>
          {tx('packageTrackPanel.no_connected_package_found_for_that_tracking_id_yet')}
        </div>
      )}
      {recentPackages.length > 0 && (
        <div style={{ marginTop: 24, textAlign: 'left' }}>
          <div style={{ color: C.text, fontWeight: 800, marginBottom: 10 }}>
            {tx('packageTrackPanel.recent_tracking_shortcuts')}
          </div>
          <div style={{ display: 'grid', gap: 10 }}>
            {recentPackages.map(item => (
              <button
                key={item.trackingId}
                onClick={() => { void onOpenRecent(item); }}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  justifyContent: 'space-between',
                  gap: 12,
                  width: '100%',
                  textAlign: 'left',
                  borderRadius: r(12),
                  border: `1px solid ${DS.border}`,
                  padding: '12px 14px',
                  background: DS.card2,
                  cursor: 'pointer',
                }}
              >
                <div>
                  <div style={{ color: C.text, fontWeight: 700, fontSize: '0.82rem' }}>
                    {item.trackingId}
                  </div>
                  <div style={{ color: DS.muted, fontSize: '0.74rem', marginTop: 4 }}>
                    {cityLabel(item.from, ar)} {tx('packageTrackPanel.to')}
                    {cityLabel(item.to, ar)}
                  </div>
                </div>
                <span style={{ ...pill(item.matchedRideId ? DS.green : DS.gold) }}>
                  {statusLabel(item.status, ar)}
                </span>
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

