/**
 * ProfilePage - /app/profile
 */
import { useEffect, useRef, useState } from 'react';
import {
  Bell,
  Camera,
  Car,
  CheckCircle,
  Clock,
  CreditCard,
  FileText,
  Key,
  LogOut,
  Monitor,
  Settings,
  Shield,
  Star,
  TrendingUp,
} from 'lucide-react';
import { ProtectedPagePreview } from '../../components/system/ProtectedPagePreview';
import { PageHero, PageShell, StatusBadge } from '../../components/wasel-ui/WaselPagePrimitives';
import { WaselButton } from '../../components/wasel-ui';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/LanguageContext';
import { useLocalAuth } from '../../contexts/LocalAuth';
import { useIframeSafeNavigate } from '../../hooks/useIframeSafeNavigate';
import { usePushNotifications } from '../../hooks/usePushNotifications';
import { C, GRAD, R, SH, SPACE } from '../../utils/wasel-ds';
import { getProfileInitials } from './profileUtils';
import {
  InsightCard as SharedInsightCard,
  QuickActionCard as SharedQuickActionCard,
  Row as SharedRow,
  Section as SharedSection,
  StatCard as SharedStatCard,
  VerificationBadge as SharedVerificationBadge,
} from './components/ProfilePageParts';
import {
  PROFILE_BG as BG,
  PROFILE_BORDER as BORD,
  PROFILE_CYAN as CYAN,
  PROFILE_FONT as FONT,
  useProfilePageController,
} from './useProfilePageController';

function showToast(message: string) {
  const element = document.createElement('div');
  element.textContent = message;
  Object.assign(element.style, {
    position: 'fixed',
    bottom: '24px',
    left: '50%',
    transform: 'translateX(-50%)',
    background: C.cardSolid,
    border: `1px solid ${C.borderHov}`,
    color: C.text,
    padding: '10px 20px',
    borderRadius: '10px',
    fontSize: '0.85rem',
    zIndex: '9999',
    boxShadow: SH.md,
  });
  document.body.appendChild(element);
  setTimeout(() => element.remove(), 2800);
}

export default function ProfilePage() {
  const { user, signOut, updateUser } = useLocalAuth();
  const { updateProfile } = useAuth();
  const { language, t } = useLanguage();
  const nav = useIframeSafeNavigate();
  const { isSupported, permission, requestPermission } = usePushNotifications();
  const ar = language === 'ar';
  const photoInputRef = useRef<HTMLInputElement>(null);

  if (!user) {
    return <ProtectedPagePreview pathname="/app/profile" />;
  }

  return (
    <ProfilePageContent
      user={user}
      signOut={signOut}
      updateProfile={updateProfile}
      updateUser={updateUser}
      ar={ar}
      t={t}
      nav={nav}
      isSupported={isSupported}
      permission={permission}
      requestPermission={requestPermission}
      photoInputRef={photoInputRef}
    />
  );
}

interface ProfilePageContentProps {
  user: NonNullable<ReturnType<typeof useLocalAuth>['user']>;
  signOut: ReturnType<typeof useLocalAuth>['signOut'];
  updateProfile: ReturnType<typeof useAuth>['updateProfile'];
  updateUser: ReturnType<typeof useLocalAuth>['updateUser'];
  ar: boolean;
  t: (key: string) => string;
  nav: ReturnType<typeof useIframeSafeNavigate>;
  isSupported: boolean;
  permission: NotificationPermission;
  requestPermission: () => Promise<NotificationPermission>;
  photoInputRef: React.MutableRefObject<HTMLInputElement | null>;
}

function ProfilePageContent({
  user,
  signOut,
  updateProfile,
  updateUser,
  ar,
  t,
  nav,
  isSupported,
  permission,
  requestPermission,
  photoInputRef,
}: ProfilePageContentProps) {
  const [avatarError, setAvatarError] = useState(false);
  const {
    editingField,
    handleDeletionContinue,
    handleExportData,
    handleNotificationSetup,
    handlePhotoSelection,
    handleSaveName,
    handleSavePhone,
    handleSignOut,
    joinedText,
    nameInput,
    permissionStatus,
    phoneInput,
    profileCompleteness,
    quickActions,
    roleLabel,
    savingField,
    setEditingField,
    setNameInput,
    setPhoneInput,
    setShowDeleteConfirm,
    showDeleteConfirm,
    trustTier,
    verificationItems,
    walletStatus,
  } = useProfilePageController({
    user,
    ar,
    nav,
    updateProfile,
    updateUser,
    notificationSupport: {
      isSupported,
      permission,
      requestPermission,
    },
    showToast,
    signOut,
    photoInputRef,
  });

  const initials = getProfileInitials(user.name);
  const memberLabel = user.joinedAt
    ? `${t('profileExpanded.memberSince')} ${joinedText}`
    : t('profileExpanded.waselMember');

  useEffect(() => {
    if (editingField !== 'name') {setNameInput(user.name ?? '');}
    if (editingField !== 'phone') {setPhoneInput(user.phone ?? '');}
  }, [editingField, setNameInput, setPhoneInput, user.name, user.phone]);

  return (
    <PageShell maxWidth={820} dir={ar ? 'rtl' : 'ltr'}>
      <div style={{ paddingInline: SPACE[4] }}>
        <input
          ref={photoInputRef}
          type="file"
          accept="image/*"
          onChange={() => { void handlePhotoSelection(); }}
          style={{ display: 'none' }}
        />

        <PageHero
          eyebrow={t('profileExpanded.accountIdentity')}
          icon={<StatusBadge label={roleLabel} accent={CYAN} />}
          title={user.name}
          description={`${user.email} · ${t('profileExpanded.trustScore')} ${user.trustScore}/100 · ${memberLabel}`}
          accent={CYAN}
          actions={
            <>
              <WaselButton
                onClick={() => {
                  setNameInput(user.name);
                  setEditingField('name');
                }}
                className="bg-primary text-primary-foreground hover:bg-primary/90"
              >
                {t('profileExpanded.editName')}
              </WaselButton>
              <WaselButton
                variant="outline"
                onClick={() => { void nav(); }}
                className="border-white/15 bg-white/5 text-white hover:bg-white/10"
              >
                {t('profileExpanded.trustCenter')}
              </WaselButton>
              <WaselButton
                variant="outline"
                onClick={() => { void nav(); }}
                className="border-white/15 bg-white/5 text-white hover:bg-white/10"
              >
                {t('profileExpanded.settings')}
              </WaselButton>
            </>
          }
          aside={
            <div style={{ display: 'grid', justifyItems: 'center', gap: 12 }}>
              <div style={{ position: 'relative' }}>
                <div
                  style={{
                    width: 92,
                    height: 92,
                    borderRadius: R.full,
                    background: GRAD,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '1.9rem',
                    fontWeight: 900,
                    color: C.bgDeep,
                    boxShadow: SH.blueL,
                    overflow: 'hidden',
                  }}
                >
                  {user.avatar && !avatarError ? (
                    <img
                      src={user.avatar}
                      alt={user.name}
                      onError={() => setAvatarError(true)}
                      style={{ width: '100%', height: '100%', objectFit: 'cover' }}
                    />
                  ) : (
                    initials
                  )}
                </div>
                <button
                  title={t('profileExpanded.changePhoto')}
                  onClick={() => photoInputRef.current?.click()}
                  disabled={savingField === 'photo'}
                  style={{
                    position: 'absolute',
                    bottom: 0,
                    right: 0,
                    width: 30,
                    height: 30,
                    borderRadius: R.full,
                    background: C.cardSolid,
                    border: `2px solid ${BG}`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    cursor: savingField === 'photo' ? 'not-allowed' : 'pointer',
                    opacity: savingField === 'photo' ? 0.65 : 1,
                  }}
                >
                  {savingField === 'photo' ? (
                    <Clock size={12} color={CYAN} />
                  ) : (
                    <Camera size={12} color={CYAN} />
                  )}
                </button>
              </div>
              <SharedVerificationBadge
                level={user.verificationLevel ?? 'level_0'}
                ar={ar}
                accent={CYAN}
              />
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', justifyContent: 'center' }}>
                <StatusBadge label={`${walletStatus.label}`} accent={walletStatus.color} />
                <StatusBadge label={permissionStatus.label} accent={permissionStatus.color} />
              </div>
            </div>
          }
        />

        {editingField === 'name' ? (
          <SharedSection title={t('profileExpanded.quickEdit')}>
            <div
              style={{
                padding: 18,
                display: 'flex',
                gap: 8,
                alignItems: 'center',
                flexWrap: 'wrap',
              }}
            >
              <input
                value={nameInput}
                onChange={event => setNameInput(event.target.value)}
                autoFocus
                style={{
                  flex: '1 1 240px',
                  minWidth: 0,
                  padding: '10px 12px',
                  borderRadius: 10,
                  border: `1.5px solid ${CYAN}`,
                  background: C.cyanDim,
                  color: C.text,
                  fontSize: '0.9rem',
                  fontFamily: FONT,
                  outline: 'none',
                }}
                onKeyDown={event => {
                  if (event.key === 'Enter') {void handleSaveName();}
                  if (event.key === 'Escape') {setEditingField(null);}
                }}
                maxLength={60}
              />
              <button
                onClick={() => void handleSaveName()}
                disabled={savingField !== null}
                style={{
                  padding: '10px 14px',
                  borderRadius: 10,
                  background: CYAN,
                  border: 'none',
                  color: C.bgDeep,
                  fontWeight: 700,
                  cursor: 'pointer',
                  fontSize: '0.8rem',
                  fontFamily: FONT,
                }}
              >
                {savingField === 'name' ? '...' : t('profileExpanded.save')}
              </button>
              <button
                onClick={() => { void setEditingField(null); }}
                style={{
                  padding: '10px 12px',
                  borderRadius: 10,
                  background: C.elevated,
                  border: `1px solid ${BORD}`,
                  color: C.textMuted,
                  cursor: 'pointer',
                  fontSize: '0.8rem',
                  fontFamily: FONT,
                }}
              >
                {t('profileExpanded.cancel')}
