              disabled={soldOut}
              style={{
                height: 44,
                padding: '0 18px',
                borderRadius: '99px',
                border: 'none',
                background: hasBooking
                  ? bookingStatus === 'pending_driver'
                    ? DS.gradGold
                    : DS.gradG
                  : soldOut
                    ? C.elevated
                    : DS.gradC,
                color: C.text,
                fontWeight: 800,
                fontSize: '0.82rem',
                boxShadow: `0 4px 16px ${
                  hasBooking
                    ? bookingStatus === 'pending_driver'
                      ? DS.gold
                      : DS.green
                    : soldOut
                      ? C.elevated
                      : DS.cyan
                }30`,
                cursor: soldOut ? 'not-allowed' : 'pointer',
                opacity: soldOut ? 0.88 : 1,
              }}
            >
               {hasBooking
                 ? ar ? 'افتح في رحلاتي' : 'Open in My Trips'
                 : soldOut
                   ? ar ? 'ممتلئ' : 'Sold out'
                   : ar ? 'عرض التفاصيل' : 'View details'}
             </button>
           </div>
         </div>
       </div>
     </div>
   );
});

