source:
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { toast } from 'sonner';
import {
  Activity,
  AlertTriangle,
  BadgeCheck,
  CheckCircle2,
  FileCheck,
  Headphones,
  MailCheck,
  Package,
  Shield,
  Wallet,
} from 'lucide-react';
import { WaselButton } from '../../components/wasel-ui/WaselButton';
import { WaselDialog, WaselInput, WaselLogo } from '../../components/wasel-ui';
import { ProtectedPagePreview } from '../../components/system/ProtectedPagePreview';
import {
  MetricCard,
  PageHero,
  PageShell,
  SectionCard,
  StatusBadge,
} from '../../components/wasel-ui/WaselPagePrimitives';
import {
  FailureNotice,
  ReviewTimeline,
  StepCard,
  TrustActionRow,
  TrustOnboarding,
  TrustScoreDisplay,
  TrustScoreExplanation,
  TrustSkeleton,
  VerificationSteps,
  stateAccent,
} from './components';
import { useAuth } from '../../contexts/AuthContext';
import { useLanguage } from '../../contexts/LanguageContext';
import { useLocalAuth } from '../../contexts/LocalAuth';
import { useIframeSafeNavigate } from '../../hooks/useIframeSafeNavigate';
import {
  confirmTrustPhoneVerification,
  enableTrustDriverMode,
  fetchReviewHistory,
  getTrustCenterStatus,
  resendTrustEmailConfirmation,
  startTrustPhoneVerification,
  submitTrustDriverDocuments,
  submitTrustIdentityVerification,
} from '../../services/trustCenter';
import {
  buildFallbackTrustCenterStatus,
  type ReviewHistoryItem,
  type TrustCenterStatus,
  type TrustStepState,
} from '../../services/trustCenterModel';
import { evaluateTrustCapability } from '../../services/trustRules';
import { C, F, GRAD_AURORA, R, SH, SPACE, TYPE } from '../../utils/wasel-ds';

function toErrorMessage(error: unknown): string {
  if (error instanceof Error) {return error.message;}
  return 'Trust Center request failed.';
}

function isNewUser(status: TrustCenterStatus | null): boolean {
  if (!status) {return false;}
  return status.completedSteps === 0 && status.nextStepId !== null;
}

function applyOptimisticStepUpdate(
  status: TrustCenterStatus,
  stepId: TrustStepState extends 'completed' ? 'identity' | 'email' | 'phone' | 'driver_documents' | 'wallet_standing' : string,
  newState: TrustStepState,
): TrustCenterStatus {
  const next = { ...status, steps: { ...status.steps } } as TrustCenterStatus;
  const stepKey = stepId as keyof TrustCenterStatus['steps'];
  if (stepKey in next.steps) {
    next.steps = {
      ...next.steps,
      [stepKey]: {
        ...next.steps[stepKey],
        state: newState,
      },
    };
  }
  const allSteps = Object.values(next.steps);
  next.completedSteps = allSteps.filter((s) => s.state === 'completed').length;
  next.totalSteps = allSteps.length;
  next.nextStepId = (() => {
    const ordered = [next.steps.phone, next.steps.email, next.steps.identity, next.steps.driverDocuments, next.steps.walletStanding];
    return ordered.find((s) => s.state !== 'completed')?.id ?? null;
  })();
  next.blockedSteps = allSteps.filter((s) => s.state === 'failed').map((s) => s.id);
  return next;
}

function getStepBadge(state: TrustStepState, t: (key: string) => string) {
  switch (state) {
    case 'completed':
      return { label: t('trustCenterExpanded.completed'), accent: C.green };
    case 'in_progress':
      return { label: t('trustCenterExpanded.inProgress'), accent: C.cyan };
    case 'failed':
      return { label: t('trustCenterExpanded.failed'), accent: C.error };
    default:
      return { label: t('trustCenterExpanded.notStarted'), accent: C.gold };
  }
}

function formatTimestamp(value?: string | null): string | null {
  if (!value) {return null;}
  const date = new Date(value);
  if (Number.isNaN(date.getTime())) {return null;}
  return date.toLocaleString();
}

function getTrustStepTitle(stepId: string | null, t: (key: string) => string): string {
  switch (stepId) {
    case 'identity':
      return t('trustCenterExpanded.identity');
    case 'email':
      return t('trustCenterExpanded.email');
    case 'phone':
      return t('trustCenterExpanded.phone');
    case 'driver_documents':
      return t('trustCenterExpanded.driverDocuments');
    case 'wallet_standing':
      return t('trustCenterExpanded.walletStanding');
    default:
      return t('trustCenterExpanded.ready');
  }
}

function getNextTrustStepDetail(
  status: TrustCenterStatus | null,
  t: (key: string) => string,
): string {
  if (!status?.nextStepId) {
    return t('trustCenterExpanded.allCapabilitiesReady');
  }

  switch (status.nextStepId) {
    case 'identity':
      return status.steps.identity.detail;
    case 'email':
      return status.steps.email.detail;
    case 'phone':
      return status.steps.phone.detail;
    case 'driver_documents':
      return status.steps.driverDocuments.detail;
    case 'wallet_standing':
      return status.steps.walletStanding.detail;
    default:
      return t('trustCenterExpanded.reviewFlowBelow');
  }
}

export default function TrustCenterPage() {
  const { language, t } = useLanguage();
  const { refreshProfile } = useAuth();
  const { user, updateUser } = useLocalAuth();
  const nav = useIframeSafeNavigate();
  const ar = language === 'ar';
  const workflowRef = useRef<HTMLDivElement | null>(null);
  const identityRef = useRef<HTMLDivElement | null>(null);
  const contactRef = useRef<HTMLDivElement | null>(null);
  const documentsRef = useRef<HTMLDivElement | null>(null);
  const walletRef = useRef<HTMLDivElement | null>(null);

  const [trustStatus, setTrustStatus] = useState<TrustCenterStatus | null>(null);
  const [statusLoading, setStatusLoading] = useState(false);
  const [initialLoading, setInitialLoading] = useState(true);
  const [actionKey, setActionKey] = useState<string | null>(null);
  const [phoneInput, setPhoneInput] = useState(user?.phone ?? '');
  const [phoneCode, setPhoneCode] = useState('');
  const [identityReference, setIdentityReference] = useState('');
  const [identityDocumentReference, setIdentityDocumentReference] = useState('');
  const [licenseNumber, setLicenseNumber] = useState('');
  const [driverDocumentReference, setDriverDocumentReference] = useState('');
  const [confirmState, setConfirmState] = useState<{
    open: boolean;
    title: string;
    description: string;
    onConfirm: () => void;
  }>({ open: false, title: '', description: '', onConfirm: () => {} });
  const [validationErrors, setValidationErrors] = useState<Record<string, string | null>>({});
  const [reviewHistory, setReviewHistory] = useState<ReviewHistoryItem[]>([]);
  const [onboardingDismissed, setOnboardingDismissed] = useState(false);
  const [pendingSync, setPendingSync] = useState(false);
  const previousStatusRef = useRef<TrustCenterStatus | null>(null);

  const fallbackStatus = useMemo(
    () => (user ? buildFallbackTrustCenterStatus(user) : null),
    [user],
  );
  const effectiveStatus = trustStatus ?? fallbackStatus;

  useEffect(() => {
    setPhoneInput(user?.phone ?? '');
  }, [user?.phone]);

  useEffect(() => {
    if (!effectiveStatus) {return;}

    const providerReference = effectiveStatus.steps.identity.meta.providerReference;
    const documentReference = effectiveStatus.steps.identity.meta.documentReference;
    const existingLicense = effectiveStatus.steps.driverDocuments.meta.licenseNumber;

    if (providerReference && !identityReference) {setIdentityReference(providerReference);}
    if (documentReference && !identityDocumentReference) {
      setIdentityDocumentReference(documentReference);
    }
    if (existingLicense && !licenseNumber) {setLicenseNumber(existingLicense);}
  }, [effectiveStatus, identityDocumentReference, identityReference, licenseNumber]);

  const reloadTrustStatus = useCallback(async (silent = false) => {
    if (!user) {return;}
    if (!silent) {setStatusLoading(true);}

    try {
      const nextStatus = await getTrustCenterStatus(user);
      setTrustStatus(nextStatus);
      previousStatusRef.current = nextStatus;
    } catch (error) {
      const fallback = buildFallbackTrustCenterStatus(user);
      setTrustStatus(fallback);
      previousStatusRef.current = fallback;
      if (!silent) {
        console.warn('[Trust Center] Using fallback status:', error);
      }
    } finally {
      if (!silent) {setStatusLoading(false);}
      if (silent) {setInitialLoading(false);}
    }
  }, [user]);

  const loadReviewHistory = useCallback(async () => {
    try {
      const items = await fetchReviewHistory();
      setReviewHistory(items);
    } catch {
      setReviewHistory([]);
    }
  }, []);

  const emailBadge = useMemo(
    () => getStepBadge(effectiveStatus?.steps.email.state ?? 'not_started', t),
    [t, effectiveStatus?.steps.email.state],
  );
  const phoneBadge = useMemo(
    () => getStepBadge(effectiveStatus?.steps.phone.state ?? 'not_started', t),
    [t, effectiveStatus?.steps.phone.state],
  );

  useEffect(() => {
    if (!user) {
      setTrustStatus(null);
      setInitialLoading(false);
      setReviewHistory([]);
      return;
    }
    setInitialLoading(true);
    void reloadTrustStatus(true);
    void loadReviewHistory();
  }, [
    user?.id,
    user?.email,
    user?.phone,
    user?.emailVerified,
    user?.phoneVerified,
    user?.sanadVerified,
    user?.verified,
    user?.verificationLevel,
    user?.walletStatus,
    user?.role,
  ]);

  if (!user) {
    return <ProtectedPagePreview pathname="/app/trust" />;
  }

  const capabilityRows = [
    {
      title: t('trustCenterExpanded.postRides'),
      icon: <BadgeCheck size={18} />,
      gate: evaluateTrustCapability(user, 'offer_ride'),
    },
    {
      title: t('trustCenterExpanded.carryPackages'),
      icon: <Package size={18} />,
      gate: evaluateTrustCapability(user, 'carry_packages'),
    },
    {
      title: t('trustCenterExpanded.receivePayouts'),
      icon: <Wallet size={18} />,
      gate: evaluateTrustCapability(user, 'receive_payouts'),
    },
    {
      title: t('trustCenterExpanded.prioritySupport'),
      icon: <Headphones size={18} />,
      gate: evaluateTrustCapability(user, 'priority_support'),
    },
  ];
  const unlockedCount = capabilityRows.filter(item => item.gate.allowed).length;
  const lockedCapabilities = capabilityRows.filter(item => !item.gate.allowed);
  const walletStep = effectiveStatus?.steps.walletStanding;
  const walletTone =
    walletStep?.meta.walletStatus === 'closed'
      ? { label: t('trustCenterExpanded.closed'), color: C.error }
      : walletStep?.meta.walletStatus === 'frozen'
        ? { label: t('trustCenterExpanded.frozen'), color: C.error }
        : walletStep?.meta.walletStatus === 'limited'
          ? { label: t('trustCenterExpanded.limited'), color: C.gold }
          : walletStep?.meta.walletStatus === 'unavailable'
            ? { label: t('trustCenterExpanded.unavailable'), color: C.error }
            : { label: t('trustCenterExpanded.active'), color: C.green };
  const heroAccent = effectiveStatus?.blockedSteps.length
    ? C.error
    : effectiveStatus?.nextStepId
      ? C.cyan
      : C.green;
  const heroLabel = effectiveStatus?.blockedSteps.length
    ? t('trustCenterExpanded.needsReview')
    : effectiveStatus?.nextStepId
      ? t('trustCenterExpanded.actionNeeded')
      : t('trustCenterExpanded.ready');
  const showOnboarding = isNewUser(effectiveStatus) && !onboardingDismissed;

  const runAction = async (key: string, work: () => Promise<void>, optimisticPatch?: (current: TrustCenterStatus) => TrustCenterStatus) => {
    setActionKey(key);
    setPendingSync(true);
    const previous = previousStatusRef.current;
    if (optimisticPatch && previous) {
      const optimistic = optimisticPatch(previous);
      setTrustStatus(optimistic);
      previousStatusRef.current = optimistic;
    }
    try {
      await work();
      toast.success(t('trustCenterExpanded.validationSyncComplete'));
    } catch (error) {
      if (previous) {
        setTrustStatus(previous);
        previousStatusRef.current = previous;
      }
      toast.error(toErrorMessage(error));
    } finally {
      setActionKey(null);
      setPendingSync(false);
    }
  };

  const handleNextAction = () => {
    switch (effectiveStatus?.nextStepId) {
      case 'identity':
        identityRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        break;
      case 'email':
      case 'phone':
        contactRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        break;
      case 'driver_documents':
        documentsRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        break;
      case 'wallet_standing':
        walletRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        break;
      default:
        workflowRef.current?.scrollIntoView({ behavior: 'smooth', block: 'start' });
        break;
    }
  };

  const handleResendEmail = async () => {
    if (!user.email) {
      toast.error(t('trustCenterExpanded.validationRequired'));
      return;
    }

    await runAction('email', async () => {
      await resendTrustEmailConfirmation(user.email);
      toast.success(t('trustCenterExpanded.sendConfirmation') + ' ' + user.email);
      await reloadTrustStatus(true);
    });
  };

  const handleStartPhone = async () => {
    const normalizedPhone = phoneInput.trim();
    if (!normalizedPhone) {
      setValidationErrors((prev) => ({ ...prev, phone: t('trustCenterExpanded.validationRequired') }));
      return;
    }
    setValidationErrors((prev) => ({ ...prev, phone: null }));

    await runAction('phone-start', async () => {
      const result = await startTrustPhoneVerification({ phoneNumber: normalizedPhone });
      updateUser({ phone: result.phoneNumber, phoneVerified: false });
      await refreshProfile();
      await reloadTrustStatus(true);
      toast.success(t('trustCenterExpanded.sendCode') + ' ' + result.phoneNumber);
    }, (current) => applyOptimisticStepUpdate(current, 'phone', 'in_progress'));
  };

  const handleConfirmPhone = async () => {
    if (!phoneCode.trim()) {
      setValidationErrors((prev) => ({ ...prev, phoneCode: t('trustCenterExpanded.validationRequired') }));
      return;
    }
    setValidationErrors((prev) => ({ ...prev, phoneCode: null }));

    await runAction('phone-confirm', async () => {
      const result = await confirmTrustPhoneVerification({ code: phoneCode.trim() });
      setPhoneCode('');
      updateUser({
        phone: result.phoneNumber,
        phoneVerified: true,
      });
      await refreshProfile();
      await reloadTrustStatus(true);
      toast.success(t('trustCenterExpanded.confirmPhone'));
    }, (current) => applyOptimisticStepUpdate(current, 'phone', 'completed'));
  };

  const handleSubmitIdentity = async () => {
    if (identityReference.trim().length < 6) {
      setValidationErrors((prev) => ({ ...prev, identityReference: t('trustCenterExpanded.validationTooShort').replace('{min}', '6') }));
      return;
    }
    setValidationErrors((prev) => ({ ...prev, identityReference: null }));

    await runAction('identity', async () => {
      await submitTrustIdentityVerification({
        providerReference: identityReference.trim(),
        documentReference: identityDocumentReference.trim() || undefined,
      });
      updateUser({ verificationLevel: 'level_1' });
      await reloadTrustStatus(true);
      await refreshProfile();
      await loadReviewHistory();
      toast.success(t('trustCenterExpanded.submitForReview'));
    }, (current) => applyOptimisticStepUpdate(current, 'identity', 'in_progress'));
  };

  const handleEnableDriverMode = async () => {
    setConfirmState({
      open: true,
      title: t('trustCenterExpanded.enableDriverMode'),
      description:
        t('trustCenterExpanded.identityHelpBody'),
      onConfirm: async () => {
        setConfirmState(prev => ({ ...prev, open: false }));
        await runAction('driver-mode', async () => {
          await enableTrustDriverMode();
          updateUser({ role: 'driver' });
          await refreshProfile();
          await reloadTrustStatus(true);
          toast.success(t('trustCenterExpanded.enableDriverMode') + ' ' + t('trustCenterExpanded.capabilityReady'));
        });
      },
    });
  };

  const handleSubmitDriverDocuments = async () => {
    if (licenseNumber.trim().length < 6) {
      setValidationErrors((prev) => ({ ...prev, licenseNumber: t('trustCenterExpanded.validationTooShort').replace('{min}', '6') }));
      return;
    }
    setValidationErrors((prev) => ({ ...prev, licenseNumber: null }));

    setConfirmState({      open: true,
      title: t('trustCenterExpanded.driverDocumentsTitle'),
      description:
        t('trustCenterExpanded.submitDocuments') + '. ' + t('trustCenterExpanded.reviewFlowBelow'),
      onConfirm: async () => {
        setConfirmState(prev => ({ ...prev, open: false }));
        await runAction('driver-documents', async () => {
          await submitTrustDriverDocuments({
            licenseNumber: licenseNumber.trim(),
            documentReference: driverDocumentReference.trim() || undefined,
          });
          updateUser({ verificationLevel: 'level_2' });
          await reloadTrustStatus(true);
          await refreshProfile();
          await loadReviewHistory();
          toast.success(t('trustCenterExpanded.submitDocuments'));
        }, (current) => applyOptimisticStepUpdate(current, 'driver_documents', 'in_progress'));
      },
    });
  };

  const identityStep = effectiveStatus?.steps.identity;
  const emailStep = effectiveStatus?.steps.email;
  const phoneStep = effectiveStatus?.steps.phone;
  const driverStep = effectiveStatus?.steps.driverDocuments;
  const walletStandingStep = effectiveStatus?.steps.walletStanding;

  return (
    <PageShell maxWidth={880} dir={ar ? 'rtl' : 'ltr'}>
      <div style={{ paddingInline: SPACE[4] }} aria-live="polite">
        {initialLoading && !trustStatus ? (
          <TrustSkeleton />
        ) : (
          <>
            {showOnboarding && (
              <TrustOnboarding
                t={t}
                onDismiss={() => setOnboardingDismissed(true)}
                onStart={() => {
                  setOnboardingDismissed(true);
                  handleNextAction();
                }}
              />
            )}
            <div
              aria-hidden="true"
              style={{
                position: 'relative',
                marginBottom: -SPACE[6],
                pointerEvents: 'none',
              }}
            >
              <div
                style={{
                  position: 'absolute',
                  inset: 0,
                  background: GRAD_AURORA,
                  opacity: 0.7,
                  filter: 'blur(40px)',
                  transform: 'scale(1.05)',
                }}
              />
            </div>
            <PageHero
          eyebrow={t('trustCenterExpanded.eyebrow')}
          icon={<StatusBadge label={heroLabel} accent={heroAccent} />}
          title={t('trustCenterExpanded.title')}
          description={
            effectiveStatus
              ? effectiveStatus.nextStepId
                ? t('trustCenterExpanded.remainingChecks').replace(
                    '{remaining}',
                    String(effectiveStatus.totalSteps - effectiveStatus.completedSteps),
                  )
                : t('trustCenterExpanded.allResolved')
              : t('trustCenterExpanded.loadingState')
          }
          accent={heroAccent}
          actions={
            <>
              <WaselButton onClick={() => { void handleNextAction(); }} variant="primary">
                {effectiveStatus?.nextStepId
                  ? t('trustCenterExpanded.openNextStep')
                  : t('trustCenterExpanded.reviewSteps')}
              </WaselButton>
              <WaselButton
                variant="outline"
                loading={statusLoading}
                onClick={() => {
                  void reloadTrustStatus();
                }}
              >
                {t('trustCenterExpanded.refreshStatus')}
              </WaselButton>
            </>
          }
          aside={
            <div style={{ display: 'grid', gap: SPACE[3] }}>
              <div style={{ display: 'flex', justifyContent: 'flex-end' }}>
                <WaselLogo size={28} theme="dark" />
              </div>
              <div
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: SPACE[3],
                  flexWrap: 'wrap',
                }}
              >
                <StatusBadge
                  label={
                    effectiveStatus
                      ? t('trustCenterExpanded.stepCounter')
                          .replace('{completed}', String(effectiveStatus.completedSteps))
                          .replace('{total}', String(effectiveStatus.totalSteps))
                      : t('trustCenterExpanded.stepCounter')
                          .replace('{completed}', '0')
                          .replace('{total}', '5')
                  }
                  accent={C.cyan}
                />
                <StatusBadge
                  label={t('trustCenterExpanded.unlocked').replace(
                    '{count}',
                    String(unlockedCount),
                  )}
                  accent={C.green}
                />
              </div>
              <TrustScoreDisplay
                score={user.trustScore}
                label={t('trustCenterExpanded.trustScore')}
                scoreLabel={
                  user.trustScore >= 80
                    ? t('trustCenterExpanded.scoreStrong')
                    : user.trustScore >= 50
                      ? t('trustCenterExpanded.scoreFair')
                      : t('trustCenterExpanded.scoreWeak')
                }
                dir={ar ? 'rtl' : 'ltr'}
              />
              <TrustScoreExplanation score={user.trustScore} t={t} compact />
              <div style={{ color: C.textMuted, fontSize: TYPE.size.sm, lineHeight: TYPE.lineHeight.relaxed, fontFamily: F }}>
                {t('trustCenterExpanded.eachCardShowsState')}
              </div>
            </div>
          }
        />

        {pendingSync && (
          <div
            role="status"
            style={{
              padding: `${SPACE[3]} ${SPACE[4]}`,
              borderRadius: R.lg,
              border: `1px solid ${C.cyan}33`,
              background: `${C.cyan}12`,
              color: C.cyan,
              fontSize: TYPE.size.sm,
              fontFamily: F,
            }}
          >
            {t('trustCenterExpanded.validationPendingSync')}
          </div>
        )}

        <VerificationSteps
          steps={(effectiveStatus?.steps ?? {}) as Record<string, { state: string; detail?: string }>}
          t={t}
          dir={ar ? 'rtl' : 'ltr'}
        />

        <div
          className="trust-metrics-grid"
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))',
            gap: SPACE[4],
            marginBottom: SPACE[6],
          }}
        >
          <MetricCard
            label={t('trustCenterExpanded.trustScore')}
            value={`${user.trustScore}/100`}
            detail={t('trustCenterExpanded.trustScoreDetail')}
            icon={<Shield size={18} />}
            accent={heroAccent}
          />
          <MetricCard
            label={t('trustCenterExpanded.checksDone')}
            value={
              effectiveStatus
                ? `${effectiveStatus.completedSteps}/${effectiveStatus.totalSteps}`
                : '0/5'
            }
            detail={t('trustCenterExpanded.checksDoneDetail')}
            icon={<CheckCircle2 size={18} />}
            accent={C.cyan}
          />
          <MetricCard
            label={t('trustCenterExpanded.blockedChecks')}
            value={`${effectiveStatus?.blockedSteps.length ?? 0}`}
            detail={t('trustCenterExpanded.failedStepsDetail')}
            icon={<Activity size={18} />}
            accent={(effectiveStatus?.blockedSteps.length ?? 0) > 0 ? C.error : C.green}
          />
          <MetricCard
            label={t('trustCenterExpanded.walletStatus')}
            value={walletTone.label}
            detail={t('trustCenterExpanded.walletDetail')}
            icon={<Wallet size={18} />}
            accent={walletTone.color}
          />
        </div>

        <SectionCard
          title={t('trustCenterExpanded.nextUnlock')}
          subtitle={t('trustCenterExpanded.capabilitiesStillGated')}
          icon={<BadgeCheck size={16} color={heroAccent} />}
        >
          <div
            className="trust-capability-grid"
            style={{
              display: 'grid',
              gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))',
              gap: SPACE[4],
            }}
          >
            <div
              style={{
                display: 'grid',
                gap: SPACE[4],
                padding: SPACE[5],
                borderRadius: R.xxl,
                border: `1px solid ${heroAccent}24`,
                background: `radial-gradient(circle at top left, ${heroAccent}12, transparent 34%), ${C.card}`,
                boxShadow: SH.md,
              }}
            >
              <div
                style={{
                  color: heroAccent,
                  fontSize: TYPE.size.xs,
                  fontWeight: TYPE.weight.bold,
                  textTransform: 'uppercase',
                  letterSpacing: TYPE.letterSpacing.wider,
                  fontFamily: F,
                }}
              >
                {t('trustCenterExpanded.nextUnlock')}
              </div>
              <div
                style={{
                  color: C.text,
                  fontSize: TYPE.size.xl,
                  fontWeight: TYPE.weight.ultra,
                  fontFamily: F,
                }}
              >
                {getTrustStepTitle(effectiveStatus?.nextStepId ?? null, t)}
              </div>
              <div
                style={{
                  color: C.textMuted,
                  fontSize: TYPE.size.sm,
                  lineHeight: 1.7,
                  fontFamily: F,
                }}
              >
                {getNextTrustStepDetail(effectiveStatus ?? null, t)}
              </div>
               {effectiveStatus?.blockedSteps.length ? (
                 <div
                   style={{
                     display: 'flex',
                     alignItems: 'flex-start',
                     gap: SPACE[3],
                     padding: `${SPACE[3]} ${SPACE[4]}`,
                     borderRadius: R.lg,
                     border: `1px solid ${C.error}33`,
                     borderLeft: `3px solid ${C.error}`,
                     background: `${C.error}12`,
                     color: C.error,
                     fontSize: TYPE.size.sm,
                     lineHeight: TYPE.lineHeight.relaxed,
                     fontFamily: F,
                   }}
                 >
                   <AlertTriangle size={16} style={{ marginTop: 2, flexShrink: 0 }} />
                   <span>
                     {t('trustCenterExpanded.blockedChecksNeeded').replace(
                       '{count}',
                       String(effectiveStatus.blockedSteps.length),
                     )}
                   </span>
                 </div>
               ) : null}
            </div>

            <div
              style={{
                display: 'grid',
                gap: SPACE[4],
                padding: SPACE[5],
                borderRadius: R.xxl,
                border: `1px solid ${C.border}`,
                background: `linear-gradient(180deg, ${C.card}, rgba(9,22,34,0.92))`,
                boxShadow: SH.sm,
              }}
            >
              <div
                style={{
                  color: C.cyan,
                  fontSize: TYPE.size.xs,
                  fontWeight: TYPE.weight.bold,
                  textTransform: 'uppercase',
                  letterSpacing: TYPE.letterSpacing.wider,
                  fontFamily: F,
                }}
              >
                {t('trustCenterExpanded.capabilitiesStillGated')}
              </div>
               {lockedCapabilities.length > 0 ? (
                 lockedCapabilities.map(item => (
                   <div
                     key={item.title}
                     style={{
                       display: 'flex',
                       alignItems: 'center',
                       justifyContent: 'space-between',
                       gap: SPACE[3],
                       padding: `${SPACE[3]} ${SPACE[4]}`,
                       borderRadius: R.lg,
                       border: `1px solid ${C.border}`,
                       borderLeft: `3px solid ${heroAccent}`,
                       background: C.card,
                       flexWrap: 'wrap',
                     }}
                   >
                    <div style={{ display: 'flex', alignItems: 'center', gap: SPACE[3], minWidth: 0 }}>
                      <span
                        style={{
                          display: 'inline-flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          width: 42,
                          height: 42,
                          borderRadius: R.lg,
                          color: heroAccent,
                          background: `${heroAccent}18`,
                          border: `1px solid ${heroAccent}28`,
                          flexShrink: 0,
                        }}
                      >
                        {item.icon}
                      </span>
                      <span style={{ color: C.text, fontSize: TYPE.size.sm, fontFamily: F }}>
                        {item.title}
                      </span>
                    </div>
                    <StatusBadge
                      label={t('trustCenterExpanded.waitingOnNextStep')}
                      accent={heroAccent}
                    />
                  </div>
                ))
              ) : (
                <div
                  style={{
                    color: C.textMuted,
                    fontSize: TYPE.size.sm,
                    lineHeight: TYPE.lineHeight.relaxed,
                    fontFamily: F,
                  }}
                >
                  {t('trustCenterExpanded.noCapabilitiesGated')}
                </div>
              )}
            </div>
          </div>
        </SectionCard>

        <div ref={workflowRef} style={{ display: 'grid', gap: SPACE[5], marginBottom: SPACE[6] }}>
          <SectionCard
            title={t('trustCenterExpanded.subtitle')}
            subtitle={t('trustCenterExpanded.workflowStepSubtitle')}
            icon={<Activity size={16} color={C.cyan} />}
          >
            <div style={{ display: 'grid', gap: SPACE[4] }}>
              <div ref={identityRef}>
                <StepCard
                  title={t('trustCenterExpanded.identity')}
                  subtitle={identityStep?.detail ?? t('trustCenterExpanded.reviewFlowBelow')}
                  state={identityStep?.state ?? 'not_started'}
                  badgeLabel={getStepBadge(identityStep?.state ?? 'not_started', t).label}
                  icon={
                    <Shield
                      size={16}
                      color={stateAccent(identityStep?.state ?? 'not_started')}
                    />
                  }
                  footer={
                    <TrustActionRow
                      primary={
                        <WaselButton
                          onClick={() => {
                            void handleSubmitIdentity();
                          }}
                          loading={actionKey === 'identity'}
                          disabled={
                            actionKey === 'identity' ||
                            identityStep?.state === 'in_progress'
                          }
                          variant="primary"
                        >
                          {identityStep?.state === 'failed'
                            ? t('trustCenterExpanded.resubmit')
                            : t('trustCenterExpanded.submitForReview')}
                        </WaselButton>
                      }
                      refresh={() => {
                        void reloadTrustStatus();
                      }}
                    />
                  }
                >
                  {identityStep?.failureReason ? (
                    <FailureNotice message={identityStep.failureReason} />
                  ) : null}
                  <WaselInput
                    id="identity-reference"
                    label={t('trustCenterExpanded.sanadReference')}
                    value={identityReference}
                    onChange={() => { void setIdentityReference(); }}
                    dir={ar ? 'rtl' : 'ltr'}
                    aria-invalid={Boolean(validationErrors.identityReference)}
                    aria-describedby="identity-reference-error"
                  />
                  {validationErrors.identityReference ? (
                    <div id="identity-reference-error" style={{ color: C.error, fontSize: TYPE.size.xs, fontFamily: F, marginTop: SPACE[1] }}>
                      {validationErrors.identityReference}
                    </div>
                  ) : null}
                  <WaselInput
                    id="identity-document-ref"
                    label={t('trustCenterExpanded.documentReferenceOptional')}
                    value={identityDocumentReference}
                    onChange={() => { void setIdentityDocumentReference(); }}
                    dir={ar ? 'rtl' : 'ltr'}
                  />
                  {formatTimestamp(identityStep?.updatedAt) ? (
                    <div style={{ color: C.textMuted, fontSize: TYPE.size.xs, fontFamily: F }}>
                      {t('trustCenterExpanded.lastUpdate')} {formatTimestamp(identityStep?.updatedAt)}
                    </div>
                  ) : null}
                </StepCard>
              </div>

              <div ref={contactRef}>
                <StepCard
                  title={t('trustCenterExpanded.emailPhoneTitle')}
                  subtitle={t('trustCenterExpanded.emailPhoneSubtitle')}
                  state={
                    phoneStep?.state === 'failed' || emailStep?.state === 'failed'
                      ? 'failed'
                      : phoneStep?.state === 'completed' && emailStep?.state === 'completed'
                        ? 'completed'
                        : phoneStep?.state === 'in_progress' || emailStep?.state === 'in_progress'
                          ? 'in_progress'
                          : 'not_started'
                  }
                  badgeLabel={
                    phoneStep?.state === 'failed' || emailStep?.state === 'failed'
                      ? t('trustCenterExpanded.failed')
                      : phoneStep?.state === 'completed' && emailStep?.state === 'completed'
                        ? t('trustCenterExpanded.completed')
                        : phoneStep?.state === 'in_progress' || emailStep?.state === 'in_progress'
                          ? t('trustCenterExpanded.inProgress')
                          : t('trustCenterExpanded.notStarted')
                  }
                  icon={<MailCheck size={16} color={C.cyan} />}
                >
                  <div
                    style={{
                      display: 'grid',
                      gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))',
                      gap: SPACE[4],
                    }}
                  >
                    <div
                      style={{
                        display: 'grid',
                        gap: SPACE[4],
                        padding: SPACE[4],
                        borderRadius: R.xl,
                        border: `1px solid ${stateAccent(emailStep?.state ?? 'not_started')}24`,
                        background: `radial-gradient(circle at top left, ${stateAccent(emailStep?.state ?? 'not_started')}12, transparent 34%), ${C.card}`,
                        boxShadow: SH.sm,
                      }}
                    >
                      <div
                        style={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          gap: 10,
                          flexWrap: 'wrap',
                        }}
                      >
                        <div style={{ color: C.text, fontWeight: TYPE.weight.bold, fontFamily: F }}>
                          {t('trustCenterExpanded.emailConfirmation')}
                        </div>
                        <StatusBadge label={emailBadge.label} accent={emailBadge.accent} />
                      </div>
                      <div
                        style={{
                          color: C.textMuted,
                          fontSize: TYPE.size.sm,
                          fontFamily: F,
                          lineHeight: 1.6,
                        }}
                      >
                        {effectiveStatus?.steps.email.detail}
                      </div>
                      <div style={{ color: C.text, fontSize: TYPE.size.sm, fontFamily: F }}>
                        {user.email || effectiveStatus?.steps.email.meta.email || t('trustCenterExpanded.email')}
                      </div>
                      <TrustActionRow
                        primary={
                          <WaselButton
                            onClick={() => {
                              void handleResendEmail();
                            }}
                            loading={actionKey === 'email'}
                            disabled={actionKey === 'email' || effectiveStatus?.steps.email.state === 'completed'}
                            variant="primary"
                          >
                            {effectiveStatus?.steps.email.state === 'completed'
                              ? t('trustCenterExpanded.confirmed')
                              : t('trustCenterExpanded.sendConfirmation')}
                          </WaselButton>
                        }
                      />
                    </div>

                    <div
                      style={{
                        display: 'grid',
                        gap: SPACE[4],
                        padding: SPACE[4],
                        borderRadius: R.xl,
                        border: `1px solid ${stateAccent(phoneStep?.state ?? 'not_started')}24`,
                        background: `radial-gradient(circle at top left, ${stateAccent(phoneStep?.state ?? 'not_started')}12, transparent 34%), ${C.card}`,
                        boxShadow: SH.sm,
                      }}
                    >
                      <div
                        style={{
                          display: 'flex',
                          justifyContent: 'space-between',
                          gap: 10,
                          flexWrap: 'wrap',
                        }}
                      >
                        <div style={{ color: C.text, fontWeight: TYPE.weight.bold, fontFamily: F }}>
                          {t('trustCenterExpanded.phoneConfirmation')}
                        </div>
                        <StatusBadge label={phoneBadge.label} accent={phoneBadge.accent} />
                      </div>
                      <div
                        style={{
                          color: C.textMuted,
                          fontSize: TYPE.size.sm,
                          fontFamily: F,
                          lineHeight: 1.6,
                        }}
                      >
                        {effectiveStatus?.steps.phone.detail}
                      </div>
                      {phoneStep?.failureReason ? (
                        <FailureNotice message={phoneStep.failureReason} />
                      ) : null}
                      <WaselInput
                        id="phone-number"
                        label={t('trustCenterExpanded.phoneNumberLabel')}
                        value={phoneInput}
                        onChange={() => { void setPhoneInput(); }}
                        type="tel"
                        dir="ltr"
                        aria-invalid={Boolean(validationErrors.phone)}
                        aria-describedby="phone-number-error"
                      />
                      {validationErrors.phone ? (
                        <div id="phone-number-error" style={{ color: C.error, fontSize: TYPE.size.xs, fontFamily: F, marginTop: SPACE[1] }}>
                          {validationErrors.phone}
                        </div>
                      ) : null}
                      <TrustActionRow
                        primary={
                          <WaselButton
                            onClick={() => {
                              void handleStartPhone();
                            }}
                            loading={actionKey === 'phone-start'}
                            disabled={actionKey === 'phone-start'}
                            variant="primary"
                          >
                            {phoneStep?.state === 'in_progress'
                              ? t('trustCenterExpanded.resendCode')
                              : t('trustCenterExpanded.sendCode')}
                          </WaselButton>
                        }
                      />
                      {phoneStep?.state === 'in_progress' || phoneStep?.state === 'failed' ? (
                        <div style={{ display: 'grid', gap: 10 }}>
                          <WaselInput
                            id="phone-code"
                            label={t('trustCenterExpanded.enterVerificationCode')}
                            value={phoneCode}
                            onChange={() => { void setPhoneCode(); }}
                            type="text"
                            dir="ltr"
                            aria-invalid={Boolean(validationErrors.phoneCode)}
                            aria-describedby="phone-code-error"
                          />
                          {validationErrors.phoneCode ? (
                            <div id="phone-code-error" style={{ color: C.error, fontSize: TYPE.size.xs, fontFamily: F, marginTop: SPACE[1] }}>
                              {validationErrors.phoneCode}
                            </div>
                          ) : null}
                          <WaselButton
                            onClick={() => {
                              void handleConfirmPhone();
                            }}
                            loading={actionKey === 'phone-confirm'}
                            disabled={actionKey === 'phone-confirm'}
                            variant="primary"
                          >
                            {t('trustCenterExpanded.confirmPhone')}
                          </WaselButton>
                          {formatTimestamp(phoneStep?.meta.expiresAt) ? (
                            <div style={{ color: C.textMuted, fontSize: TYPE.size.xs, fontFamily: F }}>
                              {t('trustCenterExpanded.codeExpires')}{' '}
                              {formatTimestamp(phoneStep?.meta.expiresAt)}
                            </div>
                          ) : null}
                        </div>
                      ) : null}
                    </div>
                  </div>
                </StepCard>
              </div>

              <div ref={documentsRef}>
                <StepCard
                  title={t('trustCenterExpanded.driverDocumentsTitle')}
                  subtitle={
                    driverStep?.detail ?? t('trustCenterExpanded.driverDocumentsTitle')
                  }
                  state={driverStep?.state ?? 'not_started'}
                  badgeLabel={getStepBadge(driverStep?.state ?? 'not_started', t).label}
                  icon={
                    <FileCheck
                      size={16}
                      color={stateAccent(driverStep?.state ?? 'not_started')}
                    />
                  }
                >
                  <div style={{ display: 'grid', gap: 10 }}>
                    {driverStep?.failureReason ? (
                      <FailureNotice message={driverStep.failureReason} />
                    ) : null}
                    {driverStep?.meta.role === 'rider' ? (
                      <TrustActionRow
                        primary={
                          <WaselButton
                            onClick={() => {
                              void handleEnableDriverMode();
                            }}
                            loading={actionKey === 'driver-mode'}
                            disabled={actionKey === 'driver-mode'}
                            variant="primary"
                          >
                            {t('trustCenterExpanded.enableDriverMode')}
                          </WaselButton>
                        }
                      />
                    ) : (
                      <>
                        <WaselInput
                          id="driver-license"
                          label={t('trustCenterExpanded.driverLicenseNumber')}
                          value={licenseNumber}
                          onChange={() => { void setLicenseNumber(); }}
                          dir={ar ? 'rtl' : 'ltr'}
                          aria-invalid={Boolean(validationErrors.licenseNumber)}
                          aria-describedby="driver-license-error"
                        />
                        {validationErrors.licenseNumber ? (
                          <div id="driver-license-error" style={{ color: C.error, fontSize: TYPE.size.xs, fontFamily: F, marginTop: SPACE[1] }}>
                            {validationErrors.licenseNumber}
                          </div>
                        ) : null}
                        <WaselInput
                          id="driver-document-ref"
                          label={t('trustCenterExpanded.documentReferenceOptional')}
                          value={driverDocumentReference}
                          onChange={() => { void setDriverDocumentReference(); }}
                          dir={ar ? 'rtl' : 'ltr'}
                        />
                        <TrustActionRow
                          primary={
                            <WaselButton
                              onClick={() => {
                                void handleSubmitDriverDocuments();
                              }}
                              loading={actionKey === 'driver-documents'}
                              disabled={
                                actionKey === 'driver-documents' ||
                                driverStep?.state === 'in_progress'
                              }
                              variant="primary"
                            >
                              {driverStep?.state === 'failed'
                                ? t('trustCenterExpanded.resubmit')
                                : t('trustCenterExpanded.submitDocuments')}
                            </WaselButton>
                          }
                        />
                      </>
                    )}
                    {formatTimestamp(driverStep?.updatedAt) ? (
                      <div style={{ color: C.textMuted, fontSize: TYPE.size.xs, fontFamily: F }}>
                        {t('trustCenterExpanded.lastUpdate')} {formatTimestamp(driverStep?.updatedAt)}
                      </div>
                    ) : null}
                  </div>
                </StepCard>
              </div>

              <div ref={walletRef}>
                <StepCard
                  title={t('trustCenterExpanded.walletStandingTitle')}
                  subtitle={
                    walletStandingStep?.detail ?? t('trustCenterExpanded.walletStandingTitle')
                  }
                  state={walletStandingStep?.state ?? 'failed'}
                  badgeLabel={getStepBadge(walletStandingStep?.state ?? 'failed', t).label}
                  icon={
                    <Wallet
                      size={16}
                      color={stateAccent(walletStandingStep?.state ?? 'failed')}
                    />
                  }
                  footer={
                    <TrustActionRow
                      primary={
                        <WaselButton onClick={() => { void nav(); }} variant="primary">
                          {t('trustCenterExpanded.openWallet')}
                        </WaselButton>
                      }
                      secondary={
                        <WaselButton
                          variant="outline"
                          onClick={() => { void nav(); }}
                        >
                          {t('trustCenterExpanded.accountSettings')}
                        </WaselButton>
                      }
                    />
                  }
                >
                  {walletStandingStep?.failureReason ? (
                    <FailureNotice message={walletStandingStep.failureReason} />
                  ) : null}
                </StepCard>
              </div>
            </div>
          </SectionCard>
        </div>

        <SectionCard
          title={t('trustCenterExpanded.reviewHistoryTitle')}
          subtitle={t('trustCenterExpanded.reviewHistorySubtitle')}
          icon={<Activity size={16} color={C.cyan} />}
        >
          <ReviewTimeline items={reviewHistory} t={t} />
        </SectionCard>

        <SectionCard
          title={t('trustCenterExpanded.capabilityMatrixTitle')}
          subtitle={t('trustCenterExpanded.capabilityMatrixSubtitle')}
          icon={<BadgeCheck size={16} color={C.green} />}
        >
          <div style={{ display: 'grid', gap: SPACE[3] }}>
            {capabilityRows.map(item => (
              <div
                key={item.title}
                style={{
                  display: 'flex',
                  justifyContent: 'space-between',
                  gap: SPACE[3],
                  alignItems: 'center',
                  padding: `${SPACE[4]} ${SPACE[4]}`,
                  borderRadius: R.xl,
                  border: `1px solid ${item.gate.allowed ? C.green : C.cyan}24`,
                  borderLeft: `3px solid ${item.gate.allowed ? C.green : C.cyan}`,
                  background: `linear-gradient(180deg, ${C.card}, rgba(9,22,34,0.92))`,
                  boxShadow: SH.sm,
                  flexWrap: 'wrap',
                }}
              >
               <div style={{ display: 'flex', alignItems: 'center', gap: SPACE[3], minWidth: 0 }}>
                 <span
                   style={{
                     display: 'inline-flex',
                     alignItems: 'center',
                     justifyContent: 'center',
                     width: 42,
                     height: 42,
                     borderRadius: R.lg,
                     color: item.gate.allowed ? C.green : C.cyan,
                     background: `${item.gate.allowed ? C.green : C.cyan}18`,
                     border: `1px solid ${item.gate.allowed ? C.green : C.cyan}28`,
                     flexShrink: 0,
                   }}
                 >
                   {item.icon}
                 </span>
                 <div style={{ display: 'grid', gap: 4, minWidth: 0 }}>
                   <div style={{ color: C.text, fontWeight: TYPE.weight.bold, fontFamily: F }}>
                     {item.title}
                   </div>
                   <div
                     style={{
                       color: C.textMuted,
                       fontSize: TYPE.size.sm,
                       fontFamily: F,
                       lineHeight: TYPE.lineHeight.relaxed,
                     }}
                   >
                     {item.gate.allowed
                       ? t('trustCenterExpanded.capabilityReady')
                       : (item.gate.reason ??
                         item.gate.recommendation ??
                         t('trustCenterExpanded.oneMoreStep'))}
                   </div>
                 </div>
               </div>
               <StatusBadge
                 label={item.gate.allowed ? t('trustCenterExpanded.open') : t('trustCenterExpanded.locked')}
                 accent={item.gate.allowed ? C.green : C.cyan}
               />
             </div>
            ))}
          </div>
        </SectionCard>
      </>
      )}
      <WaselDialog
        open={confirmState.open}
        title={confirmState.title}
        description={confirmState.description}
        size="sm"
        onClose={() => setConfirmState(prev => ({ ...prev, open: false }))}
        closeLabel={t('common.close')}
        footer={
          <>
            <WaselButton
              variant="outline"
              onClick={() => setConfirmState(prev => ({ ...prev, open: false }))}
            >
              {t('common.cancel')}
            </WaselButton>
            <WaselButton variant="primary" onClick={confirmState.onConfirm}>
              {t('common.confirm')}
            </WaselButton>
          </>
        }
      />
      </div>
    </PageShell>
  );
}

﻿/**
 * WalletDashboard
 *
 * Render-focused wallet screen. Runtime mode selection, demo/live data
 * handling, and wallet mutations now live in `useWalletDashboardController`.
 */

import { Suspense, lazy, useState } from 'react';
import { Activity, Gift, Lock, RefreshCw, Wallet } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '../../components/ui/card';
import { Button } from '../../components/ui/button';
import { Badge } from '../../components/ui/badge';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '../../components/ui/tabs';
import { WaselStateCard } from '../../components/system/WaselStateCard';
import type { WalletTransaction, RewardItem } from '../../services/walletApi';
import {
  MetricCard,
  PageHero,
  PageShell,
  StatusBadge,
} from '../../components/wasel-ui/WaselPagePrimitives';
import { C, SPACE } from '../../utils/wasel-ds';
import { useWalletDashboardController } from './useWalletDashboardController.js';
import { OverviewTab } from './components/OverviewTab';
import { SettingsTab } from './components/SettingsTab';
import { WalletActionModals } from './components/WalletActionModals';
import { TransactionRow as SharedTransactionRow } from './components/WalletShared';
import { WalletHeroCard } from './components/WalletHeroCard';

const InsightsTab = lazy(async () => {
  const mod = await import('./components/InsightsTab');
  return { default: mod.InsightsTab };
});

export function WalletDashboard() {
  const {
    actionLoading,
    autoTopUpAmount,
    autoTopUpEnabled,
    autoTopUpThreshold,
    balanceVisible,
    handleAutoTopUpToggle,
    handleClaimReward,
    handleRefresh,
    handleSend,
    handleSetPin,
    handleSubscribe,
    handleTopUp,
    handleWithdraw,
    insights,
    isRTL,
    loading,
    pinValue,
    refreshing,
    sendAmount,
    sendNote,
    sendRecipient,
    setAutoTopUpAmount,
    setAutoTopUpThreshold,
    setBalanceVisible,
    setPinValue,
    setSendAmount,
    setSendNote,
    setSendRecipient,
    setShowPinSetup,
    setShowSend,
    setShowTopUp,
    setShowWithdraw,
    setTab,
    setTopUpAmount,
    setTopUpMethod,
    setWithdrawAmount,
    setWithdrawBank,
    setWithdrawMethod,
    shouldRedirectToAuth,
    showPinSetup,
    showSend,
    showTopUp,
    showWithdraw,
    t,
    tab,
    topUpAmount,
    topUpMethod,
    walletData,
    walletCapabilities,
    walletSubtitle,
    walletUnavailable,
    withdrawAmount,
    withdrawBank,
    withdrawMethod,
  } = useWalletDashboardController();

  const [txSearch, setTxSearch] = useState('');
  const bal = walletData?.balance ?? 0;
  const pending = walletData?.pendingBalance ?? 0;
  const rewardsBal = walletData?.rewardsBalance ?? 0;
  const transactionCount = walletData?.transactions?.length ?? 0;
  const walletTitle = t.walletTitle ?? 'Wallet';
  const activeLabel = t.activeLabel ?? 'Active';
  const walletUnavailableDescription =
    t.walletUnavailableDescription ?? 'Wallet access is not available right now.';
  const loadingTitle = t.loadingTitle ?? 'Loading wallet';
  const loadingDescription = t.loadingDescription ?? 'Fetching balance, movements, and rewards.';
  const walletUnavailableTitle = t.walletUnavailableTitle ?? 'Wallet unavailable';
  const jodLabel = t.jod ?? 'JOD';
  const refreshLabel = isRTL ? 'تحديث' : 'Refresh';
  const heroDescription = isRTL
    ? `الرصيد والتحويلات والمكافآت تظهر في سطح واحد واضح. ${walletData?.currency || 'JOD'}`
    : `Balance, transfers, and rewards in one clear surface. ${walletData?.currency || 'JOD'}`;
  const insightsFallback = (
    <Card className="rounded-xl">
      <CardContent className="py-10 text-center text-sm text-muted-foreground">
        {t.processing}
      </CardContent>
    </Card>
  );

  if (shouldRedirectToAuth) {
    return (
      <WaselStateCard
        eyebrow={walletTitle}
        title={t.redirectingToSignIn ?? 'Redirecting to sign in'}
        description={walletUnavailableDescription}
        icon={Lock}
        tone="warning"
        minHeight="60vh"
      />
    );
  }

  if (loading) {
    return (
      <WaselStateCard
        eyebrow={walletTitle}
        title={loadingTitle}
        description={loadingDescription}
        icon={Wallet}
        loading
        minHeight="60vh"
        footer={activeLabel}
      />
    );
  }

  if (walletUnavailable) {
    return (
      <WaselStateCard
        eyebrow={walletTitle}
        title={walletUnavailableTitle}
        description={walletUnavailableDescription}
        icon={Wallet}
        tone="warning"
        minHeight="60vh"
        footer={t.walletUnavailableHint}
      />
    );
  }

  return (
    <PageShell maxWidth={1120} dir={isRTL ? 'rtl' : 'ltr'}>
      <div style={{ paddingInline: SPACE[4] }}>
        <PageHero
          eyebrow={isRTL ? 'المدفوعات' : 'Payments'}
          icon={<StatusBadge label={activeLabel} accent={C.green} />}
          title={isRTL ? 'محفظة واصل' : 'Wasel Wallet'}
          description={heroDescription}
          accent={C.cyan}
          actions={
            <>
              {walletCapabilities.topUp ? (
                <Button
                  onClick={() => { void setShowTopUp(true); }}
                  className="bg-primary text-primary-foreground hover:bg-primary/90"
                >
                  {t.topUp}
                </Button>
              ) : null}
              <Button
                variant="outline"
                onClick={() => { void handleRefresh(); }}
                disabled={refreshing}
                className="border-white/15 bg-white/5 text-white hover:bg-white/10"
              >
                <RefreshCw className={`w-4 h-4 ${refreshing ? 'animate-spin' : ''}`} />
                {refreshLabel}
              </Button>
            </>
          }
          aside={
            <div style={{ display: 'grid', gap: 12 }}>
              <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}>
                <StatusBadge label={walletData?.currency || 'JOD'} accent={C.cyan} />
                <StatusBadge
                  label={
                    autoTopUpEnabled
                      ? isRTL
                        ? 'شحن تلقائي'
                        : 'Auto top-up on'
                      : isRTL
                        ? 'شحن يدوي'
                        : 'Manual top-up'
                  }
                  accent={autoTopUpEnabled ? C.green : C.gold}
                />
              </div>
              <div style={{ color: C.textMuted, fontSize: '0.88rem', lineHeight: 1.7 }}>
                {isRTL
                  ? 'الرصيد والتحويلات والمكافآت في سطح واحد واضح.'
                  : 'Balance, transfers, and rewards in one clear surface.'}
              </div>
            </div>
          }
        />

        <div
          style={{
            display: 'grid',
            gridTemplateColumns: 'repeat(auto-fit, minmax(170px, 1fr))',
            gap: SPACE[4],
            marginBottom: SPACE[6],
          }}
        >
          <MetricCard
            label={isRTL ? 'الرصيد المتاح' : 'Available'}
            value={`JOD ${bal.toFixed(2)}`}
            detail={walletSubtitle}
            icon={<Wallet size={18} />}
            accent={C.cyan}
          />
          <MetricCard
            label={isRTL ? 'المعلق' : 'Pending'}
            value={`JOD ${pending.toFixed(2)}`}
            detail={
              isRTL
                ? 'أموال تنتظر التسوية أو السحب.'
                : 'Funds waiting for settlement or withdrawal.'
            }
            icon={<RefreshCw size={18} />}
            accent={C.gold}
          />
          <MetricCard
            label={isRTL ? 'المكافآت' : 'Rewards'}
            value={`JOD ${rewardsBal.toFixed(2)}`}
            detail={
              isRTL
                ? 'مكافآت متاحة داخل الدورة الحالية.'
                : 'Reward value available in the current cycle.'
            }
            icon={<Gift size={18} />}
            accent={C.green}
          />
          <MetricCard
            label={isRTL ? 'الحركات' : 'Transactions'}
            value={transactionCount}
            detail={isRTL ? 'عدد الحركات الظاهرة حالياً.' : 'Visible transaction count right now.'}
            icon={<Activity size={18} />}
            accent={C.blue}
          />
        </div>

        <div className="space-y-6 pb-8" dir={isRTL ? 'rtl' : 'ltr'}>
          <WalletHeroCard
            balanceVisible={balanceVisible}
            balance={bal}
            canTopUp={walletCapabilities.topUp}
            pendingBalance={pending}
            rewardsBalance={rewardsBal}
            t={t}
            onToggleBalance={() => setBalanceVisible(!balanceVisible)}
            onShowTopUp={() => setShowTopUp(true)}
            onShowWithdraw={() => setShowWithdraw(true)}
            onShowSend={() => setShowSend(true)}
          />

          <Tabs value={tab} onValueChange={setTab} className="w-full">
            <TabsList
              className="w-full grid grid-cols-5 h-11 rounded-xl bg-card overflow-x-auto"
              style={{ overflowX: 'auto', display: 'flex' }}
            >
              <TabsTrigger value="overview" className="text-xs rounded-lg whitespace-nowrap">
                {t.overview}
              </TabsTrigger>
              <TabsTrigger value="transactions" className="text-xs rounded-lg whitespace-nowrap">
                {t.transactions}
              </TabsTrigger>
              <TabsTrigger value="rewards" className="text-xs rounded-lg whitespace-nowrap">
                {t.rewardsTab}
              </TabsTrigger>
              <TabsTrigger value="insights" className="text-xs rounded-lg whitespace-nowrap">
                {t.insights}
              </TabsTrigger>
              <TabsTrigger value="settings" className="text-xs rounded-lg whitespace-nowrap">
                {t.settings}
              </TabsTrigger>
            </TabsList>

            <TabsContent value="overview" className="mt-4 space-y-4">
              <OverviewTab
                walletData={walletData}
                canSubscribe={walletCapabilities.subscription}
                isRTL={isRTL}
                t={t}
                onSetTab={setTab}
                onSubscribe={handleSubscribe}
                actionLoading={actionLoading}
              />
            </TabsContent>

            <TabsContent value="transactions" className="mt-4">
              <Card className="rounded-xl">
                <CardContent className="pt-4">
                  {/* Transaction search */}
                  <div style={{ marginBottom: 12 }}>
                    <input
                      type="search"
                      value={txSearch}
                      onChange={e => setTxSearch(e.target.value)}
                      placeholder={isRTL ? 'ابحث في الحركات...' : 'Search transactions...'}
                      style={{
                        width: '100%',
                        padding: '8px 12px',
                        borderRadius: 10,
                        border: `1px solid ${C.border}`,
                        background: C.elevated,
                        color: C.text,
                        fontSize: '0.84rem',
                        boxSizing: 'border-box',
                      }}
                    />
                  </div>
                  {!walletData?.transactions || walletData.transactions.length === 0 ? (
                    <div className="text-center py-12 text-muted-foreground text-sm">
                      {t.noTransactions}
                    </div>
                  ) : (
                    walletData.transactions
                      .filter(
                        (tx: WalletTransaction) =>
                          !txSearch ||
                          JSON.stringify(tx).toLowerCase().includes(txSearch.toLowerCase()),
                      )
                      .map((tx: WalletTransaction) => (
                        <SharedTransactionRow
                          key={tx.id}
                          tx={tx}
                          isRTL={isRTL}
                          jodLabel={jodLabel}
                        />
                      ))
                  )}
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="rewards" className="mt-4 space-y-4">
              <Card className="rounded-xl">
                <CardHeader className="pb-2">
                  <CardTitle className="text-sm flex items-center gap-2">
                    <Gift className="w-4 h-4 text-purple-400" />
                    {t.activeRewards}
                  </CardTitle>
                </CardHeader>
                <CardContent>
                  {!walletData?.activeRewards || walletData.activeRewards.length === 0 ? (
                    <div className="text-center py-8">
                      <Gift className="w-12 h-12 mx-auto mb-3 text-muted-foreground/30" />
                      <p className="text-muted-foreground text-sm">{t.noRewards}</p>
                      <p className="text-xs text-muted-foreground mt-1">{t.rewardsEmptyHint}</p>
                      <button
                        onClick={() => { void setTab(); }}
                        style={{
                          marginTop: 12,
                          padding: '8px 18px',
                          borderRadius: 999,
                          background: C.cyan,
                          border: 'none',
                          color: C.bg,
                          fontWeight: 700,
                          cursor: 'pointer',
                          fontSize: '0.82rem',
                        }}
                      >
                        {isRTL ? 'ابدأ رحلة لكسب مكافآت' : 'Book a ride to earn rewards'}
                      </button>
                    </div>
                  ) : (
                    <>
                      {!walletCapabilities.rewardClaim ? (
                        <p className="mb-3 text-xs text-muted-foreground">
                          {t.rewardClaimUnavailableHint}
                        </p>
                      ) : null}
                      {walletData.activeRewards.map((r: RewardItem) => (
                        <div
                          key={r.id}
                          className="flex items-center justify-between py-3 border-b border-border/30 last:border-0"
                        >
                          <div>
                            <p className="text-sm font-medium">{r.description}</p>
                            <p className="text-xs text-muted-foreground">
                              {t.expires}:{' '}
                              {new Date(r.expirationDate).toLocaleDateString(
                                isRTL ? 'ar-JO' : 'en-US',
                                { month: 'short', day: 'numeric' },
                              )}
                            </p>
                          </div>
                          <div className="flex items-center gap-2">
                            <Badge className="bg-purple-500/10 text-purple-400 border-purple-500/30 font-bold">
                              {r.amount} {t.jod}
                            </Badge>
                            <Button
                              size="sm"
                              variant="outline"
                              onClick={() => { void handleClaimReward(r.id); }}
                              disabled={!walletCapabilities.rewardClaim}
                              className="text-xs border-purple-500/30 text-purple-400 hover:bg-purple-500/10 disabled:opacity-60"
                            >
                              {t.claim}
                            </Button>
                          </div>
                        </div>
                      ))}
                    </>
                  )}
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="insights" className="mt-4 space-y-4">
              <Suspense fallback={insightsFallback}>
                <InsightsTab insights={insights} isRTL={isRTL} t={t} />
              </Suspense>
            </TabsContent>

            <TabsContent value="settings" className="mt-4 space-y-4">
              <SettingsTab
                walletData={walletData}
                canManagePin={walletCapabilities.pin}
                isRTL={isRTL}
                t={t}
                autoTopUpEnabled={autoTopUpEnabled}
                autoTopUpAmount={autoTopUpAmount}
                autoTopUpThreshold={autoTopUpThreshold}
                onAutoTopUpToggle={handleAutoTopUpToggle}
                onAutoTopUpAmountChange={setAutoTopUpAmount}
                onAutoTopUpThresholdChange={setAutoTopUpThreshold}
                onShowPinSetup={() => setShowPinSetup(true)}
              />
            </TabsContent>
          </Tabs>

          <WalletActionModals
            actionLoading={actionLoading}
            balance={bal}
            isRTL={isRTL}
            pinValue={pinValue}
            sendAmount={sendAmount}
            sendNote={sendNote}
            sendRecipient={sendRecipient}
            setPinValue={setPinValue}
            setSendAmount={setSendAmount}
            setSendNote={setSendNote}
            setSendRecipient={setSendRecipient}
            setShowPinSetup={setShowPinSetup}
            setShowSend={setShowSend}
            setShowTopUp={setShowTopUp}
            setShowWithdraw={setShowWithdraw}
            setTopUpAmount={setTopUpAmount}
            setTopUpMethod={setTopUpMethod}
            setWithdrawAmount={setWithdrawAmount}
            setWithdrawBank={setWithdrawBank}
            setWithdrawMethod={setWithdrawMethod}
            showPinSetup={showPinSetup}
            showSend={showSend}
            showTopUp={showTopUp}
            showWithdraw={showWithdraw}
            t={t}
            topUpAmount={topUpAmount}
            topUpMethod={topUpMethod}
            walletData={walletData}
            withdrawAmount={withdrawAmount}
            withdrawBank={withdrawBank}
            withdrawMethod={withdrawMethod}
            onSend={handleSend}
            onSetPin={handleSetPin}
            onTopUp={handleTopUp}
            onWithdraw={handleWithdraw}
          />
        </div>
      </div>
    </PageShell>
  );
}

/**
 * OverviewTab — Wallet Dashboard overview tab
 * Extracted from WalletDashboard to reduce file size
 */

import {
  ArrowDownLeft,
  ArrowUpRight,
  TrendingUp,
  Lock,
  Crown,
  ChevronRight,
  Car,
  Package,
} from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '../../../components/ui/card';
import { Button } from '../../../components/ui/button';
import { Badge } from '../../../components/ui/badge';
import { WaselColors } from '../../../tokens/wasel-tokens';
import { TransactionRow } from './WalletShared';
import type { WalletData } from '../../../services/walletApi';
import { tx } from '../../../locales/tx';

interface OverviewTabProps {
  walletData: WalletData | null;
  canSubscribe: boolean;
  isRTL: boolean;
  t: Record<string, string>;
  onSetTab: (tab: string) => void;
  onSubscribe: () => void;
  actionLoading: boolean;
}

export function OverviewTab({
  walletData,
  canSubscribe,
  isRTL,
  t,
  onSetTab,
  onSubscribe,
  actionLoading,
}: OverviewTabProps) {
  const transactions = walletData?.transactions ?? [];
  const jodLabel = t.jod ?? 'JOD';
  const pendingCount = transactions.filter(tx =>
    ['pending', 'processing', 'authorized', 'posted'].includes(
      String(tx.status ?? '').toLowerCase(),
    ),
  ).length;
  const failedCount = transactions.filter(tx =>
    ['failed'].includes(String(tx.status ?? '').toLowerCase()),
  ).length;
  const refundedCount = transactions.filter(tx =>
    ['refunded'].includes(String(tx.status ?? '').toLowerCase()),
  ).length;
  const paymentMethodsCount = walletData?.wallet?.paymentMethods?.length ?? 0;

  return (
    <div className="space-y-4">
      {/* Stats Grid */}
      <div className="grid grid-cols-3 gap-3">
        {[
          {
            label: isRTL
              ? '\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0625\u064A\u062F\u0627\u0639'
              : 'Deposited',
            value: walletData?.total_deposited ?? 0,
            icon: ArrowDownLeft,
            color: WaselColors.success,
          },
          {
            label: isRTL
              ? '\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0625\u0646\u0641\u0627\u0642'
              : 'Spent',
            value: walletData?.total_spent ?? 0,
            icon: ArrowUpRight,
            color: WaselColors.error,
          },
          {
            label: isRTL
              ? '\u0625\u062C\u0645\u0627\u0644\u064A \u0627\u0644\u0631\u0628\u062D'
              : 'Earned',
            value: walletData?.total_earned ?? 0,
            icon: TrendingUp,
            color: WaselColors.teal,
          },
        ].map(s => (
          <Card key={s.label} className="p-3 rounded-xl border-border/30">
            <div className="flex items-center gap-2 mb-1">
              <s.icon className="w-3.5 h-3.5" style={{ color: s.color }} />
              <span className="text-xs text-muted-foreground">{s.label}</span>
            </div>
            <p className="text-lg font-bold text-foreground tabular-nums">{s.value.toFixed(2)}</p>
          </Card>
        ))}
      </div>

      <div className="grid gap-3 md:grid-cols-3">
        <Card className="rounded-xl border-border/30">
          <CardContent className="p-4">
            <div className="text-xs text-muted-foreground mb-1">
              {isRTL ? 'التحويلات قيد المعالجة' : 'In settlement'}
            </div>
            <div className="text-lg font-bold text-foreground">{pendingCount}</div>
            <div className="text-xs text-muted-foreground mt-1">
              {walletData?.pendingBalance
                ? `${walletData.pendingBalance.toFixed(2)} ${t.jod} ${isRTL ? 'قيد الإطلاق' : 'awaiting release'}`
                : isRTL
                  ? 'لا توجد مبالغ معلقة الآن'
                  : 'No held balance right now'}
            </div>
          </CardContent>
        </Card>
        <Card className="rounded-xl border-border/30">
          <CardContent className="p-4">
            <div className="text-xs text-muted-foreground mb-1">
              {isRTL ? 'حالات تحتاج متابعة' : 'Needs follow-up'}
            </div>
            <div className="text-lg font-bold text-foreground">{failedCount + refundedCount}</div>
            <div className="text-xs text-muted-foreground mt-1">
              {failedCount > 0
                ? isRTL
                  ? 'راجع المحاولات الفاشلة أو الاستردادات.'
                  : 'Review failed payouts or refund events.'
                : isRTL
                  ? 'لا توجد مشاكل دفع مفتوحة.'
                  : 'No open payment issues.'}
            </div>
          </CardContent>
        </Card>
        <Card className="rounded-xl border-border/30">
          <CardContent className="p-4">
            <div className="text-xs text-muted-foreground mb-1">
              {isRTL ? 'جاهزية السداد' : 'Settlement readiness'}
            </div>
            <div className="text-lg font-bold text-foreground">{paymentMethodsCount}</div>
            <div className="text-xs text-muted-foreground mt-1">
              {paymentMethodsCount > 0
                ? isRTL
                  ? 'وسائل دفع محفوظة للحجز والسحب.'
                  : 'Saved payment methods for booking and withdrawal.'
                : isRTL
                  ? 'أضف وسيلة دفع لفتح السداد الكامل.'
                  : 'Add a payment method to unlock full settlement.'}
            </div>
          </CardContent>
        </Card>
      </div>

      {/* Active Escrows */}
      {walletData?.activeEscrows && walletData.activeEscrows.length > 0 && (
        <Card className="rounded-xl border-yellow-500/20">
          <CardHeader className="pb-2">
            <CardTitle className="text-sm flex items-center gap-2">
              <Lock className="w-4 h-4 text-yellow-400" />
              {t.escrow}
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-2">
            {walletData.activeEscrows.map(esc => {
              const escrowId = String(
                esc.escrowId ?? esc.bookingId ?? `${esc.status}-${esc.amount}`,
              );
              const tripLabel = String(esc.bookingId ?? escrowId).slice(0, 8);
              const escrowType = String(esc.type ?? '');

              return (
                <div
                  key={escrowId}
                  className="flex items-center justify-between py-2 border-b border-border/30 last:border-0"
                >
                  <div className="flex items-center gap-2">
                    {escrowType === 'package' ? (
                      <Package className="w-4 h-4 text-muted-foreground" />
                    ) : (
                      <Car className="w-4 h-4 text-muted-foreground" />
                    )}
                    <span className="text-sm">
                      {tx('overviewTab.trip')}
                      {tripLabel}
                    </span>
                  </div>
                  <Badge variant="outline" className="text-yellow-400 border-yellow-400/30">
                    {t.held}: {esc.amount} {t.jod}
                  </Badge>
                </div>
              );
            })}
          </CardContent>
        </Card>
      )}

      {/* Subscription Card */}
      <Card
        className="rounded-xl overflow-hidden"
        style={{ border: `1px solid ${WaselColors.bronze}30` }}
      >
        <div
          className="p-4"
          style={{ background: `linear-gradient(135deg, ${WaselColors.bronze}15, transparent)` }}
        >
          <div className="flex items-center justify-between">
            <div className="flex items-center gap-3">
              <div
                className="w-10 h-10 rounded-xl flex items-center justify-center"
                style={{ background: `${WaselColors.bronze}20` }}
              >
                <Crown className="w-5 h-5" style={{ color: WaselColors.bronze }} />
              </div>
              <div>
                <h3 className="font-bold text-foreground">{t.subscription}</h3>
                <p className="text-xs text-muted-foreground">
                  {walletData?.subscription
                    ? t.activeSubscription
                    : canSubscribe
                      ? isRTL
                        ? '10% \u062E\u0635\u0645 \u0639\u0644\u0649 \u0627\u0644\u0631\u062D\u0644\u0627\u062A \u2022 \u062D\u062C\u0632 \u0623\u0648\u0644\u0648\u064A\u0629'
                        : '10% off rides \u2022 Priority booking'
                      : t.subscriptionUnavailableHint}
                </p>
              </div>
            </div>
            {walletData?.subscription ? (
              <Badge className="bg-green-500/10 text-green-400 border-green-500/30">
                {isRTL ? '\u0641\u0639\u0651\u0627\u0644' : 'Active'}
              </Badge>
            ) : (
              <Button
                size="sm"
                onClick={() => { void onSubscribe(); }}
                disabled={!canSubscribe || actionLoading}
                style={{ background: WaselColors.bronze }}
              >
                {t.subscribeNow}
              </Button>
            )}
          </div>
        </div>
      </Card>

      {/* Recent Transactions */}
      <Card className="rounded-xl">
        <CardHeader className="pb-2">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm">{t.recentTransactions}</CardTitle>
            <Button
              variant="ghost"
              size="sm"
              onClick={() => { void onSetTab(); }}
              className="text-xs text-primary"
            >
              {t.viewAll} <ChevronRight className="w-3 h-3 ml-1" />
            </Button>
          </div>
        </CardHeader>
        <CardContent>
          {!walletData?.transactions || walletData.transactions.length === 0 ? (
            <div className="text-center py-8 text-muted-foreground text-sm">{t.noTransactions}</div>
          ) : (
            walletData.transactions
              .slice(0, 5)
              .map(tx => <TransactionRow key={tx.id} tx={tx} isRTL={isRTL} jodLabel={jodLabel} />)
          )}
        </CardContent>
      </Card>
    </div>
  );
}

import { CreditCard, Landmark, Smartphone, Zap } from 'lucide-react';
import { Button } from '../../../components/ui/button';
import { Input } from '../../../components/ui/input';
import { Label } from '../../../components/ui/label';
import { WaselColors } from '../../../tokens/wasel-tokens';
import { ActionModal as SharedActionModal } from './WalletShared';
import { tx } from '../../../locales/tx';

type WalletActionModalsProps = {
  actionLoading: boolean;
  balance: number;
  isRTL: boolean;
  pinValue: string;
  sendAmount: string;
  sendNote: string;
  sendRecipient: string;
  setPinValue: (value: string) => void;
  setSendAmount: (value: string) => void;
  setSendNote: (value: string) => void;
  setSendRecipient: (value: string) => void;
  setShowPinSetup: (value: boolean) => void;
  setShowSend: (value: boolean) => void;
  setShowTopUp: (value: boolean) => void;
  setShowWithdraw: (value: boolean) => void;
  setTopUpAmount: (value: string) => void;
  setTopUpMethod: (value: string) => void;
  setWithdrawAmount: (value: string) => void;
  setWithdrawBank: (value: string) => void;
  setWithdrawMethod: (value: string) => void;
  showPinSetup: boolean;
  showSend: boolean;
  showTopUp: boolean;
  showWithdraw: boolean;
  t: Record<string, string>;
  topUpAmount: string;
  topUpMethod: string;
  walletData: { pinSet?: boolean } | null;
  withdrawAmount: string;
  withdrawBank: string;
  withdrawMethod: string;
  onSend: () => void;
  onSetPin: () => void;
  onTopUp: () => void;
  onWithdraw: () => void;
};

export function WalletActionModals({
  actionLoading,
  balance,
  isRTL,
  pinValue,
  sendAmount,
  sendNote,
  sendRecipient,
  setPinValue,
  setSendAmount,
  setSendNote,
  setSendRecipient,
  setShowPinSetup,
  setShowSend,
  setShowTopUp,
  setShowWithdraw,
  setTopUpAmount,
  setTopUpMethod,
  setWithdrawAmount,
  setWithdrawBank,
  setWithdrawMethod,
  showPinSetup,
  showSend,
  showTopUp,
  showWithdraw,
  t,
  topUpAmount,
  topUpMethod,
  walletData,
  withdrawAmount,
  withdrawBank,
  withdrawMethod,
  onSend,
  onSetPin,
  onTopUp,
  onWithdraw,
}: WalletActionModalsProps) {
  void isRTL;

  const addMoneyLabel = t.addMoney ?? 'Add money';
  const withdrawLabel = t.withdraw ?? 'Withdraw';
  const sendMoneyLabel = t.sendMoney ?? 'Send money';
  const setPinLabel = t.setPin ?? 'Set PIN';
  const changePinLabel = t.changePin ?? 'Change PIN';

  return (
    <>
      <SharedActionModal show={showTopUp} onClose={() => setShowTopUp(false)} title={addMoneyLabel}>
        <div className="space-y-3">
          <div className="grid grid-cols-4 gap-2">
            {[5, 10, 20, 50].map(amt => (
              <Button
                key={amt}
                variant={topUpAmount === String(amt) ? 'default' : 'outline'}
                size="sm"
                onClick={() => setTopUpAmount(String(amt))}
                className="rounded-lg text-sm"
              >
                {amt}
              </Button>
            ))}
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">{t.topUpAmount}</Label>
            <Input
              type="number"
              value={topUpAmount}
              onChange={e => setTopUpAmount(e.target.value)}
              className="mt-1 rounded-lg"
              placeholder="0.00"
            />
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">{t.paymentMethod}</Label>
            <div className="mt-1 grid grid-cols-2 gap-2">
              {[
                { id: 'card', label: t.card, icon: CreditCard },
                { id: 'apple_pay', label: t.applePay, icon: Smartphone },
                { id: 'bank_transfer', label: t.bankTransfer, icon: Landmark },
                { id: 'cliq', label: t.cliq, icon: Zap },
              ].map(method => (
                <button
                  key={method.id}
                  type="button"
                  onClick={() => { void setTopUpMethod(method.id); }}
                  className={`flex items-center gap-2 rounded-lg border p-3 text-sm transition-all ${topUpMethod === method.id ? 'border-primary bg-primary/10 text-primary' : 'border-border text-muted-foreground hover:border-slate-500'}`}
                >
                  <method.icon className="h-4 w-4" />
                  {method.label}
                </button>
              ))}
            </div>
          </div>
          <Button
            onClick={() => { void onTopUp(); }}
            disabled={actionLoading}
            className="h-11 w-full rounded-xl font-semibold"
            style={{ background: WaselColors.teal }}
          >
            {actionLoading
              ? t.processing
              : `${t.topUp} ${topUpAmount ? `${topUpAmount} ${t.jod}` : ''}`}
          </Button>
        </div>
      </SharedActionModal>

      <SharedActionModal
        show={showWithdraw}
        onClose={() => setShowWithdraw(false)}
        title={withdrawLabel}
      >
        <div className="space-y-3">
          <div>
            <Label className="text-xs text-muted-foreground">{t.withdrawAmount}</Label>
            <Input
              type="number"
              value={withdrawAmount}
              onChange={e => setWithdrawAmount(e.target.value)}
              className="mt-1 rounded-lg"
              placeholder="0.00"
            />
            <p className="mt-1 text-xs text-muted-foreground">
              {t.availableLabel}: {balance.toFixed(2)} {t.jod}
            </p>
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">{t.bankAccount}</Label>
            <Input
              value={withdrawBank}
              onChange={e => setWithdrawBank(e.target.value)}
              className="mt-1 rounded-lg"
              placeholder={tx('walletActionModals.jo12abcd')}
            />
          </div>
          <div className="grid grid-cols-2 gap-2">
            {[
              { id: 'instant', label: t.instant, fee: '0.50 JOD' },
              { id: 'bank_transfer', label: t.standard, fee: t.freeLabel },
            ].map(method => (
              <button
                key={method.id}
                type="button"
                onClick={() => { void setWithdrawMethod(method.id); }}
                className={`rounded-lg border p-3 text-left transition-all ${withdrawMethod === method.id ? 'border-primary bg-primary/10' : 'border-border hover:border-slate-500'}`}
              >
                <p className="text-sm font-medium">{method.label}</p>
                <p className="text-xs text-muted-foreground">{method.fee}</p>
              </button>
            ))}
          </div>
          <Button
            onClick={() => { void onWithdraw(); }}
            disabled={actionLoading}
            className="h-11 w-full rounded-xl font-semibold"
            style={{ background: WaselColors.bronze }}
          >
            {actionLoading ? t.processing : t.confirmWithdraw}
          </Button>
        </div>
      </SharedActionModal>

      <SharedActionModal show={showSend} onClose={() => setShowSend(false)} title={sendMoneyLabel}>
        <div className="space-y-3">
          <div>
            <Label className="text-xs text-muted-foreground">{t.recipientId}</Label>
            <Input
              value={sendRecipient}
              onChange={e => setSendRecipient(e.target.value)}
              className="mt-1 rounded-lg"
              placeholder={t.userIdPlaceholder}
            />
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">{t.sendAmount}</Label>
            <Input
              type="number"
              value={sendAmount}
              onChange={e => setSendAmount(e.target.value)}
              className="mt-1 rounded-lg"
              placeholder="0.00"
            />
          </div>
          <div>
            <Label className="text-xs text-muted-foreground">{t.noteOptional}</Label>
            <Input
              value={sendNote}
              onChange={e => setSendNote(e.target.value)}
              className="mt-1 rounded-lg"
              placeholder={t.notePlaceholder}
            />
          </div>
          <Button
            onClick={() => { void onSend(); }}
            disabled={actionLoading}
            className="h-11 w-full rounded-xl font-semibold"
            style={{ background: WaselColors.teal }}
          >
            {actionLoading
              ? t.processing
              : `${t.confirmSend} ${sendAmount ? `${sendAmount} ${t.jod}` : ''}`}
          </Button>
        </div>
      </SharedActionModal>

      <SharedActionModal
        show={showPinSetup}
        onClose={() => {
          setShowPinSetup(false);
          setPinValue('');
        }}
        title={walletData?.pinSet ? changePinLabel : setPinLabel}
      >
        <div className="space-y-4">
          <p className="text-sm text-muted-foreground">{t.pinDescription}</p>
          <div className="flex justify-center gap-3">
            {[0, 1, 2, 3].map(index => (
              <div
                key={index}
                className={`flex h-14 w-12 items-center justify-center rounded-xl border-2 text-2xl font-bold transition-all ${pinValue.length > index ? 'border-primary text-foreground' : 'border-border text-transparent'}`}
              >
                {pinValue[index] ? '•' : ''}
              </div>
            ))}
          </div>
          <Input
            type="tel"
            maxLength={4}
            value={pinValue}
            onChange={e => setPinValue(e.target.value.replace(/\D/g, '').slice(0, 4))}
            className="rounded-lg text-center text-2xl tracking-[1em]"
            placeholder={t.maskedPin}
            autoFocus
          />
          <Button
            onClick={() => { void onSetPin(); }}
            disabled={actionLoading || pinValue.length !== 4}
            className="h-11 w-full rounded-xl font-semibold"
            style={{ background: WaselColors.teal }}
          >
            {actionLoading ? t.processing : t.setPin}
          </Button>
        </div>
      </SharedActionModal>
    </>
  );
}

