          <div style={HEADER_INNER_STYLE}>
            <button
              onClick={() => { void navigate(); }}
              style={{
                background: 'none',
                border: 'none',
                cursor: 'pointer',
                padding: 0,
                display: 'flex',
                alignItems: 'center',
                flexShrink: 0,
                transition: 'opacity 0.15s',
              }}
            >
              <WaselLogo size={56} theme="light" variant="full" />
            </button>

            <div
              className="wrl-desk-actions"
              style={{
                display: 'flex',
                gap: 8,
                alignItems: 'center',
                flexShrink: 0,
                paddingInlineStart: 10,
                borderInlineStart: `1px solid ${C.borderFaint}`,
              }}
            >
              <LangToggle />
              {user ? <CurrencySwitcher ar={ar} /> : null}
              {user && isDriverMode ? <OnlineToggle ar={ar} /> : null}

              {user ? (
                <>
                  <button
                    onClick={() => { void navigate(); }}
                    title={shellCopy.notifications}
                    aria-label={shellCopy.notifications}
                    style={{
                      position: 'relative',
                      width: 38,
                      height: 38,
                      borderRadius: R.md,
                      background: C.card,
                      border: `1px solid ${C.border}`,
                      cursor: 'pointer',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      transition: 'all 0.14s',
                    }}
                  >
                    <svg
                      width="15"
                      height="15"
                      viewBox="0 0 24 24"
                      fill="none"
                      stroke={C.textSub}
                      strokeWidth="2"
                      strokeLinecap="round"
                    >
                      <path d="M18 8A6 6 0 0 0 6 8c0 7-3 9-3 9h18s-3-2-3-9M13.73 21a2 2 0 0 1-3.46 0" />
                    </svg>
                    <div
                      style={{
                        position: 'absolute',
                        top: 6,
                        insetInlineEnd: 6,
                        width: 7,
                        height: 7,
                        borderRadius: '50%',
                        background: C.error,
                        border: `1.5px solid ${C.bg}`,
                      }}
                    />
                  </button>
                  <UserMenu user={user} onSignOut={signOut} ar={ar} />
                </>
              ) : (
                <>
                  <button
                    onClick={() => { void navigate(); }}
                    style={{
                      height: 38,
                      padding: '0 16px',
                      borderRadius: R.md,
                      fontSize: '0.82rem',
                      fontWeight: 600,
                      background: 'transparent',
                      border: `1.5px solid ${C.border}`,
                      color: C.text,
                      fontFamily: ar ? FA : F,
                      cursor: 'pointer',
                      transition: 'all 0.14s',
                      whiteSpace: 'nowrap',
                    }}
                  >
                    {shellCopy.signIn}
                  </button>
                  <button
                    onClick={() => { void navigate(); }}
                    style={{
                      height: 40,
                      padding: '0 18px',
                      borderRadius: R.md,
                      fontSize: '0.82rem',
                      fontWeight: 800,
                      background: GRAD,
                      border: 'none',
                      color: C.bg,
                      fontFamily: ar ? FA : F,
                      cursor: 'pointer',
                      whiteSpace: 'nowrap',
                      transition: 'all 0.14s',
                      boxShadow: '0 10px 24px rgba(56,190,255,0.22)',
                    }}
                  >
                    {shellCopy.getStarted}
                  </button>
                </>
              )}
            </div>
          </div>
        </header>

        <Suspense fallback={null}>
          <AvailabilityBanner ar={ar} />
        </Suspense>

        <div className="wrl-main-content content-visibility-auto">
          <main
            id="main-content"
            role="main"
            aria-label={shellCopy.mainContent}
            tabIndex={-1}
            style={MAIN_CONTENT_STYLE}
          >
            <div
              aria-hidden="true"
              style={BACKGROUND_OVERLAY_STYLE}
            />
            <Outlet />
          </main>

          <Suspense fallback={null}>
            <MobileBottomNav language={language} />
          </Suspense>
        </div>
      </div>
    </>
  );
});

export default memo(() => <WaselRootInner />);

import React, { useEffect, useRef, useState } from 'react';
import { Activity, Settings, ShieldCheck, Sparkles, UserCircle2, Wallet, X } from 'lucide-react';
import { WaselLogo } from '../../components/wasel-ui/WaselLogo';
import { useIframeSafeNavigate } from '../../hooks/useIframeSafeNavigate';
import { lockBodyScroll } from '../../utils/bodyScrollLock';
import {
  getVisibleNavItems,
  isVisibleNavGroup,
  PRODUCT_NAV_GROUPS,
  type NavGroup,
} from '../waselRootConfig';
import { CurrencyService } from '../../utils/currency';
import { C, F, GRAD, R } from '../../utils/wasel-ds';
import { CurrencySwitcher, LangToggle } from './controls';
import { Badge, SocialLinks, getDrawerSectionLabel } from './shared';

export function NavDropdown({
  group,
  onNavigate,
  align,
  ar,
  isAuthenticated,
}: {
  group: NavGroup;
  onNavigate: (path: string) => void;
  align?: 'left' | 'center' | 'right';
  ar: boolean;
  isAuthenticated: boolean;
}) {
  if ('direct' in group && group.direct) {return null;}
  const items = getVisibleNavItems(group, isAuthenticated);
  if (!items.length) {return null;}
