export default function WaselAuth () {
  const [ params ] = useSearchParams();
  const rawTab = params.get( 'tab' )?.toLowerCase();
  const initialTab: Tab = rawTab === 'signup' || rawTab === 'register' ? 'signup' : 'signin';
  const passwordResetCompleted = params.get( 'reset' ) === 'success';
  const { language } = useLanguage();
  const ar = language === 'ar';

  const [ tab, setTab ] = useState<Tab>( initialTab );
  const [ email, setEmail ] = useState( '' );
  const [ password, setPassword ] = useState( '' );
  const [ name, setName ] = useState( '' );
  const [ phone, setPhone ] = useState( '' );
  const [ error, setError ] = useState( '' );
  const [ success, setSuccess ] = useState( false );
  const [ notice, setNotice ] = useState(
    passwordResetCompleted
      ? ar
        ? 'تم تحديث كلمة المرور. سجّل الدخول بكلمة المرور الجديدة.'
        : 'Password updated. Sign in with your new password.'
      : '',
  );
  const [ emailError, setEmailError ] = useState( '' );
  const [ passwordError, setPasswordError ] = useState( '' );
  const [ nameError, setNameError ] = useState( '' );
  const [ phoneError, setPhoneError ] = useState( '' );

  const { signIn, register, loading, user } = useLocalAuth();
  const { resetPassword, signInWithGoogle, signInWithFacebook, signInWithMicrosoft, signInWithApple } = useAuth();
  const nav = useIframeSafeNavigate();
  const mountedRef = useRef( true );
  const { supportWhatsAppNumber } = getConfig();
  const [ oauthConfigWarning, setOauthConfigWarning ] = useState( '' );
  const [ activeProvider, setActiveProvider ] = useState<null | 'google' | 'facebook' | 'microsoft' | 'apple'>( null );

  const safeReturnTo = normalizeReturnToPath( params.get( 'returnTo' ) );

  const validateEmailRealtime = ( value: string ) => {
    if ( !value.trim() ) {
      setEmailError( ar ? 'البريد الإلكتروني مطلوب' : 'Email is required' );
      return false;
    }
    if ( !validateEmail( value ) ) {
      setEmailError( ar ? 'صيغة البريد الإلكتروني غير صحيحة' : 'Invalid email format' );
      return false;
    }
    setEmailError( '' );
    return true;
  };

  const validatePasswordRealtime = ( value: string ) => {
    if ( tab === 'signup' && value.length > 0 && value.length < 8 ) {
      setPasswordError( ar ? 'كلمة المرور يجب أن تكون 8 أحرف على الأقل' : 'Password must be at least 8 characters' );
      return false;
    }
    setPasswordError( '' );
    return true;
  };

  const validateNameRealtime = ( value: string ) => {
    if ( tab === 'signup' && !value.trim() ) {
      setNameError( ar ? 'الاسم الكامل مطلوب' : 'Full name is required' );
      return false;
    }
    setNameError( '' );
    return true;
  };

  const validatePhoneRealtime = ( value: string ) => {
    if ( tab === 'signup' && value.trim() && !validatePhone( value ) ) {
      setPhoneError( ar ? 'صيغة رقم الهاتف غير صحيحة (مثال: +962791234567)' : 'Invalid phone format (e.g. +962791234567)' );
      return false;
    }
    setPhoneError( '' );
    return true;
  };

  useEffect( () => {
    mountedRef.current = true;
    return () => {
      mountedRef.current = false;
    };
  }, [] );

  useEffect( () => {
    if ( user && mountedRef.current ) { nav( safeReturnTo ); }
  }, [ user, nav, safeReturnTo ] );

  // Check for OAuth configuration issues on mount (dev mode only)
  useEffect( () => {
    if ( !import.meta.env.DEV ) {
      return;
    }

    const checkOAuthConfig = async () => {
      try {
        if ( !supabase ) {
          return;
        }

        // Try to get Facebook auth URL without redirecting
        const { error } = await supabase.auth.signInWithOAuth( {
          provider: 'facebook',
          options: {
            skipBrowserRedirect: true,
          },
        } );

        if ( error ) {
          const message = error.message?.toLowerCase() || '';
          if ( message.includes( 'not enabled' ) ) {
            setOauthConfigWarning( ar ? 'فيسبوك غير مفعّل في Supabase' : 'Facebook is not enabled in Supabase' );
          } else if ( message.includes( 'redirect_uri' ) || message.includes( 'uri not allowed' ) ) {
            setOauthConfigWarning( ar ? 'مشكلة في إعدادات فيسبوك' : 'Facebook redirect URI is not configured correctly' );
          }
        }
      } catch {
        // Silently ignore errors in config check
      }
    };

    void checkOAuthConfig();
  }, [ ar ] );

  const pushSuccessRedirect = () => {
    setSuccess( true );
    setTimeout( () => {
      if ( mountedRef.current ) { nav( safeReturnTo ); }
    }, 700 );
  };

  const handleFormSubmit = async ( e: React.FormEvent ) => {
    e.preventDefault();
    if ( tab === 'signin' ) {
      await handleSignIn();
    } else {
      await handleSignUp();
    }
  };

  const handleTabChange = ( next: Tab ) => {
    setTab( next );
    setError( '' );
    setSuccess( false );
    if ( !passwordResetCompleted ) {
      setNotice( '' );
    }
  };

  const handleSignIn = async () => {
    setError( '' );
    if ( !passwordResetCompleted ) {
      setNotice( '' );
    }
    if ( !email.trim() ) {
      setError( tx( 'waselAuth.error_enter_email' ) );
      return;
    }
    if ( !validateEmail( email ) ) {
      setError( tx( 'waselAuth.error_enter_valid_email' ) );
      return;
    }
    if ( !password ) {
      setError( tx( 'waselAuth.error_enter_password' ) );
      return;
    }
    if ( !checkRateLimit( `signin:${ email }`, { maxRequests: 5, windowMs: 60_000 } ) ) {
      setError( tx( 'waselAuth.error_too_many_attempts' ) );
      return;
    }
    const { error: signInError } = await signIn( email, password );
    if ( signInError ) {
      setError( friendlyAuthError( signInError, tx( 'waselAuth.error_signin_failed' ) ) );
      return;
    }
    resetRateLimit( `signin:${ email }` );
    pushSuccessRedirect();
  };

  const handleSignUp = async () => {
    setError( '' );
    if ( !passwordResetCompleted ) {
      setNotice( '' );
    }
    if ( !name.trim() ) {
      setError( tx( 'waselAuth.error_enter_full_name' ) );
      return;
    }
    if ( !email.trim() ) {
      setError( tx( 'waselAuth.error_enter_email' ) );
      return;
    }
    if ( !validateEmail( email ) ) {
      setError( tx( 'waselAuth.error_enter_valid_email' ) );
      return;
    }
    if ( password.length < 8 ) {
      setError( tx( 'waselAuth.error_password_min_length' ) );
      return;
    }
    if ( !/[a-z]/.test( password ) || !/[A-Z]/.test( password ) || !/\d/.test( password ) || !/[^a-zA-Z0-9]/.test( password ) ) {
      setError( tx( 'waselAuth.error_password_requirements' ) );
      return;
    }
    if ( !checkRateLimit( `signup:${ email }`, { maxRequests: 3, windowMs: 60_000 } ) ) {
      setError( tx( 'waselAuth.error_too_many_attempts' ) );
      return;
    }
    const registration = await register({ name, email, password, phone, returnTo: safeReturnTo });
    if ( registration.error ) {
      setError( friendlyAuthError( registration.error, tx( 'waselAuth.error_signup_failed' ) ) );
      return;
    }
    if ( registration.requiresEmailConfirmation ) {
      setPassword( '' );
      setNotice(
        tx( 'waselAuth.confirm_email_notice', { email: registration.email ?? email } ),
      );
      setTab( 'signin' );
      resetRateLimit( `signup:${ email }` );
      return;
    }
    resetRateLimit( `signup:${ email }` );
    pushSuccessRedirect();
  };

  const handleForgotPassword = async () => {
    if ( !email.trim() ) {
      setError( tx( 'waselAuth.error_enter_email_first' ) );
      return;
    }
    if ( !validateEmail( email ) ) {
      setError( tx( 'waselAuth.error_enter_valid_email' ) );
      return;
    }
    const { error: resetError } = await resetPassword( email, safeReturnTo );
    if ( resetError ) {
      setError( friendlyAuthError( resetError, tx( 'waselAuth.error_reset_failed' ) ) );
      return;
    }
    setError( '' );
    toast.success( tx( 'waselAuth.reset_link_sent', { email } ) );
  };

  const runOAuth = async (
    provider: 'google' | 'facebook' | 'microsoft' | 'apple',
    signIn: ( returnTo?: string ) => Promise<{ error: AuthOperationError }>,
  ) => {
    setError( '' );
    setActiveProvider( provider );
    try {
      const { error: oauthError } = await signIn( safeReturnTo );
      if ( oauthError && mountedRef.current ) {
        const enhancedMessage = enhanceOAuthError( String( oauthError ), provider );
        setError( friendlyAuthError( enhancedMessage, tx( `waselAuth.error_${ provider }_failed` ) ) );
      }
    } finally {
      if ( mountedRef.current ) {
        setActiveProvider( null );
      }
    }
  };

  const handleGoogleSignIn = () => {
    void runOAuth( 'google', signInWithGoogle );
  };

  const handleFacebookSignIn = () => {
    void runOAuth( 'facebook', signInWithFacebook );
  };

  const handleMicrosoftSignIn = () => {
    void runOAuth( 'microsoft', signInWithMicrosoft );
  };

  const handleAppleSignIn = () => {
    void runOAuth( 'apple', signInWithApple );
  };

  const handleWhatsAppHelp = () => {
    if ( !supportWhatsAppNumber ) {
      setError( tx( 'waselAuth.error_whatsapp_not_configured' ) );
      return;
    }
    window.open( getWhatsAppSupportUrl( ar ? 'مرحبا واصل' : 'Hi Wasel' ), '_blank', 'noopener,noreferrer' );
  };

  /**
   * Enhance OAuth error messages with actionable recovery steps
   */
  const enhanceOAuthError = ( error: string, provider: 'google' | 'facebook' | 'microsoft' | 'apple' ): string => {
    const lower = error.toLowerCase();
    const providerName = provider.charAt( 0 ).toUpperCase() + provider.slice( 1 );

    if ( lower.includes( 'redirect_uri' ) || lower.includes( 'uri not allowed' ) || lower.includes( 'invalid redirect' ) ) {
      const instructions = getProviderSetupInstructions( provider );
      return `${ providerName } sign-in is not configured correctly. To fix this:\n\n${ instructions.steps.map( ( s, i ) => `${ i + 1 }. ${ s }` ).join( '\n' ) }`;
    }

    if ( lower.includes( 'client' ) && ( lower.includes( 'invalid' ) || lower.includes( 'not found' ) ) ) {
      return `${ providerName } authentication credentials are missing or invalid. Check Supabase Dashboard > Authentication > Providers > ${ providerName }.`;
    }

    return error;
  };

  const socialButtons: Array<{
    key: 'google' | 'facebook' | 'microsoft' | 'apple' | 'whatsapp';
    label: string;
    color: string;
    onClick: () => void;
  }> = [
    { key: 'google', label: 'Google', color: '#4285F4', onClick: handleGoogleSignIn },
    { key: 'facebook', label: 'Facebook', color: '#1877F2', onClick: handleFacebookSignIn },
    { key: 'microsoft', label: 'Microsoft', color: '#00A4EF', onClick: handleMicrosoftSignIn },
    { key: 'apple', label: 'Apple', color: '#000000', onClick: handleAppleSignIn },
    ...( supportWhatsAppNumber
      ? [ { key: 'whatsapp' as const, label: 'WhatsApp', color: '#25D366', onClick: handleWhatsAppHelp } ]
      : [] ),
  ];

  return (
    <div
      className="auth-grid"
      style={ {
        minHeight: '100vh',
        background: C.bg,
        color: C.text,
        fontFamily: F,
        display: 'grid',
        gridTemplateColumns: '1fr 1fr',
      } }
    >
      <style>{ `
        @media(max-width:768px){
          .auth-grid{grid-template-columns:1fr!important}
          .auth-brand-panel{display:none!important}
          .auth-form-panel{padding:${ SPACE[ 7 ] } ${ SPACE[ 5 ] }!important;align-items:flex-start!important}
          .auth-mobile-header{display:flex!important}
        }
        @keyframes spin{to{transform:rotate(360deg)}}
        @keyframes pulse-dot{0%,100%{opacity:1;transform:scale(1)}50%{opacity:.5;transform:scale(0.85)}}
      `}</style>

      <BrandPanel />

      {/* ── Form panel ─────────────────────────────────────────────────── */ }
      <div
        className="auth-form-panel"
        style={ {
          background: `linear-gradient(180deg, ${ C.bg } 0%, ${ C.bgAlt } 100%)`,
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          padding: `${ SPACE[ 16 ] } ${ SPACE[ 12 ] }`,
          overflowY: 'auto',
        } }
      >
        <div style={ { width: '100%', maxWidth: 440 } }>
          {/* Mobile header (hidden on desktop) */ }
          <div
            className="auth-mobile-header"
            style={ {
              display: 'none',
              flexDirection: 'column',
              alignItems: 'center',
              textAlign: 'center',
              marginBottom: SPACE[ 7 ],
              paddingBottom: SPACE[ 6 ],
              borderBottom: `1px solid ${ C.border }`,
            } }
          >
            <WaselLogo size={ 64 } theme="light" variant="full" />
            <h2
              style={ {
                fontSize: TYPE.size.xl,
                fontWeight: TYPE.weight.ultra,
                color: C.text,
                marginTop: SPACE[ 4 ],
                marginBottom: SPACE[ 2 ],
                letterSpacing: '-0.03em',
              } }
            >
              <span style={ { color: C.cyan } }>{ tx( 'waselAuth.one_identity_2' ) }</span>
            </h2>
            <p style={ { fontSize: TYPE.size.sm, color: C.textMuted, marginBottom: SPACE[ 3 ] } }>
              { tx( 'waselAuth.sign_in_once_for_rides_parcels_buses_and_trust' ) }
            </p>
          </div>

          <TabSwitcher tab={ tab } onChange={ handleTabChange } />

          {/* Heading */ }
          <div style={ { marginBottom: SPACE[ 6 ] } }>
            <h3
              style={ {
                fontSize: TYPE.size[ '2xl' ],
                fontWeight: TYPE.weight.ultra,
                color: C.text,
                margin: `0 0 ${ SPACE[ 2 ] }`,
                letterSpacing: '-0.02em',
              } }
            >
              { ar
                ? tab === 'signin'
                  ? 'مرحباً بعودتك إلى واصل'
                  : 'أنشئ حسابك في واصل'
                : tab === 'signin'
                  ? 'Welcome back to Wasel'
                  : 'Create your Wasel account' }
            </h3>
            <p
              style={ {
                fontSize: TYPE.size.sm,
                color: C.textMuted,
                margin: 0,
                lineHeight: TYPE.lineHeight.relaxed,
              } }
            >
              { tab === 'signin'
                ? tx( 'waselAuth.subtitle_signin' )
                : tx( 'waselAuth.subtitle_signup' ) }
            </p>
          </div>

          {/* Error banner */ }
          <AnimatePresence>
            { oauthConfigWarning && !error && (
              <motion.div
                initial={ { opacity: 0, height: 0 } }
                animate={ { opacity: 1, height: 'auto' } }
                exit={ { opacity: 0, height: 0 } }
                style={ { overflow: 'hidden', marginBottom: SPACE[ 5 ] } }
              >
                <WaselCard
                  variant="solid"
                  padding={ `${ SPACE[ 3 ] } ${ SPACE[ 4 ] }` }
                  radius={ R.lg }
                  style={ { background: '#FEF3C7', border: '1px solid #F59E0B40' } }
                >
                  <div style={ { display: 'flex', alignItems: 'flex-start', gap: SPACE[ 2 ] } }>
                    <AlertCircle size={ 16 } color="#D97706" style={ { flexShrink: 0, marginTop: 2 } } />
                    <span style={ { fontSize: TYPE.size.sm, color: '#92400E', fontFamily: F } }>
                      { oauthConfigWarning }
                    </span>
                  </div>
                </WaselCard>
              </motion.div>
            ) }
          </AnimatePresence>

          <AnimatePresence>
            { notice && !error && !success && (
              <motion.div
                initial={ { opacity: 0, height: 0 } }
                animate={ { opacity: 1, height: 'auto' } }
                exit={ { opacity: 0, height: 0 } }
                style={ { overflow: 'hidden', marginBottom: SPACE[ 5 ] } }
              >
                <WaselCard
                  variant="solid"
                  padding={ `${ SPACE[ 3 ] } ${ SPACE[ 4 ] }` }
                  radius={ R.lg }
                  style={ { background: C.greenDim, border: `1px solid ${ C.green }40` } }
                >
                  <span style={ { fontSize: TYPE.size.sm, color: C.green, fontFamily: F } }>
                    { notice }
                  </span>
                </WaselCard>
              </motion.div>
            ) }
          </AnimatePresence>

          <AnimatePresence>
            { error && (
              <motion.div
                initial={ { opacity: 0, height: 0 } }
                animate={ { opacity: 1, height: 'auto' } }
                exit={ { opacity: 0, height: 0 } }
                style={ { overflow: 'hidden', marginBottom: SPACE[ 5 ] } }
              >
                <WaselCard
                  variant="solid"
                  padding={ `${ SPACE[ 3 ] } ${ SPACE[ 4 ] }` }
                  radius={ R.lg }
                  style={ { background: C.errorDim, border: `1px solid ${ C.error }40` } }
                >
                  <div style={ { display: 'flex', alignItems: 'flex-start', gap: SPACE[ 2 ] } }>
                    { error.includes( '\n' ) && (
                      <AlertCircle size={ 16 } color={ C.error } style={ { flexShrink: 0, marginTop: 2 } } />
                    ) }
                    <span
                      style={ {
                        fontSize: TYPE.size.sm,
                        color: C.error,
                        fontFamily: F,
                        whiteSpace: 'pre-line',
                        lineHeight: TYPE.lineHeight.relaxed,
                      } }
                    >
                      { error }
                    </span>
                  </div>
                </WaselCard>
              </motion.div>
            ) }
          </AnimatePresence>

          {/* Success banner */ }
          <AnimatePresence>
            { success && (
              <motion.div
                initial={ { opacity: 0, scale: 0.96 } }
                animate={ { opacity: 1, scale: 1 } }
                style={ { marginBottom: SPACE[ 5 ] } }
              >
                <WaselCard
                  variant="solid"
                  padding={ `${ SPACE[ 3 ] } ${ SPACE[ 4 ] }` }
                  radius={ R.lg }
                  style={ { background: C.greenDim, border: `1px solid ${ C.green }40` } }
                >
                  <div style={ { display: 'flex', alignItems: 'center', gap: SPACE[ 2 ] } }>
                    <CheckCircle2 size={ 16 } color={ C.green } />
                    <span style={ { fontSize: TYPE.size.sm, color: C.green, fontFamily: F } }>
                      { tx( 'waselAuth.signed_in_successfully_redirecting_now' ) }
                    </span>
                  </div>
                </WaselCard>
              </motion.div>
            ) }
          </AnimatePresence>

          {/* Fields */ }
          <AnimatePresence mode="wait">
            <motion.div
              key={ tab }
              initial={ { opacity: 0, x: 12 } }
              animate={ { opacity: 1, x: 0 } }
              exit={ { opacity: 0, x: -12 } }
              transition={ { duration: 0.15 } }
            >
              <form
                onSubmit={ handleFormSubmit }
                style={ { display: 'flex', flexDirection: 'column', gap: SPACE[ 4 ] } }
              >
                { tab === 'signup' && (
                  <div>
                    <WaselInput
                      id="full-name"
                      label={ tx( 'auth.fullName' ) }
                      description={ tx( 'waselAuth.as_shown_on_your_profile' ) }
                      value={ name }
                      onChange={ value => { setName( value ); validateNameRealtime( value ); } }
                      placeholder={ tx( 'waselAuth.ahmad_al_rashid' ) }
                      icon={ <UserRound size={ 16 } /> }
                    />
                    { nameError && (
                      <span style={ { color: C.error, fontSize: TYPE.size.xs, marginTop: 4, display: 'block' } }>
                        { nameError }
                      </span>
                    ) }
                  </div>
                ) }

                <div>
                  <WaselInput
                    id="auth-email"
                    label={ tx( 'common.email' ) }
                    description={ tx( 'waselAuth.used_for_sign_in' ) }
                    type="email"
                    value={ email }
                    onChange={ value => { setEmail( value ); validateEmailRealtime( value ); } }
                    placeholder={ tx( 'waselAuth.you_example_com' ) }
                    icon={ <Mail size={ 16 } /> }
                  />
                  { emailError && (
                    <span style={ { color: C.error, fontSize: TYPE.size.xs, marginTop: 4, display: 'block' } }>
                      { emailError }
                    </span>
                  ) }
                </div>

                <div>
                  <WaselInput
                    id="auth-password"
                    label={ tx( 'auth.password' ) }
                    description={
                      tab === 'signin'
                        ? tx( 'waselAuth.your_account_password' )
                        : tx( 'waselAuth.minimum_8_characters' )
                    }
                    type="password"
                    value={ password }
                    onChange={ value => { setPassword( value ); validatePasswordRealtime( value ); } }
                    placeholder={
                      tab === 'signin'
                        ? tx( 'waselAuth.enter_your_password' )
                        : tx( 'waselAuth.create_a_secure_password' )
                    }
                    icon={ <Lock size={ 16 } /> }
                    hint={
                      tab === 'signup' && password.length > 0 ? (
                        <StrengthBar password={ password } />
                      ) : undefined
                    }
                  />
                  { passwordError && (
                    <span style={ { color: C.error, fontSize: TYPE.size.xs, marginTop: 4, display: 'block' } }>
                      { passwordError }
                    </span>
                  ) }
                </div>

                { tab === 'signup' && (
                  <div>
                    <WaselInput
                      id="auth-phone"
                      label={ tx( 'auth.phoneNumber' ) }
                      description={ tx( 'common.optional' ) }
                      type="tel"
                      value={ phone }
                      onChange={ value => { setPhone( value ); validatePhoneRealtime( value ); } }
                      placeholder="+962 79 123 4567"
                      icon={ <Phone size={ 16 } /> }
                    />
                    { phoneError && (
                      <span style={ { color: C.error, fontSize: TYPE.size.xs, marginTop: 4, display: 'block' } }>
                        { phoneError }
                      </span>
                    ) }
                  </div>
                ) }

                { tab === 'signin' && (
                  <div style={ { textAlign: 'right' } }>
                    <button
                      type="button"
                      onClick={ handleForgotPassword }
                      style={ {
                        background: 'none',
                        border: 'none',
                        color: C.cyan,
                        fontSize: TYPE.size.xs,
                        cursor: 'pointer',
                        fontFamily: F,
                        padding: 0,
                      } }
                    >
                      { tx( 'waselAuth.forgot_password' ) }
                    </button>
                  </div>
                ) }

                <WaselButton
                  variant="primary"
                  size="lg"
                  fullWidth
                  loading={ loading }
                  disabled={ success }
                  type="submit"
                  aria-label={ tab === 'signin' ? tx( 'waselAuth.submit_signin' ) : tx( 'waselAuth.submit_signup' ) }
                  iconEnd={ <ArrowRight size={ 16 } /> }
                >
                  { tab === 'signin' ? tx( 'waselAuth.sign_in' ) : tx( 'waselAuth.create_account' ) }
                </WaselButton>

                {/* Divider */ }
                <div style={ { display: 'flex', alignItems: 'center', gap: SPACE[ 3 ] } }>
                  <div style={ { flex: 1, height: 1, background: C.border } } />
                  <span style={ { fontSize: TYPE.size.xs, color: C.textMuted } }>
                    { tx( 'waselAuth.or_continue_with' ) }
                  </span>
                  <div style={ { flex: 1, height: 1, background: C.border } } />
                </div>

                {/* Social buttons */ }
                <div style={ { display: 'flex', gap: SPACE[ 2 ], flexWrap: 'wrap' } }>
                  { socialButtons.map( social => {
                    const isActive = activeProvider === social.key;
                    const disabled = loading || success || ( activeProvider !== null && !isActive );
                    return (
                      <motion.button
                        key={ social.key }
                        whileHover={ disabled ? undefined : { scale: 1.02 } }
                        whileTap={ disabled ? undefined : { scale: 0.97 } }
                        type="button"
                        disabled={ disabled }
                        aria-label={ ar ? `تسجيل الدخول عبر ${ social.label }` : `Continue with ${ social.label }` }
                        aria-busy={ isActive }
                        data-provider={ social.key }
                        onClick={ () => {
                          social.onClick();
                        } }
                        style={ {
                          flex: '1 1 120px',
                          minWidth: 120,
                          height: 44,
                          borderRadius: R.lg,
                          border: `1px solid ${ social.color }30`,
                          background: `${ social.color }0C`,
                          color: social.color,
                          fontWeight: TYPE.weight.black,
                          fontSize: TYPE.size.sm,
                          fontFamily: F,
                          cursor: disabled ? 'not-allowed' : 'pointer',
                          opacity: disabled ? 0.55 : 1,
                          transition: 'all 150ms ease',
                          display: 'inline-flex',
                          alignItems: 'center',
                          justifyContent: 'center',
                          gap: SPACE[ 2 ],
                        } }
                      >
                        { isActive && (
                          <span
                            aria-hidden="true"
                            style={ {
                              width: 12,
                              height: 12,
                              borderRadius: '50%',
                              border: `2px solid ${ social.color }40`,
                              borderTopColor: social.color,
                              animation: 'spin 0.8s linear infinite',
                              display: 'inline-block',
                            } }
                          />
                        ) }
                        <span>{ social.label }</span>
                      </motion.button>
                    );
                  } ) }
                </div>
              </form>
            </motion.div>
          </AnimatePresence>

          {/* Legal */ }
          <p
            style={ {
              fontSize: TYPE.size.xs,
              color: C.textMuted,
              textAlign: 'center',
              marginTop: SPACE[ 6 ],
              lineHeight: TYPE.lineHeight.relaxed,
            } }
          >
            { tx( 'waselAuth.by_continuing_you_agree_to_our' ) }{ ' ' }
            <button
              type="button"
              onClick={ () => nav( '/terms' ) }
              style={ {
                color: C.cyan,
                cursor: 'pointer',
                background: 'none',
                border: 'none',
                padding: 0,
                font: 'inherit',
              } }
            >
              { tx( 'sidebar.terms' ) }
            </button>{ ' ' }
            { tx( 'waselAuth.and' ) }{ ' ' }
            <button
              type="button"
              onClick={ () => nav( '/privacy' ) }
              style={ {
                color: C.cyan,
                cursor: 'pointer',
                background: 'none',
                border: 'none',
                padding: 0,
                font: 'inherit',
              } }
            >
              { tx( 'sidebar.privacy' ) }
            </button>
            .
          </p>
        </div>
      </div>
    </div>
  );
}

import { useEffect, useMemo, useState } from 'react';
import type { AuthChangeEvent } from '@supabase/auth-js';
import { useIframeSafeNavigate } from '../hooks/useIframeSafeNavigate';
import { supabase } from '../utils/supabase/client';
import { normalizeReturnToPath } from '../utils/env';
import { tx } from '../locales/tx';

type CallbackState = 'loading' | 'closing' | 'redirecting' | 'recovery' | 'error';

function readCallbackParam(key: string): string {
  if (typeof window === 'undefined') {
    return '';
  }

  const searchValue = new URLSearchParams(window.location.search).get(key);
  if (searchValue) {
    return searchValue;
  }

  const hash = window.location.hash.startsWith('#')
    ? window.location.hash.slice(1)
    : window.location.hash;

  return new URLSearchParams(hash).get(key) ?? '';
}

export default function WaselAuthCallback() {
  const navigate = useIframeSafeNavigate();
  const [state, setState] = useState<CallbackState>('loading');
  const [message, setMessage] = useState('Completing sign-in...');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [formError, setFormError] = useState('');
  const [savingPassword, setSavingPassword] = useState(false);
  const callbackType = useMemo(() => readCallbackParam('type'), []);
  const returnTo = useMemo(() => normalizeReturnToPath(readCallbackParam('returnTo')), []);
  const callbackError = useMemo(() => {
    const raw = readCallbackParam('error_description') || readCallbackParam('error') || '';
    if (!raw) {return '';}
    try {
      // Sanitize: only allow printable ASCII, strip control chars and HTML
      return decodeURIComponent(raw)
        .replace(/[<>"'`]/g, '')
        // eslint-disable-next-line no-control-regex
        .replace(/[\x00-\x1f\x7f]/g, '')
        .slice(0, 200);
    } catch {
      return '';
    }
  }, []);

  useEffect(() => {
    let active = true;
    let isRecoveryFlow = callbackType === 'recovery';

    const finishAuth = async () => {
      if (!supabase) {
        if (!active) {return;}
        setState('error');
        setMessage('Backend is not configured for social sign-in.');
        return;
      }

      if (callbackError) {
        if (!active) {return;}
        setState('error');
        setMessage(callbackError);
        return;
      }

      const {
        data: { subscription },
      } = supabase.auth.onAuthStateChange((event: AuthChangeEvent) => {
        if (!active) {return;}

        if (event === 'PASSWORD_RECOVERY') {
          isRecoveryFlow = true;
          setState('recovery');
          setMessage('Set a new password to finish recovering your account.');
          setFormError('');
        }
      });

      try {
        await new Promise(resolve => setTimeout(resolve, 50));

        if (isRecoveryFlow) {
          if (!active) {return;}
          setState('recovery');
          setMessage('Set a new password to finish recovering your account.');
          return;
        }

        const {
          data: { session },
          error,
        } = await supabase.auth.getSession();
        if (error) {
          throw error;
        }

        if (!session) {
          throw new Error('Authentication session could not be established.');
        }

        if (window.opener && !window.opener.closed) {
          setState('closing');
          setMessage('Sign-in complete. You can return to Wasel.');
          window.opener.postMessage({ type: 'wasel-auth-complete' }, window.location.origin);
          window.close();
          return;
        }

        setState('redirecting');
        setMessage('Sign-in complete. Redirecting...');
        navigate(returnTo, { replace: true });
      } catch (error) {
        if (!active) {return;}
        setState('error');
        setMessage(error instanceof Error ? error.message : 'Unable to complete sign-in.');
      } finally {
        subscription.unsubscribe();
      }
    };

    void finishAuth();

    return () => {
      active = false;
    };
  }, [callbackError, callbackType, navigate, returnTo]);

  const handlePasswordUpdate = async () => {
    if (!supabase) {
      setFormError('Backend is not configured for password recovery.');
      return;
    }

    if (password.length < 8) {
      setFormError('Password must be at least 8 characters long.');
      return;
    }

    if (password !== confirmPassword) {
      setFormError('Passwords do not match.');
      return;
    }

    setFormError('');
    setSavingPassword(true);

    const { error } = await supabase.auth.updateUser({ password });
    if (error) {
      setSavingPassword(false);
      setFormError(error.message || 'Unable to update your password.');
      return;
    }

    await supabase.auth.signOut().catch(() => undefined);

    setState('redirecting');
    setMessage('Password updated. Redirecting to sign in...');
    navigate(`/app/auth?tab=signin&reset=success&returnTo=${encodeURIComponent(returnTo)}`, {
      replace: true,
    });
  };

  if (state === 'recovery') {
    return (
      <div
        style={{
          minHeight: '100vh',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          background: '#040C18',
          color: '#EFF6FF',
          padding: 24,
          fontFamily: "-apple-system,'Inter',sans-serif",
        }}
      >
        <div
          style={{
            width: '100%',
            maxWidth: 420,
            borderRadius: 20,
            padding: 28,
            background: 'rgba(255,255,255,0.04)',
            border: '1px solid rgba(0,200,232,0.14)',
            display: 'grid',
            gap: 14,
          }}
        >
          <div>
            <h1 style={{ margin: '0 0 8px', fontSize: '1.35rem', lineHeight: 1.2 }}>
              {tx('waselAuthCallback.reset_your_password')}
            </h1>
            <p style={{ margin: 0, color: 'rgba(239,246,255,0.7)', lineHeight: 1.6 }}>{message}</p>
          </div>

          <label style={{ display: 'grid', gap: 6 }}>
            <span style={{ fontSize: '0.82rem', color: 'rgba(196,220,238,0.68)' }}>
              {tx('settingsExpanded.newPassword')}
            </span>
            <input
              type="password"
              value={password}
              onChange={event => setPassword(event.target.value)}
              placeholder={tx('waselAuthCallback.enter_a_new_password')}
              style={{
                width: '100%',
                minHeight: 46,
                borderRadius: 12,
                border: '1px solid rgba(0,200,232,0.18)',
                background: 'rgba(255,255,255,0.03)',
                color: '#EFF6FF',
                padding: '0 14px',
                fontSize: '0.95rem',
              }}
            />
          </label>

          <label style={{ display: 'grid', gap: 6 }}>
            <span style={{ fontSize: '0.82rem', color: 'rgba(196,220,238,0.68)' }}>
              {tx('waselAuthCallback.confirm_password')}
            </span>
            <input
              type="password"
              value={confirmPassword}
              onChange={event => setConfirmPassword(event.target.value)}
              placeholder={tx('waselAuthCallback.re_enter_your_new_password')}
              style={{
                width: '100%',
                minHeight: 46,
                borderRadius: 12,
                border: '1px solid rgba(0,200,232,0.18)',
                background: 'rgba(255,255,255,0.03)',
                color: '#EFF6FF',
                padding: '0 14px',
                fontSize: '0.95rem',
              }}
            />
          </label>

          {formError && (
            <div
              style={{
                borderRadius: 12,
                border: '1px solid rgba(255,68,85,0.28)',
                background: 'rgba(255,68,85,0.12)',
                color: '#FF8A96',
                padding: '12px 14px',
                fontSize: '0.85rem',
                lineHeight: 1.5,
              }}
            >
              {formError}
            </div>
          )}

          <button
            type="button"
            onClick={() => {
              void handlePasswordUpdate();
            }}
            disabled={savingPassword}
            style={{
              minHeight: 46,
              borderRadius: 12,
              border: 'none',
              background: 'linear-gradient(135deg, #00E5FF, #0e5cb0)',
              color: '#EFF6FF',
              fontSize: '0.95rem',
              fontWeight: 800,
              cursor: savingPassword ? 'not-allowed' : 'pointer',
              opacity: savingPassword ? 0.7 : 1,
            }}
          >
            {savingPassword ? 'Updating password...' : 'Save new password'}
          </button>

          <button
            type="button"
            onClick={() =>
              navigate(`/app/auth?tab=signin&returnTo=${encodeURIComponent(returnTo)}`, {
                replace: true,
              })
            }
            style={{
              minHeight: 42,
              borderRadius: 12,
              border: '1px solid rgba(0,200,232,0.18)',
              background: 'transparent',
              color: '#EFF6FF',
              fontSize: '0.9rem',
              fontWeight: 700,
              cursor: 'pointer',
            }}
          >
            {tx('waselAuthCallback.back_to_sign_in')}
          </button>
        </div>
      </div>
    );
  }

  return (
    <div
      style={{
        minHeight: '100vh',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        background: '#040C18',
        color: '#EFF6FF',
        padding: 24,
        fontFamily: "-apple-system,'Inter',sans-serif",
      }}
    >
      <div
        style={{
          width: '100%',
          maxWidth: 420,
          borderRadius: 20,
          padding: 28,
          background: 'rgba(255,255,255,0.04)',
          border: '1px solid rgba(0,200,232,0.14)',
          textAlign: 'center',
        }}
      >
        <div
          style={{
            width: 42,
            height: 42,
            margin: '0 auto 16px',
            borderRadius: '50%',
            border:
              state === 'error'
                ? '3px solid rgba(255,68,85,0.3)'
                : '3px solid rgba(0,200,232,0.15)',
            borderTop: state === 'error' ? '3px solid #FF7C8B' : '3px solid #00E5FF',
            animation:
              state === 'redirecting' || state === 'loading' || state === 'closing'
                ? 'spin 0.8s linear infinite'
                : 'none',
          }}
        />
        <h1 style={{ margin: '0 0 8px', fontSize: '1.35rem', lineHeight: 1.2 }}>
          {state === 'error' ? 'Sign-in could not finish' : 'Finalizing authentication'}
        </h1>
        <p style={{ margin: 0, color: 'rgba(239,246,255,0.7)' }}>{message}</p>
        <style>{`@keyframes spin { to { transform: rotate(360deg); } }`}</style>
      </div>
    </div>
  );
}

