/**
 * Live Geo-Streaming Integration
 * Production-ready driver location tracking with WebSocket real-time updates
 */

import { geoStream, type DriverLocation } from './geo-stream-realtime';
import { telemetry } from './telemetry';
import { productionMetricsCollector } from './production-metrics';
import { useCallback, useLayoutEffect, useState } from 'react';
import { tx } from '../locales/tx';
import { sanitizeLogMessage } from '../utils/sanitization';

// ============================================================================
// DRIVER LOCATION MANAGER
// ============================================================================

class DriverLocationManager {
  private activeDrivers: Map<string, DriverLocation> = new Map();
  private locationHistory: Map<string, DriverLocation[]> = new Map();
  private readonly MAX_HISTORY = 50;

  updateDriverLocation(location: DriverLocation): void {
    // Store current location
    this.activeDrivers.set(location.driverId, location);

    // Update history
    if (!this.locationHistory.has(location.driverId)) {
      this.locationHistory.set(location.driverId, []);
    }

    const history = this.locationHistory.get(location.driverId) ?? [];
    if (history.length === 0) {
      this.locationHistory.set(location.driverId, history);
    }
    history.push(location);

    if (history.length > this.MAX_HISTORY) {
      history.shift();
    }

    // Track metrics
    productionMetricsCollector.recordMetric('driver.location_update', 1);
    telemetry.recordMetric('driver.location_update', 1, 'count', {
      driverId: location.driverId,
      status: location.status,
    });
  }

  getDriverLocation(driverId: string): DriverLocation | undefined {
    return this.activeDrivers.get(driverId);
  }

  getDriverHistory(driverId: string): DriverLocation[] {
    return this.locationHistory.get(driverId) || [];
  }

  getNearbyDrivers(
    lat: number,
    lng: number,
    radiusKm: number,
    status?: 'available' | 'on_trip' | 'offline',
  ): DriverLocation[] {
    const nearby: DriverLocation[] = [];

    for (const location of this.activeDrivers.values()) {
      if (status && location.status !== status) {continue;}

      const distance = this.calculateDistance(lat, lng, location.lat, location.lng);
      if (distance <= radiusKm) {
        nearby.push(location);
      }
    }

    return nearby.sort((a, b) => {
      const distA = this.calculateDistance(lat, lng, a.lat, a.lng);
      const distB = this.calculateDistance(lat, lng, b.lat, b.lng);
      return distA - distB;
    });
  }

  private calculateDistance(lat1: number, lng1: number, lat2: number, lng2: number): number {
    const R = 6371; // Earth radius in km
    const dLat = this.toRad(lat2 - lat1);
    const dLng = this.toRad(lng2 - lng1);

    const a =
      Math.sin(dLat / 2) * Math.sin(dLat / 2) +
      Math.cos(this.toRad(lat1)) *
        Math.cos(this.toRad(lat2)) *
        Math.sin(dLng / 2) *
        Math.sin(dLng / 2);

    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }

  private toRad(degrees: number): number {
    return (degrees * Math.PI) / 180;
  }

  getActiveDriverCount(): number {
    return this.activeDrivers.size;
  }

  getAvailableDriverCount(): number {
    return Array.from(this.activeDrivers.values()).filter(d => d.status === 'available').length;
  }
}

export const driverLocationManager = new DriverLocationManager();

// ============================================================================
// REACT HOOKS FOR LIVE TRACKING
// ============================================================================

/**
 * Hook to track drivers in a specific area
 */
export function useLiveDriverTracking(
  lat: number,
  lng: number,
  radiusKm: number,
): {
  drivers: DriverLocation[];
  isConnected: boolean;
  error: Error | null;
} {
  const [drivers, setDrivers] = useState<DriverLocation[]>([]);
  const [isConnected, setIsConnected] = useState(false);
  const [error, setError] = useState<Error | null>(null);

  useLayoutEffect(() => {
    try {
      setError(null);
      setIsConnected(true);

      const unsubscribe = geoStream?.subscribeToArea(lat, lng, radiusKm, updatedDrivers => {
        setDrivers(updatedDrivers);

        // Update local manager
        updatedDrivers.forEach(driver => {
          driverLocationManager.updateDriverLocation(driver);
        });
      }) ?? (() => () => {});

      return () => {
        unsubscribe();
        setIsConnected(false);
      };
    } catch (cause) {
      setError(cause instanceof Error ? cause : new Error(String(cause)));
      setIsConnected(false);
      return undefined;
    }
  }, [lat, lng, radiusKm]);

  return { drivers, isConnected, error };
}

/**
 * Hook to track a specific driver
 */
export function useDriverTracking(driverId: string): {
  location: DriverLocation | null;
  history: DriverLocation[];
  isConnected: boolean;
} {
  const [location, setLocation] = useState<DriverLocation | null>(null);
  const [history, setHistory] = useState<DriverLocation[]>([]);
  const [isConnected, setIsConnected] = useState(false);

  useLayoutEffect(() => {
    if (!driverId) {return;}

    setIsConnected(true);

    const unsubscribe = geoStream?.subscribeToDriver(driverId, updatedLocation => {
      setLocation(updatedLocation);
      driverLocationManager.updateDriverLocation(updatedLocation);
      setHistory(driverLocationManager.getDriverHistory(driverId));
    }) ?? (() => {});

    return () => {
      unsubscribe();
      setIsConnected(false);
    };
  }, [driverId]);

  return { location, history, isConnected };
}

// ============================================================================
// LIVE DRIVER MAP COMPONENT
// ============================================================================

interface LiveDriverMapProps {
  centerLat: number;
  centerLng: number;
  radiusKm: number;
  onDriverSelect?: (driver: DriverLocation) => void;
}

export function LiveDriverMap({
  centerLat,
  centerLng,
  radiusKm,
  onDriverSelect,
}: LiveDriverMapProps) {
  const { drivers, isConnected } = useLiveDriverTracking(centerLat, centerLng, radiusKm);
  const [selectedDriver, setSelectedDriver] = useState<string | null>(null);

  const handleDriverClick = useCallback(
    (driver: DriverLocation) => {
      setSelectedDriver(driver.driverId);
      onDriverSelect?.(driver);
    },
    [onDriverSelect],
  );

  return (
    <div className="relative h-full w-full">
      {/* Connection Status */}
      <div className="absolute right-4 top-4 z-10 flex items-center gap-2 rounded-lg bg-white px-3 py-2 shadow-lg">
        <div
          className={`h-2 w-2 rounded-full ${
            isConnected ? 'bg-green-500 animate-pulse' : 'bg-red-500'
          }`}
        />
        <span className="text-sm font-medium">
          {isConnected ? 'Live Tracking' : 'Disconnected'}
        </span>
      </div>

      {/* Driver Count */}
      <div className="absolute left-4 top-4 z-10 rounded-lg bg-white px-3 py-2 shadow-lg">
        <div className="text-sm text-gray-600">{tx('liveGeoTracking.available_drivers')}</div>
        <div className="text-2xl font-bold">
          {drivers.filter(d => d.status === 'available').length}
        </div>
      </div>

      {/* Map Container */}
      <div className="h-full w-full">
        {/* In production, this would be Leaflet or Google Maps */}
        <MapPlaceholder
          drivers={drivers}
          selectedDriver={selectedDriver}
          onDriverClick={handleDriverClick}
        />
      </div>

      {/* Driver List */}
      <div className="absolute bottom-4 left-4 right-4 z-10 max-h-48 overflow-y-auto rounded-lg bg-white p-4 shadow-lg">
        <h3 className="mb-2 font-semibold">
          {tx('liveGeoTracking.nearby_drivers')}
          {drivers.length})
        </h3>
        <div className="space-y-2">
          {drivers.map(driver => (
            <DriverCard
              key={driver.driverId}
              driver={driver}
              isSelected={selectedDriver === driver.driverId}
              onClick={() => { void handleDriverClick(driver); }}
            />
          ))}
        </div>
      </div>
    </div>
  );
}

function MapPlaceholder({
  drivers,
  selectedDriver,
  onDriverClick,
}: {
  drivers: DriverLocation[];
  selectedDriver: string | null;
  onDriverClick: (driver: DriverLocation) => void;
}) {
  return (
    <div className="flex h-full items-center justify-center bg-gray-100">
      <div className="text-center">
        <div className="text-4xl">🗺️</div>
        <div className="mt-2 text-gray-600">{tx('liveGeoTracking.live_driver_map')}</div>
        <div className="mt-1 text-sm text-gray-500">
          {drivers.length} {tx('liveGeoTracking.drivers_tracked')}
        </div>
        {selectedDriver ? (
          <div className="mt-1 text-xs text-blue-600">
            {tx('liveGeoTracking.selected_driver')}
            {selectedDriver}
          </div>
        ) : null}
        {drivers.length > 0 ? (
          <button
            type="button"
            className="mt-3 rounded bg-blue-600 px-3 py-1 text-xs font-medium text-white"
            onClick={() => {
              const nearest = drivers[0];
              if (nearest) {onDriverClick(nearest);}
            }}
          >
            {tx('liveGeoTracking.select_nearest_driver')}
          </button>
        ) : null}
      </div>
    </div>
  );
}

function DriverCard({
  driver,
  isSelected,
  onClick,
}: {
  driver: DriverLocation;
  isSelected: boolean;
  onClick: () => void;
}) {
  const statusColor = {
    available: 'bg-green-100 text-green-800',
    on_trip: 'bg-blue-100 text-blue-800',
    offline: 'bg-gray-100 text-gray-800',
  };

  return (
    <button
      onClick={() => { void onClick(); }}
      className={`w-full rounded-lg border-2 p-2 text-left transition-all ${
        isSelected
          ? 'border-blue-500 bg-blue-50'
          : 'border-transparent bg-gray-50 hover:bg-gray-100'
      }`}
    >
      <div className="flex items-center justify-between">
        <div>
          <div className="font-medium">
            {tx('trips.driver')}
            {driver.driverId.slice(-6)}
          </div>
          <div className="text-xs text-gray-500">
            {driver.speed ? `${Math.round(driver.speed)} km/h` : 'Stationary'}
          </div>
        </div>
        <span
          className={`rounded-full px-2 py-1 text-xs font-medium ${statusColor[driver.status]}`}
        >
          {driver.status}
        </span>
      </div>
    </button>
  );
}

// ============================================================================
// DRIVER TRACKING COMPONENT (for active trips)
// ============================================================================

interface DriverTrackingProps {
  driverId: string;
  showHistory?: boolean;
}

export function DriverTracking({ driverId, showHistory = false }: DriverTrackingProps) {
  const { location, history, isConnected } = useDriverTracking(driverId);

  if (!location) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="text-center">
          <div className="text-4xl">📍</div>
          <div className="mt-2 text-gray-600">
            {tx('liveGeoTracking.waiting_for_driver_location')}
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-4">
      {/* Current Location */}
      <div className="rounded-lg bg-white p-4 shadow">
        <div className="mb-2 flex items-center justify-between">
          <h3 className="font-semibold">{tx('liveGeoTracking.driver_location')}</h3>
          <div
            className={`flex items-center gap-1 text-sm ${
              isConnected ? 'text-green-600' : 'text-red-600'
            }`}
          >
            <div
              className={`h-2 w-2 rounded-full ${isConnected ? 'bg-green-500' : 'bg-red-500'}`}
            />
            {isConnected ? 'Live' : 'Offline'}
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <div>
            <div className="text-sm text-gray-600">{tx('liveGeoTracking.latitude')}</div>
            <div className="font-mono">{location.lat.toFixed(6)}</div>
          </div>
          <div>
            <div className="text-sm text-gray-600">{tx('liveGeoTracking.longitude')}</div>
            <div className="font-mono">{location.lng.toFixed(6)}</div>
          </div>
          <div>
            <div className="text-sm text-gray-600">{tx('liveGeoTracking.speed')}</div>
            <div>{location.speed ? `${Math.round(location.speed)} km/h` : 'Stationary'}</div>
          </div>
          <div>
            <div className="text-sm text-gray-600">{tx('liveGeoTracking.heading')}</div>
            <div>{location.heading ? `${Math.round(location.heading)}°` : 'N/A'}</div>
          </div>
        </div>
      </div>

      {/* Location History */}
      {showHistory && history.length > 0 && (
        <div className="rounded-lg bg-white p-4 shadow">
          <h3 className="mb-2 font-semibold">{tx('liveGeoTracking.location_history')}</h3>
          <div className="max-h-48 space-y-2 overflow-y-auto">
            {history.reverse().map((loc, index) => (
              <div key={index} className="flex justify-between border-b py-2 text-sm">
                <span className="font-mono text-gray-600">
                  {new Date(loc.timestamp).toLocaleTimeString()}
                </span>
                <span>
                  {loc.lat.toFixed(4)}, {loc.lng.toFixed(4)}
                </span>
                <span className="text-gray-500">
                  {loc.speed ? `${Math.round(loc.speed)} km/h` : '-'}
                </span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

// ============================================================================
// AUTO-START GEO STREAMING IN PRODUCTION
// ============================================================================

if (typeof window !== 'undefined' && import.meta.env.MODE === 'production' && geoStream) {
  geoStream
    .connect()
    .then(() => {
      console.info('✅ Live geo-streaming connected');

      // Track connection metrics
      telemetry.recordMetric('geo_stream.connected', 1, 'count');
    })
    .catch(error => {
      console.error('❌ Failed to connect geo-streaming:', sanitizeLogMessage(error));
      telemetry.recordMetric('geo_stream.connection_error', 1, 'count');
    });
}

import { sanitizeLogMessage } from '../utils/sanitization';

export type StructuredLogLevel = 'info' | 'warning' | 'error';

export interface StructuredLogEntry {
  level: StructuredLogLevel;
  message: string;
  timestamp: string;
  requestId: string;
  service: string;
  context?: Record<string, unknown>;
}

export function createCorrelationId(prefix: string = 'req'): string {
  return `${prefix}-${Date.now()}-${crypto.randomUUID().split('-')[0]}`;
}

function sanitizeContext(context?: Record<string, unknown>): Record<string, unknown> | undefined {
  if (!context) {return undefined;}
  return Object.fromEntries(
    Object.entries(context).map(([k, v]) => [k, sanitizeLogMessage(v)]),
  );
}

export interface StructuredLogEntryOptions {
  level: StructuredLogLevel;
  message: string;
  service: string;
  context?: Record<string, unknown>;
  requestId?: string;
}

export function createStructuredLogEntry(
  level: StructuredLogLevel,
  message: string,
  service: string,
  context?: Record<string, unknown>,
  requestId?: string,
): StructuredLogEntry {
  const resolvedRequestId = requestId ?? createCorrelationId();
  return {
    level,
    message: sanitizeLogMessage(message),
    service: sanitizeLogMessage(service),
    requestId: resolvedRequestId,
    timestamp: new Date().toISOString(),
    context: sanitizeContext(context),
  };
}

/**
 * Production Metrics Collector & SLO Validator
 * Collects real production data and validates against SLO targets
 */

export interface ProductionMetrics {
  timestamp: number;
  period: '1min' | '5min' | '15min' | '1hour' | '24hour';

  // API Metrics
  api: {
    requestCount: number;
    errorCount: number;
    errorRate: number;
    latency: {
      p50: number;
      p95: number;
      p99: number;
      max: number;
    };
  };

  // Service-Level Metrics
  services: {
    [serviceName: string]: {
      requestCount: number;
      successCount: number;
      failureCount: number;
      availability: number; // percentage
      latency: {
        p50: number;
        p95: number;
        p99: number;
      };
      sloCompliance: boolean;
      sloTarget: {
        availability: string;
        p95Latency: string;
      };
    };
  };

  // Queue Metrics
  queues: {
    [topicName: string]: {
      depth: number;
      processedCount: number;
      failedCount: number;
      avgProcessingTimeMs: number;
      lagMs: number;
    };
  };

  // Worker Metrics
  workers: {
    [workerName: string]: {
      status: 'healthy' | 'degraded' | 'down';
      processedCount: number;
      failedCount: number;
      retryCount: number;
      circuitBreakerState: 'closed' | 'open' | 'half-open';
      avgProcessingTimeMs: number;
    };
  };

  // Business Metrics
  business: {
    activeUsers: number;
    ridesRequested: number;
    ridesCompleted: number;
    packagesCreated: number;
    packagesDelivered: number;
    paymentsAuthorized: number;
    paymentsCaptured: number;
    revenueJOD: number;
  };

  // Web Vitals
  webVitals: {
    cls: number;
    fid: number;
    lcp: number;
    fcp: number;
    ttfb: number;
    inp: number;
  };
}

type SLOTarget = {
  availability: number;
  p95Latency?: number;
  freshnessMs?: number;
};

class ProductionMetricsCollector {
  private metricsBuffer: Map<string, number[]> = new Map();
  private sloViolations: Array<{
    service: string;
    metric: string;
    target: number;
    actual: number;
    timestamp: number;
  }> = [];

  // SLO Targets from reliability-slos.md
  private readonly SLO_TARGETS: Record<string, SLOTarget> = {
    'api-gateway': { availability: 99.9, p95Latency: 250 },
    'identity-service': { availability: 99.95, p95Latency: 200 },
    'ride-matching-service': { availability: 99.9, p95Latency: 700 },
    'package-delivery-service': { availability: 99.9, p95Latency: 400 },
    'payment-service': { availability: 99.95, p95Latency: 350 },
    'notification-worker': { availability: 99.9, freshnessMs: 2000 },
    'matching-worker': { availability: 99.9, freshnessMs: 15000 },
    'package-worker': { availability: 99.9, freshnessMs: 10000 },
    'payment-worker': { availability: 99.95, freshnessMs: 30000 },
    'ops-worker': { availability: 99.5, freshnessMs: 300000 },
  };

  recordMetric(name: string, value: number): void {
    if (!this.metricsBuffer.has(name)) {
      this.metricsBuffer.set(name, []);
    }
    const buffer = this.metricsBuffer.get(name) ?? [];
    buffer.push(value);
    this.metricsBuffer.set(name, buffer);

    // Keep only last 1000 data points per metric
    if (buffer.length > 1000) {
      buffer.shift();
    }
  }

  calculatePercentile(values: number[], percentile: number): number {
    if (values.length === 0) {return 0;}

    const sorted = [...values].sort((a, b) => a - b);
    const index = Math.ceil((percentile / 100) * sorted.length) - 1;
    return sorted[Math.max(0, index)] ?? 0;
  }

  calculateAvailability(successCount: number, totalCount: number): number {
    if (totalCount === 0) {return 100;}
    return (successCount / totalCount) * 100;
  }

  validateSLO(
    service: string,
    metric: 'availability' | 'p95Latency' | 'freshnessMs',
    actual: number,
  ): boolean {
    const target = this.SLO_TARGETS[service];
    if (!target) {return true;}

    let isCompliant = true;
    let targetValue = 0;

    switch (metric) {
      case 'availability':
        targetValue = target.availability;
        isCompliant = actual >= targetValue;
        break;
      case 'p95Latency':
        targetValue = target.p95Latency ?? 0;
        isCompliant = actual <= targetValue;
        break;
      case 'freshnessMs':
        targetValue = target.freshnessMs ?? 0;
        isCompliant = actual <= targetValue;
        break;
    }

    if (!isCompliant) {
      this.sloViolations.push({
        service,
        metric,
        target: targetValue,
        actual,
        timestamp: Date.now(),
      });
    }

    return isCompliant;
  }

  async collectProductionMetrics(period: ProductionMetrics['period']): Promise<ProductionMetrics> {
    const now = Date.now();

    // API Metrics
    const apiLatencies = this.metricsBuffer.get('api.latency') || [];
    const apiErrors = this.metricsBuffer.get('api.errors') || [];
    const apiRequests = this.metricsBuffer.get('api.requests') || [];

    const apiMetrics = {
      requestCount: apiRequests.length,
      errorCount: apiErrors.length,
      errorRate: apiRequests.length > 0 ? apiErrors.length / apiRequests.length : 0,
      latency: {
        p50: this.calculatePercentile(apiLatencies, 50),
        p95: this.calculatePercentile(apiLatencies, 95),
        p99: this.calculatePercentile(apiLatencies, 99),
        max: Math.max(...apiLatencies, 0),
      },
    };

    // Service Metrics
    const services: ProductionMetrics['services'] = {};

    for (const [serviceName, sloTarget] of Object.entries(this.SLO_TARGETS)) {
      const latencies = this.metricsBuffer.get(`${serviceName}.latency`) || [];
      const successes = this.metricsBuffer.get(`${serviceName}.success`) || [];
      const failures = this.metricsBuffer.get(`${serviceName}.failure`) || [];

      const totalRequests = successes.length + failures.length;
      const availability = this.calculateAvailability(successes.length, totalRequests);
      const p95Latency = this.calculatePercentile(latencies, 95);

      const availabilitySLO = this.validateSLO(serviceName, 'availability', availability);
      const latencySLO = sloTarget.p95Latency
        ? this.validateSLO(serviceName, 'p95Latency', p95Latency)
        : true;

      services[serviceName] = {
        requestCount: totalRequests,
        successCount: successes.length,
        failureCount: failures.length,
        availability,
        latency: {
          p50: this.calculatePercentile(latencies, 50),
          p95: p95Latency,
          p99: this.calculatePercentile(latencies, 99),
        },
        sloCompliance: availabilitySLO && latencySLO,
        sloTarget: {
          availability: `${sloTarget.availability}%`,
          p95Latency: sloTarget.p95Latency ? `${sloTarget.p95Latency}ms` : 'N/A',
        },
      };
    }

    // Queue Metrics
    const queues: ProductionMetrics['queues'] = {
      'rides.requested': this.getQueueMetrics('rides.requested'),
      'packages.created': this.getQueueMetrics('packages.created'),
      'payments.authorized': this.getQueueMetrics('payments.authorized'),
      'notifications.dispatch': this.getQueueMetrics('notifications.dispatch'),
    };

    // Worker Metrics
    const workers: ProductionMetrics['workers'] = {
      'matching-worker': this.getWorkerMetrics('matching-worker'),
      'package-worker': this.getWorkerMetrics('package-worker'),
      'payment-worker': this.getWorkerMetrics('payment-worker'),
      'notification-worker': this.getWorkerMetrics('notification-worker'),
      'ops-worker': this.getWorkerMetrics('ops-worker'),
    };

    // Business Metrics
    const business: ProductionMetrics['business'] = {
      activeUsers: (this.metricsBuffer.get('users.active') || []).length,
      ridesRequested: (this.metricsBuffer.get('rides.requested') || []).length,
      ridesCompleted: (this.metricsBuffer.get('rides.completed') || []).length,
      packagesCreated: (this.metricsBuffer.get('packages.created') || []).length,
      packagesDelivered: (this.metricsBuffer.get('packages.delivered') || []).length,
      paymentsAuthorized: (this.metricsBuffer.get('payments.authorized') || []).length,
      paymentsCaptured: (this.metricsBuffer.get('payments.captured') || []).length,
      revenueJOD: (this.metricsBuffer.get('revenue.jod') || []).reduce((a, b) => a + b, 0),
    };

    // Web Vitals
    const webVitals: ProductionMetrics['webVitals'] = {
      cls: this.calculatePercentile(this.metricsBuffer.get('web_vital.cls') || [], 75),
      fid: this.calculatePercentile(this.metricsBuffer.get('web_vital.fid') || [], 75),
      lcp: this.calculatePercentile(this.metricsBuffer.get('web_vital.lcp') || [], 75),
      fcp: this.calculatePercentile(this.metricsBuffer.get('web_vital.fcp') || [], 75),
      ttfb: this.calculatePercentile(this.metricsBuffer.get('web_vital.ttfb') || [], 75),
      inp: this.calculatePercentile(this.metricsBuffer.get('web_vital.inp') || [], 75),
    };

    return {
      timestamp: now,
      period,
      api: apiMetrics,
      services,
      queues,
      workers,
      business,
      webVitals,
    };
  }

  private getQueueMetrics(topic: string): ProductionMetrics['queues'][string] {
    const depths = this.metricsBuffer.get(`queue.${topic}.depth`) || [];
    const processed = this.metricsBuffer.get(`queue.${topic}.processed`) || [];
    const failed = this.metricsBuffer.get(`queue.${topic}.failed`) || [];
    const times = this.metricsBuffer.get(`queue.${topic}.time`) || [];
    const lags = this.metricsBuffer.get(`queue.${topic}.lag`) || [];

    return {
      depth: depths[depths.length - 1] || 0,
      processedCount: processed.length,
      failedCount: failed.length,
      avgProcessingTimeMs: times.length > 0 ? times.reduce((a, b) => a + b, 0) / times.length : 0,
      lagMs: lags[lags.length - 1] || 0,
    };
  }

  private getWorkerMetrics(worker: string): ProductionMetrics['workers'][string] {
    const processed = this.metricsBuffer.get(`worker.${worker}.processed`) || [];
    const failed = this.metricsBuffer.get(`worker.${worker}.failed`) || [];
    const retried = this.metricsBuffer.get(`worker.${worker}.retried`) || [];
    const times = this.metricsBuffer.get(`worker.${worker}.time`) || [];
    const cbState = this.metricsBuffer.get(`worker.${worker}.circuit_breaker`) || [0];

    const failureRate = processed.length > 0 ? failed.length / processed.length : 0;
    const status: 'healthy' | 'degraded' | 'down' =
      failureRate > 0.2 ? 'down' : failureRate > 0.05 ? 'degraded' : 'healthy';

    const circuitBreakerMetric = cbState.at(-1) ?? 0;
    const circuitBreakerState: 'closed' | 'open' | 'half-open' =
      circuitBreakerMetric === 2 ? 'half-open' : circuitBreakerMetric === 1 ? 'open' : 'closed';

    return {
      status,
      processedCount: processed.length,
      failedCount: failed.length,
      retryCount: retried.length,
      circuitBreakerState,
      avgProcessingTimeMs: times.length > 0 ? times.reduce((a, b) => a + b, 0) / times.length : 0,
    };
  }

  getSLOViolations(): typeof this.sloViolations {
    return [...this.sloViolations];
  }

  clearSLOViolations(): void {
    this.sloViolations = [];
  }

  async publishMetrics(metrics: ProductionMetrics): Promise<void> {
    try {
      await fetch('/api/metrics/publish', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(metrics),
      });
    } catch {
      // Metrics publish failures are non-fatal
    }
  }

  generateSLOReport(): string {
    const violations = this.getSLOViolations();
    const last24h = violations.filter(v => Date.now() - v.timestamp < 86400000);

    let report = '# SLO Compliance Report\n\n';
    report += `Generated: ${new Date().toISOString()}\n`;
    report += `Period: Last 24 hours\n`;
    report += `Total Violations: ${last24h.length}\n\n`;

    if (last24h.length === 0) {
      report += '✅ **All SLOs are in compliance**\n';
    } else {
      report += '## Violations\n\n';

      const grouped = last24h.reduce(
        (acc, v) => {
          const serviceViolations = acc[v.service] ?? [];
          serviceViolations.push(v);
          acc[v.service] = serviceViolations;
          return acc;
        },
        {} as Record<string, typeof violations>,
      );

      for (const [service, serviceViolations] of Object.entries(grouped)) {
        report += `### ${service}\n`;
        for (const v of serviceViolations) {
          report += `- ${v.metric}: Target ${v.target}, Actual ${v.actual.toFixed(2)}\n`;
        }
        report += '\n';
      }
    }

    return report;
  }
}

export const productionMetricsCollector = new ProductionMetricsCollector();

// Auto-collect metrics every 5 minutes in production
let productionMetricsTimer: ReturnType<typeof setInterval> | null = null;
if (import.meta.env.MODE === 'production') {
  productionMetricsTimer = setInterval(() => {
    void (async () => {
      const metrics = await productionMetricsCollector.collectProductionMetrics('5min');
      await productionMetricsCollector.publishMetrics(metrics);
    })();
  }, 300000);
}

/** Stop the production metrics collection interval. */
export function stopProductionMetricsCollection(): void {
  if (productionMetricsTimer !== null) {
    clearInterval(productionMetricsTimer);
    productionMetricsTimer = null;
  }
}

/**
 * Production Worker Deployment
 *
 * Bridges the worker framework to the active event broker and implements the
 * five domain workers defined in the service topology:
 *   - matching-worker      (rides.requested)
 *   - package-worker       (packages.created, packages.location-updated)
 *   - payment-worker       (payments.authorized)
 *   - notification-worker  (rides.assigned, packages.delivered, notifications.dispatch)
 *   - ops-worker           (rides.completed, payments.captured)
 *
 * All handlers execute real Supabase operations and are resilient: when the
 * backend is unavailable they log and no-op rather than throwing, so the
 * worker pool stays healthy.
 *
 * ARCHITECTURE NOTE — in-browser workers
 * These workers currently run inside the browser bundle. This is intentional
 * for the current Jordan-market scale where Supabase Edge Functions handle the
 * critical server-side paths (matching, payments, notifications). The in-browser
 * workers act as a supplementary layer for same-session optimistic updates.
 *
 * Migration path to dedicated server-side workers:
 *   1. Extract each worker handler into a standalone Supabase Edge Function
 *      (see supabase/functions/matching-worker/ as the reference pattern).
 *   2. Replace the in-process `domainEventBus.publish()` calls with
 *      `SupabaseEventBroker.publish()` writes to the `event_outbox` table.
 *   3. Remove this file from the browser bundle once all handlers are
 *      confirmed live in the edge runtime.
 * Trigger: when ride-matching or payment-capture query latency exceeds SLO
 * targets defined in docs/reliability-slos.md.
 */

import {
  WorkerRegistry,
  createWorker,
  workerRegistry,
  type QueueMessage,
} from './worker-framework';
import { domainEventBus, createDomainEvent } from './event-bus';
import { isSupabaseConfigured, supabase } from '../utils/supabase/client';
import { notificationsAPI } from '../services/notifications';
import { trackGrowthEvent } from '../services/growthEngine';
import { telemetry } from './telemetry';
import { sanitizeLogMessage } from '../utils/sanitization';

type AnyRecord = Record<string, unknown>;

function ensureBackend(): boolean {
  if (!isSupabaseConfigured || !supabase) {
    telemetry.recordMetric('worker.backend_unavailable', 1, 'count');
    return false;
  }
  return true;
}

// ============================================================================
// MATCHING WORKER
// ============================================================================

interface RideMatchRequest {
  bookingId: string;
  rideId: string;
  routeMode: 'live_post' | 'network_inventory';
  origin: string;
  destination: string;
}

const matchingWorker = createWorker<RideMatchRequest>(
  {
    name: 'matching-worker',
    topics: ['rides.requested'],
    concurrency: 10,
    retryPolicy: { maxRetries: 5, backoffMs: 1000 },
    circuitBreaker: { failureThreshold: 5, resetTimeoutMs: 60000 },
  },
  async (message: QueueMessage<RideMatchRequest>) => {
    if (!ensureBackend()) {return;}
    const client = supabase;
    if (!client) {return;}
    const { payload } = message;
    const startTime = Date.now();

    const { data: trip } = await client
      .from('trips')
      .select('id, trip_id, driver_id, trip_status')
      .or(`trip_id.eq.${payload.rideId},id.eq.${payload.rideId}`)
      .maybeSingle();

    if (!trip) {
      console.warn('[matching-worker] trip not found', sanitizeLogMessage(payload.rideId));
      return;
    }

    const { data: driver } = await client
      .from('drivers')
      .select('driver_id, user_id')
      .in('driver_status', ['online', 'approved', 'busy'])
      .limit(1)
      .maybeSingle();

    if (!driver) {
      // No supply right now — leave the request unassigned; the poll/fallback
      // will retry on the next publish.
      telemetry.recordMetric('matching.no_supply', 1, 'count');
      return;
    }

    await client
      .from('trips')
      .update({ driver_id: driver.driver_id, trip_status: 'booked' })
      .eq('id', trip.id);

    domainEventBus.publish(
      createDomainEvent(
        'DriverAssigned',
        {
          bookingId: payload.bookingId,
          rideId: payload.rideId,
          driverId: driver.driver_id,
          driverName: undefined,
        },
        'matching-worker',
        message.correlationId,
      ),
    );

    telemetry.recordSLO('matching-worker', 'ride-matching', Date.now() - startTime, true);
  },
);

// ============================================================================
// PACKAGE WORKER
// ============================================================================

const packageWorker = createWorker<AnyRecord>(
  {
    name: 'package-worker',
    topics: ['packages.created', 'packages.location-updated'],
    concurrency: 15,
    retryPolicy: { maxRetries: 5, backoffMs: 1000 },
    circuitBreaker: { failureThreshold: 5, resetTimeoutMs: 60000 },
  },
  async (message: QueueMessage<AnyRecord>) => {
    if (!ensureBackend()) {return;}
    const client = supabase;
    if (!client) {return;}
    const { topic, payload } = message;

    if (topic === 'packages.created') {
      const packageId = (payload.packageId as string) ?? (payload.id as string);
      if (!packageId) {return;}

      const { data: trip } = await client
        .from('trips')
        .select('id, trip_id, driver_id, allows_packages, trip_status')
        .eq('allows_packages', true)
        .eq('trip_status', 'open')
        .limit(1)
        .maybeSingle();

      if (!trip) {
        telemetry.recordMetric('package.no_trip', 1, 'count');
        return;
      }

      await client
        .from('packages')
        .update({
          trip_id: trip.trip_id ?? trip.id,
          carrier_id: trip.driver_id,
          package_status: 'assigned',
        })
        .eq('package_id', packageId);

      domainEventBus.publish(
        createDomainEvent(
          'PackageAssigned',
          {
            packageId,
            rideId: (trip.trip_id ?? trip.id) as string,
            driverId: trip.driver_id as string,
          },
          'package-worker',
          message.correlationId,
        ),
      );
    } else if (topic === 'packages.location-updated') {
      const packageId = payload.packageId as string;
      if (!packageId) {return;}

      await client.from('package_events').insert({
        package_id: packageId,
        event_type: 'location_update',
        event_status: 'ok',
        notes: JSON.stringify({
          latitude: payload.latitude,
          longitude: payload.longitude,
        }),
      });

      telemetry.recordMetric('package.location_update', 1, 'count', { packageId });
    }
  },
);

// ============================================================================
// PAYMENT WORKER
// ============================================================================

interface PaymentAuthorization {
  entityId: string;
  entityType: 'ride' | 'package';
  amount: number;
}

const paymentWorker = createWorker<PaymentAuthorization>(
  {
    name: 'payment-worker',
    topics: ['payments.authorized'],
    concurrency: 20,
    retryPolicy: { maxRetries: 5, backoffMs: 2000 },
    circuitBreaker: { failureThreshold: 3, resetTimeoutMs: 120000 },
  },
  async (message: QueueMessage<PaymentAuthorization>) => {
    if (!ensureBackend()) {return;}
    const client = supabase;
    if (!client) {return;}
    const { payload } = message;
    const startTime = Date.now();

    // Capture/settle the authorized amount. The transaction row carries the
    // entity reference; mark it posted (released from hold).
    const { error } = await client
      .from('transactions')
      .update({ transaction_status: 'posted' })
      .eq('reference_id', payload.entityId)
      .eq('transaction_status', 'authorized');

    if (error) {
      throw new Error(`payment capture failed: ${error.message}`);
    }

    domainEventBus.publish(
      createDomainEvent(
        'PaymentCaptured',
        {
          entityId: payload.entityId,
          entityType: payload.entityType,
          amount: payload.amount,
        },
        'payment-worker',
        message.correlationId,
      ),
    );

    telemetry.recordSLO('payment-worker', 'payment-capture', Date.now() - startTime, true);
  },
);

// ============================================================================
// NOTIFICATION WORKER
// ============================================================================

interface NotificationDispatch {
  userId?: string;
  title: string;
  message: string;
  type: string;
  priority?: 'low' | 'medium' | 'high' | 'urgent';
  actionUrl?: string;
}

const notificationWorker = createWorker<AnyRecord>(
  {
    name: 'notification-worker',
    topics: ['rides.assigned', 'packages.delivered', 'notifications.dispatch'],
    concurrency: 50,
    retryPolicy: { maxRetries: 8, backoffMs: 500 },
    circuitBreaker: { failureThreshold: 10, resetTimeoutMs: 60000 },
  },
  async (message: QueueMessage<AnyRecord>) => {
    const { topic, payload } = message;
    const startTime = Date.now();
    const client = supabase;

    if (topic === 'notifications.dispatch') {
      const dispatch = payload as unknown as NotificationDispatch;
      if (!dispatch.userId) {return;}
      await notificationsAPI.createNotification({
        title: dispatch.title,
        message: dispatch.message,
        type: dispatch.type,
        priority: dispatch.priority,
        action_url: dispatch.actionUrl,
      } as never);
    } else if (topic === 'rides.assigned') {
      if (!ensureBackend() || !client) {return;}
      const { data: booking } = await client
        .from('bookings')
        .select('passenger_id')
        .eq('booking_id', payload.bookingId as string)
        .maybeSingle();

      const userId = booking?.passenger_id as string | undefined;
      if (!userId) {
        console.warn('[notification-worker] rides.assigned: booking not found, skipping', sanitizeLogMessage(payload.bookingId as string));
        return;
      }
      await notificationsAPI.createNotification({
        title: 'Driver assigned',
        message: `A driver has been assigned to your ride.`,
        type: 'booking',
        priority: 'high',
        action_url: '/app/my-trips?tab=rides',
      } as never);
    } else if (topic === 'packages.delivered') {
      if (!ensureBackend() || !client) {return;}
      const { data: pkg } = await client
        .from('packages')
        .select('sender_id, receiver_id')
        .eq('package_id', payload.packageId as string)
        .maybeSingle();

      const recipients = [pkg?.sender_id, pkg?.receiver_id].filter(Boolean) as string[];
      await Promise.all(
        recipients.map(() =>
          notificationsAPI.createNotification({
            title: 'Package Delivered',
            message: 'Your package has been delivered successfully.',
            type: 'booking',
            priority: 'high',
          } as never),
        ),
      );
    }

    const latency = Date.now() - startTime;
    telemetry.recordSLO('notification-worker', 'dispatch', latency, true);
    telemetry.recordMetric('notification.sent', 1, 'count', { topic });
  },
);

// ============================================================================
// OPS WORKER (Analytics & Reporting)
// ============================================================================

const opsWorker = createWorker<AnyRecord>(
  {
    name: 'ops-worker',
    topics: ['rides.completed', 'payments.captured'],
    concurrency: 5,
    retryPolicy: { maxRetries: 3, backoffMs: 5000 },
  },
  async (message: QueueMessage<AnyRecord>) => {
    const { topic, payload } = message;

    if (topic === 'rides.completed') {
      await trackGrowthEvent({
        eventName: 'ride_completed',
        funnelStage: 'completed',
        serviceType: 'ride',
        metadata: payload as AnyRecord,
      });
    } else if (topic === 'payments.captured') {
      if (ensureBackend()) {
        const client = supabase;
        if (!client) {return;}
        const metricDate = new Date().toISOString().slice(0, 10);
        await client.rpc('increment_ops_aggregate' as any, {
          p_metric_date: metricDate,
          p_metric_name: 'revenue_captured',
          p_dimension: (payload.entityType as string) ?? 'unknown',
          p_amount: (payload.amount as number) ?? 0,
        });
      }
    }

    telemetry.recordMetric('ops.analytics_updated', 1, 'count', { topic });
  },
);

