import { supabase } from '@/utils/supabase/client';
import type { RealtimeChannel } from '@supabase/supabase-js';

type MessageReadRow = {
  id: string;
  read_by: string[] | null;
};

export interface Message {
  id: string;
  trip_id: string;
  sender_id: string;
  content: string;
  type: 'text' | 'location' | 'system';
  metadata: Record<string, unknown>;
  read_by: string[];
  created_at: string;
  sender?: {
    id: string;
    full_name: string;
    avatar_url: string;
  };
}

export interface SendMessageRequest {
  tripId: string;
  content: string;
  type?: 'text' | 'location' | 'system';
  metadata?: Record<string, unknown>;
}

class ChatService {
  private channels: Map<string, RealtimeChannel> = new Map();

  async sendMessage(request: SendMessageRequest): Promise<Message> {
    if (!supabase) {throw new Error('Supabase not configured');}
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      throw new Error('Not authenticated');
    }

    const { data: trip } = await supabase
      .from('trips')
      .select('driver_id')
      .eq('id', request.tripId)
      .single();

    const { data: booking } = await supabase
      .from('bookings')
      .select('passenger_id')
      .eq('trip_id', request.tripId)
      .eq('passenger_id', user.id)
      .single();

    if (!trip && !booking) {
      throw new Error('Not authorized to send messages in this trip');
    }

    const { data, error } = await supabase
      .from('messages')
      .insert({
        trip_id: request.tripId,
        sender_id: user.id,
        content: request.content,
        type: request.type || 'text',
        metadata: request.metadata || {},
        read_by: [user.id],
      })
      .select(
        'id, trip_id, sender_id, content, type, metadata, read_by, created_at, sender:profiles(id, full_name, avatar_url)',
      )
      .single();

    if (error) {
      throw error;
    }

    return data as unknown as Message;
  }

  async getMessages(tripId: string, limit = 50): Promise<Message[]> {
    if (!supabase) {throw new Error('Supabase not configured');}
    const { data, error } = await supabase
      .from('messages')
      .select(
        'id, trip_id, sender_id, content, type, metadata, read_by, created_at, sender:profiles(id, full_name, avatar_url)',
      )
      .eq('trip_id', tripId)
      .order('created_at', { ascending: false })
      .limit(limit);

    if (error) {
      throw error;
    }

    return (data as unknown as Message[]).reverse();
  }

  async markAsRead(messageIds: string[]): Promise<void> {
    if (!supabase) {throw new Error('Supabase not configured');}
    const sb = supabase;
    const {
      data: { user },
    } = await sb.auth.getUser();

    if (!user) {
      throw new Error('Not authenticated');
    }

    if (messageIds.length === 0) {return;}

    const { data: messages, error } = await supabase
      .from('messages')
      .select('id, read_by')
      .in('id', messageIds);

    if (error || !messages) {return;}

    const messageRows = (messages ?? []) as MessageReadRow[];
    const messagesToUpdate = messageRows.filter(
      message => !(message.read_by ?? []).includes(user.id),
    );

    if (messagesToUpdate.length === 0) {return;}

    const BATCH_SIZE = 10;
    for (let i = 0; i < messagesToUpdate.length; i += BATCH_SIZE) {
      const batch = messagesToUpdate.slice(i, i + BATCH_SIZE);
      await Promise.all(
        batch.map(message =>
          sb
            .from('messages')
            .update({
              read_by: [...(message.read_by ?? []), user.id],
            })
            .eq('id', message.id),
        ),
      );
    }
  }

  subscribeToTrip(
    tripId: string,
    onMessage: (message: Message) => void,
    onError?: (error: Error) => void,
  ): () => void {
    if (!supabase) {throw new Error('Supabase not configured');}
    const sb = supabase;
    const channelName = `trip:${tripId}`;

    if (this.channels.has(channelName)) {
      const oldChannel = this.channels.get(channelName);
      if (oldChannel) {
        void oldChannel.unsubscribe();
        this.channels.delete(channelName);
      }
    }

    const channel = sb
      .channel(channelName, {
        config: { broadcast: { self: false } },
      })
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'messages',
          filter: `trip_id=eq.${tripId}`,
        },
        async (payload: { new: { id: string } }) => {
          try {
            const { data } = await sb
              .from('messages')
              .select(
                'id, trip_id, sender_id, content, type, metadata, read_by, created_at, sender:profiles(id, full_name, avatar_url)',
              )
              .eq('id', payload.new.id)
              .single();

            if (data) {
              onMessage(data as unknown as Message);
            }
          } catch {
            // Non-fatal: message fetch failed after realtime insert.
          }
        },
      )
      .subscribe((status: string) => {
        if (status === 'SUBSCRIPTION_ERROR' && onError) {
          onError(new Error('Subscription failed'));
        }
      });

    this.channels.set(channelName, channel);

    return () => {
      void channel.unsubscribe();
      this.channels.delete(channelName);
    };
  }

  async getUnreadCount(tripId: string): Promise<number> {
    if (!supabase) {throw new Error('Supabase not configured');}
    const {
      data: { user },
    } = await supabase.auth.getUser();

    if (!user) {
      return 0;
    }

    const { count } = await supabase
      .from('messages')
      .select('*', { count: 'exact', head: true })
      .eq('trip_id', tripId)
      .not('read_by', 'cs', `{${user.id}}`);

    return count || 0;
  }
}

export const chatService = new ChatService();

import { API_URL } from './api-resolver';
import { getConfig } from '../../utils/env';
import { validateApiUrl } from '../../utils/sanitization';
import { circuitBreakers, CircuitState } from '../../utils/circuitBreaker';
import { addCSRFHeader } from '../../utils/csrf';
import { supabase as supabaseClient } from '../../utils/supabase/client';
import {
  isEdgeFunctionAvailable,
  setEdgeFunctionAvailability,
  getNetworkOnline,
  setBackendStatus,
} from './availability';

export interface FetchWithRetryOptions extends RequestInit {
  timeout?: number;
}

export async function fetchWithRetry(
  url: string,
  options: FetchWithRetryOptions = {},
  retries = 1,
  backoff = 500,
): Promise<Response> {
  if (!url) {
    throw new Error(
      'Backend API is not configured. Set VITE_SUPABASE_URL and VITE_SUPABASE_PUBLISHABLE_KEY.',
    );
  }

  const { allowedApiDomain } = getConfig();
  const allowedDomains = ['supabase.co', 'supabase.net', 'localhost', allowedApiDomain].filter(
    Boolean,
  );

  if (!validateApiUrl(url, allowedDomains)) { // nosec CWE-918
    throw new Error('Invalid or unauthorized URL');
  }

  const breaker = circuitBreakers.get('api-calls', {
    failureThreshold: 5,
    timeout: 5000,
  });

  if (breaker.getState() === CircuitState.OPEN) {
    breaker.reset();
  }

  return breaker.execute(async () => {
    const { timeout = 5_000, signal: callerSignal, ...fetchOptions } = options;

    if (fetchOptions.method && ['POST', 'PUT', 'DELETE', 'PATCH'].includes(fetchOptions.method)) {
      fetchOptions.headers = addCSRFHeader(fetchOptions.headers);
    }

    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), timeout);

    if (callerSignal?.aborted) {
      clearTimeout(timer);
      throw new DOMException('Request aborted', 'AbortError');
    }

    const onCallerAbort = () => controller.abort();
    callerSignal?.addEventListener('abort', onCallerAbort, { once: true });

    try {
      const response = await fetch(url, {
        ...fetchOptions,
        signal: controller.signal,
      });

      if (response.ok) {
        if (!isEdgeFunctionAvailable() && url.includes('/health')) {
          setEdgeFunctionAvailability(true);
        }
        return response;
      }

      if (retries > 0 && [502, 503, 504].includes(response.status)) {
        await delay(backoff);
        return fetchWithRetry(url, options, retries - 1, backoff * 2);
      }

      if (!response.ok && response.status >= 500) {
        setBackendStatus(getNetworkOnline() ? 'degraded' : 'offline');
      }

      return response;
    } catch (error: unknown) {
      if (callerSignal?.aborted) {
        throw error;
      }

      const isRetryable =
        error instanceof TypeError ||
        (error instanceof DOMException && error.name === 'AbortError');

      if (retries > 0 && isRetryable) {
        await delay(backoff);
        return fetchWithRetry(url, options, retries - 1, backoff * 2);
      }

      setBackendStatus(getNetworkOnline() ? 'degraded' : 'offline');

      if (url.startsWith(API_URL)) {
        setEdgeFunctionAvailability(false);
      }

      throw error;
    } finally {
      clearTimeout(timer);
      callerSignal?.removeEventListener('abort', onCallerAbort);
    }
  });
}

function delay(ms: number): Promise<void> {
  return new Promise(resolve => setTimeout(resolve, ms));
}

export const supabase = supabaseClient;

export function resetApiCircuitBreaker(): void {
  const breaker = circuitBreakers.get('api-calls');
  breaker.reset();
  if (import.meta.env.DEV) {
    console.info('[Wasel] API circuit breaker manually reset');
  }
}

export function getApiCircuitBreakerState() {
  const breaker = circuitBreakers.get('api-calls');
  return breaker.getStats();
}

export interface AuthDetails {
  token: string;
  userId: string;
}

export async function getAuthDetails(): Promise<AuthDetails> {
  if (!supabase) {
    throw new Error('Supabase client is not initialised');
  }

  const {
    data: { session },
    error,
  } = await supabase.auth.getSession();
  if (error) {
    throw error;
  }

  const nowSeconds = Math.floor(Date.now() / 1000);
  const needsRefresh = !session || (session.expires_at ?? 0) - nowSeconds < 60;

  if (needsRefresh) {
    const { data: refreshed, error: refreshError } = await supabase.auth.refreshSession();
    if (refreshError || !refreshed.session) {
      throw new Error('Session expired. Please sign in again.');
    }
    return {
      token: refreshed.session.access_token,
      userId: refreshed.session.user.id,
    };
  }

  return {
    token: session.access_token,
    userId: session.user.id,
  };
}

