  repeatRideGoal: number;
  supplyReliability: number;
  savingsPercent: number;
  reason: string;
  nextAction: string;
}

export interface CorridorBetaPlan {
  regionCode: string;
  regionName: string;
  focusCorridors: CorridorBetaCorridor[];
  expansionDecision: CorridorBetaStage;
  nextExperiment: {
    title: string;
    instruction: string;
    metrics: string[];
  };
  updatedAt: string;
}

export interface ExpansionGateInput {
  weeklyRides: number;
  weeklyRideGoal: number;
  repeatRideRate: number;
  repeatRideGoal: number;
  supplyReliability: number;
  supplyReliabilityGoal: number;
  weeksAtTarget: number;
}

export interface ExpansionGateResult {
  stage: CorridorBetaStage;
  decision: 'narrow' | 'prove' | 'expand';
  blockers: string[];
}

const JO_REGION_CODE = 'JO';
const BETA_FOCUS_LIMIT = 3;
const WEEKLY_RIDE_GOAL = 120;
const REPEAT_RIDE_GOAL = 0.34;
const SUPPLY_RELIABILITY_GOAL = 0.72;
const WEEKS_AT_TARGET_GOAL = 3;

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function normalizeCity(value: string) {
  return value.trim().toLowerCase();
}

function corridorLabel(route: CityRoute) {
  return `${route.from} to ${route.to}`;
}

function betaPath(route: CityRoute) {
  return `/find-ride?from=${encodeURIComponent(route.from)}&to=${encodeURIComponent(route.to)}&beta=1`;
}

function marketRowForRoute(
  route: CityRoute,
  snapshot: ReturnType<typeof buildCorridorMarketSnapshot>,
): CorridorMarketRow | undefined {
  return snapshot.rows.find(row => row.id === `${JO_REGION_CODE}-${route.id}`);
}

function signalForRoute(
  route: CityRoute,
  snapshot: ReturnType<typeof buildRouteIntelligenceSnapshot>,
): LiveCorridorSignal | undefined {
  return snapshot.allSignals.find(
    signal =>
      normalizeCity(signal.from) === normalizeCity(route.from) &&
      normalizeCity(signal.to) === normalizeCity(route.to),
  );
}

function metricForRoute(
  route: CityRoute,
  metrics: CorridorBetaMetricCorridor[],
): CorridorBetaMetricCorridor | undefined {
  const key = `${normalizeCity(route.from)}|${normalizeCity(route.to)}`;
  return metrics.find(metric => metric.corridorId === key);
}

function getCorridorBetaMetricsData(): CorridorBetaMetricCorridor[] {
  return getCorridorBetaMetricCorridors();
}

function isHabitRoute(route: CityRoute) {
  const label = `${route.useCase} ${route.useCaseAr}`.toLowerCase();
  return (
    label.includes('commuter') ||
    label.includes('daily') ||
    label.includes('university') ||
    label.includes('family') ||
    label.includes('موظف') ||
    label.includes('طلاب') ||
    label.includes('عائلات')
  );
}

function calculateRepeatRideRate(route: CityRoute, signal?: LiveCorridorSignal) {
  const habitBias = isHabitRoute(route) ? 0.14 : 0.04;
  const distanceBias = route.distanceKm <= 90 ? 0.08 : route.distanceKm <= 220 ? 0.04 : 0;
  const demandBias = Math.min(0.18, ((signal?.forecastDemandScore ?? 70) / 100) * 0.16);
  const bookingBias = Math.min(0.12, (signal?.liveBookings ?? 0) * 0.018);

  return Number(
    clamp(0.12 + habitBias + distanceBias + demandBias + bookingBias, 0.08, 0.62).toFixed(2),
  );
}

function calculateWeeklyRides(signal?: LiveCorridorSignal) {
  return Math.round(
    (signal?.liveBookings ?? 4) * 7 +
      (signal?.liveSearches ?? 0) * 1.2 +
      (signal?.livePackages ?? 0) * 2,
  );
}

function calculateSupplyReliability(signal?: LiveCorridorSignal) {
  const activeSupply = Math.min(1, (signal?.activeSupply ?? 1) / 4);
  const utilization = (signal?.seatUtilizationPercent ?? 45) / 100;
  const forecast = (signal?.forecastDemandScore ?? 65) / 100;

  return Number(
    clamp(activeSupply * 0.3 + utilization * 0.42 + forecast * 0.28, 0.18, 0.96).toFixed(2),
  );
}

function calculateProofScore(args: {
  weeklyRides: number;
  repeatRideRate: number;
  supplyReliability: number;
  savingsPercent: number;
  signal?: LiveCorridorSignal;
}) {
  const weeklyScore = Math.min(25, (args.weeklyRides / WEEKLY_RIDE_GOAL) * 25);
  const repeatScore = Math.min(30, (args.repeatRideRate / REPEAT_RIDE_GOAL) * 30);
  const supplyScore = args.supplyReliability * 20;
  const economicsScore = Math.min(10, (args.savingsPercent / 40) * 10);
  const signalScore = Math.min(15, ((args.signal?.routeOwnershipScore ?? 70) / 100) * 15);

  return Math.round(
    clamp(weeklyScore + repeatScore + supplyScore + economicsScore + signalScore, 0, 100),
  );
}

function calculateWeeksAtTarget(weeklyRides: number, repeatRideRate: number, proofScore: number) {
  if (weeklyRides < WEEKLY_RIDE_GOAL || repeatRideRate < REPEAT_RIDE_GOAL) {return 0;}
  return Math.min(WEEKS_AT_TARGET_GOAL, Math.floor(proofScore / 34));
}

export function evaluateCorridorExpansion(input: ExpansionGateInput): ExpansionGateResult {
  const blockers: string[] = [];

  if (input.weeklyRides < input.weeklyRideGoal) {blockers.push('weekly rides');}
  if (input.repeatRideRate < input.repeatRideGoal) {blockers.push('repeat ride rate');}
  if (input.supplyReliability < input.supplyReliabilityGoal) {blockers.push('supply reliability');}
  if (input.weeksAtTarget < WEEKS_AT_TARGET_GOAL) {blockers.push('three-week consistency');}

  if (blockers.length === 0) {
    return { stage: 'expand', decision: 'expand', blockers };
  }

  if (
    input.weeklyRides >= input.weeklyRideGoal &&
    input.repeatRideRate >= input.repeatRideGoal &&
    input.supplyReliability >= input.supplyReliabilityGoal
  ) {
    return { stage: 'prove', decision: 'prove', blockers };
  }

  return { stage: 'narrow', decision: 'narrow', blockers };
}

function buildBetaCorridor(
  route: CityRoute,
  marketSnapshot: ReturnType<typeof buildCorridorMarketSnapshot>,
  intelligenceSnapshot: ReturnType<typeof buildRouteIntelligenceSnapshot>,
  metrics: CorridorBetaMetricCorridor[],
): CorridorBetaCorridor {
  const marketRow = marketRowForRoute(route, marketSnapshot);
  const signal = signalForRoute(route, intelligenceSnapshot);
  const metric = metricForRoute(route, metrics);
  const weeklyRides = metric?.weeklyRides ?? calculateWeeklyRides(signal);
  const repeatRideRate = metric?.repeatRideRate ?? calculateRepeatRideRate(route, signal);
  const supplyReliability = metric?.supplyReliability ?? calculateSupplyReliability(signal);
  const proofScore =
    metric?.proofScore ??
    calculateProofScore({
      weeklyRides,
      repeatRideRate,
      supplyReliability,
      savingsPercent: (marketRow?.savingsPercent ?? route.packageEnabled) ? 28 : 22,
      signal,
    });
  const weeksAtTarget =
    metric?.weeksAtTarget ?? calculateWeeksAtTarget(weeklyRides, repeatRideRate, proofScore);
  const gate = evaluateCorridorExpansion({
    weeklyRides,
    weeklyRideGoal: metric?.weeklyRideGoal ?? WEEKLY_RIDE_GOAL,
    repeatRideRate,
    repeatRideGoal: metric?.repeatRideGoal ?? REPEAT_RIDE_GOAL,
    supplyReliability,
    supplyReliabilityGoal: metric?.supplyReliabilityGoal ?? SUPPLY_RELIABILITY_GOAL,
    weeksAtTarget,
  });
  const reason =
    metric && gate.blockers.length === 0
      ? 'Observed ride data clears the corridor expansion gate.'
      : metric
        ? `Observed data is still narrowing the beta until ${gate.blockers.join(', ')} are stronger.`
        : gate.blockers.length === 0
          ? 'This corridor is ready for controlled expansion because rides, repeat behavior, and supply are all stable.'
          : `Narrow the beta until ${gate.blockers.join(', ')} are stronger.`;
  const nextAction =
    metric && gate.stage === 'expand'
      ? 'Observed rides, repeat behavior, supply, and consistency are strong enough to expand.'
      : gate.stage === 'expand'
        ? 'Open the next corridor only after the same three-week gate passes.'
        : gate.stage === 'prove'
          ? 'Keep supply fixed and push repeat riders until the consistency gate clears.'
          : 'Run one route, one pickup node, and one rider segment until demand concentrates.';

  return {
    routeId: route.id,
    corridor: corridorLabel(route),
    from: route.from,
    to: route.to,
    path: betaPath(route),
    stage: metric?.stage ?? gate.stage,
    proofScore,
    weeklyRides,
    weeklyRideGoal: metric?.weeklyRideGoal ?? WEEKLY_RIDE_GOAL,
    repeatRideRate,
    repeatRideGoal: metric?.repeatRideGoal ?? REPEAT_RIDE_GOAL,
    supplyReliability,
    savingsPercent: marketRow?.savingsPercent ?? 28,
    reason,
    nextAction,
  };
}

export function buildCorridorBetaPlan(args?: {
  regionCode?: string;
  limit?: number;
}): CorridorBetaPlan {
  const regionCode = args?.regionCode ?? JO_REGION_CODE;
  const limit = args?.limit ?? BETA_FOCUS_LIMIT;
  const region = getRegion(regionCode);
  const candidates = getTier1Routes(regionCode as 'JO')
    .slice()
    .sort((left, right) => {
      const leftHabit = isHabitRoute(left) ? 1 : 0;
      const rightHabit = isHabitRoute(right) ? 1 : 0;
      if (leftHabit !== rightHabit) {return rightHabit - leftHabit;}
      if (left.popular !== right.popular) {return Number(right.popular) - Number(left.popular);}
      return left.distanceKm - right.distanceKm;
    });
  const marketSnapshot = buildCorridorMarketSnapshot(10);
  const intelligenceSnapshot = buildRouteIntelligenceSnapshot();
  const metrics = getCorridorBetaMetricsData();
  const focusCorridors = candidates
    .slice(0, limit)
    .map(route => buildBetaCorridor(route, marketSnapshot, intelligenceSnapshot, metrics));
  const expansionDecision =
    focusCorridors.length > 0 && focusCorridors.every(corridor => corridor.stage === 'expand')
      ? 'expand'
      : focusCorridors.some(corridor => corridor.stage === 'prove')
        ? 'prove'
        : 'narrow';
  const leadCorridor = focusCorridors[0];

  return {
    regionCode,
    regionName: region.name,
    focusCorridors,
    expansionDecision,
    nextExperiment: {
      title: leadCorridor
        ? `Prove repeat rides on ${leadCorridor.corridor}`
        : 'Select the first corridor before launch',
      instruction:
        'Narrow the beta to the top three corridors, measure repeat rides for three consecutive weeks, then expand one corridor at a time.',
      metrics: [
        `${WEEKLY_RIDE_GOAL} weekly rides per corridor`,
        `${Math.round(REPEAT_RIDE_GOAL * 100)}% repeat ride rate`,
        `${Math.round(SUPPLY_RELIABILITY_GOAL * 100)}% supply reliability`,
      ],
    },
    updatedAt: new Date().toISOString(),
  };
}

// ─── Pure utility & mapping helpers ──────────────────────────────────────────

import { supabase } from '../../utils/supabase/client';
import { evaluateTrustCapability } from '../trustRules';
import { deriveAccountTrustScore } from '../../domain/trust/score';
import type { DbClient, RawBooking, RawProfile, TripRow, UserContext, WalletRow } from './types';
import type { TripCreatePayload, TripSearchResult } from '../trips';

export function getDb(): DbClient {
  if (!supabase) {throw new Error('Supabase client is not initialised');}
  return supabase as DbClient;
}

export function toNumber(value: unknown, fallback = 0): number {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : fallback;
}

export function formatTime(value: unknown): string {
  const text = String(value ?? '').trim();
  if (!text) {return '';}
  const date = new Date(text);
  if (Number.isNaN(date.getTime())) {
    const timeMatch = text.match(/^\d{2}:\d{2}/);
    return timeMatch ? timeMatch[0] : text;
  }
  return date.toISOString().slice(11, 16);
}

export function formatDate(value: unknown, fallback: string): string {
  const text = String(value ?? '').trim();
  if (!text) {return fallback;}
  const date = new Date(text);
  if (Number.isNaN(date.getTime())) {return text.slice(0, 10) || fallback;}
  return date.toISOString().slice(0, 10);
}

export function mapCanonicalRole(role?: string | null): string | null {
  if (!role) {return null;}
  if (role === 'rider') {return 'passenger';}
  if (role === 'both') {return 'driver';}
  return role;
}

export function mapProfileFromContext(
  context: UserContext,
  stats?: { tripCount?: number; rating?: number },
): RawProfile {
  const sanadVerified =
    context.verification?.sanad_status === 'verified' ||
    context.user.sanad_verified_status === 'verified' ||
    context.driver?.sanad_identity_linked === true;
  const walletBalance = toNumber(context.wallet?.balance, 0);
  const tripCount = toNumber(stats?.tripCount, 0);
  const rating = toNumber(stats?.rating, 5);

  return {
    id: context.authUserId,
    canonical_user_id: context.user.id,
    email: context.user.email ?? null,
    full_name: context.user.full_name ?? null,
    role: context.user.role ?? null,
    phone: context.user.phone_number ?? null,
    phone_number: context.user.phone_number ?? null,
    phone_verified: Boolean(context.user.phone_verified_at),
    // Email confirmation lives in auth, not the canonical user row.
    email_verified: null,
    wallet_balance: walletBalance,
    rating,
    rating_as_driver: rating,
    total_trips: tripCount,
    trip_count: tripCount,
    verified: sanadVerified,
    id_verified: sanadVerified,
    is_verified: sanadVerified,
    sanad_verified: sanadVerified,
    verification_level:
      context.verification?.verification_level ??
      context.driver?.verification_level ??
      context.user.verification_level ??
      'level_0',
    wallet_status: context.wallet?.wallet_status ?? 'active',
    avatar_url: context.user.avatar_url ?? null,
    two_factor_enabled: Boolean(context.user.two_factor_enabled),
    driver_status: context.driver?.driver_status ?? null,
    created_at: context.user.created_at ?? null,
  };
}

export function buildTrustLikeUser(profile: RawProfile) {
  const tripCount = toNumber(profile.trip_count ?? profile.total_trips, 0);
  const rating = toNumber(profile.rating ?? profile.rating_as_driver, 5);
  const verificationLevel = String(profile.verification_level ?? 'level_0');
  const phoneVerified = Boolean(profile.phone_verified);
  const emailVerified = profile.email_verified === true;
  const role = profile.role === 'driver' || profile.role === 'both' ? profile.role : 'rider';
  const trustScore = deriveAccountTrustScore({
    emailVerified,
    phoneVerified,
    trips: tripCount,
    rating,
  });
  return {
    role,
    verificationLevel,
    walletStatus:
      profile.wallet_status === 'frozen' ||
      profile.wallet_status === 'limited' ||
      profile.wallet_status === 'closed'
        ? profile.wallet_status
        : 'active',
    trustScore,
    phoneVerified,
    emailVerified,
  } as const;
}

export function ensureBookingEligibility(profile: RawProfile, allowPackageCarry = false) {
  const bookingUser = buildTrustLikeUser(profile);
  const payoutGate = evaluateTrustCapability(bookingUser, 'receive_payouts');
  if (!payoutGate.allowed && bookingUser.walletStatus === 'frozen') {
    throw new Error(payoutGate.reason ?? 'Wallet standing needs review before booking.');
  }
  if (!bookingUser.phoneVerified) {
    throw new Error('Booking requires a verified phone number.');
  }
  if (allowPackageCarry) {
    const packageGate = evaluateTrustCapability(bookingUser, 'carry_packages');
    if (!packageGate.allowed) {
      throw new Error(packageGate.reason ?? 'Package carrying requires a higher trust standing.');
    }
  }
}

export function mapTripRow(row: TripRow, driverProfile?: RawProfile | null): TripSearchResult {
  const createdAt = String(row.created_at ?? new Date().toISOString());
  const date = formatDate(row.departure_time, createdAt.slice(0, 10));
  return {
    id: String(row.trip_id ?? ''),
    from: String(row.origin_city ?? ''),
    to: String(row.destination_city ?? ''),
    date,
    time: formatTime(row.departure_time),
    seats: toNumber(row.available_seats, 0),
    price: toNumber(row.price_per_seat, 0),
    driver: {
      id: String(driverProfile?.id ?? 'driver'),
      name: String(
        driverProfile?.full_name || driverProfile?.email?.split('@')[0] || 'Wasel Driver',
      ),
      rating: toNumber(driverProfile?.rating_as_driver ?? driverProfile?.rating, 5),
      verified: Boolean(
        driverProfile?.id_verified ??
        driverProfile?.is_verified ??
        driverProfile?.sanad_verified ??
        driverProfile?.verified ??
        false,
      ),
    },
  };
}

export function buildTripNotes(payload: TripCreatePayload): string | null {
  const notes: string[] = [];
  if (payload.note?.trim()) {notes.push(payload.note.trim());}
  if (payload.acceptsPackages) {
    const packageLine = [
      `Packages enabled (${payload.packageCapacity ?? 'medium'})`,
      payload.packageNote?.trim() || '',
    ]
      .filter(Boolean)
      .join(': ');
    notes.push(packageLine);
  }
  if (payload.gender && payload.gender !== 'mixed') {notes.push(`Preference: ${payload.gender}`);}
  if (payload.prayer) {notes.push('Prayer stop requested');}
  return notes.length > 0 ? notes.join('\n') : null;
}

export function normalizeBookingStatus(status?: string | null): string {
  switch (status) {
    case 'accepted':
      return 'confirmed';
    case 'rejected':
      return 'cancelled';
    case 'pending_payment':
      return 'pending';
    default:
      return status || 'pending';
  }
}

export function normalizeTripStatus(status?: string | null): string {
  switch (status) {
    case 'active':
    case 'published':
      return 'open';
    default:
      return status || 'draft';
  }
}

export function normalizePackageCapacity(capacity?: TripCreatePayload['packageCapacity']): number {
  switch (capacity) {
    case 'small':
      return 1;
    case 'medium':
      return 2;
    case 'large':
      return 3;
    default:
      return 0;
  }
}

export function mapBookingRow(row: RawBooking): RawBooking {
  const seatNumber = toNumber(row.seat_number, 1);
  const amount = toNumber(row.amount ?? row.total_price, 0);
  const pricePerSeat = toNumber(row.price_per_seat, amount);
  return {
    ...row,
    id: String(row.booking_id ?? row.id ?? ''),
    booking_id: String(row.booking_id ?? row.id ?? ''),
    seats_requested: toNumber(row.seats_requested, 1),
    seat_number: seatNumber,
    price_per_seat: pricePerSeat,
    total_price: amount,
    amount,
    status: normalizeBookingStatus(row.booking_status ?? row.status),
    booking_status: row.booking_status ?? normalizeBookingStatus(row.status),
  };
}

export function packageSizeFromWeight(
  weightKg: number,
): 'small' | 'medium' | 'large' | 'extra_large' {
  if (weightKg <= 1) {return 'small';}
  if (weightKg <= 5) {return 'medium';}
  if (weightKg <= 12) {return 'large';}
  return 'extra_large';
}

export async function getWalletByCanonicalUserId(
  canonicalUserId: string,
): Promise<WalletRow | null> {
  const db = getDb();
  const { data, error } = await db
    .from('wallets')
    .select('*')
    .eq('user_id', canonicalUserId)
    .maybeSingle();
  if (error) {throw error;}
  return (data as WalletRow | null) ?? null;
}

export async function creditWalletBalance(canonicalUserId: string, amountJod: number) {
  const db = getDb();
  const wallet = await getWalletByCanonicalUserId(canonicalUserId);
  if (wallet?.wallet_id) {
    const nextBalance = toNumber(wallet.balance, 0) + amountJod;
    const nextPending = Math.max(0, toNumber(wallet.pending_balance, 0));
    const { error } = await db
      .from('wallets')
      .update({
        balance: nextBalance,
        pending_balance: nextPending,
        wallet_status: wallet.wallet_status ?? 'active',
      })
      .eq('wallet_id', wallet.wallet_id);
    if (error) {throw error;}
    return;
  }
  const { error } = await db.from('wallets').insert({
    user_id: canonicalUserId,
    balance: amountJod,
    pending_balance: 0,
    wallet_status: 'active',
    currency_code: 'JOD',
  });
  if (error) {throw error;}
}

