export async function updateDirectBookingStatus(
  bookingId: string,
  status: 'accepted' | 'rejected' | 'cancelled',
) {
  const db = getDb();
  const mappedStatus = normalizeBookingStatus(status);

  const { data: existing, error: existingError } = await db
    .from('bookings')
    .select('*')
    .eq('booking_id', bookingId)
    .single();
  if (existingError) {throw existingError;}

  const bookingRow = existing as RawBooking;
  const { data, error } = await db
    .from('bookings')
    .update({
      booking_status: mappedStatus,
      status: mappedStatus,
      confirmed_by_driver: mappedStatus === 'confirmed',
    })
    .eq('booking_id', bookingId)
    .select('*')
    .single();
  if (error) {throw error;}

  const tripId = bookingRow.trip_id;
  if (!tripId) {throw new Error('Booking is missing a trip id.');}

  const { data: trip } = await db
    .from('trips')
    .select('trip_id, available_seats, trip_status')
    .eq('trip_id', tripId)
    .maybeSingle();

  const availableSeats = toNumber((trip as TripRow | null)?.available_seats, 0);
  const seatsRequested = Math.max(1, toNumber(bookingRow.seats_requested, 1));

  if (mappedStatus === 'confirmed' && bookingRow.booking_status === 'pending_driver' && trip) {
    await db
      .from('trips')
      .update({
        available_seats: Math.max(availableSeats - seatsRequested, 0),
        trip_status:
          availableSeats - seatsRequested <= 0
            ? 'booked'
            : ((trip as TripRow).trip_status ?? 'open'),
      })
      .eq('trip_id', tripId);
    if (bookingRow.passenger_id) {
      await processReferralConversionForPassenger(String(bookingRow.passenger_id)).catch(() => {});
    }
  }

  if (
    (mappedStatus === 'cancelled' || mappedStatus === 'rejected') &&
    bookingRow.booking_status === 'confirmed' &&
    trip
  ) {
    await db
      .from('trips')
      .update({ available_seats: availableSeats + seatsRequested, trip_status: 'open' })
      .eq('trip_id', tripId);
  }

  await recordDirectGrowthEvent({
    userId: String(bookingRow.passenger_id ?? ''),
    eventName: 'ride_booking_status_updated',
    funnelStage: mappedStatus === 'confirmed' ? 'booked' : mappedStatus,
    serviceType: 'ride',
    valueJod: toNumber(bookingRow.amount, 0),
    metadata: {
      bookingId,
      tripId: bookingRow.trip_id,
      previousStatus: bookingRow.booking_status ?? bookingRow.status ?? null,
      nextStatus: mappedStatus,
    },
  }).catch(() => {});

  return mapBookingRow(data as RawBooking);
}

export async function getDirectDriverBookings(userId: string) {
  const context = await buildUserContext(userId);
  const driver = await ensureDriverForUser(context);
  const db = getDb();

  const { data: trips, error: tripsError } = await db
    .from('trips')
    .select('trip_id, origin_city, destination_city, departure_time')
    .eq('driver_id', driver.driver_id);
  if (tripsError) {throw tripsError;}

  const tripRows = Array.isArray(trips) ? (trips as TripRow[]) : [];
  const tripMap = new Map(tripRows.map(t => [String(t.trip_id ?? ''), t]));
  const tripIds = tripRows.map(t => String(t.trip_id ?? '')).filter(Boolean);
  if (tripIds.length === 0) {return [];}

  const { data: bookings, error } = await db
    .from('bookings')
    .select('*')
    .in('trip_id', tripIds)
    .order('created_at', { ascending: false });
  if (error) {throw error;}

  return Array.isArray(bookings)
    ? (bookings as RawBooking[]).map(booking => {
        const trip = tripMap.get(String(booking.trip_id ?? ''));
        return mapBookingRow({
          ...booking,
          pickup_location: booking.pickup_location ?? trip?.origin_city ?? null,
          dropoff_location: booking.dropoff_location ?? trip?.destination_city ?? null,
        });
      })
    : [];
}

import { supabase } from '../../utils/supabase/client';
import { getDb, getWalletByCanonicalUserId, mapCanonicalRole } from './helpers';
import type { DriverRow, RawVerificationRecord, UserContext, UserRow } from './types';

type UserSeed = {
  email?: string | null;
  full_name?: string | null;
  phone_number?: string | null;
  role?: string | null;
};

export async function resolveCanonicalUser(userKey: string): Promise<UserRow | null> {
  const db = getDb();
  const { data: byAuth } = await db
    .from('users')
    .select('*')
    .eq('auth_user_id', userKey)
    .maybeSingle();
  if (byAuth) {return byAuth as UserRow;}

  const { data: byId, error } = await db.from('users').select('*').eq('id', userKey).maybeSingle();
  if (error) {throw error;}
  return (byId as UserRow | null) ?? null;
}

function resolveAuthUserProperty(
  authUser: { email?: string | null; user_metadata?: Record<string, unknown>; phone?: string | null },
  key: 'email' | 'full_name' | 'phone_number' | 'role',
  fallback: string | null,
): string | null {
  if (key === 'email') {
    return authUser.email || null;
  }
  if (key === 'full_name') {
    const name =
      String(authUser.user_metadata?.full_name ?? authUser.user_metadata?.name ?? '').trim();
    return name || null;
  }
  if (key === 'phone_number') {
    const phone =
      String(
        authUser.user_metadata?.phone_number ??
          authUser.user_metadata?.phone ??
          authUser.phone ??
          '',
      ).trim();
    return phone || null;
  }
  if (key === 'role') {
    return String(authUser.user_metadata?.role ?? '').trim() || null;
  }
  return fallback;
}

async function resolveAuthSeed(userKey: string, seed?: UserSeed): Promise<UserSeed> {
  const mergedSeed: UserSeed = {
    email: seed?.email?.trim() || null,
    full_name: seed?.full_name?.trim() || null,
    phone_number: seed?.phone_number?.trim() || null,
    role: seed?.role ?? null,
  };

  if ((!mergedSeed.email || !mergedSeed.full_name || !mergedSeed.phone_number) && supabase) {
    const {
      data: { user: authUser },
    } = await supabase.auth.getUser().catch(() => ({ data: { user: null } }));

    if (authUser && authUser.id === userKey) {
      mergedSeed.email = mergedSeed.email || resolveAuthUserProperty(authUser, 'email', null) || null;
      mergedSeed.full_name =
        mergedSeed.full_name ||
        resolveAuthUserProperty(authUser, 'full_name', null) ||
        null;
      mergedSeed.phone_number =
        mergedSeed.phone_number ||
        resolveAuthUserProperty(authUser, 'phone_number', null) ||
        null;
      mergedSeed.role =
        mergedSeed.role || resolveAuthUserProperty(authUser, 'role', null) || null;
    }
  }

  return mergedSeed;
}

export async function ensureCanonicalUser(userKey: string, seed?: UserSeed): Promise<UserRow> {
  const existing = await resolveCanonicalUser(userKey);
  if (existing) {return existing;}

  const resolvedSeed = await resolveAuthSeed(userKey, seed);
  if (!resolvedSeed.email || !resolvedSeed.full_name || !resolvedSeed.phone_number) {
    throw new Error(
      'User profile is incomplete. Complete your account profile in Supabase before continuing.',
    );
  }

  const db = getDb();
  const { data, error } = await db
    .from('users')
    .insert({
      auth_user_id: userKey,
      email: resolvedSeed.email,
      full_name: resolvedSeed.full_name,
      phone_number: resolvedSeed.phone_number,
      role: mapCanonicalRole(resolvedSeed.role) || 'passenger',
    })
    .select('*')
    .single();
  if (error) {throw error;}
  return data as UserRow;
}

export async function getDriverByCanonicalUserId(userId: string): Promise<DriverRow | null> {
  const db = getDb();
  const { data, error } = await db.from('drivers').select('*').eq('user_id', userId).maybeSingle();
  if (error) {throw error;}
  return (data as DriverRow | null) ?? null;
}

export async function ensureDriverForUser(context: UserContext): Promise<DriverRow> {
  if (!context.driver) {
    throw new Error(
      'Driver profile is not provisioned. Complete driver onboarding and approval before offering rides.',
    );
  }

  if (
    context.driver.driver_status !== 'approved' &&
    context.driver.driver_status !== 'online' &&
    context.driver.driver_status !== 'offline' &&
    context.driver.driver_status !== 'busy'
  ) {
    throw new Error(
      'Driver profile is pending approval. You can offer rides after driver verification is approved.',
    );
  }

  return context.driver;
}

export async function getLatestVerificationRecord(
  canonicalUserId: string,
): Promise<RawVerificationRecord | null> {
  const db = getDb();
  const { data, error } = await db
    .from('verification_records')
    .select(
      'sanad_status, document_status, verification_level, verification_timestamp, failure_reason, updated_at',
    )
    .eq('user_id', canonicalUserId)
    .order('verification_timestamp', { ascending: false })
    .limit(1)
    .maybeSingle();
  if (error) {throw error;}
  return (data as RawVerificationRecord | null) ?? null;
}

export async function buildUserContext(
  userKey: string,
  seed?: Parameters<typeof ensureCanonicalUser>[1],
): Promise<UserContext> {
  const user = await ensureCanonicalUser(userKey, seed);
  const [wallet, verification, driver] = await Promise.all([
    getWalletByCanonicalUserId(user.id).catch(() => null),
    getLatestVerificationRecord(user.id).catch(() => null),
    getDriverByCanonicalUserId(user.id).catch(() => null),
  ]);
  return {
    user,
    wallet,
    verification,
    driver,
    authUserId: user.auth_user_id ?? userKey,
  };
}

const ALLOWED_GOOGLE_DOMAINS = ['googleapis.com', 'google.com', 'localhost'];

function isValidGoogleUrl(url: string): boolean {
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== 'https:' && parsed.protocol !== 'http:') {return false;}
    if (parsed.hostname === 'localhost') {return true;}
    const privateRanges = [/^127\./, /^10\./, /^172\.(1[6-9]|2[0-9]|3[01])\./, /^192\.168\./, /^169\.254\./];
    if (privateRanges.some(p => p.test(parsed.hostname))) {return false;}
    return ALLOWED_GOOGLE_DOMAINS.some(d => parsed.hostname === d || parsed.hostname.endsWith(`.${d}`));
  } catch {
    return false;
  }
}

