}

const ALLOWED_CITY_KEYS = new Set(Object.keys(CITY_COORDS));
const ROUTE_ID_PATTERN = /^[a-zA-Z0-9_-]+$/;

const TRAFFIC_CACHE_TTL_MS = 2 * 60 * 1000;
const trafficCache = new Map<string, { expiresAt: number; snapshot: GoogleTrafficSnapshot }>();

function getGoogleMapsApiKey(): string | null {
  const key = String(import.meta.env.VITE_GOOGLE_MAPS_API_KEY ?? '').trim();
  if (!key || key.length < 10) {return null;}
  return key;
}

function parseGoogleDurationSeconds(value: string | null | undefined): number | null {
  if (!value) {return null;}
  const match = /^([0-9]+(?:\.[0-9]+)?)s$/.exec(value.trim());
  if (!match) {return null;}
  const seconds = Number(match[1]);
  return Number.isFinite(seconds) ? seconds : null;
}

export async function fetchGoogleTrafficSnapshot(
  routeId: string,
  from: string,
  to: string,
): Promise<GoogleTrafficSnapshot | null> {
  const apiKey = getGoogleMapsApiKey();
  if (!apiKey) {return null;}

  const safeRouteId = ROUTE_ID_PATTERN.test(routeId) ? routeId : '';
  if (!safeRouteId) {return null;}

  const originKey = ALLOWED_CITY_KEYS.has(from) ? from : null;
  const destinationKey = ALLOWED_CITY_KEYS.has(to) ? to : null;
  if (!originKey || !destinationKey) {return null;}

  const origin = CITY_COORDS[originKey];
  const destination = CITY_COORDS[destinationKey];
  if (!origin || !destination) {return null;}

  const GOOGLE_ROUTES_URL = 'https://routes.googleapis.com/directions/v2:computeRoutes';

  if (!isValidGoogleUrl(GOOGLE_ROUTES_URL)) { // nosec CWE-94 CWE-918 CWE-78
    return null;
  }

  const cached = trafficCache.get(safeRouteId);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.snapshot;
  }

  try {
    const response = await fetch(GOOGLE_ROUTES_URL, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Goog-Api-Key': apiKey,
        'X-Goog-FieldMask': 'routes.duration,routes.staticDuration,routes.distanceMeters',
      },
      body: JSON.stringify({
        origin: { location: { latLng: { latitude: origin.lat, longitude: origin.lng } } },
        destination: {
          location: { latLng: { latitude: destination.lat, longitude: destination.lng } },
        },
        travelMode: 'DRIVE',
        routingPreference: 'TRAFFIC_AWARE',
        departureTime: new Date().toISOString(),
      }),
    });

    if (!response.ok) {return null;}
    const json = await response.json();
    const route = Array.isArray(json?.routes) ? json.routes[0] : null;
    const durationSeconds = parseGoogleDurationSeconds(route?.duration);
    const staticDurationSeconds = parseGoogleDurationSeconds(route?.staticDuration);
    const distanceMeters = Number(route?.distanceMeters ?? 0);

    if (!durationSeconds || distanceMeters <= 0) {return null;}

    const speedKph = Math.max(18, Math.round((distanceMeters / durationSeconds) * 3.6));
    const trafficRatio =
      staticDurationSeconds && staticDurationSeconds > 0
        ? durationSeconds / staticDurationSeconds
        : 1;
    const congestion = Math.max(0.05, Math.min(0.98, (trafficRatio - 1) / 0.65));
    const snapshot = {
      speedKph,
      congestion,
      updatedAt: new Date().toISOString(),
    };

    trafficCache.set(safeRouteId, {
      expiresAt: Date.now() + TRAFFIC_CACHE_TTL_MS,
      snapshot,
    });

    return snapshot;
  } catch {
    return null;
  }
}

import { API_URL, fetchWithRetry, getAuthDetails } from './core';
import {
  createDirectPackage,
  getDirectPackageByTrackingId,
  updateDirectPackageStatus,
} from './directSupabase';
import { trackGrowthEvent } from './growthEngine';
import { tripsAPI } from './trips';

export interface PostedRide {
  id: string;
  ownerId?: string;
  from: string;
  to: string;
  date: string;
  time: string;
  seats: number;
  price: number;
  gender: string;
  prayer: boolean;
  carModel: string;
  note: string;
  acceptsPackages: boolean;
  packageCapacity: 'small' | 'medium' | 'large';
  packageNote: string;
  createdAt: string;
  status?: 'active' | 'cancelled' | 'completed';
}

export type PackageStatus = 'searching' | 'matched' | 'in_transit' | 'delivered';

export interface PackageVerification {
  senderCodeSharedAt?: string;
  riderPickupConfirmedAt?: string;
  receiverDeliveryConfirmedAt?: string;
}

export interface PackageRequest {
  id: string;
  trackingId: string;
  handoffCode: string;
  from: string;
  to: string;
  weight: string;
  note: string;
  packageType: 'delivery' | 'return';
  recipientName?: string;
  recipientPhone?: string;
  matchedRideId?: string;
  matchedDriver?: string;
  status: PackageStatus;
  createdAt: string;
  verification: PackageVerification;
  timeline: Array<{ label: string; complete: boolean }>;
}

const RIDES_KEY = 'wasel-connected-rides';
const PACKAGES_KEY = 'wasel-connected-packages';
const PACKAGE_LIMIT = 50;
const RIDE_LIMIT = 50;

function readList<T> ( key: string ): T[] {
  if ( typeof window === 'undefined' ) { return []; }
  try {
    const raw = window.localStorage.getItem( key );
    const parsed = raw ? JSON.parse( raw ) : [];
    return Array.isArray( parsed ) ? parsed : [];
  } catch {
    return [];
  }
}

function writeList<T> ( key: string, list: T[] ): void {
  if ( typeof window === 'undefined' ) { return; }
  window.localStorage.setItem( key, JSON.stringify( list ) );
}

function makeId ( prefix: string ): string {
  return `${ prefix }-${ crypto.randomUUID() }`;
}

function generateHandoffCode (): string {
  return `HC-${ crypto.randomUUID().replace( /-/g, '' ).slice( 0, 6 ).toUpperCase() }`;
}

function pickDriverName ( carModel: string ): string {
  if ( !carModel.trim() ) { return 'Wasel Captain'; }
  return `${ carModel.split( ' ' )[ 0 ] } Captain`;
}

function parseWeight ( weight: string ): number {
  const matches = weight.match( /\d+(?:\.\d+)?/g );
  if ( !matches ) { return 0.5; }
  const values = matches.map( Number ).filter( value => Number.isFinite( value ) );
  if ( !values.length ) { return 0.5; }
  return Math.max( ...values );
}

function sanitizeWeight ( weight: string ): string {
  return weight.trim() || '<1 kg';
}

function sanitizePhone ( phone?: string ): string | undefined {
  const sanitized = ( phone ?? '' ).replace( /[^\d+]/g, '' ).trim();
  return sanitized || undefined;
}

function sortByCreatedAtDesc<T extends { createdAt: string }> ( items: T[] ): T[] {
  return [ ...items ].sort( ( a, b ) => {
    const left = new Date( a.createdAt ).getTime();
    const right = new Date( b.createdAt ).getTime();
    return ( Number.isFinite( right ) ? right : 0 ) - ( Number.isFinite( left ) ? left : 0 );
  } );
}

function normalizeStatus ( value: unknown, matchedRideId?: string ): PackageStatus {
  const status = String( value ?? '' ).toLowerCase();
  if ( status === 'delivered' ) { return 'delivered'; }
  if ( status === 'in_transit' || status === 'picked_up' ) { return 'in_transit'; }
  if (
    status === 'searching' ||
    status === 'pending' ||
    status === 'requested' ||
    status === 'queued'
  ) {
    return matchedRideId ? 'matched' : 'searching';
  }
  if ( status === 'matched' || status === 'assigned' || status === 'accepted' ) { return 'matched'; }
  return matchedRideId ? 'matched' : 'searching';
}

function buildTimeline (
  status: PackageStatus,
  matchedRideId?: string,
  verification: PackageVerification = {},
): Array<{ label: string; complete: boolean }> {
  const matched = Boolean( matchedRideId ) || status !== 'searching';
  const senderShared = Boolean( verification.senderCodeSharedAt );
  const inTransit =
    Boolean( verification.riderPickupConfirmedAt ) ||
    status === 'in_transit' ||
    status === 'delivered';
  const delivered = Boolean( verification.receiverDeliveryConfirmedAt ) || status === 'delivered';

  return [
    { label: 'Request received', complete: true },
    {
      label: matched ? 'Matched to a rider trip' : 'Searching for a rider trip',
      complete: matched,
    },
    { label: 'Sender shared OTP handoff code', complete: senderShared },
    { label: 'Rider pickup confirmed', complete: inTransit },
    { label: 'Receiver delivery confirmed', complete: delivered },
  ];
}

function normalizeServerRide ( raw: Record<string, unknown>, fallback: PostedRide ): PostedRide {
  return {
    ...fallback,
    id: String( raw.id ?? fallback.id ),
    from: String( raw.from_location ?? raw.from ?? fallback.from ),
    to: String( raw.to_location ?? raw.to ?? fallback.to ),
    date: String( raw.departure_date ?? raw.date ?? fallback.date ),
    time: String( raw.departure_time ?? raw.time ?? fallback.time ),
    seats: Number( raw.available_seats ?? raw.total_seats ?? raw.seats ?? fallback.seats ),
    price: Number( raw.price_per_seat ?? raw.price ?? fallback.price ),
    carModel: String( raw.vehicle_model ?? raw.carModel ?? fallback.carModel ),
    note: String( raw.notes ?? raw.note ?? fallback.note ),
    createdAt: String( raw.created_at ?? fallback.createdAt ),
    ownerId:
      String( raw.owner_id ?? raw.ownerId ?? fallback.ownerId ?? '' ).trim() || fallback.ownerId,
    status:
      raw.status === 'cancelled' || raw.status === 'completed'
        ? raw.status
        : ( fallback.status ?? 'active' ),
  };
}

function normalizeLocalRide ( raw: Partial<PostedRide> ): PostedRide | null {
  const id = String( raw.id ?? '' ).trim();
  const from = String( raw.from ?? '' ).trim();
  const to = String( raw.to ?? '' ).trim();
  if ( !id || !from || !to ) { return null; }

  return {
    id,
    from,
    to,
    date: String( raw.date ?? '' ),
    time: String( raw.time ?? '' ),
    seats: Number( raw.seats ?? 1 ) || 1,
    price: Number( raw.price ?? 0 ) || 0,
    gender: String( raw.gender ?? 'any' ),
    prayer: Boolean( raw.prayer ),
    carModel: String( raw.carModel ?? '' ),
    note: String( raw.note ?? '' ),
    acceptsPackages: Boolean( raw.acceptsPackages ),
    packageCapacity:
      raw.packageCapacity === 'large' || raw.packageCapacity === 'small'
        ? raw.packageCapacity
        : 'medium',
    packageNote: String( raw.packageNote ?? '' ),
    createdAt: String( raw.createdAt ?? new Date().toISOString() ),
    ownerId: String( raw.ownerId ?? '' ).trim() || undefined,
    status: raw.status === 'cancelled' || raw.status === 'completed' ? raw.status : 'active',
  };
}

function normalizeServerPackage (
  raw: Record<string, unknown>,
  fallback: PackageRequest,
): PackageRequest {
  const matchedRideId =
    String( raw.trip_id ?? raw.matchedRideId ?? fallback.matchedRideId ?? '' ).trim() || undefined;
  const status = normalizeStatus( raw.status, matchedRideId );
  const handoffCode =
    String( raw.handoff_code ?? raw.handoffCode ?? fallback.handoffCode ?? '' )
      .trim()
      .toUpperCase() ||
    fallback.handoffCode ||
    generateHandoffCode();

  return {
    ...fallback,
    id: String( raw.id ?? fallback.id ),
    trackingId: String( raw.tracking_code ?? raw.trackingId ?? fallback.trackingId )
      .trim()
      .toUpperCase(),
    handoffCode,
    from: String( raw.from ?? fallback.from ),
    to: String( raw.to ?? fallback.to ),
    weight: sanitizeWeight( String( raw.weight ?? fallback.weight ) ),
    note: String( raw.description ?? raw.note ?? fallback.note ),
    packageType: raw.packageType === 'return' ? 'return' : fallback.packageType,
    recipientName:
      String( raw.recipient_name ?? raw.recipientName ?? fallback.recipientName ?? '' ).trim() ||
      undefined,
    recipientPhone: sanitizePhone(
      String( raw.recipient_phone ?? raw.recipientPhone ?? fallback.recipientPhone ?? '' ),
    ),
    matchedRideId,
    matchedDriver:
      String( raw.driver_name ?? raw.matchedDriver ?? fallback.matchedDriver ?? '' ).trim() ||
      fallback.matchedDriver,
    status,
    createdAt: String( raw.created_at ?? fallback.createdAt ),
    verification: {
      senderCodeSharedAt:
        String(
          raw.sender_code_shared_at ??
          raw.senderCodeSharedAt ??
          fallback.verification?.senderCodeSharedAt ??
          '',
        ).trim() || undefined,
      riderPickupConfirmedAt:
        String(
          raw.rider_pickup_confirmed_at ??
          raw.riderPickupConfirmedAt ??
          fallback.verification?.riderPickupConfirmedAt ??
          '',
        ).trim() || undefined,
      receiverDeliveryConfirmedAt:
        String(
          raw.receiver_delivery_confirmed_at ??
          raw.receiverDeliveryConfirmedAt ??
          fallback.verification?.receiverDeliveryConfirmedAt ??
          '',
        ).trim() || undefined,
    },
    timeline: buildTimeline( status, matchedRideId, {
      senderCodeSharedAt:
        String(
          raw.sender_code_shared_at ??
          raw.senderCodeSharedAt ??
          fallback.verification?.senderCodeSharedAt ??
          '',
        ).trim() || undefined,
      riderPickupConfirmedAt:
        String(
          raw.rider_pickup_confirmed_at ??
          raw.riderPickupConfirmedAt ??
          fallback.verification?.riderPickupConfirmedAt ??
          '',
        ).trim() || undefined,
      receiverDeliveryConfirmedAt:
        String(
          raw.receiver_delivery_confirmed_at ??
          raw.receiverDeliveryConfirmedAt ??
          fallback.verification?.receiverDeliveryConfirmedAt ??
          '',
        ).trim() || undefined,
    } ),
  };
}

function normalizeLocalPackage ( raw: Partial<PackageRequest> ): PackageRequest | null {
  const trackingId = String( raw.trackingId ?? '' )
    .trim()
    .toUpperCase();
  const from = String( raw.from ?? '' ).trim();
  const to = String( raw.to ?? '' ).trim();
  if ( !trackingId || !from || !to ) { return null; }

  const matchedRideId = String( raw.matchedRideId ?? '' ).trim() || undefined;
  const status = normalizeStatus( raw.status, matchedRideId );
  const handoffCode =
    String( raw.handoffCode ?? '' )
      .trim()
      .toUpperCase() || generateHandoffCode();

  return {
    id: String( raw.id ?? makeId( 'pkg' ) ),
    trackingId,
    handoffCode,
    from,
    to,
    weight: sanitizeWeight( String( raw.weight ?? '<1 kg' ) ),
    note: String( raw.note ?? '' ).trim(),
    packageType: raw.packageType === 'return' ? 'return' : 'delivery',
    recipientName: String( raw.recipientName ?? '' ).trim() || undefined,
    recipientPhone: sanitizePhone( String( raw.recipientPhone ?? '' ) ),
    matchedRideId,
    matchedDriver: String( raw.matchedDriver ?? '' ).trim() || undefined,
    status,
    createdAt: String( raw.createdAt ?? new Date().toISOString() ),
    verification: {
      senderCodeSharedAt: String( raw.verification?.senderCodeSharedAt ?? '' ).trim() || undefined,
      riderPickupConfirmedAt:
        String( raw.verification?.riderPickupConfirmedAt ?? '' ).trim() || undefined,
      receiverDeliveryConfirmedAt:
        String( raw.verification?.receiverDeliveryConfirmedAt ?? '' ).trim() || undefined,
    },
    timeline:
      Array.isArray( raw.timeline ) && raw.timeline.length > 0
        ? raw.timeline.map( step => ( {
          label: String( step.label ?? '' ),
          complete: Boolean( step.complete ),
        } ) )
        : buildTimeline( status, matchedRideId, {
          senderCodeSharedAt:
            String( raw.verification?.senderCodeSharedAt ?? '' ).trim() || undefined,
          riderPickupConfirmedAt:
            String( raw.verification?.riderPickupConfirmedAt ?? '' ).trim() || undefined,
          receiverDeliveryConfirmedAt:
            String( raw.verification?.receiverDeliveryConfirmedAt ?? '' ).trim() || undefined,
        } ),
  };
}

function mergePackages ( ...lists: PackageRequest[][] ): PackageRequest[] {
  const merged = new Map<string, PackageRequest>();

  for ( const list of lists ) {
    for ( const item of list ) {
      const normalized = normalizeLocalPackage( item );
      if ( !normalized ) { continue; }
      merged.set( normalized.trackingId, normalized );
    }
  }

  return sortByCreatedAtDesc( Array.from( merged.values() ) ).slice( 0, PACKAGE_LIMIT );
}

function mergeRides ( ...lists: PostedRide[][] ): PostedRide[] {
  const merged = new Map<string, PostedRide>();

  for ( const list of lists ) {
    for ( const item of list ) {
      const normalized = normalizeLocalRide( item );
      if ( !normalized ) { continue; }
      merged.set( normalized.id, normalized );
    }
  }

  return sortByCreatedAtDesc( Array.from( merged.values() ) ).slice( 0, RIDE_LIMIT );
}

function savePackages ( ...lists: PackageRequest[][] ): PackageRequest[] {
  const packages = mergePackages( ...lists );
  writeList( PACKAGES_KEY, packages );
  return packages;
}

function saveRides ( ...lists: PostedRide[][] ): PostedRide[] {
  const rides = mergeRides( ...lists );
  writeList( RIDES_KEY, rides );
  return rides;
}

function findBestMatchingRide (
  rides: PostedRide[],
  input: { from: string; to: string; weight: string },
): PostedRide | undefined {
  const requestedWeight = parseWeight( input.weight );
  const capacityRank = { small: 1, medium: 5, large: 10 };

  return sortByCreatedAtDesc( rides )
    .filter( ride => ride.acceptsPackages && ride.from === input.from && ride.to === input.to )
    .find( ride => capacityRank[ ride.packageCapacity ] >= requestedWeight );
}

export function getConnectedRides (): PostedRide[] {
  const rides = mergeRides( readList<PostedRide>( RIDES_KEY ) );
  writeList( RIDES_KEY, rides );
  return rides;
}

export async function createConnectedRide (
  input: Omit<PostedRide, 'id' | 'createdAt'>,
): Promise<PostedRide> {
  const ride: PostedRide = {
    ...input,
    id: makeId( 'ride' ),
    createdAt: new Date().toISOString(),
    status: input.status ?? 'active',
  };

  try {
    const server = await tripsAPI.createTrip( {
      from: input.from,
      to: input.to,
      date: input.date,
      time: input.time,
      seats: input.seats,
      price: input.price,
      gender: input.gender,
      prayer: input.prayer,
      carModel: input.carModel,
      note: input.note,
      acceptsPackages: input.acceptsPackages,
      packageCapacity: input.packageCapacity,
      packageNote: input.packageNote,
    } );

    const created = normalizeServerRide( server as unknown as Record<string, unknown>, ride );
    saveRides( [ created ], getConnectedRides() );
    void trackGrowthEvent( {
      userId: input.ownerId,
      eventName: 'ride_offer_created',
      funnelStage: 'selected',
      serviceType: 'ride',
      from: created.from,
      to: created.to,
      valueJod: created.price,
      metadata: { seats: created.seats, acceptsPackages: created.acceptsPackages },
    } );
    return created;
  } catch ( error ) {
    throw error instanceof Error ? error : new Error( 'Ride could not be published.' );
  }
}

export function updateConnectedRide (
  rideId: string,
  updates: Partial<Pick<PostedRide, 'seats' | 'status' | 'note' | 'date' | 'time'>>,
): PostedRide | null {
  const rides = getConnectedRides();
  const target = rides.find( ride => ride.id === rideId );
  if ( !target ) { return null; }

  const updated: PostedRide = {
    ...target,
    ...updates,
    seats: typeof updates.seats === 'number' ? Math.max( 0, updates.seats ) : target.seats,
  };

  saveRides( rides.map( ride => ( ride.id === rideId ? updated : ride ) ) );
  return updated;
}

export function getConnectedPackages (): PackageRequest[] {
  const packages = mergePackages( readList<PackageRequest>( PACKAGES_KEY ) );
  writeList( PACKAGES_KEY, packages );
  return packages;
}

function buildServerPackagePayload ( pkg: PackageRequest ) {
  return {
    from: pkg.from,
    to: pkg.to,
    weight: parseWeight( pkg.weight ),
    description: pkg.note,
    price: 5,
    handoffCode: pkg.handoffCode,
    ...( pkg.recipientName ? { recipientName: pkg.recipientName } : {} ),
    ...( pkg.recipientPhone ? { recipientPhone: pkg.recipientPhone } : {} ),
    ...( pkg.packageType === 'return' ? { packageType: pkg.packageType } : {} ),
  };
}

export async function createConnectedPackage ( input: {
  from: string;
  to: string;
  weight: string;
  note: string;
  packageType?: 'delivery' | 'return';
  recipientName?: string;
  recipientPhone?: string;
} ): Promise<PackageRequest> {
  const from = input.from.trim();
  const to = input.to.trim();

  if ( !from || !to ) {
    throw new Error( 'Sender and receiver cities are required.' );
  }

  if ( from === to ) {
    throw new Error( 'Sender and receiver cities must be different.' );
  }

  const trackingId = `PKG-${ crypto.randomUUID().replace( /-/g, '' ).slice( 0, 8 ).toUpperCase() }`;

  const pkg: PackageRequest = {
    id: makeId( 'pkg' ),
    trackingId,
    handoffCode: generateHandoffCode(),
    from,
    to,
    weight: sanitizeWeight( input.weight ),
    note: input.note.trim(),
    packageType: input.packageType ?? 'delivery',
    recipientName: input.recipientName?.trim() || undefined,
    recipientPhone: sanitizePhone( input.recipientPhone ),
    matchedRideId: undefined,
    matchedDriver: undefined,
    status: 'searching',
    createdAt: new Date().toISOString(),
    verification: {},
    timeline: buildTimeline( 'searching', undefined, {} ),
  };

  try {
    const { token, userId } = await getAuthDetails();

    if ( API_URL ) {
      const response = await fetchWithRetry( `${ API_URL }/packages`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${ token }`,
        },
        body: JSON.stringify( buildServerPackagePayload( pkg ) ),
      } );

      if ( response.ok ) {
        const server = await response.json();
        const created = normalizeServerPackage( server.package as Record<string, unknown>, pkg );
        savePackages( [ created ], getConnectedPackages() );
        void trackGrowthEvent( {
          userId,
          eventName: 'package_request_created',
          funnelStage: created.matchedRideId ? 'selected' : 'searched',
          serviceType: 'package',
          from: created.from,
          to: created.to,
          valueJod: 5,
          metadata: {
            trackingId: created.trackingId,
            packageType: created.packageType,
          },
        } );
        return created;
      }
    } else {
      const createdDirect = await createDirectPackage( {
        userId,
        trackingNumber: pkg.trackingId,
        from: pkg.from,
        to: pkg.to,
        weightKg: parseWeight( pkg.weight ),
        description: pkg.note,
        recipientName: pkg.recipientName,
        recipientPhone: pkg.recipientPhone,
      } );

      const created = normalizeServerPackage( createdDirect as Record<string, unknown>, {
        ...pkg,
        from: String( createdDirect.origin_name ?? pkg.from ),
        to: String( createdDirect.destination_name ?? pkg.to ),
        weight: sanitizeWeight( String( createdDirect.weight_kg ?? pkg.weight ) ),
      } );
      savePackages( [ created ], getConnectedPackages() );
      void trackGrowthEvent( {
        userId,
        eventName: 'package_request_created',
        funnelStage: created.matchedRideId ? 'selected' : 'searched',
        serviceType: 'package',
        from: created.from,
        to: created.to,
        valueJod: 5,
        metadata: {
          trackingId: created.trackingId,
          packageType: created.packageType,
        },
      } );
      return created;
    }
  } catch {
    // Fall back to local storage below.
  }

  const rides = getConnectedRides();
  const matchedRide = findBestMatchingRide( rides, { from, to, weight: input.weight } );
  const fallbackStatus: PackageStatus = matchedRide ? 'matched' : 'searching';
  const fallbackPackage: PackageRequest = {
    ...pkg,
    matchedRideId: matchedRide?.id,
    matchedDriver: matchedRide ? pickDriverName( matchedRide.carModel ) : undefined,
    status: fallbackStatus,
    timeline: buildTimeline( fallbackStatus, matchedRide?.id, pkg.verification ),
  };

  savePackages( [ fallbackPackage ], getConnectedPackages() );
  void trackGrowthEvent( {
    eventName: 'package_request_created',
    funnelStage: fallbackPackage.matchedRideId ? 'selected' : 'searched',
    serviceType: 'package',
    from: fallbackPackage.from,
    to: fallbackPackage.to,
    valueJod: 5,
    metadata: {
      trackingId: fallbackPackage.trackingId,
      packageType: fallbackPackage.packageType,
      source: 'local',
    },
  } );
  return fallbackPackage;
}

export async function getPackageByTrackingId ( trackingId: string ): Promise<PackageRequest | null> {
  const normalizedTrackingId = trackingId.trim().toUpperCase();
  if ( !normalizedTrackingId ) { return null; }

  const local =
    getConnectedPackages().find( item => item.trackingId === normalizedTrackingId ) ?? null;
  if ( local ) { return local; }

  try {
    let server: Record<string, unknown> | null = null;

    if ( API_URL ) {
      const response = await fetchWithRetry(
        `${ API_URL }/packages/track/${ encodeURIComponent( normalizedTrackingId ) }`,
        {
          headers: {
            'Content-Type': 'application/json',
          },
        },
      );
      if ( !response.ok ) { return null; }
      server = await response.json();
    } else {
      const direct = await getDirectPackageByTrackingId( normalizedTrackingId );
      if ( !direct ) { return null; }
      server = {
        ...direct,
        id: direct.id,
        tracking_code: direct.tracking_number,
        from: direct.origin_name ?? direct.origin_location,
        to: direct.destination_name ?? direct.destination_location,
        weight: direct.weight_kg,
        description: direct.description,
        recipient_name: direct.receiver_name,
        recipient_phone: direct.receiver_phone,
      };
    }

    if ( !server ) { return null; }

    const fallback: PackageRequest = {
      id: String( server.id ?? makeId( 'pkg' ) ),
      trackingId: normalizedTrackingId,
      handoffCode: generateHandoffCode(),
      from: String( server.from ?? '' ),
      to: String( server.to ?? '' ),
      weight: sanitizeWeight( String( server.weight ?? '<1 kg' ) ),
      note: String( server.description ?? '' ),
      packageType: 'delivery',
      recipientName: String( server.recipient_name ?? '' ).trim() || undefined,
      recipientPhone: sanitizePhone( String( server.recipient_phone ?? '' ) ),
      matchedRideId: String( server.trip_id ?? '' ).trim() || undefined,
      matchedDriver: String( server.driver_name ?? '' ).trim() || undefined,
      status: normalizeStatus( server.status, String( server.trip_id ?? '' ).trim() || undefined ),
      createdAt: String( server.created_at ?? new Date().toISOString() ),
      verification: {},
      timeline: buildTimeline(
        normalizeStatus( server.status, String( server.trip_id ?? '' ).trim() || undefined ),
        String( server.trip_id ?? '' ).trim() || undefined,
        {},
      ),
    };
    const normalizedPkg = normalizeServerPackage( server as Record<string, unknown>, fallback );
    savePackages( [ normalizedPkg ], getConnectedPackages() );
    return normalizedPkg;
  } catch {
    return null;
  }
}

export function getConnectedStats () {
  const rides = getConnectedRides();
  const packages = getConnectedPackages();
  const packageEnabledRides = rides.filter( ride => ride.acceptsPackages ).length;

  return {
    ridesPosted: rides.length,
    packagesCreated: packages.length,
    packageEnabledRides,
    matchedPackages: packages.filter( pkg => Boolean( pkg.matchedRideId ) ).length,
  };
}

export type PackageVerificationAction = 'share_code' | 'confirm_pickup' | 'confirm_delivery';

export function updatePackageVerification (
  trackingId: string,
  action: PackageVerificationAction,
): PackageRequest | null {
  const normalizedTrackingId = trackingId.trim().toUpperCase();
  if ( !normalizedTrackingId ) { return null; }

  const packages = getConnectedPackages();
  const target = packages.find( item => item.trackingId === normalizedTrackingId );
  if ( !target ) { return null; }

  const now = new Date().toISOString();
  const verification: PackageVerification = { ...target.verification };
  let status = target.status;

  if ( action === 'share_code' ) {
    verification.senderCodeSharedAt = verification.senderCodeSharedAt ?? now;
    if ( status === 'searching' && target.matchedRideId ) { status = 'matched'; }
  }

  if ( action === 'confirm_pickup' ) {
    verification.senderCodeSharedAt = verification.senderCodeSharedAt ?? now;
    verification.riderPickupConfirmedAt = verification.riderPickupConfirmedAt ?? now;
    status = 'in_transit';
  }

  if ( action === 'confirm_delivery' ) {
    verification.senderCodeSharedAt = verification.senderCodeSharedAt ?? now;
    verification.riderPickupConfirmedAt = verification.riderPickupConfirmedAt ?? now;
    verification.receiverDeliveryConfirmedAt = verification.receiverDeliveryConfirmedAt ?? now;
    status = 'delivered';
  }

  const updated: PackageRequest = {
    ...target,
    status,
    verification,
    timeline: buildTimeline( status, target.matchedRideId, verification ),
  };

  savePackages( packages.map( item => ( item.trackingId === normalizedTrackingId ? updated : item ) ) );

  void updateDirectPackageStatus(
    normalizedTrackingId,
    status === 'searching' ? 'matched' : status,
  ).catch( () => { } );

  void trackGrowthEvent( {
    eventName: 'package_verification_updated',
    funnelStage:
      status === 'delivered' ? 'completed' : status === 'in_transit' ? 'booked' : 'selected',
    serviceType: 'package',
    from: updated.from,
    to: updated.to,
    metadata: {
      trackingId: updated.trackingId,
      action,
      status,
    },
  } );

  return updated;
}

import { supabase } from '../utils/supabase/client';

type LatLng = {
  lat: number;
  lng: number;
};

type LiveTripStatus =
  'en_route_to_pickup' | 'driver_arrived' | 'en_route' | 'arriving' | 'completed';

export interface LiveTripSnapshot {
  bookingId: string;
  tripId: string;
  status: LiveTripStatus;
  from: string;
  fromAr?: string;
  fromCoord: LatLng;
  to: string;
  toAr?: string;
  toCoord: LatLng;
  driver: {
    id: string;
    name: string;
    nameAr?: string;
    rating: number;
    trips: number;
    img: string;
    phone: string;
    initials: string;
  };
  vehicle: {
    model: string;
    color: string;
    plate: string;
    year: number;
  };
  price: number;
  startedAt: string;
  estimatedArrival: string;
  totalDistanceKm: number;
  passengers: number;
  shareCode: string;
  progress: number;
  timeLeftMinutes: number;
  driverPosition: LatLng;
  waypoints: Array<{
    label: string;
    coord: LatLng;
  }>;
  heartbeatAt: string | null;
  telemetryFresh: boolean;
}

const CITY_COORDS: Record<string, LatLng> = {
  amman: { lat: 31.9539, lng: 35.9106 },
  aqaba: { lat: 29.5321, lng: 35.006 },
  irbid: { lat: 32.5568, lng: 35.8479 },
  zarqa: { lat: 32.0728, lng: 36.088 },
  jerash: { lat: 32.2744, lng: 35.8961 },
  mafraq: { lat: 32.3429, lng: 36.208 },
  madaba: { lat: 31.7196, lng: 35.7939 },
  karak: { lat: 31.1854, lng: 35.7048 },
  salt: { lat: 32.0392, lng: 35.7272 },
  ajloun: { lat: 32.3326, lng: 35.7519 },
  tafila: { lat: 30.8375, lng: 35.6042 },
  maan: { lat: 30.1962, lng: 35.736 },
};

type CanonicalUserRow = {
  id: string;
};

type BookingRow = {
  booking_id?: string;
  id?: string;
  trip_id: string;
  seats_requested?: number | null;
  total_price?: number | null;
  amount?: number | null;
  created_at?: string | null;
  booking_status?: string | null;
  status?: string | null;
};

type TripRow = {
  trip_id?: string | null;
  driver_id?: string | null;
  origin_name?: string | null;
  origin_location?: string | null;
  destination_name?: string | null;
  destination_location?: string | null;
  origin_city?: string | null;
  destination_city?: string | null;
  departure_time?: string | null;
  price_per_seat?: number | null;
  trip_status?: string | null;
};

type DriverRow = {
  driver_id: string;
  user_id: string;
};

type UserRow = {
  id: string;
  full_name?: string | null;
  phone_number?: string | null;
  avatar_url?: string | null;
};

type VehicleRow = {
  vehicle_make?: string | null;
  vehicle_model?: string | null;
  plate_number?: string | null;
};

type PresenceRow = {
  trip_id: string;
  active_passengers?: number | null;
  last_location?: {
    lat?: number;
    lng?: number;
    lon?: number;
  } | null;
  last_heartbeat_at?: string | null;
};

function normalizeCity(value: string | null | undefined): string {
  return String(value ?? '')
    .trim()
    .toLowerCase()
    .replace(/[’']/g, '')
    .replace(/\s+/g, ' ');
}

function coordFromCity(city: string | null | undefined): LatLng {
  return CITY_COORDS[normalizeCity(city)] ?? CITY_COORDS.amman ?? { lat: 31.9539, lng: 35.9106 };
}

function parseCoordValue(value: unknown): number | null {
  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function parseLocation(value: string | null | undefined): LatLng | null {
  const text = String(value ?? '').trim();
  if (!text) {return null;}

  const jsonMatch = text.startsWith('{') ? text : '';
  if (jsonMatch) {
    try {
      const parsed = JSON.parse(jsonMatch) as { lat?: unknown; lng?: unknown; lon?: unknown };
      const lat = parseCoordValue(parsed.lat);
      const lng = parseCoordValue(parsed.lng ?? parsed.lon);
      if (lat !== null && lng !== null) {
        return { lat, lng };
      }
    } catch {
      // Fall through to raw pair parsing.
    }
  }

  const pair = text.match(/(-?\d+(?:\.\d+)?)\s*,\s*(-?\d+(?:\.\d+)?)/);
  if (!pair) {return null;}

  const lat = Number(pair[1]);
  const lng = Number(pair[2]);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) {return null;}
  return { lat, lng };
}

function buildInitials(name: string): string {
  const parts = name.trim().split(/\s+/).filter(Boolean).slice(0, 2);
  if (parts.length === 0) {return 'WD';}
  return parts.map(part => part[0]?.toUpperCase() ?? '').join('');
}

function haversineKm(a: LatLng, b: LatLng): number {
  const toRad = (value: number) => (value * Math.PI) / 180;
  const earthKm = 6371;
  const dLat = toRad(b.lat - a.lat);
  const dLng = toRad(b.lng - a.lng);
  const lat1 = toRad(a.lat);
  const lat2 = toRad(b.lat);
  const h =
    Math.sin(dLat / 2) * Math.sin(dLat / 2) +
    Math.sin(dLng / 2) * Math.sin(dLng / 2) * Math.cos(lat1) * Math.cos(lat2);
  return 2 * earthKm * Math.asin(Math.sqrt(h));
}

function interpolate(a: LatLng, b: LatLng, ratio: number): LatLng {
  return {
    lat: a.lat + (b.lat - a.lat) * ratio,
    lng: a.lng + (b.lng - a.lng) * ratio,
  };
}

function formatClockEta(minutesFromNow: number): string {
  const date = new Date(Date.now() + minutesFromNow * 60 * 1000);
  return date.toLocaleTimeString('en-US', {
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  });
}

function isFreshHeartbeat(value: string | null | undefined): boolean {
  if (!value) {return false;}
  const heartbeatAt = new Date(value).getTime();
  if (Number.isNaN(heartbeatAt)) {return false;}
  return Date.now() - heartbeatAt <= 5 * 60 * 1000;
}

function mapTripStatus(tripStatus: string | null | undefined, progress: number): LiveTripStatus {
  if (tripStatus === 'completed' || progress >= 99.5) {return 'completed';}
  if (tripStatus === 'in_progress' && progress >= 85) {return 'arriving';}
  if (tripStatus === 'in_progress') {return 'en_route';}
  if (progress >= 12) {return 'driver_arrived';}
  return 'en_route_to_pickup';
}

async function resolveCanonicalUserId(authUserId: string): Promise<string | null> {
  if (!supabase) {return null;}

  const { data, error } = await supabase
    .from('users')
    .select('id')
    .eq('auth_user_id', authUserId)
    .maybeSingle();

  if (error) {throw error;}
  return (data as CanonicalUserRow | null)?.id ?? null;
}

async function fetchLatestActiveBooking(canonicalUserId: string): Promise<BookingRow | null> {
  if (!supabase) {return null;}

  const { data, error } = await supabase
    .from('bookings')
    .select(
      'booking_id, id, trip_id, seats_requested, total_price, amount, created_at, booking_status, status',
    )
    .eq('passenger_id', canonicalUserId)
    .in('booking_status', ['confirmed', 'checked_in', 'completed'])
    .order('updated_at', { ascending: false })
    .order('created_at', { ascending: false })
    .limit(1)
    .maybeSingle();

  if (error) {throw error;}
  return (data as BookingRow | null) ?? null;
}

function derivePrice(booking: BookingRow, trip: TripRow): number {
  const bookingAmount = Number(booking.total_price ?? booking.amount ?? 0);
  if (Number.isFinite(bookingAmount) && bookingAmount > 0) {return bookingAmount;}
  const seats = Number(booking.seats_requested ?? 1) || 1;
  const perSeat = Number(trip.price_per_seat ?? 0);
  return Number.isFinite(perSeat) ? Number((perSeat * seats).toFixed(2)) : 0;
}

async function fetchLiveTripSnapshot(authUserId: string): Promise<LiveTripSnapshot | null> {
  if (!supabase || !authUserId) {return null;}

  const canonicalUserId = await resolveCanonicalUserId(authUserId);
  if (!canonicalUserId) {return null;}

  const booking = await fetchLatestActiveBooking(canonicalUserId);
  if (!booking?.trip_id) {return null;}

  const [{ data: tripData, error: tripError }, { data: presenceData }] = await Promise.all([
    supabase
      .from('trips')
      .select(
        'trip_id, driver_id, origin_name, origin_location, destination_name, destination_location, origin_city, destination_city, departure_time, price_per_seat, trip_status',
      )
      .eq('trip_id', booking.trip_id)
      .maybeSingle(),
    supabase
      .from('trip_presence')
      .select('trip_id, active_passengers, last_location, last_heartbeat_at')
      .eq('trip_id', booking.trip_id)
      .order('updated_at', { ascending: false })
      .limit(1)
      .maybeSingle(),
  ]);

  if (tripError) {throw tripError;}
  const trip = (tripData as TripRow | null) ?? null;
  if (!trip?.trip_id || !trip.driver_id) {return null;}

  const [{ data: driverData }, { data: vehicleData }] = await Promise.all([
    supabase
      .from('drivers')
      .select('driver_id, user_id')
      .eq('driver_id', trip.driver_id)
      .maybeSingle(),
    supabase
      .from('vehicles')
      .select('vehicle_make, vehicle_model, plate_number')
      .eq('driver_id', trip.driver_id)
      .limit(1)
      .maybeSingle(),
  ]);

  const driver = (driverData as DriverRow | null) ?? null;
  const vehicle = (vehicleData as VehicleRow | null) ?? null;
  if (!driver?.user_id) {return null;}

  const [{ data: driverUserData }, { count: tripCount }] = await Promise.all([
    supabase
      .from('users')
      .select('id, full_name, phone_number, avatar_url')
      .eq('id', driver.user_id)
      .maybeSingle(),
    supabase
      .from('trips')
      .select('trip_id', { count: 'exact', head: true })
      .eq('driver_id', trip.driver_id),
  ]);

  const driverUser = (driverUserData as UserRow | null) ?? null;
  const presence = (presenceData as PresenceRow | null) ?? null;

  const fromLabel = trip.origin_name || trip.origin_city || 'Pickup';
  const toLabel = trip.destination_name || trip.destination_city || 'Dropoff';
  const fromCoord = parseLocation(trip.origin_location) ?? coordFromCity(trip.origin_city);
  const toCoord = parseLocation(trip.destination_location) ?? coordFromCity(trip.destination_city);
  const fallbackDriverPosition = interpolate(fromCoord, toCoord, 0.18);
  const lastLocation =
    presence?.last_location && typeof presence.last_location === 'object'
      ? {
          lat: parseCoordValue(presence.last_location.lat) ?? fallbackDriverPosition.lat,
          lng:
            parseCoordValue(presence.last_location.lng ?? presence.last_location.lon) ??
            fallbackDriverPosition.lng,
        }
      : fallbackDriverPosition;

  const totalDistanceKm = Math.max(haversineKm(fromCoord, toCoord), 0.8);
  const travelledKm = Math.min(haversineKm(fromCoord, lastLocation), totalDistanceKm);
  const progress = Math.max(3, Math.min(100, (travelledKm / totalDistanceKm) * 100));
  const remainingKm = Math.max(totalDistanceKm - travelledKm, 0);
  const timeLeftMinutes = Math.max(1, Math.round((remainingKm / 48) * 60));
  const status = mapTripStatus(trip.trip_status, progress);
  const startedAtSource = trip.departure_time ?? booking.created_at ?? new Date().toISOString();
  const startedAtDate = new Date(startedAtSource);
  const startedAt = Number.isNaN(startedAtDate.getTime())
    ? startedAtSource
    : startedAtDate.toLocaleTimeString('en-US', {
        hour: 'numeric',
        minute: '2-digit',
        hour12: true,
      });

  return {
    bookingId: String(booking.booking_id ?? booking.id ?? ''),
    tripId: String(trip.trip_id),
    status,
    from: fromLabel,
    to: toLabel,
    fromCoord,
    toCoord,
    driver: {
      id: trip.driver_id,
      name: driverUser?.full_name?.trim() || 'Wasel Captain',
      rating: 4.9,
      trips: Number(tripCount ?? 0) || 0,
      img: driverUser?.avatar_url?.trim() || `https://i.pravatar.cc/150?u=${trip.driver_id}`,
      phone: driverUser?.phone_number?.trim() || '',
      initials: buildInitials(driverUser?.full_name?.trim() || 'Wasel Driver'),
    },
    vehicle: {
      model:
        [vehicle?.vehicle_make, vehicle?.vehicle_model].filter(Boolean).join(' ') ||
        'Wasel Vehicle',
      color: 'White',
      plate: vehicle?.plate_number?.trim() || 'WASEL',
      year: new Date().getFullYear(),
    },
    price: derivePrice(booking, trip),
    startedAt,
    estimatedArrival: formatClockEta(timeLeftMinutes),
    totalDistanceKm: Number(totalDistanceKm.toFixed(1)),
    passengers: Math.max(
      1,
      Number(presence?.active_passengers ?? booking.seats_requested ?? 1) || 1,
    ),
    shareCode: String(trip.trip_id).slice(-8).toUpperCase(),
    progress,
    timeLeftMinutes,
    driverPosition: lastLocation,
    waypoints: [
      { label: fromLabel, coord: fromCoord },
      { label: 'On route', coord: interpolate(fromCoord, toCoord, 0.33) },
      { label: 'Approaching', coord: interpolate(fromCoord, toCoord, 0.72) },
      { label: toLabel, coord: toCoord },
    ],
    heartbeatAt: presence?.last_heartbeat_at ?? null,
    telemetryFresh: isFreshHeartbeat(presence?.last_heartbeat_at),
  };
}

export function subscribeToLiveTripPresence(
  authUserId: string,
  onSnapshot: (snapshot: LiveTripSnapshot | null) => void,
): () => void {
  if (!supabase || !authUserId) {
    onSnapshot(null);
    return () => {};
  }

  let active = true;
  let refreshing: Promise<void> | null = null;
  let queued = false;

  const refresh = () => {
    if (!active) {return;}
    if (refreshing) {
      queued = true;
      return;
    }

    refreshing = fetchLiveTripSnapshot(authUserId)
      .then(snapshot => {
        if (active) {
          onSnapshot(snapshot);
        }
      })
      .catch(() => {
        if (active) {
          onSnapshot(null);
        }
      })
      .finally(() => {
        refreshing = null;
        if (queued) {
          queued = false;
          refresh();
        }
      });
  };

  refresh();

  const channel = supabase
    .channel(`live-trip-presence-${authUserId}`)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'bookings' }, refresh)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'trips' }, refresh)
    .on('postgres_changes', { event: '*', schema: 'public', table: 'trip_presence' }, refresh)
    .subscribe();

  return () => {
    active = false;
    if (!supabase) {throw new Error('Supabase not configured');}
    void supabase.removeChannel(channel);
  };
}

import { API_URL, fetchWithRetry, getAuthDetails } from './core';
import {
  buildDeliveryPlan,
  getCommunicationCapabilities,
  getCommunicationPreferences,
  queueCommunicationDeliveries,
  type CommunicationChannel,
  type DeliveryQueueRequest,
} from './communicationPreferences';
import {
  createDirectNotification,
  getDirectNotifications,
  markDirectNotificationAsRead,
} from './directSupabase';
import { dispatchNotification } from '../platform/async-runtime';

const LOCAL_NOTIFICATION_KEY = 'wasel-local-notifications';

// In-memory cache for notifications to reduce database I/O
type NotificationCacheEntry = {
  data: StoredNotification[];
  timestamp: number;
};
const notificationCache = new Map<string, NotificationCacheEntry>();
const NOTIFICATION_CACHE_TTL = 5 * 60 * 1000; // 5 minutes

type StoredNotification = {
  id: string;
  title: string;
  message: string;
  type: string;
  priority?: 'low' | 'medium' | 'high' | 'urgent';
  action_url?: string;
  user_id: string;
  is_read?: boolean;
  read?: boolean;
  created_at: string;
  source?: 'local' | 'server';
};

type NotificationCreateInput = {
  title: string;
  message: string;
  type: string;
  priority?: 'low' | 'medium' | 'high' | 'urgent';
  action_url?: string;
  channels?: CommunicationChannel[];
  contact?: {
    email?: string | null;
    phone?: string | null;
  };
};

type NotificationCreateResult = {
  success: boolean;
  source: 'local' | 'server';
  deliveriesQueued?: number;
  deliverySource?: 'none' | 'local' | 'server';
  channels?: CommunicationChannel[];
};

function canUseEdgeApi(): boolean {
  return Boolean(API_URL);
}

function readLocalNotifications(): StoredNotification[] {
  if (typeof window === 'undefined') {return [];}

  try {
    const raw = window.localStorage.getItem(LOCAL_NOTIFICATION_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function writeLocalNotifications(items: StoredNotification[]): void {
  if (typeof window === 'undefined') {return;}
  window.localStorage.setItem(LOCAL_NOTIFICATION_KEY, JSON.stringify(items.slice(0, 100)));
}

function normalizeNotification(item: StoredNotification): StoredNotification {
  return {
    ...item,
    read: typeof item.read === 'boolean' ? item.read : Boolean(item.is_read),
    is_read: typeof item.is_read === 'boolean' ? item.is_read : Boolean(item.read),
    priority: item.priority ?? 'medium',
  };
}

function sortNotifications(items: StoredNotification[]): StoredNotification[] {
  return [...items].sort(
    (a, b) => new Date(b.created_at).getTime() - new Date(a.created_at).getTime(),
  );
}

function mergeNotifications(
  localNotifications: StoredNotification[],
  serverNotifications: StoredNotification[],
): StoredNotification[] {
  const merged = new Map<string, StoredNotification>();

  for (const item of [...serverNotifications, ...localNotifications]) {
    const normalized = normalizeNotification(item);
    const existing = merged.get(normalized.id);

    if (!existing) {
      merged.set(normalized.id, normalized);
      continue;
    }

    merged.set(normalized.id, {
      ...existing,
      ...normalized,
      read: existing.read || normalized.read,
      is_read: existing.is_read || normalized.is_read,
    });
  }

  return sortNotifications(Array.from(merged.values()));
}

function markLocalNotificationAsRead(notificationId: string): void {
  const localNotifications = readLocalNotifications();
  writeLocalNotifications(
    localNotifications.map(item =>
      item.id === notificationId ? { ...item, is_read: true, read: true } : item,
    ),
  );
}

async function queueSecondaryDeliveries(args: {
  userId?: string | null;
  notificationId?: string;
  type: string;
  title: string;
  message: string;
  explicitChannels?: CommunicationChannel[];
  contact?: {
    email?: string | null;
    phone?: string | null;
  };
}): Promise<Pick<NotificationCreateResult, 'deliveriesQueued' | 'deliverySource' | 'channels'>> {
  const preferences = await getCommunicationPreferences(args.userId);
  const capabilities = getCommunicationCapabilities(args.contact);
  const channels = buildDeliveryPlan({
    type: args.type,
    preferences,
    capabilities,
    explicitChannels: args.explicitChannels,
  }).filter(
    (channel): channel is DeliveryQueueRequest['channel'] =>
      channel !== 'in_app' && channel !== 'push',
  );

  if (channels.length === 0) {
    return { deliveriesQueued: 0, deliverySource: 'none', channels: [] };
  }

  const requests: DeliveryQueueRequest[] = [];

  for (const channel of channels) {
    if (channel === 'email' && args.contact?.email) {
      requests.push({
        channel,
        destination: args.contact.email,
        subject: args.title,
        body: args.message,
        notificationId: args.notificationId,
        metadata: { type: args.type },
      });
      continue;
    }

    if ((channel === 'sms' || channel === 'whatsapp') && args.contact?.phone) {
      requests.push({
        channel,
        destination: args.contact.phone,
        subject: args.title,
        body: args.message,
        notificationId: args.notificationId,
        metadata: { type: args.type },
      });
    }
  }

  if (requests.length === 0) {
    return { deliveriesQueued: 0, deliverySource: 'none', channels: [] };
  }

  const result = await queueCommunicationDeliveries({
    userId: args.userId,
    notificationId: args.notificationId,
    requests,
  });

  return {
    deliveriesQueued: result.queued,
    deliverySource: result.source,
    channels,
  };
}

function dispatchAsyncNotification(data: NotificationCreateInput, userId?: string | null) {
  const targetUserId = userId ?? data.contact?.email;
  if (!targetUserId) {return;}
  try {
    dispatchNotification({
      userId: targetUserId,
      title: data.title,
      message: data.message,
      type: data.type,
      priority: data.priority,
      actionUrl: data.action_url,
    });
  } catch {
    // Non-fatal: notification-worker may not be running in this session.
  }
}

export const notificationsAPI = {
  async getNotifications() {
    const localNotifications = readLocalNotifications();
    let token: string | null = null;
    let userId: string | null = null;

    try {
      const auth = await getAuthDetails();
      token = auth.token;
      userId = auth.userId;
    } catch {
      return { notifications: sortNotifications(localNotifications.map(normalizeNotification)) };
    }

    if (!token || !userId) {
      return { notifications: sortNotifications(localNotifications.map(normalizeNotification)) };
    }

    // Check cache for server notifications
    const cachedEntry = notificationCache.get(userId);
    const now = Date.now();
    if (cachedEntry && now - cachedEntry.timestamp < NOTIFICATION_CACHE_TTL) {
      return {
        notifications: mergeNotifications(localNotifications, cachedEntry.data),
      };
    }

    if (!canUseEdgeApi()) {
      try {
        const serverNotifications = await getDirectNotifications(userId);
        notificationCache.set(userId, {
          data: serverNotifications as StoredNotification[],
          timestamp: Date.now(),
        });
        return {
          notifications: mergeNotifications(
            localNotifications,
            serverNotifications as StoredNotification[],
          ),
        };
      } catch {
        return { notifications: sortNotifications(localNotifications.map(normalizeNotification)) };
      }
    }

    try {
      const response = await fetchWithRetry(`${API_URL}/notifications`, {
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!response.ok) {
        throw new Error('Failed to fetch notifications');
      }

      const data = await response.json();
      const serverNotifications = Array.isArray(data?.notifications) ? data.notifications : [];
      notificationCache.set(userId, { data: serverNotifications, timestamp: Date.now() });
      return {
        notifications: mergeNotifications(localNotifications, serverNotifications),
      };
    } catch {
      try {
        const serverNotifications = await getDirectNotifications(userId);
        return {
          notifications: mergeNotifications(
            localNotifications,
            serverNotifications as StoredNotification[],
          ),
        };
      } catch {
        return { notifications: sortNotifications(localNotifications.map(normalizeNotification)) };
      }
    }
  },

  async markAsRead(notificationId: string) {
    markLocalNotificationAsRead(notificationId);

    let token: string | null = null;
    let userId: string | null = null;
    try {
      const auth = await getAuthDetails();
      token = auth.token;
      userId = auth.userId;
    } catch {
      return { success: true, source: 'local' };
    }

    if (!token || !userId) {return { success: true, source: 'local' };}

    if (!canUseEdgeApi()) {
      try {
        await markDirectNotificationAsRead(notificationId, userId);
        return { success: true, source: 'server' };
      } catch {
        return { success: false, source: 'server' };
      }
    }

    try {
      const response = await fetchWithRetry(`${API_URL}/notifications/${notificationId}/read`, {
        method: 'PATCH',
        headers: { Authorization: `Bearer ${token}` },
      });

      if (!response.ok) {return { success: false, source: 'server' };}
      return await response.json();
    } catch {
      try {
        await markDirectNotificationAsRead(notificationId, userId);
        return { success: true, source: 'server' };
      } catch {
        return { success: false, source: 'server' };
      }
    }
  },

  async createNotification(data: NotificationCreateInput): Promise<NotificationCreateResult> {
    const localNotifications = readLocalNotifications();
    let token: string | null = null;
    let userId: string | null = null;

    try {
      const auth = await getAuthDetails();
      token = auth.token;
      userId = auth.userId;
    } catch {
      writeLocalNotifications(
        sortNotifications([
          {
            id: `local-${Date.now()}`,
            title: data.title,
            message: data.message,
            type: data.type,
            priority: data.priority ?? 'medium',
            action_url: data.action_url,
            user_id: 'local',
            is_read: false,
            read: false,
            created_at: new Date().toISOString(),
            source: 'local',
          },
          ...localNotifications,
        ]),
      );
      dispatchAsyncNotification(data, userId);
      return {
        success: true,
        source: 'local',
        deliveriesQueued: 0,
        deliverySource: 'none',
        channels: ['in_app'],
      };
    }

    const localDraft: StoredNotification = {
      id: `local-${Date.now()}`,
      title: data.title,
      message: data.message,
      type: data.type,
      priority: data.priority ?? 'medium',
      action_url: data.action_url,
      user_id: userId ?? 'local',
      is_read: false,
      read: false,
      created_at: new Date().toISOString(),
      source: 'local',
    };

    if (!token || !userId) {
      writeLocalNotifications(sortNotifications([localDraft, ...localNotifications]));
      const deliveryResult = await queueSecondaryDeliveries({
        type: data.type,
        title: data.title,
        message: data.message,
        explicitChannels: data.channels,
        contact: data.contact,
      });
      dispatchAsyncNotification(data, userId);
      return { success: true, source: 'local', ...deliveryResult };
    }

    if (!canUseEdgeApi()) {
      try {
        const created = await createDirectNotification({
          userId,
          title: data.title,
          message: data.message,
          type: data.type,
          priority: data.priority,
          action_url: data.action_url,
        });

        const notificationId = String(created?.id ?? localDraft.id);
        writeLocalNotifications(
          sortNotifications([
            {
              ...localDraft,
              id: notificationId,
              source: 'server',
            },
            ...localNotifications,
          ]),
        );

        const deliveryResult = await queueSecondaryDeliveries({
          userId,
          notificationId,
          type: data.type,
          title: data.title,
          message: data.message,
          explicitChannels: data.channels,
          contact: data.contact,
        });
        dispatchAsyncNotification(data, userId);
        return { success: true, source: 'server', ...deliveryResult };
      } catch {
        writeLocalNotifications(sortNotifications([localDraft, ...localNotifications]));
        const deliveryResult = await queueSecondaryDeliveries({
          userId,
          notificationId: localDraft.id,
          type: data.type,
          title: data.title,
          message: data.message,
          explicitChannels: data.channels,
          contact: data.contact,
        });
        dispatchAsyncNotification(data, userId);
        return { success: false, source: 'local', ...deliveryResult };
      }
    }

    try {
      const response = await fetchWithRetry(`${API_URL}/notifications/send-push`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify({ userId, ...data, body: data.message }),
      });

      if (!response.ok) {
        writeLocalNotifications(sortNotifications([localDraft, ...localNotifications]));
        const deliveryResult = await queueSecondaryDeliveries({
          userId,
          notificationId: localDraft.id,
          type: data.type,
          title: data.title,
          message: data.message,
          explicitChannels: data.channels,
          contact: data.contact,
        });
        dispatchAsyncNotification(data, userId);
        return { success: false, source: 'local', ...deliveryResult };
      }

      const server = await response.json().catch(() => ({}));
      const notificationId = String(server?.notification?.id ?? localDraft.id);
      writeLocalNotifications(
        sortNotifications([
          {
            ...localDraft,
            id: notificationId,
            source: 'server',
          },
          ...localNotifications,
        ]),
      );

      const deliveryResult = await queueSecondaryDeliveries({
        userId,
        notificationId,
        type: data.type,
        title: data.title,
        message: data.message,
        explicitChannels: data.channels,
        contact: data.contact,
      });
      dispatchAsyncNotification(data, userId);
      return { success: true, source: 'server', ...deliveryResult };
    } catch {
      try {
        const created = await createDirectNotification({
          userId,
          title: data.title,
          message: data.message,
          type: data.type,
          priority: data.priority,
          action_url: data.action_url,
        });

        const notificationId = String(created?.id ?? localDraft.id);
        writeLocalNotifications(
          sortNotifications([
            {
              ...localDraft,
              id: notificationId,
              source: 'server',
            },
            ...localNotifications,
          ]),
        );

        const deliveryResult = await queueSecondaryDeliveries({
          userId,
          notificationId,
          type: data.type,
          title: data.title,
          message: data.message,
          explicitChannels: data.channels,
          contact: data.contact,
        });
        dispatchAsyncNotification(data, userId);
        return { success: true, source: 'server', ...deliveryResult };
      } catch {
        writeLocalNotifications(sortNotifications([localDraft, ...localNotifications]));
        const deliveryResult = await queueSecondaryDeliveries({
          userId,
          notificationId: localDraft.id,
          type: data.type,
          title: data.title,
          message: data.message,
          explicitChannels: data.channels,
          contact: data.contact,
        });
        dispatchAsyncNotification(data, userId);
        return { success: false, source: 'local', ...deliveryResult };
      }
    }
  },
};

/**
 * Ride Lifecycle Service — Supabase-first persistence
 *
 * Strategy (v2):
 *  1. All writes go to Supabase first. If Supabase is unavailable, we throw
 *     so the UI can surface a real error rather than silently creating
 *     phantom bookings that live only in the browser.
 *  2. localStorage acts as a read-through cache for instant UI hydration.
 *     It is populated AFTER a successful Supabase write, never before.
 *  3. `hydrateRideBookings` remains the authoritative sync path — it pulls
 *     from Supabase and overwrites the local cache on every app load.
 */

import {
  mapBookingStatusToRideLifecycleState,
  projectRideLifecycleState,
  type RideLifecycleState,
} from '../domain/rides/lifecycle';
import { createDomainEvent, domainEventBus } from '../platform/event-bus';
import type { PostedRide } from './journeyLogistics';
import {
  createDirectBooking,
  getDirectDriverBookings,
  getDirectUserBookings,
  updateDirectBookingStatus,
} from './directSupabase';
import { trackGrowthEvent } from './growthEngine';

// ── Types ─────────────────────────────────────────────────────────────────────

export type RideBookingStatus =
  'pending_driver' | 'confirmed' | 'rejected' | 'cancelled' | 'completed';

export type RidePaymentStatus = 'pending' | 'authorized' | 'captured' | 'refunded' | 'failed';

export interface RideBookingRecord {
  id: string;
  rideId: string;
  ownerId?: string;
  passengerId?: string;
  from: string;
  to: string;
  date: string;
  time: string;
  driverName: string;
  passengerName: string;
  seatsRequested: number;
  status: RideBookingStatus;
  lifecycleStatus: RideLifecycleState;
  paymentStatus: RidePaymentStatus;
  routeMode: 'live_post' | 'network_inventory';
  supportThreadOpen: boolean;
  ticketCode: string;
  createdAt: string;
  updatedAt: string;
  backendBookingId?: string;
  syncedAt?: string;
}

// ── Cache helpers (localStorage as L1 read-through, NOT primary store) ────────

const BOOKING_CACHE_KEY = 'wasel-ride-booking-cache-v2';
const CACHE_MAX = 100;

function readCache(): RideBookingRecord[] {
  if (typeof window === 'undefined') {return [];}
  try {
    const raw = window.localStorage.getItem(BOOKING_CACHE_KEY);
    const parsed = raw ? (JSON.parse(raw) as RideBookingRecord[]) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function writeCache(bookings: RideBookingRecord[]): void {
  if (typeof window === 'undefined') {return;}
  try {
    const sorted = [...bookings].sort(
      (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
    );
    window.localStorage.setItem(BOOKING_CACHE_KEY, JSON.stringify(sorted.slice(0, CACHE_MAX)));
  } catch {
    // Storage quota exceeded or private mode — silently skip cache write.
  }
}

function upsertCache(records: RideBookingRecord[]): void {
  const map = new Map(readCache().map(b => [b.id, b]));
  records.forEach(r => map.set(r.id, r));
  writeCache(Array.from(map.values()));
}

// ── Ticket code ───────────────────────────────────────────────────────────────

function makeTicketCode(): string {
  return crypto.randomUUID();
}

// ── Domain event publishing ───────────────────────────────────────────────────

function publishLifecycleEvent(booking: RideBookingRecord): void {
  switch (booking.lifecycleStatus) {
    case 'requested':
      domainEventBus.publish(
        createDomainEvent(
          'RideRequested',
          {
            bookingId: booking.id,
            rideId: booking.rideId,
            routeMode: booking.routeMode,
            origin: booking.from,
            destination: booking.to,
          },
          'rideLifecycle',
        ),
      );
      break;
    case 'matched':
      domainEventBus.publish(
        createDomainEvent(
          'DriverAssigned',
          { bookingId: booking.id, rideId: booking.rideId, driverName: booking.driverName },
          'rideLifecycle',
        ),
      );
      break;
    case 'accepted':
      domainEventBus.publish(
        createDomainEvent(
          'RideAccepted',
          { bookingId: booking.id, rideId: booking.rideId },
          'rideLifecycle',
        ),
      );
      break;
    case 'in_progress':
      domainEventBus.publish(
        createDomainEvent(
          'RideStarted',
          { bookingId: booking.id, rideId: booking.rideId },
          'rideLifecycle',
        ),
      );
      break;
    case 'completed':
      domainEventBus.publish(
        createDomainEvent(
          'RideCompleted',
          { bookingId: booking.id, rideId: booking.rideId },
          'rideLifecycle',
        ),
      );
      break;
    case 'cancelled':
      domainEventBus.publish(
        createDomainEvent(
          'RideCancelled',
          { bookingId: booking.id, rideId: booking.rideId },
          'rideLifecycle',
        ),
      );
      break;
    default:
      break;
  }
}

function resolveLifecycleStatus(
  current: RideLifecycleState,
  nextStatus: RideBookingStatus,
): RideLifecycleState {
  return projectRideLifecycleState(current, mapBookingStatusToRideLifecycleState(nextStatus));
}

function resolveRemoteStatus(
  persistedStatus: string | null | undefined,
  persistedId: string,
  routeMode: 'live_post' | 'network_inventory',
): RideBookingStatus {
  if (
    persistedStatus === 'confirmed' ||
    persistedStatus === 'cancelled' ||
    persistedStatus === 'completed'
  ) {
    return persistedStatus;
  }
  if (persistedStatus === 'accepted') {return 'confirmed';}
  if (persistedId) {return routeMode === 'live_post' ? 'pending_driver' : 'confirmed';}
  return 'pending_driver';
}

function resolveBookingStatus(statusRaw: string): RideBookingStatus {
  if (
    statusRaw === 'completed' ||
    statusRaw === 'cancelled' ||
    statusRaw === 'rejected' ||
    statusRaw === 'confirmed'
  ) {
    return statusRaw;
  }
  if (statusRaw === 'accepted') {return 'confirmed';}
  return 'pending_driver';
}

function resolvePaymentStatus(statusRaw: string): RidePaymentStatus {
  if (statusRaw === 'completed') {return 'captured';}
  if (statusRaw === 'cancelled' || statusRaw === 'rejected') {return 'failed';}
  return 'authorized';
}

function resolveBookingDate(ride: PostedRide | undefined, raw: Record<string, unknown>): string {
  if (ride?.date) {return ride.date;}
  return new Date(String(raw.created_at ?? new Date().toISOString())).toISOString().slice(0, 10);
}

// ── Public API ────────────────────────────────────────────────────────────────

/** Returns cached bookings for instant UI render. Call hydrateRideBookings to refresh. */
export function getRideBookings(): RideBookingRecord[] {
  return [...readCache()].sort(
    (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
  );
}

/**
 * Create a booking.
 *
 * Primary path: write to Supabase, then populate the local cache.
 * Throws on Supabase failure — callers must handle the error and surface it
 * to the user rather than silently continuing with browser-only state.
 */
export async function createRideBooking(input: {
  rideId: string;
  ownerId?: string;
  passengerId?: string;
  from: string;
  to: string;
  date: string;
  time: string;
  driverName: string;
  passengerName: string;
  seatsRequested?: number;
  pricePerSeatJod?: number;
  routeMode: 'live_post' | 'network_inventory';
}): Promise<RideBookingRecord> {
  const now = new Date().toISOString();
  const seatsRequested = Math.max(1, input.seatsRequested ?? 1);

  if (!input.passengerId) {
    throw new Error('passengerId is required — unauthenticated bookings are not permitted.');
  }

  // ── 1. Write to Supabase (primary store) ──────────────────────────────────
  let persisted: { booking_id?: string; id?: string; status?: string | null } | null = null;
  try {
    const result = await createDirectBooking({
      tripId: input.rideId,
      userId: input.passengerId,
      seatsRequested,
      pickup: input.from,
      dropoff: input.to,
      bookingStatus: input.routeMode === 'live_post' ? 'pending_driver' : 'confirmed',
      metadata: {
        total_price: input.pricePerSeatJod ? seatsRequested * input.pricePerSeatJod : seatsRequested,
      },
    });
    persisted = result.booking;
  } catch (error) {
    throw new Error(
      `Booking could not be created: ${error instanceof Error ? error.message : String(error)}`,
    );
  }

  // ── 2. Build canonical record using the persisted ID (or local fallback) ───
  const persistedId = String(persisted?.booking_id ?? persisted?.id ?? '');
  const persistedStatus = persisted?.status;
  const remoteStatus: RideBookingStatus = resolveRemoteStatus(persistedStatus, persistedId, input.routeMode);

  const booking: RideBookingRecord = {
    id: persistedId || makeTicketCode(),
    rideId: input.rideId,
    ownerId: input.ownerId,
    passengerId: input.passengerId,
    from: input.from,
    to: input.to,
    date: input.date,
    time: input.time,
    driverName: input.driverName,
    passengerName: input.passengerName,
    seatsRequested,
    status: remoteStatus,
    lifecycleStatus: mapBookingStatusToRideLifecycleState(remoteStatus),
    paymentStatus: remoteStatus === 'confirmed' ? 'authorized' : 'pending',
    routeMode: input.routeMode,
    supportThreadOpen: false,
    ticketCode: makeTicketCode(),
    backendBookingId: persistedId || undefined,
    syncedAt: persistedId ? now : undefined,
    createdAt: now,
    updatedAt: now,
  };

  // ── 3. Populate cache AFTER successful write ──────────────────────────────
  upsertCache([booking]);
  publishLifecycleEvent(booking);

  void trackGrowthEvent({
    userId: input.passengerId,
    eventName: 'ride_booking_started',
    funnelStage: booking.status === 'pending_driver' ? 'selected' : 'booked',
    serviceType: 'ride',
    from: input.from,
    to: input.to,
    valueJod: input.pricePerSeatJod
      ? Number((seatsRequested * input.pricePerSeatJod).toFixed(2))
      : undefined,
    metadata: {
      rideId: input.rideId,
      routeMode: input.routeMode,
      seatsRequested: booking.seatsRequested,
      pricePerSeatJod: input.pricePerSeatJod,
      lifecycleStatus: booking.lifecycleStatus,
    },
  });

  return booking;
}

export function getBookingsForRide(rideId: string): RideBookingRecord[] {
  return getRideBookings().filter(b => b.rideId === rideId);
}

export function getBookingsForDriver(userId: string, rides: PostedRide[]): RideBookingRecord[] {
  const rideIds = new Set(rides.filter(r => r.ownerId === userId).map(r => r.id));
  return getRideBookings().filter(b => b.ownerId === userId || rideIds.has(b.rideId));
}

export function getBookingsForPassenger(passengerId: string): RideBookingRecord[] {
  return getRideBookings().filter(b => b.passengerId === passengerId);
}

/**
 * Update a booking status.
 * Writes to Supabase first, updates cache on success.
 */
export async function updateRideBooking(
  bookingId: string,
  updates: Partial<Pick<RideBookingRecord, 'status' | 'paymentStatus' | 'supportThreadOpen'>>,
): Promise<RideBookingRecord | null> {
  const cached = readCache();
  const target = cached.find(b => b.id === bookingId);
  if (!target) {return null;}

  const lifecycleStatus = updates.status
    ? resolveLifecycleStatus(target.lifecycleStatus, updates.status)
    : target.lifecycleStatus;

  // Sync to Supabase when we have a canonical backend ID and a status change.
  if (
    target.backendBookingId &&
    updates.status &&
    (updates.status === 'rejected' ||
      updates.status === 'cancelled' ||
      updates.status === 'confirmed')
  ) {
    const directStatus = updates.status === 'confirmed' ? 'accepted' : updates.status;
    await updateDirectBookingStatus(
      target.backendBookingId,
      directStatus as 'accepted' | 'rejected' | 'cancelled',
    );
  }

  const updated: RideBookingRecord = {
    ...target,
    ...updates,
    lifecycleStatus,
    syncedAt: new Date().toISOString(),
    updatedAt: new Date().toISOString(),
  };

  upsertCache([updated]);

  if (updates.status) {
    if (updates.status === 'confirmed' && target.lifecycleStatus === 'requested') {
      domainEventBus.publish(
        createDomainEvent(
          'DriverAssigned',
          { bookingId: updated.id, rideId: updated.rideId, driverName: updated.driverName },
          'rideLifecycle',
        ),
      );
    }
    publishLifecycleEvent(updated);

    void trackGrowthEvent({
      eventName: 'ride_booking_updated',
      funnelStage:
        updates.status === 'completed'
          ? 'completed'
          : updates.status === 'confirmed'
            ? 'booked'
            : updates.status,
      serviceType: 'ride',
      from: updated.from,
      to: updated.to,
      metadata: {
        bookingId,
        paymentStatus: updated.paymentStatus,
        lifecycleStatus: updated.lifecycleStatus,
      },
    });
  }

  return updated;
}

/**
 * Authoritative sync: pulls from Supabase and overwrites the local cache.
 * Should be called on app load and after auth state changes.
 */
async function resolvePassengerNames(passengerIds: string[]): Promise<Map<string, string>> {
  const nameMap = new Map<string, string>();
  try {
    const { supabase: db } = await import('../utils/supabase/client');
    if (db) {
      const { data: profiles } = await db
        .from('profiles')
        .select('id, full_name, email')
        .in('id', passengerIds);
      if (Array.isArray(profiles)) {
        for (const u of profiles as { id: string; full_name?: string; email?: string }[]) {
          nameMap.set(String(u.id), u.full_name?.trim() || u.email?.split('@')[0] || 'Passenger');
        }
      }
    }
  } catch {
    // Non-fatal — fall back to 'Passenger' for unresolved IDs.
  }
  return nameMap;
}

export async function hydrateRideBookings(
  userId: string,
  rides: PostedRide[] = [],
): Promise<RideBookingRecord[]> {
  const [passengerResult, driverResult] = await Promise.allSettled([
    getDirectUserBookings(userId),
    getDirectDriverBookings(userId),
  ]);

  const knownRides = new Map(rides.map(r => [r.id, r]));

  // Resolve passenger names in one batch query.
  const allRaw = [
    ...(passengerResult.status === 'fulfilled' ? passengerResult.value : []),
    ...(driverResult.status === 'fulfilled' ? driverResult.value : []),
  ] as Record<string, unknown>[];

  const passengerIds = Array.from(
    new Set(allRaw.map(r => String(r.passenger_id ?? r.user_id ?? '')).filter(Boolean)),
  );

  const nameMap = passengerIds.length > 0 ? await resolvePassengerNames(passengerIds) : new Map<string, string>();

  const normalize = (raw: Record<string, unknown>): RideBookingRecord => {
    const rideId = String(raw.trip_id ?? '');
    const ride = knownRides.get(rideId);
    const statusRaw = String(raw.status ?? raw.booking_status ?? 'pending');
    const status = resolveBookingStatus(statusRaw);
    const id = String(raw.booking_id ?? raw.id ?? '');
    return {
      id,
      backendBookingId: id,
      rideId,
      ownerId: ride?.ownerId,
      passengerId: String(raw.passenger_id ?? raw.user_id ?? ''),
      from: String(raw.pickup_location ?? ride?.from ?? ''),
      to: String(raw.dropoff_location ?? ride?.to ?? ''),
      date: resolveBookingDate(ride, raw),
      time: ride?.time ?? '08:00',
      driverName: ride ? ride.carModel || 'Wasel Captain' : 'Wasel Captain',
      passengerName: nameMap.get(String(raw.passenger_id ?? raw.user_id ?? '')) ?? 'Passenger',
      seatsRequested: Number(raw.seats_requested ?? 1) || 1,
      status,
      lifecycleStatus: mapBookingStatusToRideLifecycleState(status),
      paymentStatus: resolvePaymentStatus(statusRaw),
      routeMode: ride ? 'live_post' : 'network_inventory',
      supportThreadOpen: false,
      ticketCode: `RIDE-${id.slice(-6).toUpperCase() || 'SYNCED'}`,
      createdAt: String(raw.created_at ?? new Date().toISOString()),
      updatedAt: String(raw.updated_at ?? raw.created_at ?? new Date().toISOString()),
      syncedAt: new Date().toISOString(),
    };
  };

  const remote = allRaw
    .map(item => normalize(item as Record<string, unknown>))
    .filter(item => item.id);

  if (remote.length > 0) {
    upsertCache(remote);
  }

  return getRideBookings();
}

/**
 * Auto-complete confirmed bookings whose departure time has passed.
 * Only marks bookings as completed if the departure time is more than
 * 2 hours in the past (server-side grace window) to prevent clock manipulation.
 * The authoritative completion path is the ops worker via RideCompleted event.
 */
export function syncRideBookingCompletion(referenceDate = Date.now()): RideBookingRecord[] {
  const bookings = readCache();
  const toUpdate: RideBookingRecord[] = [];
  // Require at least 2 hours past departure before auto-completing client-side.
  const GRACE_MS = 2 * 60 * 60 * 1000;

  const next = bookings.map(booking => {
    if (booking.status !== 'confirmed') {return booking;}
    const tripTime = new Date(`${booking.date}T${booking.time || '00:00'}`).getTime();
    if (!Number.isFinite(tripTime) || tripTime + GRACE_MS > referenceDate) {return booking;}

    const updated: RideBookingRecord = {
      ...booking,
      status: 'completed',
      lifecycleStatus: 'completed',
      paymentStatus: booking.paymentStatus === 'authorized' ? 'captured' : booking.paymentStatus,
      updatedAt: new Date(referenceDate).toISOString(),
    };
    toUpdate.push(updated);
    return updated;
  });

  writeCache(next);

  toUpdate.forEach(b => {
    publishLifecycleEvent(b);
  });

  return [...next].sort(
    (a, b) => new Date(b.updatedAt).getTime() - new Date(a.updatedAt).getTime(),
  );
}

import { useEffect, useMemo, useState } from 'react';
import {
  getAllCorridorOpportunities,
  getCorridorOpportunity,
  type CorridorOpportunity,
} from '../config/wasel-movement-network';
import { getDemandAlerts } from './demandCapture';
import { getGrowthEventFeed } from './growthEngine';
import { getConnectedPackages, getConnectedRides } from './journeyLogistics';
import { getMovementMembershipSnapshot } from './movementMembership';
import { getMovementPriceQuote, type MovementPriceQuote } from './movementPricing';
import { getRideBookings } from './rideLifecycle';

const REFRESH_MS = 30_000;
const DAY_MS = 86_400_000;
const LOOKBACK_MS = 14 * DAY_MS;

export interface LiveCorridorSignal {
  id: string;
  from: string;
  to: string;
  label: string;
  liveDemandScore: number;
  forecastDemandScore: number;
  activeSupply: number;
  activeDemandAlerts: number;
  liveSearches: number;
  liveBookings: number;
  livePackages: number;
  seatUtilizationPercent: number;
  pricePressure: 'surging' | 'balanced' | 'value-window';
  nextWaveWindow: string;
  recommendedPickupPoint: string;
  routeOwnershipScore: number;
  recommendedReason: string;
  freshestSignalAt: string | null;
  productionSources: string[];
  priceQuote: MovementPriceQuote;
}

export interface RouteIntelligenceSnapshot {
  updatedAt: string;
  selectedSignal: LiveCorridorSignal | null;
  featuredSignals: LiveCorridorSignal[];
  allSignals: LiveCorridorSignal[];
  membership: ReturnType<typeof getMovementMembershipSnapshot>;
}

function clamp(value: number, min: number, max: number) {
  return Math.min(max, Math.max(min, value));
}

function roundMoney(value: number) {
  return Math.round(value * 10) / 10;
}

function normalizeCity(value: string) {
  return value.trim().toLowerCase();
}

function corridorMatches(corridor: CorridorOpportunity, from?: string | null, to?: string | null) {
  if (!from || !to) {return false;}
  const leftFrom = normalizeCity(from);
  const leftTo = normalizeCity(to);
  const rightFrom = normalizeCity(corridor.from);
  const rightTo = normalizeCity(corridor.to);
  return (
    (leftFrom === rightFrom && leftTo === rightTo) || (leftFrom === rightTo && leftTo === rightFrom)
  );
}

function recencyWeight(timestamp: string, now = Date.now()) {
  const createdAt = new Date(timestamp).getTime();
  if (!Number.isFinite(createdAt)) {return 0;}
  const ageMs = Math.max(0, now - createdAt);
  if (ageMs > LOOKBACK_MS) {return 0;}
  const ageDays = ageMs / DAY_MS;
  return Math.max(0.12, 1.15 - ageDays * 0.08);
}

function inferWaveWindow(hours: number[], density: CorridorOpportunity['density']) {
  if (hours.length === 0) {
    if (density === 'surging') {return '07:00 - 09:00 and 16:30 - 18:30';}
    if (density === 'high-frequency') {return '08:00 - 10:00 and 17:00 - 19:00';}
    return 'Next 60-90 minutes once demand clusters';
  }

  const averageHour = hours.reduce((sum, hour) => sum + hour, 0) / hours.length;
  if (averageHour < 11) {return '07:00 - 09:30';}
  if (averageHour < 15) {return '12:00 - 14:30';}
  if (averageHour < 20) {return '16:30 - 19:00';}
  return '20:00 - 22:00';
}

function summarizeProductionSources(args: {
  searches: number;
  bookings: number;
  packages: number;
  alerts: number;
  supply: number;
}) {
  return [
    `${args.searches} live searches`,
    `${args.bookings} live bookings`,
    `${args.packages} package moves`,
    `${args.alerts} active demand alerts`,
    `${args.supply} active route posts`,
  ];
}

function buildRecommendedReason(args: {
  alerts: number;
  supply: number;
  seatUtilizationPercent: number;
  forecastDemandScore: number;
}) {
  if (args.alerts > args.supply) {
    return 'Demand alerts are outrunning live supply, so Wasel should suggest this route before riders search again.';
  }
  if (args.seatUtilizationPercent >= 78) {
    return 'This corridor is already filling well, which makes it ideal for automatic grouping and recurring suggestions.';
  }
  if (args.forecastDemandScore >= 85) {
    return 'Real searches, bookings, and package flow are reinforcing this route enough to treat it like a priority lane.';
  }
  return 'The corridor is building repeat demand and should be nudged with reminders, credits, and suggested departures.';
}

function computeSignal(
  corridor: CorridorOpportunity,
  membership = getMovementMembershipSnapshot(),
): LiveCorridorSignal {
  const now = Date.now();
  const rides = getConnectedRides().filter(
    ride => corridorMatches(corridor, ride.from, ride.to) && ride.status !== 'cancelled',
  );
  const bookings = getRideBookings().filter(
    booking =>
      corridorMatches(corridor, booking.from, booking.to) &&
      booking.status !== 'rejected' &&
      booking.status !== 'cancelled',
  );
  const packages = getConnectedPackages().filter(item =>
    corridorMatches(corridor, item.from, item.to),
  );
  const alerts = getDemandAlerts().filter(
    alert => corridorMatches(corridor, alert.from, alert.to) && alert.status === 'active',
  );
  const events = getGrowthEventFeed().filter(event =>
    corridorMatches(corridor, event.from, event.to),
  );

  let weightedSearches = 0;
  let weightedBookings = 0;
  let weightedPackages = 0;
  const signalHours: number[] = [];
  let freshestSignalAt: string | null = null;

  for (const event of events) {
    const weight = recencyWeight(event.createdAt, now);
    if (weight <= 0) {continue;}
    const eventTime = new Date(event.createdAt);
    signalHours.push(eventTime.getHours());
    freshestSignalAt =
      !freshestSignalAt ||
      new Date(event.createdAt).getTime() > new Date(freshestSignalAt).getTime()
        ? event.createdAt
        : freshestSignalAt;

    if (event.serviceType === 'ride' && event.funnelStage === 'searched') {
      weightedSearches += weight;
    }
    if (
      event.serviceType === 'ride' &&
      (event.funnelStage === 'booked' || event.funnelStage === 'completed')
    ) {
      weightedBookings += weight;
    }
    if (event.serviceType === 'package') {
      weightedPackages += weight;
    }
  }

  const liveSearches = Math.round(weightedSearches);
  const liveBookings = Math.max(
    Math.round(weightedBookings),
    bookings.reduce((sum, booking) => sum + Math.max(1, booking.seatsRequested || 1), 0),
  );
  const livePackages = Math.max(
    Math.round(weightedPackages),
    packages.filter(item => item.status !== 'delivered').length,
  );
  const activeSupply = rides.length;
  const activeDemandAlerts = alerts.length;
  const totalSeats = rides.reduce((sum, ride) => sum + Math.max(1, ride.seats), 0);
  const bookedSeats = Math.max(
    0,
    bookings.reduce((sum, booking) => sum + Math.max(1, booking.seatsRequested || 1), 0),
  );
  const seatUtilizationPercent =
    totalSeats > 0
      ? clamp(Math.round((bookedSeats / totalSeats) * 100), 0, 100)
      : corridor.fillTargetSeats * 18;

  const demandWeight =
    liveSearches * 1.4 + activeDemandAlerts * 2.2 + liveBookings * 2.8 + livePackages * 1.6;
  const supplyWeight = Math.max(1, activeSupply * 1.9 + totalSeats * 0.35);
  const pressureRatio = demandWeight / supplyWeight;
  const liveDemandScore = clamp(
    Math.round(corridor.predictedDemandScore * 0.56 + demandWeight * 3.4 + pressureRatio * 12),
    38,
    99,
  );

  const hour = new Date().getHours();
  const timePulse =
    (hour >= 7 && hour <= 9) || (hour >= 16 && hour <= 19) ? 6 : hour >= 11 && hour <= 14 ? 3 : 0;
  const forecastDemandScore = clamp(
    Math.round(liveDemandScore * 0.72 + seatUtilizationPercent * 0.12 + timePulse),
    40,
    99,
  );

  const pricePressure =
    pressureRatio > 1.15 ? 'surging' : pressureRatio >= 0.82 ? 'balanced' : 'value-window';
  const recommendedSharedPriceJod = roundMoney(
    corridor.sharedPriceJod *
      (pricePressure === 'surging' ? 1.04 : pricePressure === 'balanced' ? 1 : 0.96),
  );
  const priceQuote = getMovementPriceQuote({
    basePriceJod: recommendedSharedPriceJod,
    corridorId: corridor.id,
    forecastDemandScore,
    membership,
  });
  const routeOwnershipScore = clamp(
    Math.round(
      forecastDemandScore * 0.48 +
        seatUtilizationPercent * 0.24 +
        Math.min(100, demandWeight * 6.2) * 0.28,
    ),
    32,
    99,
  );

  return {
    id: corridor.id,
    from: corridor.from,
    to: corridor.to,
    label: corridor.label,
    liveDemandScore,
    forecastDemandScore,
    activeSupply,
    activeDemandAlerts,
    liveSearches,
    liveBookings,
    livePackages,
    seatUtilizationPercent,
    pricePressure,
    nextWaveWindow: inferWaveWindow(signalHours, corridor.density),
    recommendedPickupPoint: corridor.pickupPoints[0] ?? 'Trusted corridor node',
    routeOwnershipScore,
    recommendedReason: buildRecommendedReason({
      alerts: activeDemandAlerts,
      supply: activeSupply,
      seatUtilizationPercent,
      forecastDemandScore,
    }),
    freshestSignalAt,
    productionSources: summarizeProductionSources({
      searches: liveSearches,
      bookings: liveBookings,
      packages: livePackages,
      alerts: activeDemandAlerts,
      supply: activeSupply,
    }),
    priceQuote,
  };
}

export function buildRouteIntelligenceSnapshot(args?: {
  from?: string | null;
  to?: string | null;
  membership?: ReturnType<typeof getMovementMembershipSnapshot>;
}) {
  const membership = args?.membership ?? getMovementMembershipSnapshot();
  const allSignals = getAllCorridorOpportunities()
    .map(corridor => computeSignal(corridor, membership))
    .sort((left, right) => {
      const leftScore = left.forecastDemandScore + left.routeOwnershipScore;
      const rightScore = right.forecastDemandScore + right.routeOwnershipScore;
      return rightScore - leftScore;
    });

  const selectedCorridor =
    args?.from && args?.to ? getCorridorOpportunity(args.from, args.to) : membership.dailyRoute;
  const selectedSignal = selectedCorridor
    ? (allSignals.find(signal => signal.id === selectedCorridor.id) ?? null)
    : null;

  return {
    updatedAt: new Date().toISOString(),
    selectedSignal,
    featuredSignals: allSignals.slice(0, 6),
    allSignals,
    membership,
  } satisfies RouteIntelligenceSnapshot;
}

export function getLiveCorridorSignal(
  from?: string | null,
  to?: string | null,
  membership?: ReturnType<typeof getMovementMembershipSnapshot>,
) {
  return buildRouteIntelligenceSnapshot({ from, to, membership }).selectedSignal;
}

export function useLiveRouteIntelligence(args?: { from?: string | null; to?: string | null }) {
  const [tick, setTick] = useState(0);

  useEffect(() => {
    if (typeof window === 'undefined') {return undefined;}
    const refresh = () => setTick(value => value + 1);
    const interval = window.setInterval(refresh, REFRESH_MS);
    window.addEventListener('storage', refresh);
    return () => {
      window.clearInterval(interval);
      window.removeEventListener('storage', refresh);
    };
  }, []);

  return useMemo(() => buildRouteIntelligenceSnapshot(args), [args, tick]);
}

import type { WaselUser } from '../contexts/LocalAuth';

export type TrustCapability =
  'offer_ride' | 'carry_packages' | 'receive_payouts' | 'priority_support';

export interface TrustGateResult {
  allowed: boolean;
  reason: string | null;
  recommendation: string | null;
}

function verificationRank ( level?: string ): number {
  switch ( level ) {
    case 'level_3':
      return 3;
    case 'level_2':
      return 2;
    case 'level_1':
      return 1;
    default:
      return 0;
  }
}

export function evaluateTrustCapability (
  user:
    | Pick<
      WaselUser,
      | 'role'
      | 'verificationLevel'
      | 'walletStatus'
      | 'trustScore'
      | 'phoneVerified'
      | 'emailVerified'
      | 'driverStatus'
    >
    | null
    | undefined,
  capability: TrustCapability,
): TrustGateResult {
  if ( !user ) {
    return {
      allowed: false,
      reason: 'Sign in to continue.',
      recommendation: 'Open your account first.',
    };
  }

  const level = verificationRank( user.verificationLevel );
  const walletBlocked =
    user.walletStatus === 'frozen' ||
    user.walletStatus === 'closed' ||
    user.walletStatus === 'unavailable';

  if ( walletBlocked && capability !== 'priority_support' ) {
    return {
      allowed: false,
      reason: 'Wallet needs review.',
      recommendation: 'Fix wallet status in Wallet or Settings.',
    };
  }

  if ( capability === 'offer_ride' ) {
    if ( user.role !== 'driver' && user.role !== 'both' ) {
      return {
        allowed: false,
        reason: 'Turn on Driver mode first.',
        recommendation: 'Open Driver to start.',
      };
    }
    if ( !user.phoneVerified || !user.emailVerified ) {
      return {
        allowed: false,
        reason: 'Verify phone and email.',
        recommendation: 'Finish checks in Trust Center.',
      };
    }
    if ( level < 3 || user.driverStatus !== 'approved' ) {
      return {
        allowed: false,
        reason: 'Driver approval is required before publishing rides.',
        recommendation: 'Submit your driver documents and wait for final approval.',
      };
    }
    return { allowed: true, reason: null, recommendation: null };
  }

  if ( capability === 'carry_packages' ) {
    if ( user.role !== 'driver' && user.role !== 'both' ) {
      return {
        allowed: false,
        reason: 'Turn on Driver mode first.',
        recommendation: 'Complete driver setup.',
      };
    }
    if ( level < 3 || user.trustScore < 70 ) {
      return {
        allowed: false,
        reason: 'Packages need full trust approval.',
        recommendation: 'Reach full driver verification first.',
      };
    }
    return { allowed: true, reason: null, recommendation: null };
  }

  if ( capability === 'receive_payouts' ) {
    if ( !user.emailVerified ) {
      return {
        allowed: false,
        reason: 'Payouts need a verified email.',
        recommendation: 'Confirm your email address.',
      };
    }
    return { allowed: true, reason: null, recommendation: null };
  }

  if ( user.trustScore < 70 ) {
    return {
      allowed: false,
      reason: 'Priority support needs stronger trust.',
      recommendation: 'Complete checks and keep a good trip record.',
    };
  }

  return { allowed: true, reason: null, recommendation: null };
}

export function getTrustReadinessSummary (
  user:
    | Pick<
      WaselUser,
      | 'role'
      | 'verificationLevel'
      | 'walletStatus'
      | 'trustScore'
      | 'phoneVerified'
      | 'emailVerified'
      | 'driverStatus'
    >
    | null
    | undefined,
) {
  return {
    canOfferRide: evaluateTrustCapability( user, 'offer_ride' ).allowed,
    canCarryPackages: evaluateTrustCapability( user, 'carry_packages' ).allowed,
    canReceivePayouts: evaluateTrustCapability( user, 'receive_payouts' ).allowed,
    canUsePrioritySupport: evaluateTrustCapability( user, 'priority_support' ).allowed,
  };
}

/**
 * Wallet API — public facade.
 *
 * Strategy (edge → direct → local):
 *  1. Edge Function (production, authenticated)
 *  2. Direct Supabase (dev / fallback when allowDirectSupabaseFallback=true)
 *  3. localStorage (offline / cold-start last resort)
 */

import { API_URL } from '../core';
import { BackendRequestError, requestEdgeJson } from '../backendWorkflow';
import { getConfig } from '../../utils/env';
import {
  canUseLocalWalletStorage,
  fetchWalletLocal,
  setAutoTopUpLocal,
  getPaymentMethodsLocal,
  addPaymentMethodLocal,
  deletePaymentMethodLocal,
  getTrustScoreLocal,
  buildInsightsFromTransactions,
  toWalletTransaction,
} from './walletLocalStorage';
import {
  fetchWalletDirect,
  getWalletTransactionRows,
  transferWalletFundsDirect,
  withdrawWalletFundsDirect,
  updateWalletPreferencesDirect,
  getPaymentMethodsDirect,
  addPaymentMethodDirect,
  deletePaymentMethodDirect,
  getTrustScoreDirect,
  payWithWalletDirect,
} from './walletDirect';
import type {
  InsightsData,
  PaymentMethodInput,
  PaymentMethodRow,
  WalletCapabilities,
  WalletData,
  WalletSubscription,
  WalletTransaction,
} from './walletTypes';

// Re-export types so existing import sites keep working.
export type {
  InsightsData,
  PaymentMethodInput,
  PaymentMethodRow,
  WalletCapabilities,
  WalletData,
  WalletEscrow,
  WalletSubscription,
  WalletSummary,
  WalletTransaction,
  RewardItem,
} from './walletTypes';

const WALLET_API_BASE = API_URL ? `${API_URL}/v1/wallet` : '';

function canUseEdgeApi(): boolean {
  return Boolean(WALLET_API_BASE);
}

async function tryEdgeThenDirect<T>(edgeFn: () => Promise<T>, directFn: () => Promise<T>): Promise<T> {
  const { allowDirectSupabaseFallback } = getConfig();

  if (canUseEdgeApi()) {
    try {
      return await edgeFn();
    } catch (edgeError) {
      if (!allowDirectSupabaseFallback) {throw edgeError;}
    }
  }

  if (allowDirectSupabaseFallback) {return directFn();}

  throw new Error('Secure API is not configured and direct database access is disabled for this environment.');
}

function getWalletPath(userId: string, suffix = ''): string {
  return `/v1/wallet/${userId}${suffix}`;
}

function sanitizeString(value: unknown): string {
  if (typeof value !== 'string') {return '';}
  return value
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#x27;');
}

function sanitizeTransactions(transactions: WalletTransaction[]): WalletTransaction[] { // nosec CWE-79 CWE-80
  return transactions.map(tx => ({
    ...tx,
    description: sanitizeString(tx.description),
  }));
}

function sanitizeWalletData(data: WalletData): WalletData {
  return {
    ...data,
    transactions: sanitizeTransactions(data.transactions),
    activeRewards: data.activeRewards.map(reward => ({
      ...reward,
      description: sanitizeString(reward.description),
    })),
  };
}

async function requestWalletJson<T>(
  userId: string,
  suffix: string,
  operation: string,
  init?: { method?: string; body?: unknown; headers?: HeadersInit; timeout?: number; retries?: number },
): Promise<T> {
  return requestEdgeJson<T>({
    path: getWalletPath(userId, suffix),
    operation,
    authMode: 'required',
    method: init?.method,
    body: init?.body,
    headers: init?.headers,
    timeout: init?.timeout,
    retries: init?.retries,
  });
}

function isConnectivityError(error: unknown): boolean {
  if (error instanceof BackendRequestError) {return error.status === 404;}
  const message = error instanceof Error ? error.message : String(error);
  return message.includes('Route not found') || message.includes('request failed: 404');
}

async function fetchSubscriptionViaBackend(userId: string): Promise<WalletSubscription | null> {
  const result = await requestWalletJson<{ subscription?: WalletSubscription | null }>(
    userId, '/subscription', 'Load wallet subscription',
  );
  return result.subscription ?? null;
}

export function getWalletCapabilities(): WalletCapabilities {
  const secureEdgeReady = canUseEdgeApi();
  return { topUp: secureEdgeReady, rewardClaim: secureEdgeReady, subscription: secureEdgeReady, pin: secureEdgeReady, send: true, withdraw: true, autoTopUp: true };
}

export const walletApi = {
  async getWallet(userId: string): Promise<WalletData> {
    let wallet: WalletData;
    try {
      wallet = await tryEdgeThenDirect(
        () => requestWalletJson<WalletData>(userId, '', 'Load wallet'),
        () => fetchWalletDirect(userId),
      );
    } catch (error) {
      if (!canUseLocalWalletStorage()) {throw error;}
      return fetchWalletLocal(userId);
    }

    if (canUseEdgeApi()) {
      try { wallet.subscription = await fetchSubscriptionViaBackend(userId); } catch { /* keep direct payload */ }
    }
    return sanitizeWalletData(wallet);
  },

  async getTransactions(userId: string, page = 1, limit = 20, type?: string) {
    const edgeFn = async () => {
      const params = new URLSearchParams({ page: String(page), limit: String(limit) });
      if (type) {params.set('type', type);}
      const result = await requestWalletJson<{ transactions: WalletTransaction[]; page: number; limit: number; total: number }>(userId, `/transactions?${params.toString()}`, 'Load wallet transactions');
      return { ...result, transactions: sanitizeTransactions(result.transactions) };
    };
    const directFn = async () => {
      const wallet = canUseLocalWalletStorage()
        ? await fetchWalletDirect(userId).catch(() => fetchWalletLocal(userId))
        : await fetchWalletDirect(userId);
      const filtered = type ? wallet.transactions.filter(tx => tx.type === type) : wallet.transactions;
      const start = (page - 1) * limit;
      return { transactions: filtered.slice(start, start + limit), page, limit, total: filtered.length };
    };
    return tryEdgeThenDirect(edgeFn, directFn);
  },

  async topUp(userId: string, amount: number, paymentMethod: string) {
    if (canUseEdgeApi()) {
      try {
        return await requestWalletJson(userId, '/top-up', 'Create wallet top-up', { method: 'POST', body: { amount, paymentMethod } });
      } catch (error) {
