/**
 * Shared auth error message normaliser.
 * Single source of truth — imported by WaselAuth and auth.ts.
 */
export function friendlyAuthError(error: unknown, fallback: string, code?: string): string {
  const message = error instanceof Error ? error.message : String(error ?? '');
  const lower = message.toLowerCase();
  const errorCode =
    code ||
    (typeof error === 'object' &&
    error !== null &&
    'code' in error
      ? (error as Record<string, unknown>).code
      : undefined);
  const normalizedCode = typeof errorCode === 'string' ? errorCode : undefined;

  if (
    lower.includes('invalid login credentials') ||
    lower.includes('invalid credentials') ||
    lower.includes('authentication failed') ||
    lower.includes('wrong email') ||
    lower.includes('wrong password') ||
    normalizedCode === 'invalid_credentials'
  )
    {return 'Incorrect email or password.';}

  if (lower.includes('email not confirmed') || normalizedCode === 'email_not_confirmed')
    {return 'Please confirm your email before signing in.';}

  if (
    lower.includes('already registered') ||
    lower.includes('already been registered') ||
    normalizedCode === 'email_exists'
  )
    {return 'This email is already registered.';}

  if (normalizedCode === 'user_not_found' || lower.includes('user not found'))
    {return 'Account not found. Please check your email or sign up.';}

  if (normalizedCode === 'over_request_rate_limit' || lower.includes('too many requests'))
    {return 'Too many attempts. Please wait a moment and try again.';}

  if (
    normalizedCode === 'email_address_not_authorized' ||
    lower.includes('signups not allowed') ||
    lower.includes('not allowed for this email domain')
  )
    {return 'Sign-up is not allowed for this email domain.';}

  if (normalizedCode === 'email_address_invalid' || lower.includes('invalid email'))
    {return 'Please enter a valid email address.';}

  if (normalizedCode === 'user_banned' || lower.includes('user banned'))
    {return 'Your account has been suspended. Please contact support.';}

  if (normalizedCode === 'weak_password')
    {return 'Password is too weak. Please choose a stronger password.';}

  if (normalizedCode === 'signup_disabled' || lower.includes('signup disabled'))
    {return 'Sign-up is currently disabled. Please contact support.';}

  if (normalizedCode === 'phone_exists' || lower.includes('phone already exists'))
    {return 'This phone number is already registered.';}

  return message || fallback;
}

/**
 * Password strength scorer.
 * Returns score 0-5, label, and colour token from wasel-ds.
 */
import { C } from '../utils/wasel-ds';

export function pwStrength(password: string): { score: number; label: string; color: string } {
  if (!password) {return { score: 0, label: '', color: C.textMuted };}

  let score = 0;
  if (password.length >= 8) {score += 1;}
  if (password.length >= 12) {score += 1;}
  if (/[A-Z]/.test(password)) {score += 1;}
  if (/\d/.test(password)) {score += 1;}
  if (/[^A-Za-z0-9]/.test(password)) {score += 1;}

  const map = [
    { score: 0, label: '', color: C.textMuted },
    { score: 1, label: 'Weak', color: C.error },
    { score: 2, label: 'Fair', color: C.gold },
    { score: 3, label: 'Good', color: C.cyan },
    { score: 4, label: 'Strong', color: C.green },
    { score: 5, label: 'Excellent', color: C.green },
  ];

  return map[Math.min(score, 5)] ?? { score: 0, label: '', color: C.textMuted };
}

import type { SupportedCurrency, CurrencyConfig, Money } from './types';
import { PLATFORM_CURRENCY, CURRENCIES, EXCHANGE_RATES_FROM_JOD, SUPPORTED_CURRENCY_CODES } from './data';

/** Create a Money object with explicit currency. */
export function money(amount: number, currency: SupportedCurrency = PLATFORM_CURRENCY): Money {
  return { amount, currency };
}

// ─── Currency service ─────────────────────────────────────────────────────────

const STORAGE_KEY = import.meta.env.VITE_CURRENCY_STORAGE_KEY || 'wasel-preferred-currency';

export class CurrencyService {
  private static _instance: CurrencyService | null = null;
  private _current: SupportedCurrency;

  private constructor() {
    this._current = this._detectPreference();
  }

  static getInstance(): CurrencyService {
    if (!CurrencyService._instance) {
      CurrencyService._instance = new CurrencyService();
    }
    return CurrencyService._instance;
  }

  static getCurrencyConfig(code: SupportedCurrency): CurrencyConfig {
    return CURRENCIES[code];
  }

  static formatAmount(amount: number, currency: SupportedCurrency = PLATFORM_CURRENCY): string {
    return CurrencyService.getInstance().format(amount, currency);
  }

  // ── Preference detection ──────────────────────────────────────────────────

  private _detectPreference(): SupportedCurrency {
    try {
      const saved = localStorage.getItem(STORAGE_KEY);
      if (saved && (SUPPORTED_CURRENCY_CODES as readonly string[]).includes(saved)) {
        return saved as SupportedCurrency;
      }
    } catch {
      // localStorage unavailable (SSR / private mode)
    }

    // Infer from browser locale — Jordan is primary, so JOD first.
    const lang = typeof navigator === 'undefined' ? 'ar-jo' : navigator.language.toLowerCase();
    if (lang.startsWith('ar-jo') || lang.startsWith('ar')) {return 'JOD';}
    if (lang.startsWith('en-gb')) {return 'GBP';}
    if (lang.startsWith('ar-ae')) {return 'AED';}
    if (lang.startsWith('ar-sa')) {return 'SAR';}
    if (lang.startsWith('ar-eg')) {return 'EGP';}
    if (lang.startsWith('ar-kw')) {return 'KWD';}
    if (lang.startsWith('ar-bh')) {return 'BHD';}
    if (lang.startsWith('ar-qa')) {return 'QAR';}
    if (lang.startsWith('ar-om')) {return 'OMR';}
    if (lang.startsWith('ar-ma')) {return 'MAD';}
    if (lang.startsWith('ar-tn')) {return 'TND';}
    if (lang.startsWith('ar-iq')) {return 'IQD';}
    if (lang.startsWith('de') || lang.startsWith('fr')) {return 'EUR';}
    if (lang.startsWith('en')) {return 'USD';}

    return PLATFORM_CURRENCY;
  }

  // ── Getters / setters ─────────────────────────────────────────────────────

  get current(): SupportedCurrency {
    return this._current;
  }
  get config(): CurrencyConfig {
    return CURRENCIES[this._current];
  }
  get minFare(): number {
    return CURRENCIES[this._current].minFare;
  }

  setCurrency(code: SupportedCurrency): void {
    this._current = code;
    try {
      localStorage.setItem(STORAGE_KEY, code);
    } catch {
      /* noop */
    }
  }

  // ── Conversion ────────────────────────────────────────────────────────────

  /**
   * Convert a JOD amount to the display currency.
   * All backend amounts are stored in JOD.
   */
  fromJOD(jodAmount: number, to: SupportedCurrency = this._current): number {
    if (to === 'JOD') {return jodAmount;}
    const rate = EXCHANGE_RATES_FROM_JOD[to];
    return Math.round(jodAmount * rate * 1_000) / 1_000;
  }

  /**
   * Convert a display-currency amount back to JOD for storage / API calls.
   */
  toJOD(amount: number, from: SupportedCurrency = this._current): number {
    if (from === 'JOD') {return amount;}
    const rate = EXCHANGE_RATES_FROM_JOD[from];
    return Math.round((amount / rate) * 1_000) / 1_000;
  }

  /**
   * Convert between any two supported currencies via JOD as the pivot.
   */
  convert(amount: number, from: SupportedCurrency, to: SupportedCurrency): number {
    if (from === to) {return amount;}
    const inJOD = this.toJOD(amount, from);
    return this.fromJOD(inJOD, to);
  }

  // ── Formatting ────────────────────────────────────────────────────────────

  /**
   * Format an amount in the given (or current) currency using Intl.NumberFormat.
   * @example format(3.5, 'JOD') → "3.500 د.أ"
   */
  format(amount: number, currency?: SupportedCurrency): string {
    const curr = currency ?? this._current;
    const config = CURRENCIES[curr];
    try {
      return new Intl.NumberFormat(config.locale, {
        style: 'currency',
        currency: config.code,
        minimumFractionDigits: config.decimals,
        maximumFractionDigits: config.decimals,
      }).format(amount);
    } catch {
      // Fallback if Intl doesn't recognise the currency (rare)
      return `${amount.toFixed(config.decimals)} ${config.symbol}`;
    }
  }

  /**
   * Short format: symbol + amount, no Intl (useful for compact UI).
   * @example formatShort(3.5, 'JOD') → "د.أ 3.500"
   */
  formatShort(amount: number, currency?: SupportedCurrency): string {
    const curr = currency ?? this._current;
    const config = CURRENCIES[curr];
    return `${config.symbol} ${amount.toFixed(config.decimals)}`;
  }

  /**
   * Format a JOD amount for display in the user's preferred currency.
   * Convenience wrapper for fromJOD + format.
   */
  formatFromJOD(jodAmount: number): string {
    const displayAmount = this.fromJOD(jodAmount);
    return this.format(displayAmount);
  }

  getSymbol(currency?: SupportedCurrency): string {
    return CURRENCIES[currency ?? this._current].symbol;
  }

  getAvailable(): CurrencyConfig[] {
    return SUPPORTED_CURRENCY_CODES.map(c => CURRENCIES[c]);
  }
}

import {
  type EnvSource,
  type RuntimeConfigIssue,
  getSupabaseProjectRefFromJwt,
  getSupabaseProjectRefFromUrl,
  isAbsoluteHttpUrl,
  isTruthy,
  readEnvSource,
  resolveApiUrl,
  resolveAppUrl,
  resolveSupabasePublicKey,
  resolveSupabaseUrl,
  trimConfiguredValue,
} from './resolvers';

export function getRuntimeConfigIssues(
  envSource: EnvSource = readEnvSource(),
): RuntimeConfigIssue[] {
  const issues: RuntimeConfigIssue[] = [];
  const apiUrl = resolveApiUrl(envSource);
  const supabaseUrl = resolveSupabaseUrl(envSource);
  const supabasePublicKey = resolveSupabasePublicKey(envSource);
  const appUrl = resolveAppUrl(envSource);
  const sentryDsn = trimConfiguredValue(envSource.VITE_SENTRY_DSN);
  const mode = envSource.MODE || envSource.VITE_MODE || envSource.NODE_ENV || 'development';
  const isProd = mode === 'production';
  const isBuildTime = typeof window === 'undefined';
  const isLocalE2E = !isProd && isTruthy(envSource.VITE_E2E_LOCAL_AUTH);

  if (isLocalE2E) {
    return issues;
  }

  const hasApiTransport = Boolean(apiUrl) || (Boolean(supabaseUrl) && Boolean(supabasePublicKey));

  if (!appUrl) {
    issues.push({
      key: 'VITE_APP_URL',
      message: 'VITE_APP_URL should be set so auth callbacks and support links resolve correctly.',
      severity: isBuildTime ? 'warning' : 'error',
    });
  } else if (!isAbsoluteHttpUrl(appUrl)) {
    issues.push({
      key: 'VITE_APP_URL',
      message: 'VITE_APP_URL must be an absolute http(s) URL.',
      severity: isBuildTime ? 'warning' : 'error',
    });
  } else if (isProd && !isBuildTime && !appUrl.startsWith('https://')) {
    issues.push({
      key: 'VITE_APP_URL',
      message: 'Protected environments must use an HTTPS VITE_APP_URL',
      severity: 'error',
    });
  }

  if (!supabaseUrl) {
    issues.push({
      key: 'VITE_SUPABASE_URL',
      message: 'VITE_SUPABASE_URL is not configured',
      severity: 'error',
    });
  }

  if (!supabasePublicKey) {
    issues.push({
      key: 'VITE_SUPABASE_PUBLISHABLE_KEY',
      message: 'VITE_SUPABASE_PUBLISHABLE_KEY or VITE_SUPABASE_ANON_KEY is not configured',
      severity: 'error',
    });
  }

  if (!hasApiTransport) {
    issues.push({
      key: 'VITE_API_URL',
      message: 'Protected environments must define VITE_API_URL or VITE_EDGE_FUNCTION_NAME',
      severity: 'error',
    });
  }

  if (apiUrl && !isAbsoluteHttpUrl(apiUrl)) {
    issues.push({
      key: 'VITE_API_URL',
      message: 'VITE_API_URL must be an absolute http(s) URL when provided.',
      severity: 'error',
    });
  }

  if (supabaseUrl && !isAbsoluteHttpUrl(supabaseUrl)) {
    issues.push({
      key: 'VITE_SUPABASE_URL',
      message: 'VITE_SUPABASE_URL must be an absolute http(s) URL when provided.',
      severity: 'error',
    });
  } else if (isProd && !isBuildTime && supabaseUrl && !supabaseUrl.startsWith('https://')) {
    issues.push({
      key: 'VITE_SUPABASE_URL',
      message: 'Protected environments must use an HTTPS Supabase URL',
      severity: 'error',
    });
  }

  const supabaseUrlProjectRef = supabaseUrl ? getSupabaseProjectRefFromUrl(supabaseUrl) : null;
  const publicKeyProjectRef = getSupabaseProjectRefFromJwt(supabasePublicKey);
  if (
    supabaseUrlProjectRef &&
    publicKeyProjectRef &&
    supabaseUrlProjectRef !== publicKeyProjectRef
  ) {
    issues.push({
      key: 'VITE_SUPABASE_PUBLISHABLE_KEY',
      message: `Configured Supabase public key belongs to project ${publicKeyProjectRef}, but VITE_SUPABASE_URL points to ${supabaseUrlProjectRef}.`,
      severity: 'error',
    });
  }

  if (isProd && isTruthy(envSource.VITE_ALLOW_DIRECT_SUPABASE_FALLBACK)) {
    issues.push({
      key: 'VITE_ALLOW_DIRECT_SUPABASE_FALLBACK',
      message: 'Production should fail closed. Disable direct Supabase fallback before shipping.',
      severity: 'error',
    });
  }

  if (isProd && !sentryDsn) {
    issues.push({
      key: 'VITE_SENTRY_DSN',
      message: 'Production should set VITE_SENTRY_DSN so failures are traceable.',
      severity: 'warning',
    });
  }

  if (
    isTruthy(envSource.VITE_ENABLE_EMAIL_NOTIFICATIONS) &&
    !envSource.VITE_SUPPORT_EMAIL?.trim()
  ) {
    issues.push({
      key: 'VITE_SUPPORT_EMAIL',
      message: 'Email notifications are enabled but no support email is configured.',
      severity: 'warning',
    });
  }

  if (
    isTruthy(envSource.VITE_ENABLE_SMS_NOTIFICATIONS) &&
    !envSource.VITE_SUPPORT_SMS_NUMBER?.trim()
  ) {
    issues.push({
      key: 'VITE_SUPPORT_SMS_NUMBER',
      message: 'SMS notifications are enabled but no support SMS number is configured.',
      severity: 'warning',
    });
  }

  if (
    isTruthy(envSource.VITE_ENABLE_WHATSAPP_NOTIFICATIONS) &&
    !envSource.VITE_SUPPORT_WHATSAPP_NUMBER?.trim()
  ) {
    issues.push({
      key: 'VITE_SUPPORT_WHATSAPP_NUMBER',
      message: 'WhatsApp notifications are enabled but no support WhatsApp number is configured.',
      severity: 'warning',
    });
  }

  if (isTruthy(envSource.VITE_ENABLE_TWO_FACTOR_AUTH) && !hasApiTransport) {
    issues.push({
      key: 'VITE_ENABLE_TWO_FACTOR_AUTH',
      message:
        'Two-factor auth requires a backend transport. Configure the API path before enabling it.',
      severity: 'error',
    });
  }

  return issues;
}

export function validateRuntimeConfiguration(envSource: EnvSource = readEnvSource()) {
  const issues = getRuntimeConfigIssues(envSource);
  return {
    ok: issues.every(issue => issue.severity !== 'error'),
    issues,
  };
}

/**
 * OAuth Configuration Validator
 * Validates that OAuth providers are properly configured before use
 */

import type { SupabaseClient } from '@supabase/supabase-js';

export type OAuthProvider = 'google' | 'facebook' | 'microsoft' | 'apple';

export interface OAuthProviderStatus {
  provider: OAuthProvider;
  enabled: boolean;
  configured: boolean;
  error?: string;
}

export interface OAuthValidationResult {
  valid: boolean;
  providers: OAuthProviderStatus[];
  redirectUri: string;
  warnings: string[];
}

/**
 * Get the expected redirect URI for Supabase OAuth
 */
export function getOAuthRedirectUri(supabaseUrl: string): string {
  const base = supabaseUrl.replace(/\/$/, '');
  return `${base}/auth/v1/callback`;
}

/**
 * Validate OAuth configuration by attempting to get the provider's auth URL
 * without actually redirecting the user
 */
export async function validateOAuthProvider(
  client: SupabaseClient,
  provider: OAuthProvider,
): Promise<OAuthProviderStatus> {
  try {
    // signInWithOAuth with shouldCreateSession=false lets us check config
    // without initiating the full flow
    const { data, error } = await client.auth.signInWithOAuth({
      provider: provider as any,
      options: {
        redirectTo: window.location.origin + '/app/auth/callback',
        skipBrowserRedirect: true,
      },
    });

    if (error) {
      return {
        provider,
        enabled: true,
        configured: false,
        error: classifyConfigError(error.message, provider),
      };
    }

    // If we got a URL back, the provider is configured
    return {
      provider,
      enabled: true,
      configured: Boolean(data?.url),
    };
  } catch (err) {
    const message = err instanceof Error ? err.message : 'Unknown error';
    return {
      provider,
      enabled: true,
      configured: false,
      error: classifyConfigError(message, provider),
    };
  }
}

/**
 * Classify configuration errors into actionable messages
 */
function classifyConfigError(message: string, provider: OAuthProvider): string {
  const providerName = provider.charAt(0).toUpperCase() + provider.slice(1);
  const lower = message.toLowerCase();

  if (lower.includes('redirect_uri') || lower.includes('redirect uri') || lower.includes('uri not allowed')) {
    return `${providerName} redirect URI is not whitelisted. Add "${getExpectedRedirectUri()}" to your ${provider === 'facebook' ? 'Facebook Developer Console' : 'Google Cloud Console'} > Valid OAuth Redirect URIs.`;
  }

  if (lower.includes('client_id') || lower.includes('client id') || lower.includes('invalid_client')) {
    return `${providerName} Client ID is missing or invalid. Check your Supabase Dashboard > Authentication > Providers > ${providerName}.`;
  }

  if (lower.includes('client_secret') || lower.includes('client secret') || lower.includes('unauthorized')) {
    return `${providerName} Client Secret is missing or invalid. Check your Supabase Dashboard > Authentication > Providers > ${providerName}.`;
  }

  if (lower.includes('provider is not enabled') || lower.includes('not enabled')) {
    return `${providerName} provider is not enabled in Supabase Dashboard > Authentication > Providers.`;
  }

  return `${providerName} OAuth configuration error: ${message}`;
}

/**
 * Get the expected redirect URI for this app
 */
export function getExpectedRedirectUri(): string {
  const supabaseUrl = import.meta.env.VITE_SUPABASE_URL || '';
  return getOAuthRedirectUri(supabaseUrl);
}

/**
 * Get setup instructions for each provider
 */
export function getProviderSetupInstructions(provider: OAuthProvider): {
  steps: string[];
  docsUrl: string;
} {
  const redirectUri = getExpectedRedirectUri();

  if (provider === 'facebook') {
    return {
      steps: [
        'Go to Facebook Developers → Your App → Facebook Login → Settings',
        `Add "${redirectUri}" to Valid OAuth Redirect URIs`,
        'Go to Supabase Dashboard → Authentication → Providers → Facebook',
        'Enable Facebook and enter your App ID + App Secret',
        'Ensure your Facebook app is in "Live" mode for public access',
      ],
      docsUrl: 'https://developers.facebook.com/docs/facebook-login',
    };
  }

  if (provider === 'microsoft') {
    return {
      steps: [
        'Go to Azure Portal → Microsoft Entra ID → App registrations',
        `Add "${redirectUri}" to Redirect URIs (web)`,
        'Go to Supabase Dashboard → Authentication → Providers → Microsoft',
        'Enable Microsoft and enter your Client ID + Client Secret',
        'Ensure the app is published and consent is granted for the required scopes',
      ],
      docsUrl: 'https://learn.microsoft.com/en-us/azure/active-directory/develop/quickstart-register-app',
    };
  }

  if (provider === 'apple') {
    return {
      steps: [
        'Go to Apple Developer → Certificates, Identifiers & Profiles → Identifiers',
        `Add "${redirectUri}" to Return URLs in your Apple Services ID`,
        'Go to Supabase Dashboard → Authentication → Providers → Apple',
        'Enable Apple and enter your Services ID, Team ID, Key ID, and Private Key',
        'Ensure your Apple app is configured for Sign in with Apple',
      ],
      docsUrl: 'https://developer.apple.com/documentation/sign_in_with_apple',
    };
  }

  return {
    steps: [
      'Go to Google Cloud Console → Credentials',
      `Add "${redirectUri}" to Authorized redirect URIs`,
      'Go to Supabase Dashboard → Authentication → Providers → Google',
      'Enable Google and enter your Client ID + Client Secret',
    ],
    docsUrl: 'https://developers.google.com/identity/protocols/oauth2',
  };
}

/**
 * Check if the current origin is in the Supabase allow-list
 */
export function isOriginAllowed(allowedOrigins: string[]): boolean {
  if (typeof window === 'undefined') {
    return true;
  }
  const origin = window.location.origin;
  return allowedOrigins.some(allowed => {
    try {
      const allowedUrl = new URL(allowed);
      return allowedUrl.origin === origin;
    } catch {
      return allowed === origin;
    }
  });
}

/**
 * Wasel Router v7.2 — WaselServicePage monolith split into feature files.
 *
 * Changes from v7.1:
 *  - FindRidePage   → src/features/rides/FindRidePage.tsx   (re-exported from WaselServicePage for compatibility)
 *  - OfferRidePage  → src/features/rides/OfferRidePage.tsx  (re-exported)
 *  - BusPage        → src/features/bus/BusPage.tsx
 *  - PackagesPage   → src/features/packages/PackagesPage.tsx (re-exported)
 *  - Shared primitives extracted to src/features/shared/pageShared.tsx
 *  - WaselServicePage.tsx retained as the source of truth for FindRide, OfferRide, Packages
 *    until those are individually migrated; BusPage is now fully standalone.
 */
import React, { memo, Suspense, useEffect } from 'react';
import { AlertTriangle, LoaderCircle, SearchX } from 'lucide-react';
import { createBrowserRouter, isRouteErrorResponse, Navigate, useRouteError, type RouteObject } from 'react-router';
import { Button } from './components/ui/button';
import { WaselStateCard } from './components/system/WaselStateCard';
import { useLanguage } from './contexts/LanguageContext';
import WaselRoot from './layouts/WaselRoot';
import ProtectedOutlet from './router/ProtectedOutlet';

const PageLoader = memo(() => {
  const { language } = useLanguage();
  const ar = language === 'ar';

  return (
    <WaselStateCard
      eyebrow={ar ? 'تحميل' : 'Loading'}
      title={ar ? 'نفتح شاشة واصل التالية' : 'Opening the next Wasel view'}
      description={
        ar
          ? 'نجهز المسار ونحمل بيانات الشاشة ونستعيد آخر سياق لك.'
          : 'We are preparing the route, loading the screen data, and restoring your last context.'
      }
      icon={LoaderCircle}
      loading
      minHeight="60vh"
    />
  );
});

function lazy(
  importFn: () => Promise<Record<string, React.ComponentType<Record<string, unknown>>>>,
  exportName?: string,
) {
  return async () => {
    const mod = await importFn();
    const Component = (exportName ? mod[exportName] : mod.default) as React.ComponentType<
      Record<string, unknown>
    >;
    return {
      Component: memo((props: Record<string, unknown>) => (
        <Suspense fallback={<PageLoader />}>
          <Component {...props} />
        </Suspense>
      )),
    };
  };
}

// ── Utility redirects ─────────────────────────────────────────────────────────
const RedirectTo = memo(({ to }: { to: string }) => <Navigate to={to} replace />);

const NotFound = memo(() => {
  const { language } = useLanguage();
  const ar = language === 'ar';

  return (
    <WaselStateCard
      eyebrow="404"
      title={ar ? 'الصفحة غير موجودة' : 'Page not found'}
      description={
        ar
          ? 'الصفحة المطلوبة غير متاحة أو أن الرابط قديم.'
          : 'The page you requested is unavailable or the link is outdated.'
      }
      icon={SearchX}
      minHeight="80vh"
      actions={
        <Button asChild className="bg-primary text-primary-foreground hover:bg-primary/90">
          <a href="/">{ar ? 'العودة إلى واصل' : 'Back to Wasel'}</a>
        </Button>
      }
    />
  );
});

const isInvalidHookCallError = (message: string): boolean =>
  /invalid hook call/i.test(message);

const RouteErrorFallback = memo(() => {
  const { language } = useLanguage();
  const ar = language === 'ar';
  const error = useRouteError();
  const message = isRouteErrorResponse(error)
    ? `${error.status} ${error.statusText}`
    : error instanceof Error
      ? error.message
      : ar
        ? 'تعذر تحميل هذه الصفحة.'
        : 'This page could not be loaded.';

  const isHookError = isInvalidHookCallError(message);

  useEffect(() => {
    if (!isHookError) {
      return;
    }

    const timer = setTimeout(() => {
      const hardRecover = (window as unknown as { waselHardRecover?: () => void }).waselHardRecover;
      if (typeof hardRecover === 'function') {
        hardRecover();
      } else {
        window.location.reload();
      }
    }, 2000);

    return () => clearTimeout(timer);
  }, [isHookError]);

  if (isHookError) {
    return (
      <WaselStateCard
        eyebrow={ar ? 'خطأ في التطبيق' : 'App Error'}
        title={ar ? 'تعذر تحميل هذه الصفحة' : 'This page could not be loaded'}
        description={message}
        icon={AlertTriangle}
        tone="danger"
        minHeight="100vh"
        actions={
          <>
            <Button asChild className="bg-primary text-primary-foreground hover:bg-primary/90">
              <a href="/app/find-ride">{ar ? 'ابحث عن مشوار' : 'Find a ride'}</a>
            </Button>
            <Button
              asChild
              variant="outline"
              className="border-white/15 bg-white/5 text-white hover:bg-white/10"
            >
              <a href="/">{ar ? 'العودة للرئيسية' : 'Go home'}</a>
            </Button>
          </>
        }
        footer={
          ar
            ? 'تم اكتشاف خطأ في استدعاء Hook. جارٍ إعادة تشغيل التطبيق تلقائياً...'
            : 'Invalid hook call detected. Automatically recovering...'
        }
      />
    );
  }

  return (
    <WaselStateCard
      eyebrow={ar ? 'خطأ في التطبيق' : 'App Error'}
      title={ar ? 'تعذر تحميل هذه الصفحة' : 'This page could not be loaded'}
      description={message}
      icon={AlertTriangle}
      tone="danger"
      minHeight="100vh"
      actions={
        <>
          <Button asChild className="bg-primary text-primary-foreground hover:bg-primary/90">
            <a href="/app/find-ride">{ar ? 'ابحث عن مشوار' : 'Find a ride'}</a>
          </Button>
          <Button
            asChild
            variant="outline"
            className="border-white/15 bg-white/5 text-white hover:bg-white/10"
          >
            <a href="/">{ar ? 'العودة للرئيسية' : 'Go home'}</a>
          </Button>
        </>
      }
      footer={
        ar
          ? 'إذا تكرر هذا، فأعد تحميل التطبيق أو افتح التدفق مرة أخرى من الشاشة الرئيسية.'
          : 'If this repeats, reload the app shell or reopen the flow from the home screen.'
      }
    />
  );
});

